// Parking Lot - full LLD implementation (single-file demo).
// Difficulty badge includes "Concurrency", so spot allocation + occupation is guarded
// by a lock to guarantee two concurrent parkVehicle() calls never get the same spot.
import java.util.*;
import java.util.concurrent.locks.*;

public class p1 {

    // ---------- Vehicle hierarchy ----------
    enum VehicleSize { MOTORCYCLE, COMPACT, LARGE }

    static abstract class Vehicle {
        private final String licensePlate;
        Vehicle(String licensePlate) { this.licensePlate = licensePlate; }
        String getLicensePlate() { return licensePlate; }
        abstract VehicleSize getSize();
    }

    static class Motorcycle extends Vehicle {
        Motorcycle(String plate) { super(plate); }
        VehicleSize getSize() { return VehicleSize.MOTORCYCLE; }
    }

    static class Car extends Vehicle {
        Car(String plate) { super(plate); }
        VehicleSize getSize() { return VehicleSize.COMPACT; }
    }

    static class Bus extends Vehicle {
        Bus(String plate) { super(plate); }
        VehicleSize getSize() { return VehicleSize.LARGE; }
    }

    // ---------- ParkingSpot ----------
    static class ParkingSpot {
        private final String id;
        private final VehicleSize size;
        private boolean occupied = false;
        private Vehicle currentVehicle;

        ParkingSpot(String id, VehicleSize size) { this.id = id; this.size = size; }

        String getId() { return id; }
        VehicleSize getSize() { return size; }
        boolean isOccupied() { return occupied; }

        // A larger spot can host a smaller vehicle; ordinal() works because the enum
        // is declared smallest-to-largest.
        boolean canFit(VehicleSize vehicleSize) { return !occupied && size.ordinal() >= vehicleSize.ordinal(); }

        void occupy(Vehicle vehicle) {
            if (occupied) throw new IllegalStateException("Spot " + id + " already occupied");
            occupied = true;
            currentVehicle = vehicle;
        }

        void vacate() {
            occupied = false;
            currentVehicle = null;
        }
    }

    // ---------- Floor ----------
    static class Floor {
        private final int floorNumber;
        private final List<ParkingSpot> spots;

        Floor(int floorNumber, List<ParkingSpot> spots) {
            this.floorNumber = floorNumber;
            this.spots = spots;
        }

        int getFloorNumber() { return floorNumber; }
        List<ParkingSpot> getSpots() { return spots; }

        // First compatible free spot on this floor, or null if none.
        ParkingSpot findAvailableSpot(VehicleSize size) {
            for (ParkingSpot s : spots) {
                if (s.canFit(size)) return s;
            }
            return null;
        }
    }

    // ---------- SpotAllocator (interface) + strategies ----------
    interface SpotAllocator {
        ParkingSpot allocate(Vehicle vehicle);
    }

    // Picks the first free compatible spot, scanning floors in order.
    static class FirstAvailableAllocator implements SpotAllocator {
        private final List<Floor> floors;
        FirstAvailableAllocator(List<Floor> floors) { this.floors = floors; }
        public ParkingSpot allocate(Vehicle vehicle) {
            for (Floor f : floors) {
                ParkingSpot spot = f.findAvailableSpot(vehicle.getSize());
                if (spot != null) return spot;
            }
            return null;
        }
    }

    // Picks the compatible spot whose size is the closest fit (least wasted space),
    // scanning floors in order and comparing candidates across floors.
    static class NearestSpotAllocator implements SpotAllocator {
        private final List<Floor> floors;
        NearestSpotAllocator(List<Floor> floors) { this.floors = floors; }
        public ParkingSpot allocate(Vehicle vehicle) {
            ParkingSpot best = null;
            for (Floor f : floors) {
                for (ParkingSpot s : f.getSpots()) {
                    if (!s.canFit(vehicle.getSize())) continue;
                    if (best == null || s.getSize().ordinal() < best.getSize().ordinal()) best = s;
                }
            }
            return best;
        }
    }

    // ---------- Ticket ----------
    enum TicketStatus { ACTIVE, CLOSED }

    static class Ticket {
        private static int SEQ = 1;
        private final String id;
        private final Vehicle vehicle;
        private final ParkingSpot spot;
        private final long entryTime;
        private long exitTime;
        private TicketStatus status;

        private Ticket(Vehicle vehicle, ParkingSpot spot, long entryTime) {
            this.id = "T-" + (SEQ++);
            this.vehicle = vehicle;
            this.spot = spot;
            this.entryTime = entryTime;
            this.status = TicketStatus.ACTIVE;
        }

        static Ticket create(Vehicle vehicle, ParkingSpot spot, long entryTime) {
            return new Ticket(vehicle, spot, entryTime);
        }

        void close(long exitTime) {
            this.exitTime = exitTime;
            this.status = TicketStatus.CLOSED;
        }

        String getId() { return id; }
        Vehicle getVehicle() { return vehicle; }
        ParkingSpot getSpot() { return spot; }
        long getEntryTime() { return entryTime; }
        long getExitTime() { return exitTime; }
        TicketStatus getStatus() { return status; }
    }

    // ---------- FeeStrategy (interface) + strategies ----------
    interface FeeStrategy {
        double calculate(Ticket closedTicket);
    }

    static class HourlyFeeStrategy implements FeeStrategy {
        private final double ratePerHour;
        HourlyFeeStrategy(double ratePerHour) { this.ratePerHour = ratePerHour; }
        public double calculate(Ticket t) {
            long durationMs = t.getExitTime() - t.getEntryTime();
            double hours = Math.max(1, Math.ceil(durationMs / 3600000.0)); // round up, min 1 hour
            return hours * ratePerHour;
        }
    }

    // Applies a surcharge multiplier if entry happened during peak hours (9-11, 17-19).
    static class PeakHourFeeStrategy implements FeeStrategy {
        private final double ratePerHour;
        private final double peakMultiplier;
        PeakHourFeeStrategy(double ratePerHour, double peakMultiplier) {
            this.ratePerHour = ratePerHour;
            this.peakMultiplier = peakMultiplier;
        }
        public double calculate(Ticket t) {
            long durationMs = t.getExitTime() - t.getEntryTime();
            double hours = Math.max(1, Math.ceil(durationMs / 3600000.0));
            int entryHour = (int) ((t.getEntryTime() / 3600000) % 24);
            boolean peak = (entryHour >= 9 && entryHour < 11) || (entryHour >= 17 && entryHour < 19);
            return hours * ratePerHour * (peak ? peakMultiplier : 1.0);
        }
    }

    // ---------- Exceptions ----------
    static class NoAvailableSpotException extends RuntimeException {
        NoAvailableSpotException(String msg) { super(msg); }
    }
    static class InvalidTicketException extends RuntimeException {
        InvalidTicketException(String msg) { super(msg); }
    }

    // ---------- ParkingLot (facade) ----------
    static class ParkingLot {
        private final List<Floor> floors;
        private final SpotAllocator allocator;   // injected interface, not a concrete class
        private final FeeStrategy feeStrategy;    // injected interface, not a concrete class
        // Single lock guarding the "decide spot + occupy spot" sequence, which spans two
        // separate objects (allocator, spot) and therefore cannot be made atomic by either
        // object alone.
        private final Lock lock = new ReentrantLock();

        ParkingLot(List<Floor> floors, SpotAllocator allocator, FeeStrategy feeStrategy) {
            this.floors = floors;
            this.allocator = allocator;
            this.feeStrategy = feeStrategy;
        }

        Ticket parkVehicle(Vehicle vehicle) {
            lock.lock();
            try {
                ParkingSpot spot = allocator.allocate(vehicle);
                if (spot == null) throw new NoAvailableSpotException("No available spot for " + vehicle.getSize());
                spot.occupy(vehicle);
                return Ticket.create(vehicle, spot, System.currentTimeMillis());
            } finally {
                lock.unlock();
            }
        }

        double unparkVehicle(Ticket ticket) {
            lock.lock();
            try {
                if (ticket.getStatus() != TicketStatus.ACTIVE) throw new InvalidTicketException("Ticket not active: " + ticket.getId());
                ticket.close(System.currentTimeMillis());
                double fee = feeStrategy.calculate(ticket);
                ticket.getSpot().vacate();
                return fee;
            } finally {
                lock.unlock();
            }
        }
    }

    // ---------- Demo ----------
    public static void main(String[] args) {
        List<ParkingSpot> f1Spots = Arrays.asList(
                new ParkingSpot("F1-M1", VehicleSize.MOTORCYCLE),
                new ParkingSpot("F1-C1", VehicleSize.COMPACT)
        );
