        SpotAllocator allocator = new NearestSpotAllocator(floors);
        FeeStrategy feeStrategy = new HourlyFeeStrategy(10.0);
        ParkingLot lot = new ParkingLot(floors, allocator, feeStrategy);

        Car car = new Car("KA-01-1234");
        Ticket t1 = lot.parkVehicle(car);
