        Ticket t2 = lot.parkVehicle(bike);
        System.out.println("Parked bike, ticket=" + t2.getId() + " spot=" + t2.getSpot().getId());

        try {
            Bus bus = new Bus("KA-01-9999");
            lot.parkVehicle(bus); // no LARGE spot exists -> should fail
        } catch (NoAvailableSpotException e) {
            System.out.println("Expected failure parking bus: " + e.getMessage());
        }

        double fee = lot.unparkVehicle(t1);
        System.out.println("Unparked car, fee=" + fee);
    }
}

