// Parking Lot - full LLD implementation (single-file demo).
// Difficulty badge includes "Concurrency", so spot allocation + occupation is guarded
// by a mutex to guarantee two concurrent parkVehicle() calls never get the same spot.
#include <iostream>
#include <vector>
#include <memory>
#include <string>
#include <mutex>
#include <stdexcept>
#include <chrono>
#include <cmath>

// ---------- Vehicle hierarchy ----------
enum class VehicleSize { MOTORCYCLE = 0, COMPACT = 1, LARGE = 2 };

class Vehicle {
public:
    Vehicle(std::string plate) : licensePlate(std::move(plate)) {}
    virtual ~Vehicle() = default;
    const std::string& getLicensePlate() const { return licensePlate; }
    virtual VehicleSize getSize() const = 0;
private:
    std::string licensePlate;
};

class Motorcycle : public Vehicle {
public:
    explicit Motorcycle(std::string plate) : Vehicle(std::move(plate)) {}
    VehicleSize getSize() const override { return VehicleSize::MOTORCYCLE; }
};

class Car : public Vehicle {
public:
    explicit Car(std::string plate) : Vehicle(std::move(plate)) {}
    VehicleSize getSize() const override { return VehicleSize::COMPACT; }
};

class Bus : public Vehicle {
public:
    explicit Bus(std::string plate) : Vehicle(std::move(plate)) {}
    VehicleSize getSize() const override { return VehicleSize::LARGE; }
};

// ---------- ParkingSpot ----------
class ParkingSpot {
public:
    ParkingSpot(std::string id, VehicleSize size) : id(std::move(id)), size(size) {}

    const std::string& getId() const { return id; }
    VehicleSize getSize() const { return size; }
    bool isOccupied() const { return occupied; }

    // A larger spot can host a smaller vehicle; enum values are ordered smallest-to-largest.
    bool canFit(VehicleSize vehicleSize) const {
        return !occupied && static_cast<int>(size) >= static_cast<int>(vehicleSize);
    }

    void occupy(Vehicle* vehicle) {
        if (occupied) throw std::runtime_error("Spot " + id + " already occupied");
        occupied = true;
        currentVehicle = vehicle;
    }

    void vacate() {
        occupied = false;
        currentVehicle = nullptr;
    }

private:
    std::string id;
    VehicleSize size;
    bool occupied = false;
    Vehicle* currentVehicle = nullptr;
};

// ---------- Floor ----------
class Floor {
public:
    Floor(int floorNumber, std::vector<std::unique_ptr<ParkingSpot>> spots)
        : floorNumber(floorNumber), spots(std::move(spots)) {}

    int getFloorNumber() const { return floorNumber; }
    std::vector<std::unique_ptr<ParkingSpot>>& getSpots() { return spots; }

    // First compatible free spot on this floor, or nullptr if none.
    ParkingSpot* findAvailableSpot(VehicleSize size) {
        for (auto& s : spots) {
            if (s->canFit(size)) return s.get();
        }
        return nullptr;
    }

private:
    int floorNumber;
    std::vector<std::unique_ptr<ParkingSpot>> spots;
};

// ---------- Ticket ----------
enum class TicketStatus { ACTIVE, CLOSED };

class Ticket {
public:
    static std::unique_ptr<Ticket> create(Vehicle* vehicle, ParkingSpot* spot, long long entryTime) {
        return std::unique_ptr<Ticket>(new Ticket(vehicle, spot, entryTime));
    }

    void close(long long exit) { exitTime = exit; status = TicketStatus::CLOSED; }

    const std::string& getId() const { return id; }
    Vehicle* getVehicle() const { return vehicle; }
    ParkingSpot* getSpot() const { return spot; }
    long long getEntryTime() const { return entryTime; }
    long long getExitTime() const { return exitTime; }
    TicketStatus getStatus() const { return status; }

private:
    Ticket(Vehicle* vehicle, ParkingSpot* spot, long long entryTime)
        : id("T-" + std::to_string(nextId++)), vehicle(vehicle), spot(spot),
          entryTime(entryTime), exitTime(0), status(TicketStatus::ACTIVE) {}

    static int nextId;
    std::string id;
    Vehicle* vehicle;
    ParkingSpot* spot;
    long long entryTime;
    long long exitTime;
    TicketStatus status;
};
int Ticket::nextId = 1;

// ---------- SpotAllocator (interface) + strategies ----------
class SpotAllocator {
public:
    virtual ~SpotAllocator() = default;
    virtual ParkingSpot* allocate(Vehicle* vehicle) = 0;
};

// Picks the first free compatible spot, scanning floors in order.
class FirstAvailableAllocator : public SpotAllocator {
public:
    explicit FirstAvailableAllocator(std::vector<Floor*> floors) : floors(std::move(floors)) {}
    ParkingSpot* allocate(Vehicle* vehicle) override {
        for (auto* f : floors) {
            ParkingSpot* spot = f->findAvailableSpot(vehicle->getSize());
            if (spot) return spot;
        }
        return nullptr;
    }
private:
    std::vector<Floor*> floors;
};

// Picks the compatible spot whose size is the closest fit (least wasted space).
class NearestSpotAllocator : public SpotAllocator {
public:
    explicit NearestSpotAllocator(std::vector<Floor*> floors) : floors(std::move(floors)) {}
    ParkingSpot* allocate(Vehicle* vehicle) override {
        ParkingSpot* best = nullptr;
        for (auto* f : floors) {
            for (auto& s : f->getSpots()) {
                if (!s->canFit(vehicle->getSize())) continue;
                if (!best || static_cast<int>(s->getSize()) < static_cast<int>(best->getSize())) best = s.get();
            }
        }
        return best;
    }
private:
    std::vector<Floor*> floors;
};

// ---------- FeeStrategy (interface) + strategies ----------
class FeeStrategy {
public:
    virtual ~FeeStrategy() = default;
    virtual double calculate(const Ticket& closedTicket) const = 0;
};

class HourlyFeeStrategy : public FeeStrategy {
public:
    explicit HourlyFeeStrategy(double ratePerHour) : ratePerHour(ratePerHour) {}
    double calculate(const Ticket& t) const override {
        long long durationMs = t.getExitTime() - t.getEntryTime();
        double hours = std::max(1.0, std::ceil(durationMs / 3600000.0));
        return hours * ratePerHour;
    }
private:
    double ratePerHour;
};

// Applies a surcharge multiplier if entry happened during peak hours (9-11, 17-19).
class PeakHourFeeStrategy : public FeeStrategy {
public:
    PeakHourFeeStrategy(double ratePerHour, double peakMultiplier)
        : ratePerHour(ratePerHour), peakMultiplier(peakMultiplier) {}
    double calculate(const Ticket& t) const override {
        long long durationMs = t.getExitTime() - t.getEntryTime();
        double hours = std::max(1.0, std::ceil(durationMs / 3600000.0));
        int entryHour = static_cast<int>((t.getEntryTime() / 3600000) % 24);
        bool peak = (entryHour >= 9 && entryHour < 11) || (entryHour >= 17 && entryHour < 19);
        return hours * ratePerHour * (peak ? peakMultiplier : 1.0);
    }
private:
    double ratePerHour;
    double peakMultiplier;
};

// ---------- Exceptions ----------
class NoAvailableSpotException : public std::runtime_error {
public:
    explicit NoAvailableSpotException(const std::string& msg) : std::runtime_error(msg) {}
};
class InvalidTicketException : public std::runtime_error {
public:
    explicit InvalidTicketException(const std::string& msg) : std::runtime_error(msg) {}
};

// ---------- ParkingLot (facade) ----------
class ParkingLot {
public:
    ParkingLot(std::vector<Floor*> floors, std::unique_ptr<SpotAllocator> allocator,
               std::unique_ptr<FeeStrategy> feeStrategy)
        : floors(std::move(floors)), allocator(std::move(allocator)), feeStrategy(std::move(feeStrategy)) {}

    std::unique_ptr<Ticket> parkVehicle(Vehicle* vehicle) {
        // Single lock guarding "decide spot + occupy spot", which spans two separate
        // objects (allocator, spot) and cannot be made atomic by either object alone.
        std::lock_guard<std::mutex> guard(lock);
        ParkingSpot* spot = allocator->allocate(vehicle);
        if (!spot) throw NoAvailableSpotException("No available spot for this vehicle size");
        spot->occupy(vehicle);
        return Ticket::create(vehicle, spot, nowMs());
    }

    double unparkVehicle(Ticket* ticket) {
        std::lock_guard<std::mutex> guard(lock);
        if (ticket->getStatus() != TicketStatus::ACTIVE) throw InvalidTicketException("Ticket not active: " + ticket->getId());
        ticket->close(nowMs());
        double fee = feeStrategy->calculate(*ticket);
        ticket->getSpot()->vacate();
        return fee;
    }

private:
    static long long nowMs() {
        return std::chrono::duration_cast<std::chrono::milliseconds>(
                   std::chrono::system_clock::now().time_since_epoch())
            .count();
    }

    std::vector<Floor*> floors;
    std::unique_ptr<SpotAllocator> allocator;
    std::unique_ptr<FeeStrategy> feeStrategy;
    std::mutex lock;
};

// ---------- Demo ----------
int main() {
    std::vector<std::unique_ptr<ParkingSpot>> f1Spots;
    f1Spots.push_back(std::make_unique<ParkingSpot>("F1-M1", VehicleSize::MOTORCYCLE));
    f1Spots.push_back(std::make_unique<ParkingSpot>("F1-C1", VehicleSize::COMPACT));
    Floor floor1(1, std::move(f1Spots));
    std::vector<Floor*> floors = {&floor1};

    auto allocator = std::make_unique<NearestSpotAllocator>(floors);
    auto feeStrategy = std::make_unique<HourlyFeeStrategy>(10.0);
    ParkingLot lot(floors, std::move(allocator), std::move(feeStrategy));

    Car car("KA-01-1234");
    auto t1 = lot.parkVehicle(&car);
    std::cout << "Parked car, ticket=" << t1->getId() << " spot=" << t1->getSpot()->getId() << "\n";

    Motorcycle bike("KA-01-5678");
    auto t2 = lot.parkVehicle(&bike);
    std::cout << "Parked bike, ticket=" << t2->getId() << " spot=" << t2->getSpot()->getId() << "\n";

    try {
        Bus bus("KA-01-9999");
        lot.parkVehicle(&bus); // no LARGE spot exists -> should fail
    } catch (const NoAvailableSpotException& e) {
        std::cout << "Expected failure parking bus: " << e.what() << "\n";
    }

    double fee = lot.unparkVehicle(t1.get());
    std::cout << "Unparked car, fee=" << fee << "\n";
    return 0;
}

