// Parking Lot - full LLD implementation (single-file demo).
// Difficulty badge includes "Concurrency". JS/TS is single-threaded, so true data races
// can't happen, but the critical section is still modeled explicitly with a tiny async
// mutex so the *design* reflects "allocate+occupy must be atomic" faithfully.

// ---------- Vehicle hierarchy ----------
enum VehicleSize {
  MOTORCYCLE = 0,
  COMPACT = 1,
  LARGE = 2,
}

abstract class Vehicle {
  constructor(protected readonly licensePlate: string) {}
  abstract getSize(): VehicleSize;
  getLicensePlate(): string { return this.licensePlate; }
}

class Motorcycle extends Vehicle {
  getSize(): VehicleSize { return VehicleSize.MOTORCYCLE; }
}

class Car extends Vehicle {
  getSize(): VehicleSize { return VehicleSize.COMPACT; }
}

class Bus extends Vehicle {
  getSize(): VehicleSize { return VehicleSize.LARGE; }
}

// ---------- ParkingSpot ----------
class ParkingSpot {
  private occupied = false;
  private currentVehicle: Vehicle | null = null;

  constructor(private readonly id: string, private readonly size: VehicleSize) {}

  getId(): string { return this.id; }
  getSize(): VehicleSize { return this.size; }
  isOccupied(): boolean { return this.occupied; }

  // A larger spot can host a smaller vehicle; VehicleSize is ordered smallest-to-largest.
  canFit(vehicleSize: VehicleSize): boolean {
    return !this.occupied && this.size >= vehicleSize;
  }

  occupy(vehicle: Vehicle): void {
    if (this.occupied) throw new Error(`Spot ${this.id} already occupied`);
    this.occupied = true;
    this.currentVehicle = vehicle;
  }

  vacate(): void {
    this.occupied = false;
    this.currentVehicle = null;
  }
}

// ---------- Floor ----------
class Floor {
  constructor(private readonly floorNumber: number, private readonly spots: ParkingSpot[]) {}

  getFloorNumber(): number { return this.floorNumber; }
  getSpots(): ParkingSpot[] { return this.spots; }

  // First compatible free spot on this floor, or null if none.
  findAvailableSpot(size: VehicleSize): ParkingSpot | null {
    for (const s of this.spots) {
      if (s.canFit(size)) return s;
    }
    return null;
  }
}

// ---------- Ticket ----------
enum TicketStatus { ACTIVE = "ACTIVE", CLOSED = "CLOSED" }

let ticketSeq = 1;
class Ticket {
  readonly id: string;
  exitTime: number | null = null;
  status: TicketStatus = TicketStatus.ACTIVE;

  private constructor(
    readonly vehicle: Vehicle,
    readonly spot: ParkingSpot,
    readonly entryTime: number
  ) {
    this.id = `T-${ticketSeq++}`;
  }

  static create(vehicle: Vehicle, spot: ParkingSpot, entryTime: number): Ticket {
    return new Ticket(vehicle, spot, entryTime);
  }

  close(exitTime: number): void {
    this.exitTime = exitTime;
    this.status = TicketStatus.CLOSED;
  }
}

// ---------- SpotAllocator (interface) + strategies ----------
interface SpotAllocator {
  allocate(vehicle: Vehicle): ParkingSpot | null;
}

// Picks the first free compatible spot, scanning floors in order.
class FirstAvailableAllocator implements SpotAllocator {
  constructor(private readonly floors: Floor[]) {}
  allocate(vehicle: Vehicle): ParkingSpot | null {
    for (const f of this.floors) {
      const spot = f.findAvailableSpot(vehicle.getSize());
      if (spot) return spot;
    }
    return null;
  }
}

// Picks the compatible spot whose size is the closest fit (least wasted space).
class NearestSpotAllocator implements SpotAllocator {
  constructor(private readonly floors: Floor[]) {}
  allocate(vehicle: Vehicle): ParkingSpot | null {
    let best: ParkingSpot | null = null;
    for (const f of this.floors) {
      for (const s of f.getSpots()) {
        if (!s.canFit(vehicle.getSize())) continue;
        if (!best || s.getSize() < best.getSize()) best = s;
      }
    }
    return best;
  }
}

// ---------- FeeStrategy (interface) + strategies ----------
interface FeeStrategy {
  calculate(closedTicket: Ticket): number;
}

class HourlyFeeStrategy implements FeeStrategy {
  constructor(private readonly ratePerHour: number) {}
  calculate(t: Ticket): number {
    const durationMs = (t.exitTime ?? 0) - t.entryTime;
    const hours = Math.max(1, Math.ceil(durationMs / 3600000));
    return hours * this.ratePerHour;
  }
}

// Applies a surcharge multiplier if entry happened during peak hours (9-11, 17-19).
class PeakHourFeeStrategy implements FeeStrategy {
  constructor(private readonly ratePerHour: number, private readonly peakMultiplier: number) {}
  calculate(t: Ticket): number {
    const durationMs = (t.exitTime ?? 0) - t.entryTime;
    const hours = Math.max(1, Math.ceil(durationMs / 3600000));
    const entryHour = Math.floor(t.entryTime / 3600000) % 24;
    const peak = (entryHour >= 9 && entryHour < 11) || (entryHour >= 17 && entryHour < 19);
    return hours * this.ratePerHour * (peak ? this.peakMultiplier : 1);
  }
}

// ---------- Errors ----------
class NoAvailableSpotException extends Error {}
class InvalidTicketException extends Error {}

// ---------- Tiny async mutex (see file header for why) ----------
class Mutex {
  private locked = false;
  private waiters: Array<() => void> = [];

  async acquire(): Promise<void> {
    if (!this.locked) { this.locked = true; return; }
    await new Promise<void>((resolve) => this.waiters.push(resolve));
    this.locked = true;
  }

  release(): void {
    this.locked = false;
    const next = this.waiters.shift();
    if (next) next();
  }
}

// ---------- ParkingLot (facade) ----------
class ParkingLot {
  private readonly lock = new Mutex();

  constructor(
    private readonly floors: Floor[],
    private readonly allocator: SpotAllocator,   // injected interface, not a concrete class
    private readonly feeStrategy: FeeStrategy     // injected interface, not a concrete class
  ) {}

  async parkVehicle(vehicle: Vehicle): Promise<Ticket> {
    await this.lock.acquire();
    try {
      const spot = this.allocator.allocate(vehicle);
      if (!spot) throw new NoAvailableSpotException(`No available spot for vehicle size ${vehicle.getSize()}`);
      spot.occupy(vehicle);
      return Ticket.create(vehicle, spot, Date.now());
    } finally {
      this.lock.release();
    }
  }

  async unparkVehicle(ticket: Ticket): Promise<number> {
    await this.lock.acquire();
    try {
      if (ticket.status !== TicketStatus.ACTIVE) throw new InvalidTicketException(`Ticket not active: ${ticket.id}`);
      ticket.close(Date.now());
      const fee = this.feeStrategy.calculate(ticket);
      ticket.spot.vacate();
      return fee;
    } finally {
      this.lock.release();
    }
  }
}

// ---------- Demo ----------
async function main(): Promise<void> {
  const f1Spots: ParkingSpot[] = [
    new ParkingSpot("F1-M1", VehicleSize.MOTORCYCLE),
    new ParkingSpot("F1-C1", VehicleSize.COMPACT),
  ];
  const floor1 = new Floor(1, f1Spots);
  const floors: Floor[] = [floor1];

  const allocator: SpotAllocator = new NearestSpotAllocator(floors);
  const feeStrategy: FeeStrategy = new HourlyFeeStrategy(10.0);
  const lot = new ParkingLot(floors, allocator, feeStrategy);

  const car = new Car("KA-01-1234");
  const t1 = await lot.parkVehicle(car);
  console.log(`Parked car, ticket=${t1.id} spot=${t1.spot.getId()}`);

  const bike = new Motorcycle("KA-01-5678");
  const t2 = await lot.parkVehicle(bike);
  console.log(`Parked bike, ticket=${t2.id} spot=${t2.spot.getId()}`);

  try {
    const bus = new Bus("KA-01-9999");
    await lot.parkVehicle(bus); // no LARGE spot exists -> should fail
  } catch (e) {
    console.log(`Expected failure parking bus: ${(e as Error).message}`);
  }

  const fee = await lot.unparkVehicle(t1);
  console.log(`Unparked car, fee=${fee}`);
}

main();

export {
  VehicleSize, Vehicle, Motorcycle, Car, Bus, ParkingSpot, Floor, Ticket, TicketStatus,
  SpotAllocator, FirstAvailableAllocator, NearestSpotAllocator,
  FeeStrategy, HourlyFeeStrategy, PeakHourFeeStrategy,
  NoAvailableSpotException, InvalidTicketException, ParkingLot,
};

