            this.remaining = remaining;
            this.retryAfterMs = retryAfterMs;
        }

        static RateLimitResult allow(long remaining) { return new RateLimitResult(true, remaining, 0); }
        static RateLimitResult deny(long retryAfterMs) { return new RateLimitResult(false, 0, retryAfterMs); }

        public String toString() {
            return "RateLimitResult{allowed=" + allowed + ", remaining=" + remaining + ", retryAfterMs=" + retryAfterMs + "}";
        }
    }

    // ---------- RateLimitConfig (pure data) ----------
    enum AlgorithmType { TOKEN_BUCKET, SLIDING_WINDOW, FIXED_WINDOW }

    static class RateLimitConfig {
        final long capacity;      // max tokens / max requests per window
        final long windowMs;      // window size in ms (or refill window for token bucket)
        final AlgorithmType algorithmType;

        RateLimitConfig(long capacity, long windowMs, AlgorithmType algorithmType) {
            this.capacity = capacity;
            this.windowMs = windowMs;
            this.algorithmType = algorithmType;
        }
    }

    // ---------- RateLimitAlgorithm (interface) ----------
    interface RateLimitAlgorithm {
        RateLimitResult allowRequest(String clientKey, long nowMs);
    }

    // Each algorithm owns its own per-client state map, since the state shape genuinely
    // differs (a counter vs. a timestamp deque vs. two rolling counters) - forcing a shared
    // generic "Bucket" class would either bloat it or leak abstraction.
    static class TokenBucketLimiter implements RateLimitAlgorithm {
        private static class Bucket {
            double tokens;
            long lastRefillTime;
        }

        private final long capacity;
        private final double refillRatePerMs; // tokens added per millisecond
        private final Map<String, Bucket> buckets = new HashMap<>();

        TokenBucketLimiter(RateLimitConfig config) {
            this.capacity = config.capacity;
            this.refillRatePerMs = (double) config.capacity / config.windowMs;
        }

        public RateLimitResult allowRequest(String clientKey, long nowMs) {
            Bucket bucket = buckets.computeIfAbsent(clientKey, k -> {
                Bucket b = new Bucket();
                b.tokens = capacity;
                b.lastRefillTime = nowMs;
                return b;
            });
            long elapsed = nowMs - bucket.lastRefillTime;
            bucket.tokens = Math.min(capacity, bucket.tokens + elapsed * refillRatePerMs);
            bucket.lastRefillTime = nowMs;
            if (bucket.tokens >= 1) {
                bucket.tokens -= 1;
                return RateLimitResult.allow((long) Math.floor(bucket.tokens));
            }
            double deficit = 1 - bucket.tokens;
            long retryAfterMs = (long) Math.ceil(deficit / refillRatePerMs);
            return RateLimitResult.deny(retryAfterMs);
        }
    }

    // Sliding window: keeps an exact deque of recent request timestamps per client and
    // counts how many fall within the last windowMs - more accurate than fixed window at
    // the cost of memory proportional to request rate.
    static class SlidingWindowLimiter implements RateLimitAlgorithm {
        private final long capacity;
        private final long windowMs;
        private final Map<String, Deque<Long>> history = new HashMap<>();

        SlidingWindowLimiter(RateLimitConfig config) {
            this.capacity = config.capacity;
            this.windowMs = config.windowMs;
        }

        public RateLimitResult allowRequest(String clientKey, long nowMs) {
            Deque<Long> timestamps = history.computeIfAbsent(clientKey, k -> new ArrayDeque<>());
            long windowStart = nowMs - windowMs;
            while (!timestamps.isEmpty() && timestamps.peekFirst() <= windowStart) {
                timestamps.pollFirst();
            }
            if (timestamps.size() < capacity) {
                timestamps.addLast(nowMs);
                return RateLimitResult.allow(capacity - timestamps.size());
            }
            long retryAfterMs = timestamps.peekFirst() + windowMs - nowMs;
            return RateLimitResult.deny(Math.max(0, retryAfterMs));
        }
    }

    // Fixed window: counts requests in discrete, non-overlapping windows - cheap (one
    // counter per client) but allows bursts at window boundaries.
    static class FixedWindowLimiter implements RateLimitAlgorithm {
        private static class WindowCounter {
            long windowStart;
            long count;
        }

        private final long capacity;
        private final long windowMs;
        private final Map<String, WindowCounter> counters = new HashMap<>();

        FixedWindowLimiter(RateLimitConfig config) {
            this.capacity = config.capacity;
            this.windowMs = config.windowMs;
        }

        public RateLimitResult allowRequest(String clientKey, long nowMs) {
            WindowCounter counter = counters.computeIfAbsent(clientKey, k -> {
                WindowCounter c = new WindowCounter();
                c.windowStart = nowMs;
                c.count = 0;
                return c;
            });
            if (nowMs - counter.windowStart >= windowMs) {
                counter.windowStart = nowMs;
                counter.count = 0;
            }
            if (counter.count < capacity) {
                counter.count++;
                return RateLimitResult.allow(capacity - counter.count);
            }
            long retryAfterMs = counter.windowStart + windowMs - nowMs;
            return RateLimitResult.deny(Math.max(0, retryAfterMs));
        }
    }

