    // algorithms themselves so that mapping logic has exactly one home.
    static class RateLimiterFactory {
        private final Map<String, RateLimitConfig> configsByEndpoint;
        private final Map<String, RateLimitAlgorithm> instancesByEndpoint = new HashMap<>();

        RateLimiterFactory(Map<String, RateLimitConfig> configsByEndpoint) {
            this.configsByEndpoint = configsByEndpoint;
        }

        RateLimitAlgorithm getLimiter(String endpoint) {
            return instancesByEndpoint.computeIfAbsent(endpoint, ep -> {
                RateLimitConfig config = configsByEndpoint.get(ep);
                if (config == null) throw new IllegalArgumentException("No config for endpoint: " + ep);
                switch (config.algorithmType) {
                    case TOKEN_BUCKET: return new TokenBucketLimiter(config);
                    case SLIDING_WINDOW: return new SlidingWindowLimiter(config);
                    case FIXED_WINDOW: return new FixedWindowLimiter(config);
                    default: throw new IllegalStateException("Unknown algorithm type");
                }
            });
        }
    }

    // ---------- RateLimiter (facade) ----------
    static class RateLimiter {
        private final RateLimiterFactory factory; // injected interface-like dependency

        RateLimiter(RateLimiterFactory factory) {
            this.factory = factory;
        }

        RateLimitResult check(String clientId, String endpoint, long nowMs) {
            RateLimitAlgorithm algorithm = factory.getLimiter(endpoint);
            String clientKey = endpoint + ":" + clientId; // scope quota per endpoint+client
            return algorithm.allowRequest(clientKey, nowMs);
        }
    }

    // ---------- Demo ----------
    public static void main(String[] args) {
        Map<String, RateLimitConfig> configs = new HashMap<>();
        configs.put("/api/login", new RateLimitConfig(3, 1000, AlgorithmType.TOKEN_BUCKET));
        configs.put("/api/search", new RateLimitConfig(2, 1000, AlgorithmType.FIXED_WINDOW));

        RateLimiterFactory factory = new RateLimiterFactory(configs);
        RateLimiter limiter = new RateLimiter(factory);

