// though a production system would eventually need per-key locking or a distributed store.
#include <iostream>
#include <unordered_map>
#include <deque>
#include <string>
#include <memory>
#include <cmath>
#include <stdexcept>

// ---------- RateLimitResult (pure data) ----------
struct RateLimitResult {
    bool allowed;
    long long remaining;
    long long retryAfterMs; // 0 if allowed

    static RateLimitResult allow(long long remaining) { return {true, remaining, 0}; }
    static RateLimitResult deny(long long retryAfterMs) { return {false, 0, retryAfterMs}; }
};

std::ostream& operator<<(std::ostream& os, const RateLimitResult& r) {
    os << "RateLimitResult{allowed=" << (r.allowed ? "true" : "false")
       << ", remaining=" << r.remaining << ", retryAfterMs=" << r.retryAfterMs << "}";
    return os;
}

// ---------- RateLimitConfig (pure data) ----------
enum class AlgorithmType { TOKEN_BUCKET, SLIDING_WINDOW, FIXED_WINDOW };

struct RateLimitConfig {
    long long capacity;   // max tokens / max requests per window
    long long windowMs;   // window size in ms (or refill window for token bucket)
    AlgorithmType algorithmType;
};

// ---------- RateLimitAlgorithm (interface) ----------
class RateLimitAlgorithm {
public:
    virtual ~RateLimitAlgorithm() = default;
    virtual RateLimitResult allowRequest(const std::string& clientKey, long long nowMs) = 0;
};

// Each algorithm owns its own per-client state map, since the state shape genuinely
// differs (a counter vs. a timestamp deque vs. two rolling counters) - forcing a shared
// generic "Bucket" class would either bloat it or leak abstraction.
class TokenBucketLimiter : public RateLimitAlgorithm {
public:
    explicit TokenBucketLimiter(const RateLimitConfig& config)
        : capacity(config.capacity), refillRatePerMs(static_cast<double>(config.capacity) / config.windowMs) {}

    RateLimitResult allowRequest(const std::string& clientKey, long long nowMs) override {
        Bucket& bucket = buckets[clientKey];
        if (!bucket.initialized) {
            bucket.tokens = static_cast<double>(capacity);
            bucket.lastRefillTime = nowMs;
            bucket.initialized = true;
        }
        long long elapsed = nowMs - bucket.lastRefillTime;
        bucket.tokens = std::min(static_cast<double>(capacity), bucket.tokens + elapsed * refillRatePerMs);
        bucket.lastRefillTime = nowMs;
        if (bucket.tokens >= 1.0) {
            bucket.tokens -= 1.0;
            return RateLimitResult::allow(static_cast<long long>(std::floor(bucket.tokens)));
        }
        double deficit = 1.0 - bucket.tokens;
        long long retryAfterMs = static_cast<long long>(std::ceil(deficit / refillRatePerMs));
        return RateLimitResult::deny(retryAfterMs);
    }

private:
    struct Bucket {
        double tokens = 0;
        long long lastRefillTime = 0;
        bool initialized = false;
    };
    long long capacity;
    double refillRatePerMs;
    std::unordered_map<std::string, Bucket> buckets;
};

// Sliding window: keeps an exact deque of recent request timestamps per client and
// counts how many fall within the last windowMs - more accurate than fixed window at
// the cost of memory proportional to request rate.
class SlidingWindowLimiter : public RateLimitAlgorithm {
public:
    explicit SlidingWindowLimiter(const RateLimitConfig& config)
        : capacity(config.capacity), windowMs(config.windowMs) {}

    RateLimitResult allowRequest(const std::string& clientKey, long long nowMs) override {
        std::deque<long long>& timestamps = history[clientKey];
        long long windowStart = nowMs - windowMs;
        while (!timestamps.empty() && timestamps.front() <= windowStart) {
            timestamps.pop_front();
        }
        if (static_cast<long long>(timestamps.size()) < capacity) {
            timestamps.push_back(nowMs);
            return RateLimitResult::allow(capacity - static_cast<long long>(timestamps.size()));
        }
        long long retryAfterMs = timestamps.front() + windowMs - nowMs;
        return RateLimitResult::deny(std::max<long long>(0, retryAfterMs));
    }

private:
    long long capacity;
    long long windowMs;
    std::unordered_map<std::string, std::deque<long long>> history;
};

// Fixed window: counts requests in discrete, non-overlapping windows - cheap (one
// counter per client) but allows bursts at window boundaries.
class FixedWindowLimiter : public RateLimitAlgorithm {
public:
    explicit FixedWindowLimiter(const RateLimitConfig& config)
        : capacity(config.capacity), windowMs(config.windowMs) {}

    RateLimitResult allowRequest(const std::string& clientKey, long long nowMs) override {
        WindowCounter& counter = counters[clientKey];
        if (!counter.initialized) {
            counter.windowStart = nowMs;
            counter.count = 0;
            counter.initialized = true;
        }
        if (nowMs - counter.windowStart >= windowMs) {
            counter.windowStart = nowMs;
            counter.count = 0;
        }
        if (counter.count < capacity) {
            counter.count++;
            return RateLimitResult::allow(capacity - counter.count);
        }
        long long retryAfterMs = counter.windowStart + windowMs - nowMs;
        return RateLimitResult::deny(std::max<long long>(0, retryAfterMs));
    }

private:
    struct WindowCounter {
        long long windowStart = 0;
        long long count = 0;
        bool initialized = false;
    };
    long long capacity;
    long long windowMs;
    std::unordered_map<std::string, WindowCounter> counters;
};

// ---------- RateLimiterFactory ----------
// Resolves "which algorithm for which endpoint" - kept out of both the facade and the
// algorithms themselves so that mapping logic has exactly one home.
class RateLimiterFactory {
public:
    explicit RateLimiterFactory(std::unordered_map<std::string, RateLimitConfig> configsByEndpoint)
        : configsByEndpoint(std::move(configsByEndpoint)) {}

    RateLimitAlgorithm* getLimiter(const std::string& endpoint) {
        auto it = instancesByEndpoint.find(endpoint);
        if (it != instancesByEndpoint.end()) return it->second.get();

        auto configIt = configsByEndpoint.find(endpoint);
        if (configIt == configsByEndpoint.end()) throw std::invalid_argument("No config for endpoint: " + endpoint);
        const RateLimitConfig& config = configIt->second;

        std::unique_ptr<RateLimitAlgorithm> algorithm;
        switch (config.algorithmType) {
            case AlgorithmType::TOKEN_BUCKET: algorithm = std::make_unique<TokenBucketLimiter>(config); break;
            case AlgorithmType::SLIDING_WINDOW: algorithm = std::make_unique<SlidingWindowLimiter>(config); break;
            case AlgorithmType::FIXED_WINDOW: algorithm = std::make_unique<FixedWindowLimiter>(config); break;
        }
        RateLimitAlgorithm* raw = algorithm.get();
        instancesByEndpoint[endpoint] = std::move(algorithm);
        return raw;
    }

private:
    std::unordered_map<std::string, RateLimitConfig> configsByEndpoint;
    std::unordered_map<std::string, std::unique_ptr<RateLimitAlgorithm>> instancesByEndpoint;
};

// ---------- RateLimiter (facade) ----------
class RateLimiter {
public:
    explicit RateLimiter(RateLimiterFactory* factory) : factory(factory) {}

    RateLimitResult check(const std::string& clientId, const std::string& endpoint, long long nowMs) {
        RateLimitAlgorithm* algorithm = factory->getLimiter(endpoint);
        std::string clientKey = endpoint + ":" + clientId; // scope quota per endpoint+client
        return algorithm->allowRequest(clientKey, nowMs);
    }

private:
    RateLimiterFactory* factory; // injected dependency, not owned
};

// ---------- Demo ----------
int main() {
    std::unordered_map<std::string, RateLimitConfig> configs;
    configs["/api/login"] = {3, 1000, AlgorithmType::TOKEN_BUCKET};
    configs["/api/search"] = {2, 1000, AlgorithmType::FIXED_WINDOW};

    RateLimiterFactory factory(configs);
    RateLimiter limiter(&factory);

    long long t = 0;
    for (int i = 0; i < 5; i++) {
        RateLimitResult result = limiter.check("clientA", "/api/login", t);
        std::cout << "t=" << t << " login attempt " << (i + 1) << " -> " << result << "\n";
        t += 100; // 100ms between requests, faster than refill can keep up
    }

    std::cout << "\n";
    long long t2 = 0;
    for (int i = 0; i < 3; i++) {
        RateLimitResult result = limiter.check("clientB", "/api/search", t2);
        std::cout << "t=" << t2 << " search attempt " << (i + 1) << " -> " << result << "\n";
    }
    return 0;
}

