// Rate Limiter - full LLD implementation (single-file demo).
// Difficulty badge is "Intermediate -> Advanced+Distributed" - it does NOT explicitly say
// "Concurrency", so per convention this stays single-threaded/simple (no locks), even
// though a production system would eventually need per-key locking or a distributed store.

// ---------- RateLimitResult (pure data) ----------
class RateLimitResult {
  constructor(allowed, remaining, retryAfterMs) {
    this.allowed = allowed;
    this.remaining = remaining;
    this.retryAfterMs = retryAfterMs; // 0 if allowed
  }
  static allow(remaining) { return new RateLimitResult(true, remaining, 0); }
  static deny(retryAfterMs) { return new RateLimitResult(false, 0, retryAfterMs); }
}

// ---------- RateLimitConfig (pure data) ----------
const AlgorithmType = { TOKEN_BUCKET: "TOKEN_BUCKET", SLIDING_WINDOW: "SLIDING_WINDOW", FIXED_WINDOW: "FIXED_WINDOW" };

class RateLimitConfig {
  constructor(capacity, windowMs, algorithmType) {
    this.capacity = capacity;   // max tokens / max requests per window
    this.windowMs = windowMs;   // window size in ms (or refill window for token bucket)
    this.algorithmType = algorithmType;
  }
}

// ---------- RateLimitAlgorithm (interface) ----------
class RateLimitAlgorithm {
  allowRequest(_clientKey, _nowMs) {
    throw new Error("allowRequest() must be implemented");
  }
}

// Each algorithm owns its own per-client state map, since the state shape genuinely
// differs (a counter vs. a timestamp deque vs. two rolling counters) - forcing a shared
// generic "Bucket" class would either bloat it or leak abstraction.
class TokenBucketLimiter extends RateLimitAlgorithm {
  constructor(config) {
    super();
    this.capacity = config.capacity;
    this.refillRatePerMs = config.capacity / config.windowMs; // tokens added per ms
    this.buckets = new Map(); // clientKey -> { tokens, lastRefillTime }
  }

  allowRequest(clientKey, nowMs) {
    let bucket = this.buckets.get(clientKey);
    if (!bucket) {
      bucket = { tokens: this.capacity, lastRefillTime: nowMs };
      this.buckets.set(clientKey, bucket);
    }
    const elapsed = nowMs - bucket.lastRefillTime;
    bucket.tokens = Math.min(this.capacity, bucket.tokens + elapsed * this.refillRatePerMs);
    bucket.lastRefillTime = nowMs;
    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return RateLimitResult.allow(Math.floor(bucket.tokens));
    }
    const deficit = 1 - bucket.tokens;
    const retryAfterMs = Math.ceil(deficit / this.refillRatePerMs);
    return RateLimitResult.deny(retryAfterMs);
  }
}

// Sliding window: keeps an exact queue of recent request timestamps per client and
// counts how many fall within the last windowMs - more accurate than fixed window at
// the cost of memory proportional to request rate.
class SlidingWindowLimiter extends RateLimitAlgorithm {
  constructor(config) {
    super();
    this.capacity = config.capacity;
    this.windowMs = config.windowMs;
    this.history = new Map(); // clientKey -> array of timestamps (oldest first)
  }

  allowRequest(clientKey, nowMs) {
    let timestamps = this.history.get(clientKey);
    if (!timestamps) { timestamps = []; this.history.set(clientKey, timestamps); }
    const windowStart = nowMs - this.windowMs;
    while (timestamps.length > 0 && timestamps[0] <= windowStart) {
      timestamps.shift();
    }
    if (timestamps.length < this.capacity) {
      timestamps.push(nowMs);
      return RateLimitResult.allow(this.capacity - timestamps.length);
    }
    const retryAfterMs = timestamps[0] + this.windowMs - nowMs;
    return RateLimitResult.deny(Math.max(0, retryAfterMs));
  }
}

// Fixed window: counts requests in discrete, non-overlapping windows - cheap (one
// counter per client) but allows bursts at window boundaries.
class FixedWindowLimiter extends RateLimitAlgorithm {
  constructor(config) {
    super();
    this.capacity = config.capacity;
    this.windowMs = config.windowMs;
    this.counters = new Map(); // clientKey -> { windowStart, count }
  }

  allowRequest(clientKey, nowMs) {
    let counter = this.counters.get(clientKey);
    if (!counter) {
      counter = { windowStart: nowMs, count: 0 };
      this.counters.set(clientKey, counter);
    }
    if (nowMs - counter.windowStart >= this.windowMs) {
      counter.windowStart = nowMs;
      counter.count = 0;
    }
    if (counter.count < this.capacity) {
      counter.count += 1;
      return RateLimitResult.allow(this.capacity - counter.count);
    }
    const retryAfterMs = counter.windowStart + this.windowMs - nowMs;
    return RateLimitResult.deny(Math.max(0, retryAfterMs));
  }
}

// ---------- RateLimiterFactory ----------
// Resolves "which algorithm for which endpoint" - kept out of both the facade and the
// algorithms themselves so that mapping logic has exactly one home.
class RateLimiterFactory {
  constructor(configsByEndpoint) {
    this.configsByEndpoint = configsByEndpoint; // Map<endpoint, RateLimitConfig>
    this.instancesByEndpoint = new Map();
  }

  getLimiter(endpoint) {
    let instance = this.instancesByEndpoint.get(endpoint);
    if (instance) return instance;

    const config = this.configsByEndpoint.get(endpoint);
    if (!config) throw new Error(`No config for endpoint: ${endpoint}`);

    switch (config.algorithmType) {
      case AlgorithmType.TOKEN_BUCKET: instance = new TokenBucketLimiter(config); break;
      case AlgorithmType.SLIDING_WINDOW: instance = new SlidingWindowLimiter(config); break;
      case AlgorithmType.FIXED_WINDOW: instance = new FixedWindowLimiter(config); break;
      default: throw new Error("Unknown algorithm type");
    }
    this.instancesByEndpoint.set(endpoint, instance);
    return instance;
  }
}

// ---------- RateLimiter (facade) ----------
class RateLimiter {
  constructor(factory) {
    this.factory = factory; // injected dependency
  }

  check(clientId, endpoint, nowMs) {
    const algorithm = this.factory.getLimiter(endpoint);
    const clientKey = `${endpoint}:${clientId}`; // scope quota per endpoint+client
    return algorithm.allowRequest(clientKey, nowMs);
  }
}

// ---------- Demo ----------
function main() {
  const configs = new Map([
    ["/api/login", new RateLimitConfig(3, 1000, AlgorithmType.TOKEN_BUCKET)],
    ["/api/search", new RateLimitConfig(2, 1000, AlgorithmType.FIXED_WINDOW)],
  ]);

  const factory = new RateLimiterFactory(configs);
  const limiter = new RateLimiter(factory);

  let t = 0;
  for (let i = 0; i < 5; i++) {
    const result = limiter.check("clientA", "/api/login", t);
    console.log(`t=${t} login attempt ${i + 1} ->`, result);
    t += 100; // 100ms between requests, faster than refill can keep up
  }

  console.log();
  let t2 = 0;
  for (let i = 0; i < 3; i++) {
    const result = limiter.check("clientB", "/api/search", t2);
    console.log(`t=${t2} search attempt ${i + 1} ->`, result);
  }
}

if (require.main === module) {
  main();
}

module.exports = {
  RateLimitResult, RateLimitConfig, AlgorithmType, RateLimitAlgorithm,
  TokenBucketLimiter, SlidingWindowLimiter, FixedWindowLimiter,
  RateLimiterFactory, RateLimiter,
};

