// Splitwise (Expense Sharing) — full LLD implementation with demo.
// Single-file Java translation of the Mermaid class diagram in section J.
import java.util.*;

public class p4 {

    // ---------- Value objects ----------

    /** Fixed-point money (cents) to avoid floating point drift in splits/settlements. */
    static final class Money implements Comparable<Money> {
        final long cents;
        private Money(long cents) { this.cents = cents; }
        static Money ofCents(long cents) { return new Money(cents); }
        static Money of(double dollars) { return new Money(Math.round(dollars * 100)); }
        static Money zero() { return new Money(0); }
        Money plus(Money o) { return new Money(this.cents + o.cents); }
        Money minus(Money o) { return new Money(this.cents - o.cents); }
        Money negate() { return new Money(-this.cents); }
        boolean isZero() { return cents == 0; }
        public int compareTo(Money o) { return Long.compare(this.cents, o.cents); }
        public String toString() { return String.format("$%.2f", cents / 100.0); }
        public boolean equals(Object o) { return o instanceof Money && ((Money) o).cents == cents; }
        public int hashCode() { return Long.hashCode(cents); }
    }

    enum SplitType { EQUAL, EXACT, PERCENT }

    // ---------- Core entities ----------

    static final class User {
        final String id, name, email;
        User(String id, String name, String email) { this.id = id; this.name = name; this.email = email; }
        public String toString() { return name; }
    }

    /** Aggregation: Group holds Users but does not own their lifecycle. */
    static final class Group {
        final String id;
        final List<User> members = new ArrayList<>();
        Group(String id) { this.id = id; }
        void addMember(User u) { members.add(u); }
    }

    /** Pure data: how much one participant owes for one expense. No computation. */
    static final class Split {
        final User user;
        final Money amount;
        Split(User user, Money amount) { this.user = user; this.amount = amount; }
    }

    /** Immutable record of one shared-cost event. Composes its Splits. */
    static final class Expense {
        final String id;
        final Money amount;
        final User paidBy;
        final List<Split> splits; // composition — splits have no meaning outside this expense
        final String groupId; // nullable
        final long timestamp;
        Expense(String id, Money amount, User paidBy, List<Split> splits, String groupId) {
            this.id = id; this.amount = amount; this.paidBy = paidBy;
            this.splits = List.copyOf(splits); this.groupId = groupId;
            this.timestamp = System.currentTimeMillis();
        }
    }

    /** Records a settle-up action. Sibling of Expense, not a subclass (see section I). */
    static final class Payment {
        final String id;
        final User from, to;
        final Money amount;
        final long timestamp;
        Payment(String id, User from, User to, Money amount) {
            this.id = id; this.from = from; this.to = to; this.amount = amount;
            this.timestamp = System.currentTimeMillis();
        }
    }

    // ---------- SplitStrategy hierarchy ----------

    interface SplitStrategy {
        List<Split> compute(Money total, List<User> participants, Map<String, Object> params);
    }

    static final class EqualSplitStrategy implements SplitStrategy {
        public List<Split> compute(Money total, List<User> participants, Map<String, Object> params) {
            int n = participants.size();
            long base = total.cents / n;
            long remainder = total.cents % n; // distribute leftover cents deterministically
            List<Split> splits = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                long cents = base + (i < remainder ? 1 : 0);
                splits.add(new Split(participants.get(i), Money.ofCents(cents)));
            }
            return splits;
        }
    }

    @SuppressWarnings("unchecked")
    static final class ExactSplitStrategy implements SplitStrategy {
        public List<Split> compute(Money total, List<User> participants, Map<String, Object> params) {
            Map<String, Money> amounts = (Map<String, Money>) params.get("amounts"); // userId -> exact amount
            List<Split> splits = new ArrayList<>();
            for (User u : participants) {
                Money amt = amounts.get(u.id);
                if (amt == null) throw new IllegalArgumentException("Missing exact amount for " + u.id);
                splits.add(new Split(u, amt));
            }
            return splits;
        }
    }

    @SuppressWarnings("unchecked")
    static final class PercentSplitStrategy implements SplitStrategy {
        public List<Split> compute(Money total, List<User> participants, Map<String, Object> params) {
            Map<String, Double> pct = (Map<String, Double>) params.get("percentages"); // userId -> % (sums to 100)
            List<Split> splits = new ArrayList<>();
            long allocated = 0;
            for (int i = 0; i < participants.size(); i++) {
                User u = participants.get(i);
                Double p = pct.get(u.id);
                if (p == null) throw new IllegalArgumentException("Missing percentage for " + u.id);
                long cents = (i == participants.size() - 1)
                        ? total.cents - allocated // last participant absorbs rounding remainder
                        : Math.round(total.cents * (p / 100.0));
                allocated += cents;
                splits.add(new Split(u, Money.ofCents(cents)));
            }
            return splits;
        }
    }

    // ---------- BalanceSheet ----------

    /** Single source of truth for who-owes-whom. Stores one signed net cents value per unordered pair. */
    static final class BalanceSheet {
        // key: "idA|idB" with idA < idB lexicographically; value > 0 means idA owes idB.
        private final Map<String, Long> pairwise = new HashMap<>();

        private String key(User a, User b) {
            return a.id.compareTo(b.id) < 0 ? a.id + "|" + b.id : b.id + "|" + a.id;
        }

        /** a owes b `amount` more (amount may be negative to reduce/reverse). */
        void adjust(User a, User b, Money amount) {
            String k = key(a, b);
            long signed = a.id.compareTo(b.id) < 0 ? amount.cents : -amount.cents;
            pairwise.merge(k, signed, Long::sum);
        }

        /** Positive => a owes b; negative => b owes a. */
        Money getBalance(User a, User b) {
            String k = key(a, b);
            long stored = pairwise.getOrDefault(k, 0L);
            long fromAPerspective = a.id.compareTo(b.id) < 0 ? stored : -stored;
            return Money.ofCents(fromAPerspective);
        }
    }

    // ---------- Idempotent payment log ----------

    static final class PaymentLog {
        private final Map<String, Payment> byKey = new HashMap<>();
        boolean seen(String idemKey) { return byKey.containsKey(idemKey); }
        Payment get(String idemKey) { return byKey.get(idemKey); }
        void record(String idemKey, Payment p) { byKey.put(idemKey, p); }
    }

    // ---------- ExpenseService (facade) ----------

    static final class ExpenseService {
        private final Map<SplitType, SplitStrategy> strategyFactory;
        private final BalanceSheet balanceSheet = new BalanceSheet();
        private final PaymentLog paymentLog = new PaymentLog();
        private final List<Expense> expenses = new ArrayList<>();
        private int expenseCounter = 0, paymentCounter = 0;

        ExpenseService(Map<SplitType, SplitStrategy> strategyFactory) {
            this.strategyFactory = strategyFactory;
        }

        Expense addExpense(Money total, User paidBy, List<User> participants,
                            SplitType type, Map<String, Object> params, Group group) {
            SplitStrategy strategy = strategyFactory.get(type);
            List<Split> splits = strategy.compute(total, participants, params);

            long sum = 0;
            for (Split s : splits) sum += s.amount.cents;
            if (sum != total.cents) throw new IllegalStateException("Split strategy produced mismatched total");

            Expense expense = new Expense("EXP-" + (++expenseCounter), total, paidBy, splits,
                    group != null ? group.id : null);
            for (Split s : splits) {
                if (!s.user.id.equals(paidBy.id)) {
                    balanceSheet.adjust(s.user, paidBy, s.amount); // s.user owes paidBy s.amount
                }
            }
            expenses.add(expense);
            return expense;
        }

        Payment settleUp(User from, User to, Money amount, String idempotencyKey) {
            if (paymentLog.seen(idempotencyKey)) return paymentLog.get(idempotencyKey); // idempotent replay
            balanceSheet.adjust(from, to, amount.negate()); // paying down reduces what `from` owes `to`
            Payment payment = new Payment("PAY-" + (++paymentCounter), from, to, amount);
            paymentLog.record(idempotencyKey, payment);
            return payment;
        }

        Money getBalance(User a, User b) { return balanceSheet.getBalance(a, b); }

        /** net(u) = sum over others of (-balance(u, other)); positive => u is owed money overall. */
        Map<User, Money> getNetBalances(Group group) {
            Map<User, Money> net = new LinkedHashMap<>();
            for (User u : group.members) {
                long total = 0;
                for (User other : group.members) {
                    if (other == u) continue;
                    total -= balanceSheet.getBalance(u, other).cents;
                }
                net.put(u, Money.ofCents(total));
            }
            return net;
        }
    }

    // ---------- Demo ----------

    public static void main(String[] args) {
        User alice = new User("u1", "Alice", "alice@mail.com");
        User bob = new User("u2", "Bob", "bob@mail.com");
        User carol = new User("u3", "Carol", "carol@mail.com");

        Group trip = new Group("g1");
        trip.addMember(alice);
        trip.addMember(bob);
        trip.addMember(carol);

        Map<SplitType, SplitStrategy> factory = new HashMap<>();
        factory.put(SplitType.EQUAL, new EqualSplitStrategy());
        factory.put(SplitType.EXACT, new ExactSplitStrategy());
        factory.put(SplitType.PERCENT, new PercentSplitStrategy());
        ExpenseService service = new ExpenseService(factory);

        // Alice pays $100 for dinner, split equally among the three.
        service.addExpense(Money.of(100.00), alice, List.of(alice, bob, carol),
                SplitType.EQUAL, Map.of(), trip);

        // Bob pays $60 for a cab, split by exact amounts.
        Map<String, Object> exactParams = new HashMap<>();
        exactParams.put("amounts", Map.of("u1", Money.of(20.00), "u2", Money.of(20.00), "u3", Money.of(20.00)));
        service.addExpense(Money.of(60.00), bob, List.of(alice, bob, carol),
                SplitType.EXACT, exactParams, trip);

        System.out.println("Alice owes Bob: " + service.getBalance(alice, bob));
        System.out.println("Carol owes Alice: " + service.getBalance(carol, alice));

        // Carol settles part of her debt to Alice.
        service.settleUp(carol, alice, Money.of(20.00), "idem-1");
        System.out.println("After settle, Carol owes Alice: " + service.getBalance(carol, alice));

        System.out.println("Net balances:");
        service.getNetBalances(trip).forEach((u, m) -> System.out.println("  " + u + ": " + m));
    }
}

