// Splitwise (Expense Sharing) — full LLD implementation with demo.
// Single-file C++ translation of the Mermaid class diagram in section J.
#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <unordered_map>
#include <memory>
#include <variant>
#include <stdexcept>
#include <cmath>
#include <sstream>

// ---------- Money (fixed-point cents) ----------
struct Money {
    long long cents = 0;
    static Money ofCents(long long c) { return Money{c}; }
    static Money of(double dollars) { return Money{ (long long)std::llround(dollars * 100) }; }
    static Money zero() { return Money{0}; }
    Money plus(const Money& o) const { return Money{cents + o.cents}; }
    Money minus(const Money& o) const { return Money{cents - o.cents}; }
    Money negate() const { return Money{-cents}; }
    bool isZero() const { return cents == 0; }
    std::string str() const {
        std::ostringstream os;
        bool neg = cents < 0;
        long long c = neg ? -cents : cents;
        os << (neg ? "-$" : "$") << (c / 100) << "." << (c % 100 < 10 ? "0" : "") << (c % 100);
        return os.str();
    }
};

enum class SplitType { EQUAL, EXACT, PERCENT };

// ---------- Core entities ----------
struct User {
    std::string id, name, email;
};

// Aggregation: Group holds Users but does not own their lifecycle.
struct Group {
    std::string id;
    std::vector<std::shared_ptr<User>> members;
    void addMember(std::shared_ptr<User> u) { members.push_back(u); }
};

// Pure data: how much one participant owes for one expense.
struct Split {
    std::shared_ptr<User> user;
    Money amount;
};

// Params bag for strategies: keyed maps of userId -> value.
struct SplitParams {
    std::unordered_map<std::string, Money> exactAmounts;   // for ExactSplitStrategy
    std::unordered_map<std::string, double> percentages;   // for PercentSplitStrategy
};

// Immutable record of one shared-cost event. Composes its Splits.
struct Expense {
    std::string id;
    Money amount;
    std::shared_ptr<User> paidBy;
    std::vector<Split> splits; // composition
    std::string groupId;
    long long timestamp;
};

// Records a settle-up action. Sibling of Expense, not a subclass.
struct Payment {
    std::string id;
    std::shared_ptr<User> from, to;
    Money amount;
    long long timestamp;
};

// ---------- SplitStrategy hierarchy ----------
class SplitStrategy {
public:
    virtual ~SplitStrategy() = default;
    virtual std::vector<Split> compute(const Money& total, const std::vector<std::shared_ptr<User>>& participants,
                                        const SplitParams& params) = 0;
};

class EqualSplitStrategy : public SplitStrategy {
public:
    std::vector<Split> compute(const Money& total, const std::vector<std::shared_ptr<User>>& participants,
                                const SplitParams&) override {
        long long n = (long long)participants.size();
        long long base = total.cents / n;
        long long remainder = total.cents % n;
        std::vector<Split> splits;
        for (long long i = 0; i < n; i++) {
            long long cents = base + (i < remainder ? 1 : 0);
            splits.push_back({participants[i], Money::ofCents(cents)});
        }
        return splits;
    }
};

class ExactSplitStrategy : public SplitStrategy {
public:
    std::vector<Split> compute(const Money& total, const std::vector<std::shared_ptr<User>>& participants,
                                const SplitParams& params) override {
        std::vector<Split> splits;
        for (auto& u : participants) {
            auto it = params.exactAmounts.find(u->id);
            if (it == params.exactAmounts.end()) throw std::invalid_argument("Missing exact amount for " + u->id);
            splits.push_back({u, it->second});
        }
        return splits;
    }
};

class PercentSplitStrategy : public SplitStrategy {
public:
    std::vector<Split> compute(const Money& total, const std::vector<std::shared_ptr<User>>& participants,
                                const SplitParams& params) override {
        std::vector<Split> splits;
        long long allocated = 0;
        for (size_t i = 0; i < participants.size(); i++) {
            auto& u = participants[i];
            auto it = params.percentages.find(u->id);
            if (it == params.percentages.end()) throw std::invalid_argument("Missing percentage for " + u->id);
            long long cents = (i == participants.size() - 1)
                    ? total.cents - allocated
                    : (long long)std::llround(total.cents * (it->second / 100.0));
            allocated += cents;
            splits.push_back({u, Money::ofCents(cents)});
        }
        return splits;
    }
};

// ---------- BalanceSheet ----------
// Single source of truth for who-owes-whom: one signed net cents value per unordered pair.
class BalanceSheet {
    std::map<std::pair<std::string, std::string>, long long> pairwise;

    std::pair<std::string, std::string> key(const std::string& a, const std::string& b) const {
        return a < b ? std::make_pair(a, b) : std::make_pair(b, a);
    }
public:
    // a owes b `amount` more (amount may be negative to reduce/reverse).
    void adjust(const std::shared_ptr<User>& a, const std::shared_ptr<User>& b, const Money& amount) {
        auto k = key(a->id, b->id);
        long long signed_ = (a->id < b->id) ? amount.cents : -amount.cents;
        pairwise[k] += signed_;
    }

    // Positive => a owes b; negative => b owes a.
    Money getBalance(const std::shared_ptr<User>& a, const std::shared_ptr<User>& b) const {
        auto k = key(a->id, b->id);
        auto it = pairwise.find(k);
        long long stored = (it == pairwise.end()) ? 0 : it->second;
        long long fromAPerspective = (a->id < b->id) ? stored : -stored;
        return Money::ofCents(fromAPerspective);
    }
};

// ---------- Idempotent payment log ----------
class PaymentLog {
    std::unordered_map<std::string, Payment> byKey;
public:
    bool seen(const std::string& k) const { return byKey.count(k) > 0; }
    Payment get(const std::string& k) const { return byKey.at(k); }
    void record(const std::string& k, const Payment& p) { byKey[k] = p; }
};

// ---------- ExpenseService (facade) ----------
class ExpenseService {
    std::unordered_map<int, std::shared_ptr<SplitStrategy>> strategyFactory; // keyed by SplitType
    BalanceSheet balanceSheet;
    PaymentLog paymentLog;
    std::vector<Expense> expenses;
    int expenseCounter = 0, paymentCounter = 0;

public:
    ExpenseService(std::unordered_map<int, std::shared_ptr<SplitStrategy>> factory)
        : strategyFactory(std::move(factory)) {}

    Expense addExpense(const Money& total, std::shared_ptr<User> paidBy,
                        const std::vector<std::shared_ptr<User>>& participants,
                        SplitType type, const SplitParams& params, std::shared_ptr<Group> group) {
        auto strategy = strategyFactory[(int)type];
        std::vector<Split> splits = strategy->compute(total, participants, params);

        long long sum = 0;
        for (auto& s : splits) sum += s.amount.cents;
        if (sum != total.cents) throw std::logic_error("Split strategy produced mismatched total");

        Expense expense{"EXP-" + std::to_string(++expenseCounter), total, paidBy, splits,
                         group ? group->id : "", 0};
        for (auto& s : splits) {
            if (s.user->id != paidBy->id) {
                balanceSheet.adjust(s.user, paidBy, s.amount); // s.user owes paidBy s.amount
            }
        }
        expenses.push_back(expense);
        return expense;
    }

    Payment settleUp(std::shared_ptr<User> from, std::shared_ptr<User> to, const Money& amount,
                      const std::string& idempotencyKey) {
        if (paymentLog.seen(idempotencyKey)) return paymentLog.get(idempotencyKey); // idempotent replay
        balanceSheet.adjust(from, to, amount.negate()); // paying down reduces what `from` owes `to`
        Payment payment{"PAY-" + std::to_string(++paymentCounter), from, to, amount, 0};
        paymentLog.record(idempotencyKey, payment);
        return payment;
    }

    Money getBalance(const std::shared_ptr<User>& a, const std::shared_ptr<User>& b) {
        return balanceSheet.getBalance(a, b);
    }

    // net(u) = sum over others of (-balance(u, other)); positive => u is owed money overall.
    std::vector<std::pair<std::shared_ptr<User>, Money>> getNetBalances(const std::shared_ptr<Group>& group) {
        std::vector<std::pair<std::shared_ptr<User>, Money>> net;
        for (auto& u : group->members) {
