// Splitwise (Expense Sharing) — full LLD implementation with demo.
// Single-file Node/JS translation of the Mermaid class diagram in section J.
'use strict';

// ---------- Money (fixed-point cents) ----------
class Money {
  constructor(cents) { this.cents = cents; }
  static ofCents(c) { return new Money(c); }
  static of(dollars) { return new Money(Math.round(dollars * 100)); }
  static zero() { return new Money(0); }
  plus(o) { return new Money(this.cents + o.cents); }
  minus(o) { return new Money(this.cents - o.cents); }
  negate() { return new Money(-this.cents); }
  isZero() { return this.cents === 0; }
  toString() {
    const neg = this.cents < 0;
    const c = Math.abs(this.cents);
    const cents = String(c % 100).padStart(2, '0');
    return `${neg ? '-' : ''}$${Math.floor(c / 100)}.${cents}`;
  }
}

const SplitType = Object.freeze({ EQUAL: 'EQUAL', EXACT: 'EXACT', PERCENT: 'PERCENT' });

// ---------- Core entities ----------
class User {
  constructor(id, name, email) { this.id = id; this.name = name; this.email = email; }
  toString() { return this.name; }
}

// Aggregation: Group holds Users but does not own their lifecycle.
class Group {
  constructor(id) { this.id = id; this.members = []; }
  addMember(u) { this.members.push(u); }
}

// Pure data: how much one participant owes for one expense. No computation.
class Split {
  constructor(user, amount) { this.user = user; this.amount = amount; }
}

// Immutable record of one shared-cost event. Composes its Splits.
class Expense {
  constructor(id, amount, paidBy, splits, groupId) {
    this.id = id; this.amount = amount; this.paidBy = paidBy;
    this.splits = [...splits]; this.groupId = groupId || null;
    this.timestamp = Date.now();
  }
}

// Records a settle-up action. Sibling of Expense, not a subclass (see section I).
class Payment {
  constructor(id, from, to, amount) {
    this.id = id; this.from = from; this.to = to; this.amount = amount;
    this.timestamp = Date.now();
  }
}

// ---------- SplitStrategy hierarchy ----------
class SplitStrategy {
  // eslint-disable-next-line no-unused-vars
  compute(total, participants, params) { throw new Error('not implemented'); }
}

class EqualSplitStrategy extends SplitStrategy {
  compute(total, participants) {
    const n = participants.length;
    const base = Math.trunc(total.cents / n);
    const remainder = total.cents % n; // distribute leftover cents deterministically
    return participants.map((u, i) => new Split(u, Money.ofCents(base + (i < remainder ? 1 : 0))));
  }
}

class ExactSplitStrategy extends SplitStrategy {
  compute(total, participants, params) {
    const amounts = params.amounts; // Map<userId, Money>
    return participants.map((u) => {
      const amt = amounts.get(u.id);
      if (!amt) throw new Error(`Missing exact amount for ${u.id}`);
      return new Split(u, amt);
    });
  }
}

class PercentSplitStrategy extends SplitStrategy {
  compute(total, participants, params) {
    const pct = params.percentages; // Map<userId, percent>
    let allocated = 0;
    return participants.map((u, i) => {
      const p = pct.get(u.id);
      if (p === undefined) throw new Error(`Missing percentage for ${u.id}`);
      const cents = (i === participants.length - 1)
        ? total.cents - allocated // last participant absorbs rounding remainder
        : Math.round(total.cents * (p / 100));
      allocated += cents;
      return new Split(u, Money.ofCents(cents));
    });
  }
}

// ---------- BalanceSheet ----------
// Single source of truth for who-owes-whom: one signed net cents value per unordered pair.
class BalanceSheet {
  constructor() { this.pairwise = new Map(); }

  _key(a, b) { return a.id < b.id ? `${a.id}|${b.id}` : `${b.id}|${a.id}`; }

  // a owes b `amount` more (amount may be negative to reduce/reverse).
  adjust(a, b, amount) {
    const k = this._key(a, b);
    const signed = a.id < b.id ? amount.cents : -amount.cents;
    this.pairwise.set(k, (this.pairwise.get(k) || 0) + signed);
  }

  // Positive => a owes b; negative => b owes a.
  getBalance(a, b) {
    const k = this._key(a, b);
    const stored = this.pairwise.get(k) || 0;
    const fromAPerspective = a.id < b.id ? stored : -stored;
    return Money.ofCents(fromAPerspective);
  }
}

// ---------- Idempotent payment log ----------
class PaymentLog {
  constructor() { this.byKey = new Map(); }
  seen(idemKey) { return this.byKey.has(idemKey); }
  get(idemKey) { return this.byKey.get(idemKey); }
  record(idemKey, p) { this.byKey.set(idemKey, p); }
}

// ---------- ExpenseService (facade) ----------
class ExpenseService {
  constructor(strategyFactory) {
    this.strategyFactory = strategyFactory; // Map<SplitType, SplitStrategy>
    this.balanceSheet = new BalanceSheet();
    this.paymentLog = new PaymentLog();
    this.expenses = [];
    this.expenseCounter = 0;
    this.paymentCounter = 0;
  }

  addExpense(total, paidBy, participants, type, params, group) {
    const strategy = this.strategyFactory.get(type);
    const splits = strategy.compute(total, participants, params || {});

    const sum = splits.reduce((acc, s) => acc + s.amount.cents, 0);
    if (sum !== total.cents) throw new Error('Split strategy produced mismatched total');

    const expense = new Expense(`EXP-${++this.expenseCounter}`, total, paidBy, splits, group ? group.id : null);
    for (const s of splits) {
      if (s.user.id !== paidBy.id) {
        this.balanceSheet.adjust(s.user, paidBy, s.amount); // s.user owes paidBy s.amount
      }
    }
    this.expenses.push(expense);
    return expense;
  }

  settleUp(from, to, amount, idempotencyKey) {
    if (this.paymentLog.seen(idempotencyKey)) return this.paymentLog.get(idempotencyKey); // idempotent replay
    this.balanceSheet.adjust(from, to, amount.negate()); // paying down reduces what `from` owes `to`
    const payment = new Payment(`PAY-${++this.paymentCounter}`, from, to, amount);
    this.paymentLog.record(idempotencyKey, payment);
    return payment;
  }

  getBalance(a, b) { return this.balanceSheet.getBalance(a, b); }

  // net(u) = sum over others of (-balance(u, other)); positive => u is owed money overall.
  getNetBalances(group) {
    const net = new Map();
    for (const u of group.members) {
      let total = 0;
      for (const other of group.members) {
        if (other === u) continue;
        total -= this.balanceSheet.getBalance(u, other).cents;
      }
      net.set(u, Money.ofCents(total));
    }
    return net;
  }
}

// ---------- Demo ----------
function main() {
  const alice = new User('u1', 'Alice', 'alice@mail.com');
  const bob = new User('u2', 'Bob', 'bob@mail.com');
  const carol = new User('u3', 'Carol', 'carol@mail.com');

  const trip = new Group('g1');
  trip.addMember(alice);
  trip.addMember(bob);
  trip.addMember(carol);

  const factory = new Map([
    [SplitType.EQUAL, new EqualSplitStrategy()],
    [SplitType.EXACT, new ExactSplitStrategy()],
    [SplitType.PERCENT, new PercentSplitStrategy()],
  ]);
  const service = new ExpenseService(factory);

  // Alice pays $100 for dinner, split equally among the three.
  service.addExpense(Money.of(100.0), alice, [alice, bob, carol], SplitType.EQUAL, {}, trip);

  // Bob pays $60 for a cab, split by exact amounts.
  const exactParams = { amounts: new Map([['u1', Money.of(20.0)], ['u2', Money.of(20.0)], ['u3', Money.of(20.0)]]) };
  service.addExpense(Money.of(60.0), bob, [alice, bob, carol], SplitType.EXACT, exactParams, trip);

  console.log('Alice owes Bob:', service.getBalance(alice, bob).toString());
  console.log('Carol owes Alice:', service.getBalance(carol, alice).toString());

  service.settleUp(carol, alice, Money.of(20.0), 'idem-1');
  console.log('After settle, Carol owes Alice:', service.getBalance(carol, alice).toString());

  console.log('Net balances:');
  for (const [u, m] of service.getNetBalances(trip)) {
    console.log(`  ${u}: ${m.toString()}`);
  }
}

if (require.main === module) {
  main();
}

module.exports = {
  Money, SplitType, User, Group, Split, Expense, Payment,
  SplitStrategy, EqualSplitStrategy, ExactSplitStrategy, PercentSplitStrategy,
  BalanceSheet, PaymentLog, ExpenseService,
};

