// Notification System -- full LLD implementation with demo.
// Single-file Java translation of the Mermaid class diagram in section J.
import java.util.*;

public class p7 {

    enum Category { TRANSACTIONAL, PROMOTIONAL, SECURITY_ALERT }
    enum ChannelType { EMAIL, SMS, PUSH }
    enum Status { PENDING, SENT, FAILED, DEAD_LETTERED }

    // ---------- Notification (data record) ----------
    static final class Notification {
        final String id;
        final String userId;
        final Category category;
        final String templateId;
        final Map<String, Object> params;
        final List<ChannelType> channels;
        final String idempotencyKey;
        Status status = Status.PENDING;
        // Retry context: populated by NotificationService just before a scheduleRetry() call
        // so RetryScheduler can re-attempt delivery on exactly the medium that failed.
        ChannelType retryChannel;
        RenderedContent retryContent;
        String retryRecipient;

        Notification(String id, String userId, Category category, String templateId,
                      Map<String, Object> params, List<ChannelType> channels, String idempotencyKey) {
            this.id = id; this.userId = userId; this.category = category; this.templateId = templateId;
            this.params = params; this.channels = channels; this.idempotencyKey = idempotencyKey;
        }
    }

    /** Content once rendered from a template -- has no lifecycle of its own. */
    static final class RenderedContent {
        final String subject;
        final String body;
        RenderedContent(String subject, String body) { this.subject = subject; this.body = body; }
        public String toString() { return (subject != null ? "[" + subject + "] " : "") + body; }
    }

    static final class DeliveryResult {
        final boolean failed;
        final String error;
        static DeliveryResult ok() { return new DeliveryResult(false, null); }
        static DeliveryResult fail(String error) { return new DeliveryResult(true, error); }
        private DeliveryResult(boolean failed, String error) { this.failed = failed; this.error = error; }
    }

    // ---------- NotificationTemplate ----------
    /** Content pattern per category+channel; substitutes {{placeholders}} with params at render time. */
    static final class NotificationTemplate {
        final String id;
        final Map<ChannelType, String> subjectPatterns = new HashMap<>(); // optional, e.g. email only
        final Map<ChannelType, String> bodyPatterns = new HashMap<>();

        NotificationTemplate(String id) { this.id = id; }

        NotificationTemplate withBody(ChannelType channel, String pattern) {
            bodyPatterns.put(channel, pattern);
            return this;
        }
        NotificationTemplate withSubject(ChannelType channel, String pattern) {
            subjectPatterns.put(channel, pattern);
            return this;
        }

        RenderedContent render(ChannelType channel, Map<String, Object> params) {
            String bodyPattern = bodyPatterns.get(channel);
            if (bodyPattern == null) throw new IllegalStateException("No template body for channel " + channel);
            String subjectPattern = subjectPatterns.get(channel);
            return new RenderedContent(substitute(subjectPattern, params), substitute(bodyPattern, params));
        }

        private String substitute(String pattern, Map<String, Object> params) {
            if (pattern == null) return null;
            String out = pattern;
            for (Map.Entry<String, Object> e : params.entrySet()) {
                out = out.replace("{{" + e.getKey() + "}}", String.valueOf(e.getValue()));
            }
            return out;
        }
    }

    // ---------- UserPreference ----------
    /** Per-user opt-in/opt-out. Default is allowed unless explicitly opted out. */
    static final class UserPreference {
        // key: userId|channel|category -> enabled
        private final Map<String, Boolean> overrides = new HashMap<>();

        private String key(String userId, ChannelType channel, Category category) {
            return userId + "|" + channel + "|" + category;
        }

        void setPreference(String userId, ChannelType channel, Category category, boolean enabled) {
            overrides.put(key(userId, channel, category), enabled);
        }

        boolean isAllowed(String userId, ChannelType channel, Category category) {
            return overrides.getOrDefault(key(userId, channel, category), true); // opt-out model
        }
    }

    // ---------- RateLimiter (reused from Problem 3) ----------
    /** Fixed-window limiter: caps sends per key within a rolling window. */
    static final class RateLimiter {
        private final int maxPerWindow;
        private final long windowMillis;
        private final Map<String, Deque<Long>> history = new HashMap<>();

        RateLimiter(int maxPerWindow, long windowMillis) {
            this.maxPerWindow = maxPerWindow; this.windowMillis = windowMillis;
        }

        boolean tryAcquire(String key) {
            long now = System.currentTimeMillis();
            Deque<Long> timestamps = history.computeIfAbsent(key, k -> new ArrayDeque<>());
            while (!timestamps.isEmpty() && now - timestamps.peekFirst() > windowMillis) timestamps.pollFirst();
            if (timestamps.size() >= maxPerWindow) return false;
            timestamps.addLast(now);
            return true;
        }
    }

    // ---------- NotificationChannel (Strategy interface) ----------
    interface NotificationChannel {
        DeliveryResult send(RenderedContent content, String recipientAddress);
    }

    static final class EmailChannel implements NotificationChannel {
        public DeliveryResult send(RenderedContent content, String recipientAddress) {
            System.out.println("  [EMAIL -> " + recipientAddress + "] " + content);
            return DeliveryResult.ok();
        }
    }

    /** Simulates a transient network failure: fails once per recipient, then succeeds. */
    static final class SMSChannel implements NotificationChannel {
        private final Set<String> failedOnce = new HashSet<>();
        public DeliveryResult send(RenderedContent content, String recipientAddress) {
            if (failedOnce.add(recipientAddress)) {
                System.out.println("  [SMS -> " + recipientAddress + "] transient failure");
                return DeliveryResult.fail("carrier timeout");
            }
            System.out.println("  [SMS -> " + recipientAddress + "] " + content);
            return DeliveryResult.ok();
        }
    }

    /** Simulates a permanently broken provider, to demonstrate dead-lettering. */
    static final class PushChannel implements NotificationChannel {
        public DeliveryResult send(RenderedContent content, String recipientAddress) {
            System.out.println("  [PUSH -> " + recipientAddress + "] provider unavailable");
            return DeliveryResult.fail("device token invalid");
        }
    }

    // ---------- DeadLetterQueue ----------
    static final class DeadLetterQueue {
        private final List<String> entries = new ArrayList<>();
        void record(Notification notification, String error) {
            entries.add(notification.id + " (" + notification.retryChannel + "): " + error);
            notification.status = Status.DEAD_LETTERED;
        }
        List<String> entries() { return entries; }
    }

    // ---------- RetryScheduler ----------
    /** Re-attempts failed sends with backoff, up to MAX_ATTEMPTS, then dead-letters. */
    static final class RetryScheduler {
        private static final int MAX_ATTEMPTS = 3;
        private final Map<ChannelType, NotificationChannel> channels;
        private final DeadLetterQueue deadLetterQueue;

        RetryScheduler(Map<ChannelType, NotificationChannel> channels, DeadLetterQueue deadLetterQueue) {
            this.channels = channels; this.deadLetterQueue = deadLetterQueue;
        }

        /** In production this enqueues a delayed timer job; here we simulate the delay synchronously for the demo. */
        void scheduleRetry(Notification notification, int attempt) {
            long delayMs = backoff(attempt);
            System.out.println("  retry scheduled for " + notification.id + " attempt=" + attempt + " delay=" + delayMs + "ms");
            onRetryDue(notification, attempt);
        }

        private void onRetryDue(Notification notification, int attempt) {
            NotificationChannel channel = channels.get(notification.retryChannel);
            DeliveryResult result = channel.send(notification.retryContent, notification.retryRecipient);
            if (result.failed) {
                if (attempt >= MAX_ATTEMPTS) {
                    deadLetterQueue.record(notification, result.error);
                } else {
                    scheduleRetry(notification, attempt + 1);
                }
            } else {
                notification.status = Status.SENT;
            }
        }

        private long backoff(int attempt) { return 100L * (1L << attempt); } // exponential backoff
    }

    // ---------- NotificationService (facade) ----------
    static final class NotificationService {
        private final Map<String, NotificationTemplate> templates;
        private final UserPreference userPreference;
        private final RateLimiter rateLimiter;
        private final Map<ChannelType, NotificationChannel> channels;
        private final RetryScheduler retryScheduler;
        private final Set<String> dedupeCache = new HashSet<>();
        private int counter = 0;

        NotificationService(Map<String, NotificationTemplate> templates, UserPreference userPreference,
                             RateLimiter rateLimiter, Map<ChannelType, NotificationChannel> channels,
                             RetryScheduler retryScheduler) {
            this.templates = templates; this.userPreference = userPreference; this.rateLimiter = rateLimiter;
            this.channels = channels; this.retryScheduler = retryScheduler;
        }

        Notification notify(String userId, Category category, String templateId,
                             Map<String, Object> params, List<ChannelType> requestedChannels, String idempotencyKey) {
            Notification notification = new Notification("N" + (++counter), userId, category, templateId,
                    params, requestedChannels, idempotencyKey);

            if (dedupeCache.contains(idempotencyKey)) { // idempotent replay guard
                System.out.println("Skipping duplicate notify() for idemKey=" + idempotencyKey);
                return notification;
            }

            NotificationTemplate template = templates.get(templateId);
            for (ChannelType channel : requestedChannels) {
                if (!userPreference.isAllowed(userId, channel, category)) {
                    System.out.println("  " + channel + " skipped: user opted out for " + category);
                    continue;
                }
                if (!rateLimiter.tryAcquire(userId + "|" + channel)) {
                    System.out.println("  " + channel + " skipped: rate limit exceeded");
                    continue;
                }
                RenderedContent content = template.render(channel, params);
                String recipient = resolveAddress(userId, channel);
                DeliveryResult result = channels.get(channel).send(content, recipient);
                if (result.failed) {
                    notification.status = Status.FAILED;
                    notification.retryChannel = channel;
                    notification.retryContent = content;
                    notification.retryRecipient = recipient;
                    retryScheduler.scheduleRetry(notification, 1);
                } else if (notification.status != Status.SENT) {
                    notification.status = Status.SENT;
                }
            }
            dedupeCache.add(idempotencyKey);
            return notification;
        }

        private String resolveAddress(String userId, ChannelType channel) {
            switch (channel) {
                case EMAIL: return userId + "@example.com";
                case SMS: return "+1-555-" + userId;
                case PUSH: return "device-token-" + userId;
                default: throw new IllegalArgumentException("Unknown channel: " + channel);
            }
        }
    }

    // ---------- Demo ----------
    public static void main(String[] args) {
        NotificationTemplate welcome = new NotificationTemplate("welcome")
                .withSubject(ChannelType.EMAIL, "Welcome, {{name}}!")
                .withBody(ChannelType.EMAIL, "Hi {{name}}, thanks for joining.")
                .withBody(ChannelType.SMS, "Hi {{name}}, welcome aboard!")
                .withBody(ChannelType.PUSH, "Welcome, {{name}}!");
        Map<String, NotificationTemplate> templates = new HashMap<>();
        templates.put("welcome", welcome);

        UserPreference preferences = new UserPreference();

        RateLimiter rateLimiter = new RateLimiter(5, 24L * 60 * 60 * 1000); // 5 per day per (user, channel)

        Map<ChannelType, NotificationChannel> channels = new HashMap<>();
        channels.put(ChannelType.EMAIL, new EmailChannel());
        channels.put(ChannelType.SMS, new SMSChannel());
        channels.put(ChannelType.PUSH, new PushChannel());

        DeadLetterQueue dlq = new DeadLetterQueue();
        RetryScheduler retryScheduler = new RetryScheduler(channels, dlq);

        NotificationService service = new NotificationService(templates, preferences, rateLimiter, channels, retryScheduler);

        Map<String, Object> params = new HashMap<>();
        params.put("name", "Alice");

        System.out.println("First notify (SMS will fail once then retry-succeed; PUSH will exhaust retries -> DLQ):");
        service.notify("u1", Category.TRANSACTIONAL, "welcome", params,
                List.of(ChannelType.EMAIL, ChannelType.SMS, ChannelType.PUSH), "idem-1");

        System.out.println("\nReplaying same idempotencyKey (should be skipped):");
        service.notify("u1", Category.TRANSACTIONAL, "welcome", params,
                List.of(ChannelType.EMAIL, ChannelType.SMS, ChannelType.PUSH), "idem-1");

        System.out.println("\nOpting out u2 from SMS/PROMOTIONAL, then attempting anyway:");
        preferences.setPreference("u2", ChannelType.SMS, Category.PROMOTIONAL, false);
        service.notify("u2", Category.PROMOTIONAL, "welcome", params, List.of(ChannelType.SMS), "idem-2");

        System.out.println("\nDead letter queue entries: " + dlq.entries());
    }
}

