// Notification System -- full class-diagram implementation, single-threaded.
#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <unordered_map>
#include <unordered_set>
#include <deque>
#include <memory>
#include <chrono>
#include <stdexcept>

enum class Category { TRANSACTIONAL, PROMOTIONAL, SECURITY_ALERT };
enum class ChannelType { EMAIL, SMS, PUSH };
enum class Status { PENDING, SENT, FAILED, DEAD_LETTERED };

std::string toString(ChannelType c) {
    switch (c) { case ChannelType::EMAIL: return "EMAIL"; case ChannelType::SMS: return "SMS"; default: return "PUSH"; }
}
std::string toString(Category c) {
    switch (c) { case Category::TRANSACTIONAL: return "TRANSACTIONAL"; case Category::PROMOTIONAL: return "PROMOTIONAL"; default: return "SECURITY_ALERT"; }
}

// ---------- RenderedContent / DeliveryResult ----------
struct RenderedContent {
    std::string subject; // may be empty
    std::string body;
    std::string toString() const { return (subject.empty() ? "" : "[" + subject + "] ") + body; }
};

struct DeliveryResult {
    bool failed;
    std::string error;
    static DeliveryResult ok() { return {false, ""}; }
    static DeliveryResult fail(const std::string& e) { return {true, e}; }
};

// ---------- Notification ----------
struct Notification {
    std::string id, userId, templateId, idempotencyKey;
    Category category;
    std::vector<ChannelType> channels;
    std::map<std::string, std::string> params;
    Status status = Status::PENDING;
    // Retry context, populated right before scheduleRetry().
    ChannelType retryChannel = ChannelType::EMAIL;
    RenderedContent retryContent;
    std::string retryRecipient;
};

// ---------- NotificationTemplate ----------
class NotificationTemplate {
public:
    std::string id;
    explicit NotificationTemplate(std::string id_) : id(std::move(id_)) {}

    NotificationTemplate& withBody(ChannelType c, const std::string& pattern) { bodyPatterns_[c] = pattern; return *this; }
    NotificationTemplate& withSubject(ChannelType c, const std::string& pattern) { subjectPatterns_[c] = pattern; return *this; }

    RenderedContent render(ChannelType channel, const std::map<std::string, std::string>& params) const {
        auto bit = bodyPatterns_.find(channel);
        if (bit == bodyPatterns_.end()) throw std::runtime_error("No template body for channel");
        RenderedContent rc;
        rc.body = substitute(bit->second, params);
        auto sit = subjectPatterns_.find(channel);
        if (sit != subjectPatterns_.end()) rc.subject = substitute(sit->second, params);
        return rc;
    }
private:
    std::map<ChannelType, std::string> bodyPatterns_, subjectPatterns_;
    static std::string substitute(std::string pattern, const std::map<std::string, std::string>& params) {
        for (auto& kv : params) {
            std::string token = "{{" + kv.first + "}}";
            size_t pos;
            while ((pos = pattern.find(token)) != std::string::npos) pattern.replace(pos, token.size(), kv.second);
        }
        return pattern;
    }
};

// ---------- UserPreference ----------
class UserPreference {
public:
    void setPreference(const std::string& userId, ChannelType channel, Category category, bool enabled) {
        overrides_[key(userId, channel, category)] = enabled;
    }
    bool isAllowed(const std::string& userId, ChannelType channel, Category category) const {
        auto it = overrides_.find(key(userId, channel, category));
        return it == overrides_.end() ? true : it->second; // opt-out model: default allowed
    }
private:
    std::map<std::string, bool> overrides_;
    static std::string key(const std::string& userId, ChannelType c, Category cat) {
        return userId + "|" + toString(c) + "|" + toString(cat);
    }
};

// ---------- RateLimiter ----------
class RateLimiter {
public:
    RateLimiter(int maxPerWindow, long long windowMs) : maxPerWindow_(maxPerWindow), windowMs_(windowMs) {}
    bool tryAcquire(const std::string& key) {
        long long now = nowMs();
        auto& q = history_[key];
        while (!q.empty() && now - q.front() > windowMs_) q.pop_front();
        if ((int)q.size() >= maxPerWindow_) return false;
        q.push_back(now);
        return true;
    }
private:
    int maxPerWindow_;
    long long windowMs_;
    std::unordered_map<std::string, std::deque<long long>> history_;
    static long long nowMs() {
        return std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();
    }
};

// ---------- NotificationChannel (Strategy interface) ----------
struct NotificationChannel {
    virtual ~NotificationChannel() = default;
    virtual DeliveryResult send(const RenderedContent& content, const std::string& recipient) = 0;
};

struct EmailChannel : NotificationChannel {
    DeliveryResult send(const RenderedContent& content, const std::string& recipient) override {
        std::cout << "  [EMAIL -> " << recipient << "] " << content.toString() << "\n";
        return DeliveryResult::ok();
    }
};

// Fails once per recipient (simulated transient failure), then succeeds.
struct SMSChannel : NotificationChannel {
    std::unordered_set<std::string> failedOnce;
    DeliveryResult send(const RenderedContent& content, const std::string& recipient) override {
        if (failedOnce.insert(recipient).second) {
            std::cout << "  [SMS -> " << recipient << "] transient failure\n";
            return DeliveryResult::fail("carrier timeout");
        }
        std::cout << "  [SMS -> " << recipient << "] " << content.toString() << "\n";
        return DeliveryResult::ok();
    }
};

// Permanently broken provider, to demonstrate dead-lettering.
struct PushChannel : NotificationChannel {
    DeliveryResult send(const RenderedContent&, const std::string& recipient) override {
        std::cout << "  [PUSH -> " << recipient << "] provider unavailable\n";
        return DeliveryResult::fail("device token invalid");
    }
};

// ---------- DeadLetterQueue ----------
class DeadLetterQueue {
public:
    void record(Notification& n, const std::string& error) {
        entries_.push_back(n.id + " (" + toString(n.retryChannel) + "): " + error);
        n.status = Status::DEAD_LETTERED;
    }
    const std::vector<std::string>& entries() const { return entries_; }
private:
    std::vector<std::string> entries_;
};

// ---------- RetryScheduler ----------
class RetryScheduler {
public:
    RetryScheduler(std::map<ChannelType, std::shared_ptr<NotificationChannel>> channels,
                    std::shared_ptr<DeadLetterQueue> dlq)
        : channels_(std::move(channels)), deadLetterQueue_(std::move(dlq)) {}

    // Simulates a delayed timer job synchronously for this single-threaded demo.
    void scheduleRetry(Notification& n, int attempt) {
        long long delayMs = backoff(attempt);
        std::cout << "  retry scheduled for " << n.id << " attempt=" << attempt << " delay=" << delayMs << "ms\n";
        onRetryDue(n, attempt);
    }
private:
    static const int MAX_ATTEMPTS = 3;
    std::map<ChannelType, std::shared_ptr<NotificationChannel>> channels_;
    std::shared_ptr<DeadLetterQueue> deadLetterQueue_;

    void onRetryDue(Notification& n, int attempt) {
        auto result = channels_[n.retryChannel]->send(n.retryContent, n.retryRecipient);
        if (result.failed) {
            if (attempt >= MAX_ATTEMPTS) deadLetterQueue_->record(n, result.error);
            else scheduleRetry(n, attempt + 1);
        } else {
            n.status = Status::SENT;
        }
    }
    long long backoff(int attempt) { return 100LL * (1LL << attempt); }
};

// ---------- NotificationService (facade) ----------
class NotificationService {
public:
    NotificationService(std::map<std::string, NotificationTemplate> templates, std::shared_ptr<UserPreference> pref,
                         std::shared_ptr<RateLimiter> rateLimiter, std::map<ChannelType, std::shared_ptr<NotificationChannel>> channels,
                         std::shared_ptr<RetryScheduler> retryScheduler)
        : templates_(std::move(templates)), userPreference_(std::move(pref)), rateLimiter_(std::move(rateLimiter)),
          channels_(std::move(channels)), retryScheduler_(std::move(retryScheduler)) {}

    Notification notify(const std::string& userId, Category category, const std::string& templateId,
                         std::map<std::string, std::string> params, std::vector<ChannelType> requestedChannels,
                         const std::string& idempotencyKey) {
        Notification n;
        n.id = "N" + std::to_string(++counter_);
        n.userId = userId; n.category = category; n.templateId = templateId;
        n.params = params; n.channels = requestedChannels; n.idempotencyKey = idempotencyKey;

        if (dedupeCache_.count(idempotencyKey)) {
            std::cout << "Skipping duplicate notify() for idemKey=" << idempotencyKey << "\n";
            return n;
        }

        const NotificationTemplate& tmpl = templates_.at(templateId);
        for (ChannelType channel : requestedChannels) {
            if (!userPreference_->isAllowed(userId, channel, category)) {
                std::cout << "  " << toString(channel) << " skipped: user opted out for " << toString(category) << "\n";
                continue;
            }
            if (!rateLimiter_->tryAcquire(userId + "|" + toString(channel))) {
                std::cout << "  " << toString(channel) << " skipped: rate limit exceeded\n";
                continue;
            }
            RenderedContent content = tmpl.render(channel, params);
            std::string recipient = resolveAddress(userId, channel);
            DeliveryResult result = channels_[channel]->send(content, recipient);
            if (result.failed) {
                n.status = Status::FAILED;
                n.retryChannel = channel; n.retryContent = content; n.retryRecipient = recipient;
                retryScheduler_->scheduleRetry(n, 1);
            } else if (n.status != Status::SENT) {
                n.status = Status::SENT;
            }
        }
        dedupeCache_.insert(idempotencyKey);
        return n;
    }

private:
    std::map<std::string, NotificationTemplate> templates_;
    std::shared_ptr<UserPreference> userPreference_;
    std::shared_ptr<RateLimiter> rateLimiter_;
    std::map<ChannelType, std::shared_ptr<NotificationChannel>> channels_;
    std::shared_ptr<RetryScheduler> retryScheduler_;
    std::unordered_set<std::string> dedupeCache_;
    int counter_ = 0;

    std::string resolveAddress(const std::string& userId, ChannelType channel) {
        switch (channel) {
            case ChannelType::EMAIL: return userId + "@example.com";
            case ChannelType::SMS: return "+1-555-" + userId;
            default: return "device-token-" + userId;
        }
    }
};

int main() {
    NotificationTemplate welcome("welcome");
    welcome.withSubject(ChannelType::EMAIL, "Welcome, {{name}}!")
           .withBody(ChannelType::EMAIL, "Hi {{name}}, thanks for joining.")
           .withBody(ChannelType::SMS, "Hi {{name}}, welcome aboard!")
           .withBody(ChannelType::PUSH, "Welcome, {{name}}!");
    std::map<std::string, NotificationTemplate> templates;
    templates.emplace("welcome", welcome);

    auto preferences = std::make_shared<UserPreference>();
    auto rateLimiter = std::make_shared<RateLimiter>(5, 24LL * 60 * 60 * 1000);

    std::map<ChannelType, std::shared_ptr<NotificationChannel>> channels;
    channels[ChannelType::EMAIL] = std::make_shared<EmailChannel>();
    channels[ChannelType::SMS] = std::make_shared<SMSChannel>();
    channels[ChannelType::PUSH] = std::make_shared<PushChannel>();

    auto dlq = std::make_shared<DeadLetterQueue>();
    auto retryScheduler = std::make_shared<RetryScheduler>(channels, dlq);

    NotificationService service(templates, preferences, rateLimiter, channels, retryScheduler);

    std::map<std::string, std::string> params = { {"name", "Alice"} };

    std::cout << "First notify (SMS fails once then retry-succeeds; PUSH exhausts retries -> DLQ):\n";
    service.notify("u1", Category::TRANSACTIONAL, "welcome", params,
                    {ChannelType::EMAIL, ChannelType::SMS, ChannelType::PUSH}, "idem-1");

    std::cout << "\nReplaying same idempotencyKey (should be skipped):\n";
    service.notify("u1", Category::TRANSACTIONAL, "welcome", params,
                    {ChannelType::EMAIL, ChannelType::SMS, ChannelType::PUSH}, "idem-1");

    std::cout << "\nOpting out u2 from SMS/PROMOTIONAL, then attempting anyway:\n";
    preferences->setPreference("u2", ChannelType::SMS, Category::PROMOTIONAL, false);
    service.notify("u2", Category::PROMOTIONAL, "welcome", params, {ChannelType::SMS}, "idem-2");

    std::cout << "\nDead letter queue entries: ";
    for (auto& e : dlq->entries()) std::cout << e << " | ";
    std::cout << "\n";
    return 0;
}

