// Notification System -- full class-diagram implementation, single-threaded.
// Node-style, plain classes, CommonJS.

const Category = { TRANSACTIONAL: 'TRANSACTIONAL', PROMOTIONAL: 'PROMOTIONAL', SECURITY_ALERT: 'SECURITY_ALERT' };
const ChannelType = { EMAIL: 'EMAIL', SMS: 'SMS', PUSH: 'PUSH' };
const Status = { PENDING: 'PENDING', SENT: 'SENT', FAILED: 'FAILED', DEAD_LETTERED: 'DEAD_LETTERED' };

// ---------- Notification (data record) ----------
class Notification {
  constructor(id, userId, category, templateId, params, channels, idempotencyKey) {
    this.id = id;
    this.userId = userId;
    this.category = category;
    this.templateId = templateId;
    this.params = params;
    this.channels = channels;
    this.idempotencyKey = idempotencyKey;
    this.status = Status.PENDING;
    // Retry context, populated by NotificationService right before scheduleRetry().
    this.retryChannel = null;
    this.retryContent = null;
    this.retryRecipient = null;
  }
}

class RenderedContent {
  constructor(subject, body) { this.subject = subject; this.body = body; }
  toString() { return (this.subject ? `[${this.subject}] ` : '') + this.body; }
}

class DeliveryResult {
  constructor(failed, error) { this.failed = failed; this.error = error; }
  static ok() { return new DeliveryResult(false, null); }
  static fail(error) { return new DeliveryResult(true, error); }
}

// ---------- NotificationTemplate ----------
class NotificationTemplate {
  constructor(id) {
    this.id = id;
    this.subjectPatterns = new Map();
    this.bodyPatterns = new Map();
  }
  withBody(channel, pattern) { this.bodyPatterns.set(channel, pattern); return this; }
  withSubject(channel, pattern) { this.subjectPatterns.set(channel, pattern); return this; }

  render(channel, params) {
    const bodyPattern = this.bodyPatterns.get(channel);
    if (!bodyPattern) throw new Error(`No template body for channel ${channel}`);
    const subjectPattern = this.subjectPatterns.get(channel);
    return new RenderedContent(
      subjectPattern ? this._substitute(subjectPattern, params) : null,
      this._substitute(bodyPattern, params)
    );
  }
  _substitute(pattern, params) {
    let out = pattern;
    for (const [k, v] of Object.entries(params)) out = out.split(`{{${k}}}`).join(String(v));
    return out;
  }
}

// ---------- UserPreference ----------
class UserPreference {
  constructor() { this.overrides = new Map(); }
  _key(userId, channel, category) { return `${userId}|${channel}|${category}`; }
  setPreference(userId, channel, category, enabled) {
    this.overrides.set(this._key(userId, channel, category), enabled);
  }
  isAllowed(userId, channel, category) {
    const key = this._key(userId, channel, category);
    return this.overrides.has(key) ? this.overrides.get(key) : true; // opt-out model: default allowed
  }
}

// ---------- RateLimiter (reused from Problem 3) ----------
class RateLimiter {
  constructor(maxPerWindow, windowMillis) {
    this.maxPerWindow = maxPerWindow;
    this.windowMillis = windowMillis;
    this.history = new Map();
  }
  tryAcquire(key) {
    const now = Date.now();
    if (!this.history.has(key)) this.history.set(key, []);
    const timestamps = this.history.get(key);
    while (timestamps.length && now - timestamps[0] > this.windowMillis) timestamps.shift();
    if (timestamps.length >= this.maxPerWindow) return false;
    timestamps.push(now);
    return true;
  }
}

// ---------- NotificationChannel (Strategy interface) ----------
class NotificationChannel {
  send(_content, _recipientAddress) { throw new Error('send() not implemented'); }
}

class EmailChannel extends NotificationChannel {
  send(content, recipientAddress) {
    console.log(`  [EMAIL -> ${recipientAddress}] ${content}`);
    return DeliveryResult.ok();
  }
}

// Simulates a transient failure: fails once per recipient, then succeeds.
class SMSChannel extends NotificationChannel {
  constructor() { super(); this.failedOnce = new Set(); }
  send(content, recipientAddress) {
    if (!this.failedOnce.has(recipientAddress)) {
      this.failedOnce.add(recipientAddress);
      console.log(`  [SMS -> ${recipientAddress}] transient failure`);
      return DeliveryResult.fail('carrier timeout');
    }
    console.log(`  [SMS -> ${recipientAddress}] ${content}`);
    return DeliveryResult.ok();
  }
}

// Permanently broken provider, to demonstrate dead-lettering.
class PushChannel extends NotificationChannel {
  send(content, recipientAddress) {
    console.log(`  [PUSH -> ${recipientAddress}] provider unavailable`);
    return DeliveryResult.fail('device token invalid');
  }
}

// ---------- DeadLetterQueue ----------
class DeadLetterQueue {
  constructor() { this.entriesList = []; }
  record(notification, error) {
    this.entriesList.push(`${notification.id} (${notification.retryChannel}): ${error}`);
    notification.status = Status.DEAD_LETTERED;
  }
  entries() { return this.entriesList; }
}

// ---------- RetryScheduler ----------
class RetryScheduler {
  static MAX_ATTEMPTS = 3;
  constructor(channels, deadLetterQueue) {
    this.channels = channels;
    this.deadLetterQueue = deadLetterQueue;
  }
  // Simulates a delayed timer job synchronously for this demo (no real event loop needed).
  scheduleRetry(notification, attempt) {
    const delayMs = this._backoff(attempt);
    console.log(`  retry scheduled for ${notification.id} attempt=${attempt} delay=${delayMs}ms`);
    this._onRetryDue(notification, attempt);
  }
  _onRetryDue(notification, attempt) {
    const channel = this.channels.get(notification.retryChannel);
    const result = channel.send(notification.retryContent, notification.retryRecipient);
    if (result.failed) {
      if (attempt >= RetryScheduler.MAX_ATTEMPTS) {
        this.deadLetterQueue.record(notification, result.error);
      } else {
        this.scheduleRetry(notification, attempt + 1);
      }
    } else {
      notification.status = Status.SENT;
    }
  }
  _backoff(attempt) { return 100 * Math.pow(2, attempt); }
}

// ---------- NotificationService (facade) ----------
class NotificationService {
  constructor(templates, userPreference, rateLimiter, channels, retryScheduler) {
    this.templates = templates;
    this.userPreference = userPreference;
    this.rateLimiter = rateLimiter;
    this.channels = channels;
    this.retryScheduler = retryScheduler;
    this.dedupeCache = new Set();
    this.counter = 0;
  }

  notify(userId, category, templateId, params, requestedChannels, idempotencyKey) {
    const notification = new Notification(
      `N${++this.counter}`, userId, category, templateId, params, requestedChannels, idempotencyKey
    );

    if (this.dedupeCache.has(idempotencyKey)) { // idempotent replay guard
      console.log(`Skipping duplicate notify() for idemKey=${idempotencyKey}`);
      return notification;
    }

    const template = this.templates.get(templateId);
    for (const channel of requestedChannels) {
      if (!this.userPreference.isAllowed(userId, channel, category)) {
        console.log(`  ${channel} skipped: user opted out for ${category}`);
        continue;
      }
      if (!this.rateLimiter.tryAcquire(`${userId}|${channel}`)) {
        console.log(`  ${channel} skipped: rate limit exceeded`);
        continue;
      }
      const content = template.render(channel, params);
      const recipient = this._resolveAddress(userId, channel);
      const result = this.channels.get(channel).send(content, recipient);
      if (result.failed) {
        notification.status = Status.FAILED;
        notification.retryChannel = channel;
        notification.retryContent = content;
        notification.retryRecipient = recipient;
        this.retryScheduler.scheduleRetry(notification, 1);
      } else if (notification.status !== Status.SENT) {
        notification.status = Status.SENT;
      }
    }
    this.dedupeCache.add(idempotencyKey);
    return notification;
  }

  _resolveAddress(userId, channel) {
    switch (channel) {
      case ChannelType.EMAIL: return `${userId}@example.com`;
      case ChannelType.SMS: return `+1-555-${userId}`;
      case ChannelType.PUSH: return `device-token-${userId}`;
      default: throw new Error(`Unknown channel: ${channel}`);
    }
  }
}

// ---------- Demo ----------
function main() {
  const welcome = new NotificationTemplate('welcome')
    .withSubject(ChannelType.EMAIL, 'Welcome, {{name}}!')
    .withBody(ChannelType.EMAIL, 'Hi {{name}}, thanks for joining.')
    .withBody(ChannelType.SMS, 'Hi {{name}}, welcome aboard!')
    .withBody(ChannelType.PUSH, 'Welcome, {{name}}!');
  const templates = new Map([['welcome', welcome]]);

  const preferences = new UserPreference();
  const rateLimiter = new RateLimiter(5, 24 * 60 * 60 * 1000); // 5 per day per (user, channel)

  const channels = new Map([
    [ChannelType.EMAIL, new EmailChannel()],
    [ChannelType.SMS, new SMSChannel()],
    [ChannelType.PUSH, new PushChannel()],
  ]);

  const dlq = new DeadLetterQueue();
  const retryScheduler = new RetryScheduler(channels, dlq);

  const service = new NotificationService(templates, preferences, rateLimiter, channels, retryScheduler);

  const params = { name: 'Alice' };

  console.log('First notify (SMS fails once then retry-succeeds; PUSH exhausts retries -> DLQ):');
  service.notify('u1', Category.TRANSACTIONAL, 'welcome', params,
    [ChannelType.EMAIL, ChannelType.SMS, ChannelType.PUSH], 'idem-1');

  console.log('\nReplaying same idempotencyKey (should be skipped):');
  service.notify('u1', Category.TRANSACTIONAL, 'welcome', params,
    [ChannelType.EMAIL, ChannelType.SMS, ChannelType.PUSH], 'idem-1');

  console.log('\nOpting out u2 from SMS/PROMOTIONAL, then attempting anyway:');
  preferences.setPreference('u2', ChannelType.SMS, Category.PROMOTIONAL, false);
  service.notify('u2', Category.PROMOTIONAL, 'welcome', params, [ChannelType.SMS], 'idem-2');

  console.log('\nDead letter queue entries:', dlq.entries());
}

if (require.main === module) main();

module.exports = {
  Category, ChannelType, Status, Notification, RenderedContent, DeliveryResult,
  NotificationTemplate, UserPreference, RateLimiter, NotificationChannel,
  EmailChannel, SMSChannel, PushChannel, DeadLetterQueue, RetryScheduler, NotificationService,
};

