// Notification System -- full class-diagram implementation, single-threaded.
// Note: the diagram's `Notification` class is named `NotificationRecord` here because
// TypeScript's default lib set includes DOM, which declares a global `Notification` type;
// this avoids that name collision while keeping identical fields/behavior.

enum Category { TRANSACTIONAL = 'TRANSACTIONAL', PROMOTIONAL = 'PROMOTIONAL', SECURITY_ALERT = 'SECURITY_ALERT' }
enum ChannelType { EMAIL = 'EMAIL', SMS = 'SMS', PUSH = 'PUSH' }
enum Status { PENDING = 'PENDING', SENT = 'SENT', FAILED = 'FAILED', DEAD_LETTERED = 'DEAD_LETTERED' }

// ---------- NotificationRecord (data record) ----------
class NotificationRecord {
  status: Status = Status.PENDING;
  // Retry context, populated by NotificationService right before scheduleRetry().
  retryChannel: ChannelType | null = null;
  retryContent: RenderedContent | null = null;
  retryRecipient: string | null = null;

  constructor(
    public readonly id: string,
    public readonly userId: string,
    public readonly category: Category,
    public readonly templateId: string,
    public readonly params: Record<string, unknown>,
    public readonly channels: ChannelType[],
    public readonly idempotencyKey: string
  ) {}
}

class RenderedContent {
  constructor(public readonly subject: string | null, public readonly body: string) {}
  toString(): string { return (this.subject ? `[${this.subject}] ` : '') + this.body; }
}

class DeliveryResult {
  private constructor(public readonly failed: boolean, public readonly error: string | null) {}
  static ok(): DeliveryResult { return new DeliveryResult(false, null); }
  static fail(error: string): DeliveryResult { return new DeliveryResult(true, error); }
}

// ---------- NotificationTemplate ----------
class NotificationTemplate {
  private readonly subjectPatterns = new Map<ChannelType, string>();
  private readonly bodyPatterns = new Map<ChannelType, string>();

  constructor(public readonly id: string) {}

  withBody(channel: ChannelType, pattern: string): this { this.bodyPatterns.set(channel, pattern); return this; }
  withSubject(channel: ChannelType, pattern: string): this { this.subjectPatterns.set(channel, pattern); return this; }

  render(channel: ChannelType, params: Record<string, unknown>): RenderedContent {
    const bodyPattern = this.bodyPatterns.get(channel);
    if (!bodyPattern) throw new Error(`No template body for channel ${channel}`);
    const subjectPattern = this.subjectPatterns.get(channel);
    return new RenderedContent(
      subjectPattern ? this.substitute(subjectPattern, params) : null,
      this.substitute(bodyPattern, params)
    );
  }

  private substitute(pattern: string, params: Record<string, unknown>): string {
    let out = pattern;
    for (const [k, v] of Object.entries(params)) out = out.split(`{{${k}}}`).join(String(v));
    return out;
  }
}

// ---------- UserPreference ----------
class UserPreference {
  private readonly overrides = new Map<string, boolean>();

  private key(userId: string, channel: ChannelType, category: Category): string {
    return `${userId}|${channel}|${category}`;
  }

  setPreference(userId: string, channel: ChannelType, category: Category, enabled: boolean): void {
    this.overrides.set(this.key(userId, channel, category), enabled);
  }

  isAllowed(userId: string, channel: ChannelType, category: Category): boolean {
    const k = this.key(userId, channel, category);
    return this.overrides.has(k) ? this.overrides.get(k)! : true; // opt-out model: default allowed
  }
}

// ---------- RateLimiter (reused from Problem 3) ----------
class RateLimiter {
  private readonly history = new Map<string, number[]>();

  constructor(private readonly maxPerWindow: number, private readonly windowMillis: number) {}

  tryAcquire(key: string): boolean {
    const now = Date.now();
    if (!this.history.has(key)) this.history.set(key, []);
    const timestamps = this.history.get(key)!;
    while (timestamps.length && now - timestamps[0] > this.windowMillis) timestamps.shift();
    if (timestamps.length >= this.maxPerWindow) return false;
    timestamps.push(now);
    return true;
  }
}

// ---------- NotificationChannel (Strategy interface) ----------
interface NotificationChannel {
  send(content: RenderedContent, recipientAddress: string): DeliveryResult;
}

class EmailChannel implements NotificationChannel {
  send(content: RenderedContent, recipientAddress: string): DeliveryResult {
    console.log(`  [EMAIL -> ${recipientAddress}] ${content}`);
    return DeliveryResult.ok();
  }
}

// Simulates a transient failure: fails once per recipient, then succeeds.
class SMSChannel implements NotificationChannel {
  private readonly failedOnce = new Set<string>();
  send(content: RenderedContent, recipientAddress: string): DeliveryResult {
    if (!this.failedOnce.has(recipientAddress)) {
      this.failedOnce.add(recipientAddress);
      console.log(`  [SMS -> ${recipientAddress}] transient failure`);
      return DeliveryResult.fail('carrier timeout');
    }
    console.log(`  [SMS -> ${recipientAddress}] ${content}`);
    return DeliveryResult.ok();
  }
}

// Permanently broken provider, to demonstrate dead-lettering.
class PushChannel implements NotificationChannel {
  send(content: RenderedContent, recipientAddress: string): DeliveryResult {
    console.log(`  [PUSH -> ${recipientAddress}] provider unavailable`);
    return DeliveryResult.fail('device token invalid');
  }
}

// ---------- DeadLetterQueue ----------
class DeadLetterQueue {
  private readonly entriesList: string[] = [];
  record(notification: NotificationRecord, error: string): void {
    this.entriesList.push(`${notification.id} (${notification.retryChannel}): ${error}`);
    notification.status = Status.DEAD_LETTERED;
  }
  entries(): string[] { return this.entriesList; }
}

// ---------- RetryScheduler ----------
class RetryScheduler {
  private static readonly MAX_ATTEMPTS = 3;

  constructor(
    private readonly channels: Map<ChannelType, NotificationChannel>,
    private readonly deadLetterQueue: DeadLetterQueue
  ) {}

  // Simulates a delayed timer job synchronously for this demo (no real event loop needed).
  scheduleRetry(notification: NotificationRecord, attempt: number): void {
    const delayMs = this.backoff(attempt);
    console.log(`  retry scheduled for ${notification.id} attempt=${attempt} delay=${delayMs}ms`);
    this.onRetryDue(notification, attempt);
  }

  private onRetryDue(notification: NotificationRecord, attempt: number): void {
    const channel = this.channels.get(notification.retryChannel!)!;
    const result = channel.send(notification.retryContent!, notification.retryRecipient!);
    if (result.failed) {
      if (attempt >= RetryScheduler.MAX_ATTEMPTS) {
        this.deadLetterQueue.record(notification, result.error!);
      } else {
        this.scheduleRetry(notification, attempt + 1);
      }
    } else {
      notification.status = Status.SENT;
    }
  }

  private backoff(attempt: number): number { return 100 * Math.pow(2, attempt); }
}

// ---------- NotificationService (facade) ----------
class NotificationService {
  private readonly dedupeCache = new Set<string>();
  private counter = 0;

  constructor(
    private readonly templates: Map<string, NotificationTemplate>,
    private readonly userPreference: UserPreference,
    private readonly rateLimiter: RateLimiter,
    private readonly channels: Map<ChannelType, NotificationChannel>,
    private readonly retryScheduler: RetryScheduler
  ) {}

  notify(
    userId: string, category: Category, templateId: string, params: Record<string, unknown>,
    requestedChannels: ChannelType[], idempotencyKey: string
  ): NotificationRecord {
    const notification = new NotificationRecord(
      `N${++this.counter}`, userId, category, templateId, params, requestedChannels, idempotencyKey
    );

    if (this.dedupeCache.has(idempotencyKey)) { // idempotent replay guard
      console.log(`Skipping duplicate notify() for idemKey=${idempotencyKey}`);
      return notification;
    }

    const template = this.templates.get(templateId)!;
    for (const channel of requestedChannels) {
      if (!this.userPreference.isAllowed(userId, channel, category)) {
        console.log(`  ${channel} skipped: user opted out for ${category}`);
        continue;
      }
      if (!this.rateLimiter.tryAcquire(`${userId}|${channel}`)) {
        console.log(`  ${channel} skipped: rate limit exceeded`);
        continue;
      }
      const content = template.render(channel, params);
      const recipient = this.resolveAddress(userId, channel);
      const result = this.channels.get(channel)!.send(content, recipient);
      if (result.failed) {
        notification.status = Status.FAILED;
        notification.retryChannel = channel;
        notification.retryContent = content;
        notification.retryRecipient = recipient;
        this.retryScheduler.scheduleRetry(notification, 1);
      } else if (notification.status !== Status.SENT) {
        notification.status = Status.SENT;
      }
    }
    this.dedupeCache.add(idempotencyKey);
    return notification;
  }

  private resolveAddress(userId: string, channel: ChannelType): string {
    switch (channel) {
      case ChannelType.EMAIL: return `${userId}@example.com`;
      case ChannelType.SMS: return `+1-555-${userId}`;
      case ChannelType.PUSH: return `device-token-${userId}`;
      default: throw new Error(`Unknown channel: ${channel}`);
    }
  }
}

// ---------- Demo ----------
function main(): void {
  const welcome = new NotificationTemplate('welcome')
    .withSubject(ChannelType.EMAIL, 'Welcome, {{name}}!')
    .withBody(ChannelType.EMAIL, 'Hi {{name}}, thanks for joining.')
    .withBody(ChannelType.SMS, 'Hi {{name}}, welcome aboard!')
    .withBody(ChannelType.PUSH, 'Welcome, {{name}}!');
  const templates = new Map<string, NotificationTemplate>([['welcome', welcome]]);

  const preferences = new UserPreference();
