// Coffee Vending Machine -- full class-diagram implementation, single-threaded.
#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <memory>
#include <stdexcept>
#include <algorithm>

// ---------- Ingredient ----------
// One stocked ingredient; owns its own quantity so reserve/release/refill stay in one place.
class Ingredient {
public:
    std::string name;
    int quantity;
    int capacity;

    Ingredient(std::string name_, int quantity_, int capacity_)
        : name(std::move(name_)), quantity(quantity_), capacity(capacity_) {}

    // Atomic check-and-decrement: never lets quantity go negative.
    bool reserve(int qty) {
        if (quantity < qty) return false;
        quantity -= qty;
        return true;
    }
    void release(int qty) { quantity = std::min(capacity, quantity + qty); }
    void refill(int qty) { quantity = std::min(capacity, quantity + qty); }
};

// ---------- Recipe ----------
// Pure data: what a beverage needs and how much it costs. No computation.
struct Recipe {
    std::vector<std::pair<std::shared_ptr<Ingredient>, int>> requirements;
    int priceCents;
};

// ---------- Beverage ----------
// A sellable item. Composes its Recipe -- the recipe has no meaning outside the beverage.
struct Beverage {
    std::string name;
    Recipe recipe;
};

// ---------- PaymentStrategy (Strategy interface) ----------
struct PaymentStrategy {
    virtual ~PaymentStrategy() = default;
    virtual void charge(int amountCents) = 0;
    virtual void refund(int amountCents) = 0;
};

struct CashPayment : PaymentStrategy {
    int inserted = 0;
    void insert(int cents) { inserted += cents; }
    void charge(int amountCents) override {
        if (inserted < amountCents) throw std::runtime_error("Insufficient cash inserted");
        inserted -= amountCents;
        std::cout << "  [CASH] charged " << amountCents << "c, change=" << inserted << "c\n";
    }
    void refund(int amountCents) override {
        inserted += amountCents;
        std::cout << "  [CASH] refunded " << amountCents << "c\n";
    }
};

struct CardPayment : PaymentStrategy {
    void charge(int amountCents) override { std::cout << "  [CARD] charged " << amountCents << "c\n"; }
    void refund(int amountCents) override { std::cout << "  [CARD] refunded " << amountCents << "c\n"; }
};

class CoffeeMachine; // fwd decl

// ---------- CoffeeMachineState (State interface) ----------
struct CoffeeMachineState {
    virtual ~CoffeeMachineState() = default;
    virtual void selectBeverage(CoffeeMachine& ctx, std::shared_ptr<Beverage> b) = 0;
    virtual void insertPayment(CoffeeMachine& ctx, std::shared_ptr<PaymentStrategy> method, int amountCents) = 0;
    virtual void dispense(CoffeeMachine& ctx) = 0;
    virtual void cancel(CoffeeMachine& ctx) = 0;
};

// ---------- CoffeeMachine (context/facade) ----------
class CoffeeMachine {
public:
    std::shared_ptr<CoffeeMachineState> currentState;
    std::shared_ptr<CoffeeMachineState> idleState, selectingState, dispensingState, outOfStockState;

    std::map<std::string, std::shared_ptr<Ingredient>> ingredients;
    std::map<std::string, std::shared_ptr<Beverage>> beverages;
    std::shared_ptr<Beverage> selectedBeverage;
    std::shared_ptr<PaymentStrategy> paymentMethod;

    void setState(std::shared_ptr<CoffeeMachineState> state) { currentState = std::move(state); }
    void addIngredient(std::shared_ptr<Ingredient> ing) { ingredients[ing->name] = ing; }
    void addBeverage(std::shared_ptr<Beverage> b) { beverages[b->name] = b; }

    void select(std::shared_ptr<Beverage> b) { currentState->selectBeverage(*this, std::move(b)); }
    void pay(std::shared_ptr<PaymentStrategy> method, int amountCents) { currentState->insertPayment(*this, std::move(method), amountCents); }
    void dispense() { currentState->dispense(*this); }
    void cancel() { currentState->cancel(*this); }
    void refill(std::shared_ptr<Ingredient> ing, int qty) { ing->refill(qty); } // technician action, legal in any state

    // Reserve every required ingredient in sequence; on the first shortfall, roll back whatever
    // was already reserved, refund, and flip to OutOfStockState. Never dispenses a half-made drink.
    void dispenseNow() {
        Recipe& recipe = selectedBeverage->recipe;
        std::vector<std::pair<std::shared_ptr<Ingredient>, int>> reserved;
        for (auto& req : recipe.requirements) {
            if (!req.first->reserve(req.second)) {
                for (auto& r : reserved) r.first->release(r.second); // roll back
                paymentMethod->refund(recipe.priceCents);
                setState(outOfStockState);
                std::cout << "  Out of stock: missing " << req.first->name << " -- refunded and rolled back\n";
                return;
            }
            reserved.push_back(req);
        }
        std::cout << "  Pouring " << selectedBeverage->name << "...\n";
        selectedBeverage = nullptr;
        setState(idleState);
    }
};

struct IdleState : CoffeeMachineState {
    void selectBeverage(CoffeeMachine& ctx, std::shared_ptr<Beverage> b) override {
        ctx.selectedBeverage = b;
        ctx.setState(ctx.selectingState);
        std::cout << "  Selected " << b->name << " -- please pay " << b->recipe.priceCents << "c\n";
    }
    void insertPayment(CoffeeMachine&, std::shared_ptr<PaymentStrategy>, int) override {
        std::cout << "  Reject: select a beverage first\n";
    }
    void dispense(CoffeeMachine&) override { std::cout << "  Reject: nothing selected\n"; }
    void cancel(CoffeeMachine&) override { std::cout << "  Nothing to cancel\n"; }
};

struct SelectingState : CoffeeMachineState {
    void selectBeverage(CoffeeMachine&, std::shared_ptr<Beverage>) override { std::cout << "  Reject: already selecting\n"; }
    void insertPayment(CoffeeMachine& ctx, std::shared_ptr<PaymentStrategy> method, int amountCents) override {
        int price = ctx.selectedBeverage->recipe.priceCents;
        if (amountCents < price) { std::cout << "  Reject: insufficient payment\n"; return; }
        ctx.paymentMethod = method;
        method->charge(price);
        ctx.setState(ctx.dispensingState);
        std::cout << "  Payment accepted -> dispensing\n";
    }
    void dispense(CoffeeMachine&) override { std::cout << "  Reject: pay first\n"; }
    void cancel(CoffeeMachine& ctx) override {
        ctx.selectedBeverage = nullptr;
        ctx.setState(ctx.idleState);
        std::cout << "  Selection cancelled\n";
    }
};

struct DispensingState : CoffeeMachineState {
    void selectBeverage(CoffeeMachine&, std::shared_ptr<Beverage>) override { std::cout << "  Reject: already dispensing\n"; }
    void insertPayment(CoffeeMachine&, std::shared_ptr<PaymentStrategy>, int) override { std::cout << "  Reject: already paid\n"; }
    void dispense(CoffeeMachine& ctx) override { ctx.dispenseNow(); }
    void cancel(CoffeeMachine& ctx) override {
        ctx.paymentMethod->refund(ctx.selectedBeverage->recipe.priceCents);
        ctx.selectedBeverage = nullptr;
        ctx.setState(ctx.idleState);
        std::cout << "  Cancelled after payment; refunded\n";
    }
};

struct OutOfStockState : CoffeeMachineState {
    void selectBeverage(CoffeeMachine&, std::shared_ptr<Beverage>) override { std::cout << "  Reject: machine out of stock\n"; }
    void insertPayment(CoffeeMachine&, std::shared_ptr<PaymentStrategy>, int) override { std::cout << "  Reject: machine out of stock\n"; }
    void dispense(CoffeeMachine&) override { std::cout << "  Reject: machine out of stock\n"; }
    void cancel(CoffeeMachine& ctx) override {
        ctx.selectedBeverage = nullptr;
        ctx.setState(ctx.idleState);
        std::cout << "  Reset from out-of-stock -> idle\n";
    }
};

int main() {
    CoffeeMachine machine;
    machine.idleState = std::make_shared<IdleState>();
    machine.selectingState = std::make_shared<SelectingState>();
    machine.dispensingState = std::make_shared<DispensingState>();
    machine.outOfStockState = std::make_shared<OutOfStockState>();
    machine.currentState = machine.idleState;

    auto water = std::make_shared<Ingredient>("water", 500, 1000);
