// Coffee Vending Machine -- full class-diagram implementation, single-threaded.

// ---------- Ingredient ----------
// One stocked ingredient; owns its own quantity so reserve/release/refill stay in one place.
class Ingredient {
  quantity: number;
  constructor(public readonly name: string, quantity: number, public readonly capacity: number) {
    this.quantity = quantity;
  }
  // Atomic check-and-decrement: never lets quantity go negative.
  reserve(qty: number): boolean {
    if (this.quantity < qty) return false;
    this.quantity -= qty;
    return true;
  }
  release(qty: number): void { this.quantity = Math.min(this.capacity, this.quantity + qty); }
  refill(qty: number): void { this.quantity = Math.min(this.capacity, this.quantity + qty); }
  toString(): string { return `${this.name}(${this.quantity}/${this.capacity})`; }
}

// ---------- Recipe ----------
// Pure data: what a beverage needs and how much it costs. No computation.
class Recipe {
  constructor(public readonly requirements: Map<Ingredient, number>, public readonly priceCents: number) {}
}

// ---------- Beverage ----------
// A sellable item. Composes its Recipe -- the recipe has no meaning outside the beverage.
class Beverage {
  constructor(public readonly name: string, public readonly recipe: Recipe) {}
  toString(): string { return this.name; }
}

// ---------- PaymentStrategy (Strategy interface) ----------
interface PaymentStrategy {
  charge(amountCents: number): void;
  refund(amountCents: number): void;
}

class CashPayment implements PaymentStrategy {
  inserted = 0;
  insert(cents: number): void { this.inserted += cents; }
  charge(amountCents: number): void {
    if (this.inserted < amountCents) throw new Error('Insufficient cash inserted');
    this.inserted -= amountCents;
    console.log(`  [CASH] charged ${amountCents}c, change=${this.inserted}c`);
  }
  refund(amountCents: number): void {
    this.inserted += amountCents;
    console.log(`  [CASH] refunded ${amountCents}c`);
  }
}

