// ---------- Directory (composite) ----------
class Directory extends FileSystemNode {
  readonly children = new Map<string, FileSystemNode>();
  constructor(name: string, parent: Directory | null) { super(name, parent); }
  addChild(node: FileSystemNode): void { this.children.set(node.name, node); }
  removeChild(name: string): void { this.children.delete(name); }
  getChild(name: string): FileSystemNode | undefined { return this.children.get(name); }
  accept(visitor: NodeVisitor): void { visitor.visitDirectory(this); }
