}

type SearchCriteria = (node: FileSystemNode) => boolean;

class SearchVisitor implements NodeVisitor {
  private readonly matches: Path[] = [];
  constructor(private readonly criteria: SearchCriteria, private readonly base: Path) {}

  search(node: FileSystemNode): Path[] { this.walk(node, this.base); return this.matches; }
  visitFile(_f: FileNode): void {}      // traversal is driven by walk(), not the visitor dispatch
  visitDirectory(_d: Directory): void {}

  private walk(node: FileSystemNode, path: Path): void {
    if (this.criteria(node)) this.matches.push(path);
    if (node instanceof Directory) {
      const it = new DirectoryIterator(node);
      while (it.hasNext()) {
        const child = it.next();
        this.walk(child, path.resolveChild(child.name));
      }
    }
  }
}

// ---------- VirtualFileSystem (facade) ----------
class VirtualFileSystem {
  readonly root = new Directory('', null);

  private resolveParent(path: Path): Directory {
    let current = this.root;
    for (let i = 0; i < path.segments.length - 1; i++) {
      const next = current.getChild(path.segments[i]);
      if (!(next instanceof Directory)) throw new Error(`No such directory: ${path}`);
      current = next;
    }
    return current;
  }

  private resolve(path: Path): FileSystemNode {
    if (path.segments.length === 0) return this.root;
    const parentDir = this.resolveParent(path);
    const node = parentDir.getChild(path.lastSegment());
    if (!node) throw new Error(`No such path: ${path}`);
    return node;
  }

  createFile(path: Path): void {
    const parentDir = this.resolveParent(path);
    parentDir.addChild(new FileNode(path.lastSegment(), parentDir));
  }

  createDirectory(path: Path): void {
    const parentDir = this.resolveParent(path);
    parentDir.addChild(new Directory(path.lastSegment(), parentDir));
  }

  delete(path: Path, recursive: boolean): void {
    const parentDir = this.resolveParent(path);
    const node = parentDir.getChild(path.lastSegment());
    if (node instanceof Directory && node.children.size > 0 && !recursive) {
      throw new Error(`Directory not empty; pass recursive=true to delete: ${path}`);
    }
    parentDir.removeChild(path.lastSegment());
  }

  read(path: Path): string {
    const node = this.resolve(path);
    if (!(node instanceof FileNode)) throw new Error(`Not a file: ${path}`);
    return node.read();
  }

  write(path: Path, data: string): void {
    const node = this.resolve(path);
    if (!(node instanceof FileNode)) throw new Error(`Not a file: ${path}`);
    node.write(data);
  }

  list(directoryPath: Path): string[] {
    const node = this.resolve(directoryPath);
    if (!(node instanceof Directory)) throw new Error(`Not a directory: ${directoryPath}`);
    const names: string[] = [];
    const it = new DirectoryIterator(node);
    while (it.hasNext()) names.push(it.next().name);
    return names;
  }

  // Move source under destination's parent (destination's last segment becomes the new name).
  // Guards against moving a directory into its own subtree. No real threads exist in this
  // single-threaded translation, so canonical-path lock ordering is left as commentary only --
  // this is where a two-mutex ABBA-safe acquisition would go under a concurrent implementation.
  move(source: Path, destination: Path): void {
    const srcParent = this.resolveParent(source);
    const destParent = this.resolveParent(destination);
    const node = srcParent.getChild(source.lastSegment());
    if (!node) throw new Error(`No such path: ${source}`);

    if (node instanceof Directory && destination.isDescendantOf(source)) {
      throw new Error('cannot move a directory into its own subtree');
    }

    // lock ordering would be established here by canonical path in a concurrent version
    srcParent.removeChild(node.name);
    node.name = destination.lastSegment();
    node.parent = destParent;
    destParent.addChild(node);
  }

  search(startPath: Path, criteria: SearchCriteria): Path[] {
    const startNode = this.resolve(startPath);
    return new SearchVisitor(criteria, startPath).search(startNode);
  }

  diskUsage(startPath: Path): number {
    const startNode = this.resolve(startPath);
    return new DiskUsageVisitor().compute(startNode);
  }
}

// ---------- Demo ----------
function main(): void {
  const fs = new VirtualFileSystem();
  fs.createDirectory(Path.of('/docs'));
  fs.createDirectory(Path.of('/docs/reports'));
  fs.createFile(Path.of('/docs/readme.txt'));
  fs.createFile(Path.of('/docs/reports/q1.csv'));
  fs.createFile(Path.of('/docs/reports/q2.csv'));
  fs.createDirectory(Path.of('/media'));

  fs.write(Path.of('/docs/readme.txt'), 'hello world');
  fs.write(Path.of('/docs/reports/q1.csv'), 'a,b,c\n1,2,3');
  fs.write(Path.of('/docs/reports/q2.csv'), 'x,y,z\n4,5,6\n7,8,9');

  console.log('Listing /docs:', fs.list(Path.of('/docs')));
  console.log('Listing /docs/reports:', fs.list(Path.of('/docs/reports')));

  console.log('Read /docs/readme.txt:', fs.read(Path.of('/docs/readme.txt')));
  console.log('Disk usage of /docs:', fs.diskUsage(Path.of('/docs')), 'bytes');

  const csvFiles = fs.search(Path.of('/docs'), (node) => node instanceof FileNode && node.name.endsWith('.csv'));
  console.log('Search *.csv under /docs:', csvFiles.map(String));

  console.log('\nMoving /docs/reports -> /media/reports');
  fs.move(Path.of('/docs/reports'), Path.of('/media/reports'));
  console.log('Listing /media:', fs.list(Path.of('/media')));
  console.log('Listing /docs after move:', fs.list(Path.of('/docs')));

  try {
    fs.move(Path.of('/media'), Path.of('/media/reports/media'));
  } catch (e) {
    console.log('\nExpected rejection moving a directory into its own subtree:', (e as Error).message);
  }

  try {
    fs.delete(Path.of('/media'), false);
  } catch (e) {
    console.log('Expected rejection deleting non-empty dir without recursive:', (e as Error).message);
  }
  fs.delete(Path.of('/media'), true);
  console.log('Root listing after recursive delete of /media:', fs.list(Path.of('')));
}

