    // ---------- Subscriber (interface) ----------
    /** Business logic for handling one message. Must be idempotent (at-least-once delivery). */
    interface Subscriber {
        void onMessage(Message message) throws Exception;
    }

    // ---------- OverflowPolicy (Strategy interface) ----------
    /** What happens when a subscriber's queue is full. */
    interface OverflowPolicy {
        void onOverflow(Subscription subscription, Message incoming);
    }

    /** Drop the oldest queued message to make room for the incoming one. */
    static final class DropOldest implements OverflowPolicy {
        @Override
        public void onOverflow(Subscription subscription, Message incoming) {
            subscription.queue.poll();               // discard oldest
            subscription.queue.offer(incoming);       // make room for the new message
        }
    }

    /** Block the publishing thread until space is available (backpressure). */
    static final class BlockPublisher implements OverflowPolicy {
        @Override
        public void onOverflow(Subscription subscription, Message incoming) {
            try {
                subscription.queue.put(incoming);      // blocks caller thread until room frees up
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    /** Simply drop the new incoming message, keeping what's already queued. */
    static final class DropNewest implements OverflowPolicy {
        @Override
        public void onOverflow(Subscription subscription, Message incoming) {
            // intentionally no-op: newest message is dropped
        }
    }

    // ---------- DeadLetterQueue ----------
    /** Holds messages that exhausted their retry budget. Reprocessing is manual/operator-triggered. */
    static final class DeadLetterQueue {
        private final List<String> entries = new CopyOnWriteArrayList<>();

        void add(Message message, String reason) {
            entries.add(message.id + " :: " + reason);
        }

        List<String> entries() {
            return entries;
        }
    }

    // ---------- Subscription ----------
    /** Per-subscriber delivery state on a topic: bounded queue, ack/retry tracking, background consumer. */
    static final class Subscription {
        private static final int MAX_RETRIES = 3;
        private static final int CAPACITY = 16;

        final String id = UUID.randomUUID().toString();
        final BlockingQueue<Message> queue = new ArrayBlockingQueue<>(CAPACITY);
        private final Subscriber subscriber;
        private final OverflowPolicy overflowPolicy;
        private final DeadLetterQueue deadLetterQueue;
        private final Map<String, Message> inFlight = new ConcurrentHashMap<>();
        private final Map<String, AtomicInteger> retryCount = new ConcurrentHashMap<>();
        private volatile boolean running = true;
        private Thread consumerThread;

        Subscription(Subscriber subscriber, OverflowPolicy overflowPolicy, DeadLetterQueue dlq) {
            this.subscriber = subscriber;
            this.overflowPolicy = overflowPolicy;
            this.deadLetterQueue = dlq;
        }

        /** Try to enqueue; on a full queue delegate to the overflow policy. */
        void enqueue(Message message) {
            if (!queue.offer(message)) {
                overflowPolicy.onOverflow(this, message);
            }
        }

        void start() {
            consumerThread = new Thread(this::consumeLoop, "sub-" + id.substring(0, 8));
            consumerThread.setDaemon(true);
            consumerThread.start();
