        void stop() {
            running = false;
            if (consumerThread != null) consumerThread.interrupt();
        }

        /** One consumer loop per subscriber, running on its own background thread. */
        private void consumeLoop() {
            while (running) {
                try {
                    Message message = queue.poll(200, TimeUnit.MILLISECONDS);
                    if (message == null) continue;
                    inFlight.put(message.id, message);
                    try {
                        subscriber.onMessage(message);   // must be idempotent -- may be a redelivery
                        ack(message.id);
                    } catch (Exception e) {
                        nack(message.id);
                    }
