                    if (!running) break;
                }
            }
        }

        void ack(String messageId) {
            inFlight.remove(messageId);
            retryCount.remove(messageId);
        }

        void nack(String messageId) {
            Message message = inFlight.remove(messageId);
            if (message == null) return;
            int attempts = retryCount.computeIfAbsent(messageId, k -> new AtomicInteger(0))
                    .incrementAndGet();
            if (attempts > MAX_RETRIES) {
                deadLetterQueue.add(message, "retry exhausted");
                retryCount.remove(messageId);
            } else {
                enqueue(message);   // redeliver -- subscriber will see this message again
            }
        }
    }

    // ---------- Topic ----------
    /** A named channel; owns its subscriber list and fans out on publish. */
    static final class Topic {
        final String name;
        private final List<Subscription> subscriptions = new CopyOnWriteArrayList<>();

        Topic(String name) {
            this.name = name;
        }

        Subscription subscribe(Subscriber subscriber, OverflowPolicy policy, DeadLetterQueue dlq) {
            Subscription subscription = new Subscription(subscriber, policy, dlq);
            subscriptions.add(subscription);
            subscription.start();
            return subscription;
        }

        void unsubscribe(Subscription subscription) {
            subscriptions.remove(subscription);
            subscription.stop();
        }

        /** Fan out to every subscription's own bounded queue -- never calls the subscriber inline. */
        void publish(Message message) {
            for (Subscription subscription : subscriptions) {
                subscription.enqueue(message);
            }
        }
    }

    // ---------- Broker (facade) ----------
    /** Owns all topics; top-level publish/subscribe entry point. */
    static final class Broker {
        private final Map<String, Topic> topics = new ConcurrentHashMap<>();
        private final DeadLetterQueue deadLetterQueue = new DeadLetterQueue();

        Topic createTopic(String name) {
            return topics.computeIfAbsent(name, Topic::new);
        }

        void publish(String topicName, Message message) {
            Topic topic = topics.get(topicName);
            if (topic == null) throw new IllegalArgumentException("No such topic: " + topicName);
            topic.publish(message);
        }

        Subscription subscribe(String topicName, Subscriber subscriber, OverflowPolicy policy) {
            Topic topic = topics.get(topicName);
            if (topic == null) throw new IllegalArgumentException("No such topic: " + topicName);
            return topic.subscribe(subscriber, policy, deadLetterQueue);
        }

        void unsubscribe(String topicName, Subscription subscription) {
            Topic topic = topics.get(topicName);
            if (topic != null) topic.unsubscribe(subscription);
        }

        DeadLetterQueue deadLetterQueue() {
            return deadLetterQueue;
        }
    }

    // ---------- Demo ----------
    public static void main(String[] args) throws InterruptedException {
        Broker broker = new Broker();
        broker.createTopic("orders");

        List<String> fastReceived = new CopyOnWriteArrayList<>();
        Subscriber fastSubscriber = msg -> fastReceived.add(msg.payload);

        // Always fails for one specific message id to deterministically exercise
        // the retry -> dead-letter path while other messages succeed normally.
        Subscriber flakySubscriber = msg -> {
            if (msg.id.equals("m2")) {
                throw new RuntimeException("permanent failure for m2");
            }
        };

        broker.subscribe("orders", fastSubscriber, new DropOldest());
        broker.subscribe("orders", flakySubscriber, new DropOldest());

