            broker.publish("orders", new Message("m" + i, "order-" + i, "p0"));
        }

        Thread.sleep(1000);

        System.out.println("Fast subscriber received: " + fastReceived);
        System.out.println("Dead letters: " + broker.deadLetterQueue().entries());
    }
