// Pub-Sub / Message Queue -- full class-diagram implementation.
//
// Broker owns Topics; a Topic owns Subscriptions (one per Subscriber); each Subscription
// has its own bounded queue + background consumer thread so a slow subscriber can never
// block the publisher or other subscribers.

#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <unordered_map>
#include <deque>
#include <memory>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <chrono>
#include <functional>
#include <sstream>
#include <algorithm>
#include <stdexcept>

// ---------- Message ----------
struct Message {
    std::string id;
    std::string payload;
    std::string partitionKey;
    long long timestamp;

    Message(std::string id_, std::string payload_, std::string partitionKey_)
        : id(std::move(id_)), payload(std::move(payload_)), partitionKey(std::move(partitionKey_)) {
        timestamp = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();
    }
};

// ---------- Subscriber (interface) ----------
// Business logic for handling one message. Must be idempotent (at-least-once delivery).
struct Subscriber {
    virtual ~Subscriber() = default;
    virtual void onMessage(const Message& message) = 0; // throws on failure
};

class Subscription; // fwd decl

// ---------- OverflowPolicy (Strategy interface) ----------
struct OverflowPolicy {
    virtual ~OverflowPolicy() = default;
    virtual void onOverflow(Subscription& subscription, const Message& incoming) = 0;
};

// ---------- DeadLetterQueue ----------
class DeadLetterQueue {
    std::mutex mtx;
    std::vector<std::string> entries_;
public:
    void add(const Message& message, const std::string& reason) {
        std::lock_guard<std::mutex> lock(mtx);
        entries_.push_back(message.id + " :: " + reason);
    }
    std::vector<std::string> entries() {
        std::lock_guard<std::mutex> lock(mtx);
        return entries_;
    }
};

// ---------- Subscription ----------
// Per-subscriber delivery state on a topic: bounded queue, ack/retry tracking, background consumer.
class Subscription {
public:
    static const size_t CAPACITY = 16;
    static const int MAX_RETRIES = 3;

    std::string id;
    std::deque<Message> queue;
    std::mutex queueMutex;
    std::condition_variable queueCv;

    Subscription(std::shared_ptr<Subscriber> subscriber,
                 std::shared_ptr<OverflowPolicy> overflowPolicy,
                 std::shared_ptr<DeadLetterQueue> dlq,
                 std::string subId)
        : id(std::move(subId)), subscriber_(std::move(subscriber)),
          overflowPolicy_(std::move(overflowPolicy)), deadLetterQueue_(std::move(dlq)) {}

    ~Subscription() { stop(); }

    // Try to enqueue; on a full queue delegate to the overflow policy.
    void enqueue(const Message& message) {
        std::unique_lock<std::mutex> lock(queueMutex);
        if (queue.size() < CAPACITY) {
            queue.push_back(message);
            lock.unlock();
            queueCv.notify_one();
        } else {
            lock.unlock();
            overflowPolicy_->onOverflow(*this, message);   // policy may itself re-lock and enqueue
        }
    }

    // Raw push used only by overflow policies that already decided to bypass capacity checks.
    void forcePush(const Message& message) {
        std::unique_lock<std::mutex> lock(queueMutex);
        queue.push_back(message);
        lock.unlock();
        queueCv.notify_one();
    }

    void popOldest() {
        std::lock_guard<std::mutex> lock(queueMutex);
        if (!queue.empty()) queue.pop_front();
    }

    void start() {
        running_ = true;
        thread_ = std::thread(&Subscription::consumeLoop, this);
    }

    void stop() {
        if (!running_) return;
        running_ = false;
        queueCv.notify_all();
        if (thread_.joinable()) thread_.join();
    }

    void ack(const std::string& messageId) {
        std::lock_guard<std::mutex> lock(stateMutex_);
        inFlight_.erase(messageId);
        retryCount_.erase(messageId);
    }

    void nack(const std::string& messageId) {
        std::lock_guard<std::mutex> lock(stateMutex_);
        auto it = inFlight_.find(messageId);
        if (it == inFlight_.end()) return;
        Message message = it->second;
        inFlight_.erase(it);
        int attempts = ++retryCount_[messageId];
        if (attempts > MAX_RETRIES) {
            deadLetterQueue_->add(message, "retry exhausted");
            retryCount_.erase(messageId);
        } else {
            enqueue(message);   // redeliver -- subscriber will see this message again
        }
    }

private:
    std::shared_ptr<Subscriber> subscriber_;
    std::shared_ptr<OverflowPolicy> overflowPolicy_;
    std::shared_ptr<DeadLetterQueue> deadLetterQueue_;
    std::atomic<bool> running_{false};
    std::thread thread_;

    std::mutex stateMutex_;
    std::unordered_map<std::string, Message> inFlight_;
    std::unordered_map<std::string, int> retryCount_;

    // One consumer loop per subscriber, running on its own background thread.
    void consumeLoop() {
        while (running_) {
            Message message("", "", "");
            bool got = false;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                queueCv.wait_for(lock, std::chrono::milliseconds(200),
                                  [this] { return !queue.empty() || !running_; });
                if (!queue.empty()) {
                    message = queue.front();
                    queue.pop_front();
                    got = true;
                }
            }
            if (!got) continue;
            {
                std::lock_guard<std::mutex> lock(stateMutex_);
                inFlight_.emplace(message.id, message);
            }
            try {
                subscriber_->onMessage(message);   // must be idempotent -- may be a redelivery
                ack(message.id);
            } catch (...) {
                nack(message.id);
            }
        }
    }
};

// Drop the oldest queued message to make room for the incoming one.
struct DropOldest : OverflowPolicy {
    void onOverflow(Subscription& subscription, const Message& incoming) override {
        subscription.popOldest();
        subscription.forcePush(incoming);
    }
};

// Block the publishing thread until space is available (backpressure).
struct BlockPublisher : OverflowPolicy {
    void onOverflow(Subscription& subscription, const Message& incoming) override {
        std::unique_lock<std::mutex> lock(subscription.queueMutex);
        subscription.queueCv.wait(lock, [&] { return subscription.queue.size() < Subscription::CAPACITY; });
        subscription.queue.push_back(incoming);
        lock.unlock();
        subscription.queueCv.notify_one();
    }
};

// Simply drop the new incoming message, keeping what's already queued.
struct DropNewest : OverflowPolicy {
    void onOverflow(Subscription& subscription, const Message& incoming) override {
        (void)subscription; (void)incoming; // intentionally no-op
    }
};

// ---------- Topic ----------
// A named channel; owns its subscriber list and fans out on publish.
class Topic {
public:
    std::string name;
    explicit Topic(std::string name_) : name(std::move(name_)) {}

    std::shared_ptr<Subscription> subscribe(std::shared_ptr<Subscriber> subscriber,
                                             std::shared_ptr<OverflowPolicy> policy,
                                             std::shared_ptr<DeadLetterQueue> dlq) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto sub = std::make_shared<Subscription>(subscriber, policy, dlq,
                                                    "sub" + std::to_string(nextId_++));
        subscriptions_.push_back(sub);
        sub->start();
        return sub;
    }

    void unsubscribe(const std::shared_ptr<Subscription>& subscription) {
        std::lock_guard<std::mutex> lock(mtx_);
        subscription->stop();
        subscriptions_.erase(std::remove(subscriptions_.begin(), subscriptions_.end(), subscription),
                              subscriptions_.end());
    }

    // Fan out to every subscription's own bounded queue -- never calls the subscriber inline.
    void publish(const Message& message) {
        std::vector<std::shared_ptr<Subscription>> snapshot;
        {
            std::lock_guard<std::mutex> lock(mtx_);
            snapshot = subscriptions_;
        }
        for (auto& sub : snapshot) sub->enqueue(message);
    }

private:
    std::mutex mtx_;
    std::vector<std::shared_ptr<Subscription>> subscriptions_;
    int nextId_ = 0;
};

// ---------- Broker (facade) ----------
// Owns all topics; top-level publish/subscribe entry point.
class Broker {
public:
    Broker() : deadLetterQueue_(std::make_shared<DeadLetterQueue>()) {}

    std::shared_ptr<Topic> createTopic(const std::string& name) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = topics_.find(name);
        if (it != topics_.end()) return it->second;
        auto topic = std::make_shared<Topic>(name);
        topics_[name] = topic;
        return topic;
    }

    void publish(const std::string& topicName, const Message& message) {
        auto topic = getTopic(topicName);
        topic->publish(message);
    }

    std::shared_ptr<Subscription> subscribe(const std::string& topicName,
                                             std::shared_ptr<Subscriber> subscriber,
                                             std::shared_ptr<OverflowPolicy> policy) {
        auto topic = getTopic(topicName);
        return topic->subscribe(subscriber, policy, deadLetterQueue_);
    }

    void unsubscribe(const std::string& topicName, const std::shared_ptr<Subscription>& subscription) {
        auto topic = getTopic(topicName);
        topic->unsubscribe(subscription);
    }

    std::shared_ptr<DeadLetterQueue> deadLetterQueue() { return deadLetterQueue_; }

private:
    std::mutex mtx_;
    std::map<std::string, std::shared_ptr<Topic>> topics_;
    std::shared_ptr<DeadLetterQueue> deadLetterQueue_;

    std::shared_ptr<Topic> getTopic(const std::string& name) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = topics_.find(name);
        if (it == topics_.end()) throw std::invalid_argument("No such topic: " + name);
        return it->second;
    }
};

// ---------- Demo subscribers ----------
struct FastSubscriber : Subscriber {
