// Always fails for one specific message id to deterministically exercise
// the retry -> dead-letter path while other messages succeed normally.
struct FlakySubscriber : Subscriber {
    void onMessage(const Message& message) override {
        if (message.id == "m2") throw std::runtime_error("permanent failure for m2");
    }
