    broker.createTopic("orders");

    auto fast = std::make_shared<FastSubscriber>();
    auto flaky = std::make_shared<FlakySubscriber>();

    broker.subscribe("orders", fast, std::make_shared<DropOldest>());
    broker.subscribe("orders", flaky, std::make_shared<DropOldest>());

    for (int i = 0; i < 5; i++) {
        broker.publish("orders", Message("m" + std::to_string(i), "order-" + std::to_string(i), "p0"));
    }

    std::this_thread::sleep_for(std::chrono::milliseconds(1000));

    std::cout << "Fast subscriber received: ";
    for (auto& p : fast->received) std::cout << p << " ";
    std::cout << "\n";

    std::cout << "Dead letters: ";
    for (auto& e : broker.deadLetterQueue()->entries()) std::cout << e << " | ";
    std::cout << "\n";

    return 0;
