const { randomUUID } = require('crypto');

// ---------- Message ----------
class Message {
  constructor(id, payload, partitionKey) {
    this.id = id;
    this.payload = payload;
    this.partitionKey = partitionKey;
    this.timestamp = Date.now();
  }
}

// ---------- OverflowPolicy (Strategy interface) ----------
class OverflowPolicy {
  onOverflow(_subscription, _incoming) {
    throw new Error('not implemented');
  }
}

class DropOldest extends OverflowPolicy {
  onOverflow(subscription, incoming) {
    subscription.queue.shift();     // discard oldest
    subscription.queue.push(incoming);
  }
}

class DropNewest extends OverflowPolicy {
  onOverflow(_subscription, _incoming) {
    // intentionally no-op: newest message is dropped
  }
}

class BlockPublisher extends OverflowPolicy {
  onOverflow(subscription, incoming) {
    // No real OS blocking available in single-threaded JS; approximate
    // backpressure by force-pushing past capacity (publisher "waits its turn"
    // conceptually -- the queue will drain before growing further).
    subscription.queue.push(incoming);
  }
}

