/**
 * Pub-Sub / Message Queue -- full class-diagram implementation.
 *
 * Broker owns Topics; a Topic owns Subscriptions (one per Subscriber); each Subscription
 * has its own bounded queue + async consumption loop so a slow subscriber can never
 * block the publisher or other subscribers (decoupling publish() from consumption).
 */

import { randomUUID } from 'crypto';

// ---------- Message ----------
class Message {
  readonly timestamp: number;
  constructor(
    readonly id: string,
    readonly payload: string,
    readonly partitionKey: string,
  ) {
    this.timestamp = Date.now();
  }
}

// ---------- Subscriber (interface) ----------
interface Subscriber {
  onMessage(message: Message): void | Promise<void>;
}

// ---------- OverflowPolicy (Strategy interface) ----------
interface OverflowPolicy {
  onOverflow(subscription: Subscription, incoming: Message): void;
}

class DropOldest implements OverflowPolicy {
  onOverflow(subscription: Subscription, incoming: Message): void {
    subscription.queue.shift();
    subscription.queue.push(incoming);
  }
}

class DropNewest implements OverflowPolicy {
  onOverflow(_subscription: Subscription, _incoming: Message): void {
    // intentionally no-op: newest message is dropped
  }
}

class BlockPublisher implements OverflowPolicy {
  onOverflow(subscription: Subscription, incoming: Message): void {
    // Single-threaded JS has no real blocking primitive; approximate
    // backpressure by force-pushing -- the queue drains before growing further.
    subscription.queue.push(incoming);
  }
}

// ---------- DeadLetterQueue ----------
class DeadLetterQueue {
  private readonly _entries: string[] = [];

  add(message: Message, reason: string): void {
    this._entries.push(`${message.id} :: ${reason}`);
  }

  entries(): string[] {
    return this._entries;
  }
}

// ---------- Subscription ----------
const CAPACITY = 16;
const MAX_RETRIES = 3;

class Subscription {
  readonly id: string = randomUUID();
  readonly queue: Message[] = [];
  private readonly inFlight = new Map<string, Message>();
  private readonly retryCount = new Map<string, number>();
  private running = false;

  constructor(
    private readonly subscriber: Subscriber,
    private readonly overflowPolicy: OverflowPolicy,
    private readonly deadLetterQueue: DeadLetterQueue,
  ) {}

  /** Try to enqueue; on a full queue delegate to the overflow policy. */
  enqueue(message: Message): void {
    if (this.queue.length < CAPACITY) {
      this.queue.push(message);
    } else {
      this.overflowPolicy.onOverflow(this, message);
    }
  }

  start(): void {
    this.running = true;
    this.scheduleNext();
  }

  stop(): void {
    this.running = false;
  }

  private scheduleNext(): void {
    if (!this.running) return;
    setImmediate(() => this.consumeOne());
  }

  /** One "tick" of the consumer loop -- pulls one message and processes it. */
  private async consumeOne(): Promise<void> {
    if (!this.running) return;
    const message = this.queue.shift();
    if (!message) {
      this.scheduleNext();
      return;
    }
    this.inFlight.set(message.id, message);
    try {
      await this.subscriber.onMessage(message); // must be idempotent -- may be a redelivery
      this.ack(message.id);
    } catch {
      this.nack(message.id);
    }
    this.scheduleNext();
  }

  ack(messageId: string): void {
    this.inFlight.delete(messageId);
    this.retryCount.delete(messageId);
  }

  nack(messageId: string): void {
    const message = this.inFlight.get(messageId);
    this.inFlight.delete(messageId);
    if (!message) return;
    const attempts = (this.retryCount.get(messageId) ?? 0) + 1;
    this.retryCount.set(messageId, attempts);
    if (attempts > MAX_RETRIES) {
      this.deadLetterQueue.add(message, 'retry exhausted');
      this.retryCount.delete(messageId);
    } else {
      this.enqueue(message); // redeliver -- subscriber will see this message again
    }
  }
}

// ---------- Topic ----------
class Topic {
  private subscriptions: Subscription[] = [];

  constructor(readonly name: string) {}

  subscribe(subscriber: Subscriber, policy: OverflowPolicy, dlq: DeadLetterQueue): Subscription {
    const subscription = new Subscription(subscriber, policy, dlq);
    this.subscriptions.push(subscription);
    subscription.start();
    return subscription;
  }

  unsubscribe(subscription: Subscription): void {
    subscription.stop();
    this.subscriptions = this.subscriptions.filter((s) => s !== subscription);
  }

  /** Fan out to every subscription's own bounded queue -- never calls the subscriber inline. */
  publish(message: Message): void {
    for (const subscription of this.subscriptions) {
      subscription.enqueue(message);
    }
  }
}

// ---------- Broker (facade) ----------
class Broker {
  private readonly topics = new Map<string, Topic>();
  private readonly _deadLetterQueue = new DeadLetterQueue();

  createTopic(name: string): Topic {
    if (!this.topics.has(name)) this.topics.set(name, new Topic(name));
    return this.topics.get(name)!;
  }

  private getTopic(name: string): Topic {
    const topic = this.topics.get(name);
    if (!topic) throw new Error(`No such topic: ${name}`);
    return topic;
  }

  publish(topicName: string, message: Message): void {
    this.getTopic(topicName).publish(message);
  }

  subscribe(topicName: string, subscriber: Subscriber, policy: OverflowPolicy): Subscription {
    return this.getTopic(topicName).subscribe(subscriber, policy, this._deadLetterQueue);
  }

  unsubscribe(topicName: string, subscription: Subscription): void {
    this.getTopic(topicName).unsubscribe(subscription);
  }

  deadLetterQueue(): DeadLetterQueue {
    return this._deadLetterQueue;
  }
}

// ---------- Demo ----------
function main(): void {
  const broker = new Broker();
  broker.createTopic('orders');

  const fastReceived: string[] = [];
  const fastSubscriber: Subscriber = {
    onMessage: (msg) => {
      fastReceived.push(msg.payload);
    },
  };

  // Always fails for one specific message id to deterministically exercise
  // the retry -> dead-letter path while other messages succeed normally.
  const flakySubscriber: Subscriber = {
    onMessage: (msg) => {
      if (msg.id === 'm2') throw new Error('permanent failure for m2');
    },
  };

  broker.subscribe('orders', fastSubscriber, new DropOldest());
  broker.subscribe('orders', flakySubscriber, new DropOldest());

  for (let i = 0; i < 5; i++) {
    broker.publish('orders', new Message(`m${i}`, `order-${i}`, 'p0'));
  }

  setTimeout(() => {
    console.log('Fast subscriber received:', fastReceived);
    console.log('Dead letters:', broker.deadLetterQueue().entries());
  }, 500);
}

if (require.main === module) {
  main();
}

export {
  Message, Subscriber, Topic, Broker, Subscription,
  OverflowPolicy, DropOldest, DropNewest, BlockPublisher, DeadLetterQueue,
};

