import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.*;

/**
 * Elevator System — full class-diagram implementation.
 *
 * Elevator delegates behavior to its current ElevatorState (State pattern) so illegal
 * transitions (e.g. opening doors while moving) are structurally unrepresentable.
 * Dispatcher uses a swappable DispatchStrategy to select a candidate elevator, then
 * atomically claims the hall call under a per-elevator lock (closing the check-then-act
 * gap between "selected" and "claimed").
 */
public class p11 {

    enum Direction { UP, DOWN, IDLE }
    enum DoorState { OPEN, CLOSED }

    // ---------- Value objects ----------
    static final class HallCall {
        final int floor;
        final Direction direction;
        HallCall(int floor, Direction direction) { this.floor = floor; this.direction = direction; }
    }

    static final class CarCall {
        final int destinationFloor;
        CarCall(int destinationFloor) { this.destinationFloor = destinationFloor; }
    }

    // ---------- ElevatorState (interface, State pattern) ----------
    interface ElevatorState {
        void handleArrival(Elevator e);
        boolean canOpenDoor();
        String name();
    }

    static final class IdleState implements ElevatorState {
        @Override public void handleArrival(Elevator e) { /* nothing pending; stays idle */ }
        @Override public boolean canOpenDoor() { return true; }
        @Override public String name() { return "IDLE"; }
    }

    static final class MovingState implements ElevatorState {
        @Override public void handleArrival(Elevator e) {
            // The cabin reports arrival at a floor it must serve -> transition to DoorsOpenState.
            e.setState(new DoorsOpenState());
            e.openDoor();
        }
        @Override public boolean canOpenDoor() { return false; } // cannot open while moving
        @Override public String name() { return "MOVING"; }
    }

    static final class DoorsOpenState implements ElevatorState {
        @Override public void handleArrival(Elevator e) { /* already stopped */ }
        @Override public boolean canOpenDoor() { return true; }
        @Override public String name() { return "DOORS_OPEN"; }
    }

    static final class OutOfServiceState implements ElevatorState {
        @Override public void handleArrival(Elevator e) { /* no-op: not serving calls */ }
        @Override public boolean canOpenDoor() { return false; }
        @Override public String name() { return "OUT_OF_SERVICE"; }
    }

    // ---------- Elevator ----------
    /** Owns one cabin's physical state and its own pending-stop queue. */
    static final class Elevator {
        final String id;
        final int capacity;
        volatile int currentFloor = 0;
        volatile Direction direction = Direction.IDLE;
        volatile DoorState doorState = DoorState.CLOSED;
        private ElevatorState state = new IdleState();
        private final TreeSet<Integer> upStops = new TreeSet<>();
        private final TreeSet<Integer> downStops = new TreeSet<>();
        final ReentrantLock lock = new ReentrantLock();

        Elevator(String id, int capacity) { this.id = id; this.capacity = capacity; }

        void setState(ElevatorState state) { this.state = state; }
        ElevatorState getState() { return state; }

        boolean isInService() { return !(state instanceof OutOfServiceState); }
        boolean isFull() { return false; } // capacity tracking simplified for this demo

        /** Add a stop request; SCAN-style: keep the elevator moving in its current direction if possible. */
        void addStop(int floor) {
            if (floor > currentFloor) upStops.add(floor);
            else if (floor < currentFloor) downStops.add(floor);
            else { /* already there: open doors immediately */ }
            if (direction == Direction.IDLE && (!upStops.isEmpty() || !downStops.isEmpty())) {
                direction = !upStops.isEmpty() ? Direction.UP : Direction.DOWN;
                setState(new MovingState());
            }
        }

        /** Advance the cabin by one floor toward its next pending stop (SCAN algorithm). */
        void step() {
            if (!(state instanceof MovingState) && !(state instanceof IdleState)) return;
            if (direction == Direction.UP) {
                if (upStops.isEmpty()) {
                    direction = downStops.isEmpty() ? Direction.IDLE : Direction.DOWN;
                    if (direction == Direction.IDLE) setState(new IdleState());
                    return;
                }
                currentFloor++;
                if (upStops.contains(currentFloor)) {
                    upStops.remove(currentFloor);
                    state.handleArrival(this);
                }
            } else if (direction == Direction.DOWN) {
                if (downStops.isEmpty()) {
                    direction = upStops.isEmpty() ? Direction.IDLE : Direction.UP;
                    if (direction == Direction.IDLE) setState(new IdleState());
                    return;
                }
                currentFloor--;
                if (downStops.contains(currentFloor)) {
                    downStops.remove(currentFloor);
                    state.handleArrival(this);
                }
            }
        }

        void openDoor() {
            if (!state.canOpenDoor()) throw new IllegalStateException("Cannot open doors in state " + state.name());
            doorState = DoorState.OPEN;
        }

        void closeDoor() {
            doorState = DoorState.CLOSED;
            // Resume motion after servicing this floor, or go idle if nothing left.
            if (!upStops.isEmpty() || !downStops.isEmpty()) setState(new MovingState());
            else { direction = Direction.IDLE; setState(new IdleState()); }
        }

        void setOutOfService() { setState(new OutOfServiceState()); direction = Direction.IDLE; }

        List<Integer> pendingStops() {
            List<Integer> all = new ArrayList<>(upStops);
            all.addAll(downStops);
            return all;
        }
    }

    // ---------- DispatchStrategy (interface, Strategy pattern) ----------
    interface DispatchStrategy {
        Elevator selectElevator(HallCall call, List<Elevator> elevators);
    }

    static final class NearestCarStrategy implements DispatchStrategy {
        @Override
        public Elevator selectElevator(HallCall call, List<Elevator> elevators) {
            Elevator best = null;
            int bestDistance = Integer.MAX_VALUE;
            for (Elevator e : elevators) {
                if (!e.isInService()) continue;
                if (e.direction == call.direction || e.direction == Direction.IDLE) {
                    int d = Math.abs(e.currentFloor - call.floor);
                    if (d < bestDistance) { best = e; bestDistance = d; }
                }
            }
            return best;
        }
    }

    /** Zones the building into bands; prefers an elevator already assigned near that band. */
    static final class ScanZoneStrategy implements DispatchStrategy {
        private final int zoneSize;
        ScanZoneStrategy(int zoneSize) { this.zoneSize = zoneSize; }

        @Override
        public Elevator selectElevator(HallCall call, List<Elevator> elevators) {
            int callZone = call.floor / zoneSize;
            Elevator best = null;
            int bestScore = Integer.MAX_VALUE;
            for (Elevator e : elevators) {
                if (!e.isInService()) continue;
                int elevatorZone = e.currentFloor / zoneSize;
                int zoneDistance = Math.abs(elevatorZone - callZone) * 1000;
                int floorDistance = Math.abs(e.currentFloor - call.floor);
                int score = zoneDistance + floorDistance;
                if (score < bestScore) { best = e; bestScore = score; }
            }
            return best;
        }
    }

    // ---------- Dispatcher ----------
    /** Atomically assigns each incoming hall call to one elevator via the active strategy. */
    static final class Dispatcher {
        private final List<Elevator> elevators;
        private volatile DispatchStrategy strategy;

        Dispatcher(List<Elevator> elevators, DispatchStrategy strategy) {
            this.elevators = elevators;
            this.strategy = strategy;
        }

        void setStrategy(DispatchStrategy strategy) { this.strategy = strategy; }

        /** Select then atomically claim; retries against remaining elevators if claim fails. */
        void dispatch(HallCall call) {
            List<Elevator> remaining = new ArrayList<>(elevators);
            while (!remaining.isEmpty()) {
                Elevator candidate = strategy.selectElevator(call, remaining);
                if (candidate == null) return; // no elevator can currently serve this call
                candidate.lock.lock();
                try {
                    if (candidate.isInService() && !candidate.isFull()) {
                        candidate.addStop(call.floor);
                        return; // claimed
                    }
                } finally {
                    candidate.lock.unlock();
                }
                // candidate became unavailable between selection and claim -- retry with the rest
                remaining.remove(candidate);
            }
        }
    }

    // ---------- ElevatorController (facade) ----------
    static final class ElevatorStatus {
        final String id; final int currentFloor; final Direction direction; final DoorState doorState; final String state;
        ElevatorStatus(Elevator e) {
            this.id = e.id; this.currentFloor = e.currentFloor; this.direction = e.direction;
            this.doorState = e.doorState; this.state = e.getState().name();
        }
        @Override public String toString() {
            return String.format("Elevator[%s] floor=%d dir=%s door=%s state=%s", id, currentFloor, direction, doorState, state);
        }
    }

    static final class ElevatorController {
        private final Dispatcher dispatcher;
        private final Map<String, Elevator> elevators = new LinkedHashMap<>();

        ElevatorController(List<Elevator> elevatorList, DispatchStrategy strategy) {
            for (Elevator e : elevatorList) elevators.put(e.id, e);
            this.dispatcher = new Dispatcher(elevatorList, strategy);
        }

        void requestElevator(int floor, Direction dir) {
            dispatcher.dispatch(new HallCall(floor, dir));
        }

        void selectFloor(String elevatorId, int floor) {
            Elevator e = elevators.get(elevatorId);
            if (e == null) throw new IllegalArgumentException("No such elevator: " + elevatorId);
            e.lock.lock();
            try {
                e.addStop(floor); // car call: destination chosen from inside the cabin
            } finally {
                e.lock.unlock();
            }
        }

        void setOutOfService(String elevatorId) {
            Elevator e = elevators.get(elevatorId);
            if (e == null) return;
            e.lock.lock();
            try {
                List<Integer> pending = e.pendingStops();
                e.setOutOfService();
                // Redistribute this elevator's pending requests to the rest of the fleet.
                for (int floor : pending) {
                    dispatcher.dispatch(new HallCall(floor, Direction.IDLE));
                }
            } finally {
                e.lock.unlock();
            }
        }

        ElevatorStatus getStatus(String elevatorId) {
            Elevator e = elevators.get(elevatorId);
            if (e == null) throw new IllegalArgumentException("No such elevator: " + elevatorId);
            return new ElevatorStatus(e);
        }

        /**
         * Advance every in-service elevator by one simulated time-step. An elevator that
         * just opened its doors (previous tick's arrival) spends this tick "boarding" and
         * closes its doors, resuming motion on the following tick.
         */
        void tick() {
            for (Elevator e : elevators.values()) {
                e.lock.lock();
                try {
                    if (e.getState() instanceof DoorsOpenState) e.closeDoor();
                    else e.step();
                } finally {
                    e.lock.unlock();
                }
            }
        }
    }

    // ---------- Demo ----------
    public static void main(String[] args) {
        List<Elevator> cabins = List.of(new Elevator("E1", 8), new Elevator("E2", 8));
        ElevatorController controller = new ElevatorController(cabins, new NearestCarStrategy());

        controller.requestElevator(5, Direction.UP);
        controller.requestElevator(2, Direction.DOWN);
        controller.selectFloor("E1", 8);

        for (int i = 0; i < 12; i++) {
            controller.tick();
        }

        System.out.println(controller.getStatus("E1"));
        System.out.println(controller.getStatus("E2"));

        controller.setOutOfService("E2");
        System.out.println("After maintenance: " + controller.getStatus("E2"));
    }
}

