    void closeDoor() {
        doorState = DoorState::CLOSED;
        if (!upStops_.empty() || !downStops_.empty()) setMoving();
        else { direction = Direction::IDLE; setIdle(); }
    }

    void setOutOfService();

    std::vector<int> pendingStops() const {
        std::vector<int> all(upStops_.begin(), upStops_.end());
        all.insert(all.end(), downStops_.begin(), downStops_.end());
        return all;
    }

    void setIdle();
    void setMoving();
    void setDoorsOpen();

private:
    std::unique_ptr<ElevatorState> state_;
    std::string stateName_ = "IDLE";
    std::set<int> upStops_;
    std::set<int> downStops_;

    std::unique_ptr<ElevatorState> makeIdle();
    std::unique_ptr<ElevatorState> makeMoving();
    std::unique_ptr<ElevatorState> makeDoorsOpen();
    std::unique_ptr<ElevatorState> makeOutOfService();

    friend struct IdleState;
    friend struct MovingState;
    friend struct DoorsOpenState;
    friend struct OutOfServiceState;
};

struct IdleState : ElevatorState {
    void handleArrival(Elevator&) override {}
    bool canOpenDoor() const override { return true; }
    std::string name() const override { return "IDLE"; }
};

struct MovingState : ElevatorState {
    void handleArrival(Elevator& e) override {
        // The cabin reports arrival at a floor it must serve -> transition to DoorsOpenState.
        e.setDoorsOpen();
        e.openDoor();
    }
    bool canOpenDoor() const override { return false; } // cannot open while moving
    std::string name() const override { return "MOVING"; }
};

struct DoorsOpenState : ElevatorState {
    void handleArrival(Elevator&) override {}
    bool canOpenDoor() const override { return true; }
    std::string name() const override { return "DOORS_OPEN"; }
};

struct OutOfServiceState : ElevatorState {
    void handleArrival(Elevator&) override {}
    bool canOpenDoor() const override { return false; }
    std::string name() const override { return "OUT_OF_SERVICE"; }
};

std::unique_ptr<ElevatorState> Elevator::makeIdle() { return std::make_unique<IdleState>(); }
std::unique_ptr<ElevatorState> Elevator::makeMoving() { return std::make_unique<MovingState>(); }
std::unique_ptr<ElevatorState> Elevator::makeDoorsOpen() { return std::make_unique<DoorsOpenState>(); }
std::unique_ptr<ElevatorState> Elevator::makeOutOfService() { return std::make_unique<OutOfServiceState>(); }

void Elevator::setIdle() { state_ = makeIdle(); stateName_ = "IDLE"; }
void Elevator::setMoving() { state_ = makeMoving(); stateName_ = "MOVING"; }
void Elevator::setDoorsOpen() { state_ = makeDoorsOpen(); stateName_ = "DOORS_OPEN"; }
void Elevator::setOutOfService() { state_ = makeOutOfService(); stateName_ = "OUT_OF_SERVICE"; direction = Direction::IDLE; }

void Elevator::step() {
    if (stateName_ != "MOVING" && stateName_ != "IDLE") return;
    if (direction == Direction::UP) {
        if (upStops_.empty()) {
            direction = downStops_.empty() ? Direction::IDLE : Direction::DOWN;
            if (direction == Direction::IDLE) setIdle();
            return;
        }
        currentFloor++;
        if (upStops_.count(currentFloor)) {
            upStops_.erase(currentFloor);
            state_->handleArrival(*this);
        }
    } else if (direction == Direction::DOWN) {
        if (downStops_.empty()) {
            direction = upStops_.empty() ? Direction::IDLE : Direction::UP;
            if (direction == Direction::IDLE) setIdle();
            return;
        }
        currentFloor--;
        if (downStops_.count(currentFloor)) {
            downStops_.erase(currentFloor);
            state_->handleArrival(*this);
        }
    }
}

// ---------- DispatchStrategy (interface, Strategy pattern) ----------
struct DispatchStrategy {
    virtual ~DispatchStrategy() = default;
    virtual Elevator* selectElevator(const HallCall& call, const std::vector<Elevator*>& elevators) = 0;
};

struct NearestCarStrategy : DispatchStrategy {
    Elevator* selectElevator(const HallCall& call, const std::vector<Elevator*>& elevators) override {
        Elevator* best = nullptr;
        int bestDistance = INT32_MAX;
        for (auto* e : elevators) {
            if (!e->isInService()) continue;
            if (e->direction == call.direction || e->direction == Direction::IDLE) {
                int d = std::abs(e->currentFloor - call.floor);
                if (d < bestDistance) { best = e; bestDistance = d; }
            }
        }
        return best;
    }
};

// Zones the building into bands; prefers an elevator already assigned near that band.
struct ScanZoneStrategy : DispatchStrategy {
    int zoneSize;
    explicit ScanZoneStrategy(int zoneSize_) : zoneSize(zoneSize_) {}
    Elevator* selectElevator(const HallCall& call, const std::vector<Elevator*>& elevators) override {
        int callZone = call.floor / zoneSize;
        Elevator* best = nullptr;
        int bestScore = INT32_MAX;
        for (auto* e : elevators) {
            if (!e->isInService()) continue;
            int elevatorZone = e->currentFloor / zoneSize;
            int score = std::abs(elevatorZone - callZone) * 1000 + std::abs(e->currentFloor - call.floor);
            if (score < bestScore) { best = e; bestScore = score; }
        }
        return best;
    }
};

// ---------- Dispatcher ----------
// Atomically assigns each incoming hall call to one elevator via the active strategy.
class Dispatcher {
public:
    Dispatcher(std::vector<Elevator*> elevators, std::shared_ptr<DispatchStrategy> strategy)
        : elevators_(std::move(elevators)), strategy_(std::move(strategy)) {}

    void setStrategy(std::shared_ptr<DispatchStrategy> strategy) { strategy_ = std::move(strategy); }

    // Select then atomically claim; retries against remaining elevators if claim fails.
    void dispatch(const HallCall& call) {
        std::vector<Elevator*> remaining = elevators_;
        while (!remaining.empty()) {
            Elevator* candidate = strategy_->selectElevator(call, remaining);
            if (candidate == nullptr) return; // no elevator can currently serve this call
            {
                std::lock_guard<std::mutex> guard(candidate->lock);
                if (candidate->isInService() && !candidate->isFull()) {
                    candidate->addStop(call.floor);
                    return; // claimed
                }
            }
            remaining.erase(std::remove(remaining.begin(), remaining.end(), candidate), remaining.end());
        }
    }

private:
    std::vector<Elevator*> elevators_;
    std::shared_ptr<DispatchStrategy> strategy_;
};

// ---------- ElevatorController (facade) ----------
struct ElevatorStatus {
    std::string id; int currentFloor; Direction direction; DoorState doorState; std::string state;
};

std::ostream& operator<<(std::ostream& os, const ElevatorStatus& s) {
    os << "Elevator[" << s.id << "] floor=" << s.currentFloor << " dir=" << toString(s.direction)
       << " door=" << toString(s.doorState) << " state=" << s.state;
    return os;
}

class ElevatorController {
public:
    ElevatorController(std::vector<std::unique_ptr<Elevator>> elevatorList, std::shared_ptr<DispatchStrategy> strategy) {
        elevators_ = std::move(elevatorList);
        std::vector<Elevator*> raw;
        for (auto& e : elevators_) raw.push_back(e.get());
        dispatcher_ = std::make_unique<Dispatcher>(raw, std::move(strategy));
    }

    void requestElevator(int floor, Direction dir) {
        dispatcher_->dispatch(HallCall{floor, dir});
    }

    void selectFloor(const std::string& elevatorId, int floor) {
        Elevator* e = find(elevatorId);
        std::lock_guard<std::mutex> guard(e->lock);
        e->addStop(floor); // car call: destination chosen from inside the cabin
    }

    void setOutOfService(const std::string& elevatorId) {
        Elevator* e = find(elevatorId);
        std::vector<int> pending;
        {
            std::lock_guard<std::mutex> guard(e->lock);
            pending = e->pendingStops();
            e->setOutOfService();
        }
        // Redistribute this elevator's pending requests to the rest of the fleet.
        for (int floor : pending) dispatcher_->dispatch(HallCall{floor, Direction::IDLE});
    }

    ElevatorStatus getStatus(const std::string& elevatorId) {
        Elevator* e = find(elevatorId);
        return ElevatorStatus{e->id, e->currentFloor, e->direction, e->doorState, e->getState()->name()};
    }

    // Advance every in-service elevator by one simulated time-step; an elevator that
    // just opened its doors spends this tick "boarding" and closes them, resuming next tick.
    void tick() {
        for (auto& e : elevators_) {
            std::lock_guard<std::mutex> guard(e->lock);
            if (e->getState()->name() == "DOORS_OPEN") e->closeDoor();
            else e->step();
        }
    }

private:
    std::vector<std::unique_ptr<Elevator>> elevators_;
    std::unique_ptr<Dispatcher> dispatcher_;

    Elevator* find(const std::string& id) {
        for (auto& e : elevators_) if (e->id == id) return e.get();
        throw std::invalid_argument("No such elevator: " + id);
    }
};

int main() {
    std::vector<std::unique_ptr<Elevator>> cabins;
    cabins.push_back(std::make_unique<Elevator>("E1", 8));
    cabins.push_back(std::make_unique<Elevator>("E2", 8));

    ElevatorController controller(std::move(cabins), std::make_shared<NearestCarStrategy>());

    controller.requestElevator(5, Direction::UP);
    controller.requestElevator(2, Direction::DOWN);
    controller.selectFloor("E1", 8);

    for (int i = 0; i < 12; i++) controller.tick();

    std::cout << controller.getStatus("E1") << "\n";
    std::cout << controller.getStatus("E2") << "\n";

    controller.setOutOfService("E2");
    std::cout << "After maintenance: " << controller.getStatus("E2") << "\n";

    return 0;
}

