'use strict';
/**
 * Elevator System -- full class-diagram implementation.
 *
 * Elevator delegates behavior to its current ElevatorState (State pattern) so illegal
 * transitions (e.g. opening doors while moving) are structurally unrepresentable.
 * Dispatcher uses a swappable DispatchStrategy to select a candidate elevator, then
 * atomically claims the hall call under a per-elevator "lock" (a synchronous critical
 * section -- Node has no preemptive threading, but the same check-then-act gap this
 * models is real once you add async I/O around dispatch, so we still guard it explicitly).
 */

const Direction = { UP: 'UP', DOWN: 'DOWN', IDLE: 'IDLE' };
const DoorState = { OPEN: 'OPEN', CLOSED: 'CLOSED' };

// ---------- ElevatorState (interface, State pattern) ----------
class ElevatorState {
  handleArrival(_elevator) { throw new Error('not implemented'); }
  canOpenDoor() { throw new Error('not implemented'); }
  name() { throw new Error('not implemented'); }
}

class IdleState extends ElevatorState {
  handleArrival(_e) {}
  canOpenDoor() { return true; }
  name() { return 'IDLE'; }
}

class MovingState extends ElevatorState {
  handleArrival(e) {
    // The cabin reports arrival at a floor it must serve -> transition to DoorsOpenState.
    e.setState(new DoorsOpenState());
    e.openDoor();
  }
  canOpenDoor() { return false; } // cannot open while moving
  name() { return 'MOVING'; }
}

class DoorsOpenState extends ElevatorState {
  handleArrival(_e) {}
  canOpenDoor() { return true; }
  name() { return 'DOORS_OPEN'; }
}

class OutOfServiceState extends ElevatorState {
  handleArrival(_e) {}
  canOpenDoor() { return false; }
  name() { return 'OUT_OF_SERVICE'; }
}

// ---------- Elevator ----------
// Owns one cabin's physical state and its own pending-stop queue.
class Elevator {
  constructor(id, capacity) {
    this.id = id;
    this.capacity = capacity;
    this.currentFloor = 0;
    this.direction = Direction.IDLE;
    this.doorState = DoorState.CLOSED;
    this._state = new IdleState();
    this._upStops = new Set();
    this._downStops = new Set();
  }

  setState(state) { this._state = state; }
  getState() { return this._state; }

  isInService() { return !(this._state instanceof OutOfServiceState); }
  isFull() { return false; } // capacity tracking simplified for this demo

  // Add a stop request; SCAN-style: keep the elevator moving in its current direction if possible.
  addStop(floor) {
    if (floor > this.currentFloor) this._upStops.add(floor);
    else if (floor < this.currentFloor) this._downStops.add(floor);
    if (this.direction === Direction.IDLE && (this._upStops.size > 0 || this._downStops.size > 0)) {
      this.direction = this._upStops.size > 0 ? Direction.UP : Direction.DOWN;
      this.setState(new MovingState());
    }
  }

  // Advance the cabin by one floor toward its next pending stop (SCAN algorithm).
  step() {
    const name = this._state.name();
    if (name !== 'MOVING' && name !== 'IDLE') return;
    if (this.direction === Direction.UP) {
      if (this._upStops.size === 0) {
        this.direction = this._downStops.size === 0 ? Direction.IDLE : Direction.DOWN;
        if (this.direction === Direction.IDLE) this.setState(new IdleState());
        return;
      }
      this.currentFloor++;
      if (this._upStops.has(this.currentFloor)) {
        this._upStops.delete(this.currentFloor);
        this._state.handleArrival(this);
      }
    } else if (this.direction === Direction.DOWN) {
      if (this._downStops.size === 0) {
        this.direction = this._upStops.size === 0 ? Direction.IDLE : Direction.UP;
        if (this.direction === Direction.IDLE) this.setState(new IdleState());
        return;
      }
      this.currentFloor--;
      if (this._downStops.has(this.currentFloor)) {
        this._downStops.delete(this.currentFloor);
        this._state.handleArrival(this);
      }
    }
  }

  openDoor() {
    if (!this._state.canOpenDoor()) throw new Error(`Cannot open doors in state ${this._state.name()}`);
    this.doorState = DoorState.OPEN;
  }

  closeDoor() {
    this.doorState = DoorState.CLOSED;
    if (this._upStops.size > 0 || this._downStops.size > 0) this.setState(new MovingState());
    else { this.direction = Direction.IDLE; this.setState(new IdleState()); }
  }

  setOutOfService() {
    this.setState(new OutOfServiceState());
    this.direction = Direction.IDLE;
  }

  pendingStops() {
    return [...this._upStops, ...this._downStops];
  }
}

// ---------- DispatchStrategy (interface, Strategy pattern) ----------
class DispatchStrategy {
  selectElevator(_call, _elevators) { throw new Error('not implemented'); }
}

class NearestCarStrategy extends DispatchStrategy {
  selectElevator(call, elevators) {
    let best = null;
    let bestDistance = Infinity;
    for (const e of elevators) {
      if (!e.isInService()) continue;
      if (e.direction === call.direction || e.direction === Direction.IDLE) {
        const d = Math.abs(e.currentFloor - call.floor);
        if (d < bestDistance) { best = e; bestDistance = d; }
      }
    }
    return best;
  }
}

// Zones the building into bands; prefers an elevator already assigned near that band.
class ScanZoneStrategy extends DispatchStrategy {
  constructor(zoneSize) { super(); this.zoneSize = zoneSize; }
  selectElevator(call, elevators) {
    const callZone = Math.floor(call.floor / this.zoneSize);
    let best = null;
    let bestScore = Infinity;
    for (const e of elevators) {
      if (!e.isInService()) continue;
      const elevatorZone = Math.floor(e.currentFloor / this.zoneSize);
      const score = Math.abs(elevatorZone - callZone) * 1000 + Math.abs(e.currentFloor - call.floor);
      if (score < bestScore) { best = e; bestScore = score; }
    }
    return best;
  }
}

// ---------- Dispatcher ----------
// Atomically assigns each incoming hall call to one elevator via the active strategy.
class Dispatcher {
  constructor(elevators, strategy) {
    this.elevators = elevators;
    this.strategy = strategy;
  }

  setStrategy(strategy) { this.strategy = strategy; }

  // Select then atomically claim; retries against remaining elevators if claim fails.
  dispatch(hallCall) {
    let remaining = [...this.elevators];
    while (remaining.length > 0) {
      const candidate = this.strategy.selectElevator(hallCall, remaining);
      if (!candidate) return; // no elevator can currently serve this call
      // Single synchronous critical section -- stands in for "lock(candidate)".
      if (candidate.isInService() && !candidate.isFull()) {
        candidate.addStop(hallCall.floor);
        return; // claimed
      }
      remaining = remaining.filter((e) => e !== candidate);
    }
  }
}

// ---------- ElevatorController (facade) ----------
class ElevatorController {
  constructor(elevatorList, strategy) {
    this.elevators = new Map(elevatorList.map((e) => [e.id, e]));
    this.dispatcher = new Dispatcher(elevatorList, strategy);
  }

  requestElevator(floor, dir) {
    this.dispatcher.dispatch({ floor, direction: dir });
  }

  selectFloor(elevatorId, floor) {
    const e = this._find(elevatorId);
    e.addStop(floor); // car call: destination chosen from inside the cabin
  }

  setOutOfService(elevatorId) {
    const e = this._find(elevatorId);
    const pending = e.pendingStops();
    e.setOutOfService();
    // Redistribute this elevator's pending requests to the rest of the fleet.
    for (const floor of pending) this.dispatcher.dispatch({ floor, direction: Direction.IDLE });
  }

  getStatus(elevatorId) {
    const e = this._find(elevatorId);
    return {
      id: e.id, currentFloor: e.currentFloor, direction: e.direction,
      doorState: e.doorState, state: e.getState().name(),
      toString() { return `Elevator[${this.id}] floor=${this.currentFloor} dir=${this.direction} door=${this.doorState} state=${this.state}`; },
    };
  }

  // Advance every in-service elevator by one simulated time-step. An elevator that just
  // opened its doors spends this tick "boarding" and closes them, resuming motion next tick.
  tick() {
    for (const e of this.elevators.values()) {
      if (e.getState() instanceof DoorsOpenState) e.closeDoor();
      else e.step();
    }
  }

  _find(elevatorId) {
    const e = this.elevators.get(elevatorId);
    if (!e) throw new Error(`No such elevator: ${elevatorId}`);
    return e;
  }
}

// ---------- Demo ----------
function main() {
  const cabins = [new Elevator('E1', 8), new Elevator('E2', 8)];
  const controller = new ElevatorController(cabins, new NearestCarStrategy());

  controller.requestElevator(5, Direction.UP);
  controller.requestElevator(2, Direction.DOWN);
  controller.selectFloor('E1', 8);

  for (let i = 0; i < 12; i++) controller.tick();

  console.log(controller.getStatus('E1').toString());
  console.log(controller.getStatus('E2').toString());

  controller.setOutOfService('E2');
  console.log('After maintenance: ' + controller.getStatus('E2').toString());
}

if (require.main === module) {
  main();
}

module.exports = {
  Direction, DoorState, Elevator, Dispatcher, ElevatorController,
  NearestCarStrategy, ScanZoneStrategy, IdleState, MovingState, DoorsOpenState, OutOfServiceState,
};

