      if (!e.isInService()) continue;
      const elevatorZone = Math.floor(e.currentFloor / this.zoneSize);
      const score = Math.abs(elevatorZone - callZone) * 1000 + Math.abs(e.currentFloor - call.floor);
      if (score < bestScore) { best = e; bestScore = score; }
    }
    return best;
  }
}

// ---------- Dispatcher ----------
// Atomically assigns each incoming hall call to one elevator via the active strategy.
class Dispatcher {
  constructor(private readonly elevators: Elevator[], private strategy: DispatchStrategy) {}

  setStrategy(strategy: DispatchStrategy): void { this.strategy = strategy; }

  /** Select then atomically claim; retries against remaining elevators if claim fails. */
  dispatch(hallCall: HallCall): void {
    let remaining = [...this.elevators];
    while (remaining.length > 0) {
      const candidate = this.strategy.selectElevator(hallCall, remaining);
      if (!candidate) return; // no elevator can currently serve this call
      // Single synchronous critical section -- stands in for "lock(candidate)".
      if (candidate.isInService() && !candidate.isFull()) {
        candidate.addStop(hallCall.floor);
        return; // claimed
      }
      remaining = remaining.filter((e) => e !== candidate);
    }
  }
}

// ---------- ElevatorController (facade) ----------
interface ElevatorStatus {
  id: string;
  currentFloor: number;
  direction: Direction;
  doorState: DoorState;
  state: string;
}

class ElevatorController {
  private readonly elevators: Map<string, Elevator>;
  private readonly dispatcher: Dispatcher;

  constructor(elevatorList: Elevator[], strategy: DispatchStrategy) {
    this.elevators = new Map(elevatorList.map((e) => [e.id, e]));
    this.dispatcher = new Dispatcher(elevatorList, strategy);
  }

  requestElevator(floor: number, dir: Direction): void {
    this.dispatcher.dispatch({ floor, direction: dir });
  }

  selectFloor(elevatorId: string, floor: number): void {
    const e = this.find(elevatorId);
    e.addStop(floor); // car call: destination chosen from inside the cabin
  }

  setOutOfService(elevatorId: string): void {
    const e = this.find(elevatorId);
    const pending = e.pendingStops();
    e.setOutOfService();
    // Redistribute this elevator's pending requests to the rest of the fleet.
    for (const floor of pending) this.dispatcher.dispatch({ floor, direction: Direction.IDLE });
  }

  getStatus(elevatorId: string): ElevatorStatus {
    const e = this.find(elevatorId);
    return { id: e.id, currentFloor: e.currentFloor, direction: e.direction, doorState: e.doorState, state: e.getState().name() };
  }

  /**
   * Advance every in-service elevator by one simulated time-step. An elevator that just
   * opened its doors spends this tick "boarding" and closes them, resuming motion next tick.
   */
  tick(): void {
    for (const e of this.elevators.values()) {
      if (e.getState() instanceof DoorsOpenState) e.closeDoor();
      else e.step();
    }
  }

  private find(elevatorId: string): Elevator {
    const e = this.elevators.get(elevatorId);
    if (!e) throw new Error(`No such elevator: ${elevatorId}`);
    return e;
  }
}

function statusToString(s: ElevatorStatus): string {
  return `Elevator[${s.id}] floor=${s.currentFloor} dir=${s.direction} door=${s.doorState} state=${s.state}`;
}

// ---------- Demo ----------
function main(): void {
  const cabins = [new Elevator('E1', 8), new Elevator('E2', 8)];
  const controller = new ElevatorController(cabins, new NearestCarStrategy());

  controller.requestElevator(5, Direction.UP);
  controller.requestElevator(2, Direction.DOWN);
  controller.selectFloor('E1', 8);

  for (let i = 0; i < 12; i++) controller.tick();

  console.log(statusToString(controller.getStatus('E1')));
  console.log(statusToString(controller.getStatus('E2')));

  controller.setOutOfService('E2');
  console.log('After maintenance: ' + statusToString(controller.getStatus('E2')));
}

if (require.main === module) {
  main();
}

export {
  Direction, DoorState, Elevator, Dispatcher, ElevatorController,
  DispatchStrategy, NearestCarStrategy, ScanZoneStrategy,
  ElevatorState, IdleState, MovingState, DoorsOpenState, OutOfServiceState,
};

