/**
 * Tic-Tac-Toe / Board Game Engine — full class-diagram implementation.
 *
 * TurnBasedGame is a Template Method: play() defines the fixed skeleton (setup -> loop
 * of get move / validate / place / check win-or-draw / switch turn) while setupBoard()
 * and the WinningStrategy are the pluggable hooks. WinningStrategy generically scans
 * K-in-a-row through the last move in every direction, so board size/win-length are
 * just parameters, never hardcoded coordinate lists.
 */
public class p12 {

    // ---------- Symbol (value) ----------
    static final class Symbol {
        final char value;
        Symbol(char value) { this.value = value; }
        @Override public String toString() { return String.valueOf(value); }
        @Override public boolean equals(Object o) { return o instanceof Symbol && ((Symbol) o).value == value; }
        @Override public int hashCode() { return value; }
    }

    // ---------- Move (value) ----------
    static final class Move {
        final int row, col;
        final Symbol symbol;
        Move(int row, int col, Symbol symbol) { this.row = row; this.col = col; this.symbol = symbol; }
    }

    enum MoveResultType { OK, INVALID, WIN, DRAW }
    static final class MoveResult {
        final MoveResultType type;
        final String message;
        MoveResult(MoveResultType type, String message) { this.type = type; this.message = message; }
    }

    // ---------- Board ----------
    /** Owns the grid and cell occupancy. Does NOT decide whether a placement wins. */
    static final class Board {
        final int size;
        private final Symbol[][] grid;

        Board(int size) {
            this.size = size;
            this.grid = new Symbol[size][size];
        }

        boolean isValidMove(int row, int col) {
            return row >= 0 && row < size && col >= 0 && col < size && grid[row][col] == null;
        }

        void placeMark(int row, int col, Symbol symbol) {
            if (!isValidMove(row, col)) throw new IllegalArgumentException("Illegal move at " + row + "," + col);
            grid[row][col] = symbol;
        }

        Symbol get(int row, int col) {
            if (row < 0 || row >= size || col < 0 || col >= size) return null;
            return grid[row][col];
        }

        boolean isFull() {
            for (Symbol[] r : grid) for (Symbol s : r) if (s == null) return false;
            return true;
        }

        void print() {
            for (Symbol[] r : grid) {
                StringBuilder sb = new StringBuilder();
                for (Symbol s : r) sb.append(s == null ? '.' : s.value).append(' ');
                System.out.println(sb.toString().trim());
            }
        }
    }

    // ---------- WinningStrategy (interface, Strategy) ----------
    interface WinningStrategy {
        boolean checkWinner(Board board, Move lastMove);
    }

    /** Generic K-in-a-row check: scans every row/col/diagonal direction through the last move. */
    static final class LineScanWinningStrategy implements WinningStrategy {
        private final int k;
        LineScanWinningStrategy(int k) { this.k = k; }

        @Override
        public boolean checkWinner(Board board, Move lastMove) {
            Symbol symbol = board.get(lastMove.row, lastMove.col);
            if (symbol == null) return false;
            int[][] directions = { {0, 1}, {1, 0}, {1, 1}, {1, -1} }; // horizontal, vertical, diag, anti-diag
            for (int[] dir : directions) {
                int count = 1;
                count += countMatching(board, lastMove, dir[0], dir[1], symbol);
                count += countMatching(board, lastMove, -dir[0], -dir[1], symbol);
                if (count >= k) return true;
            }
            return false;
        }

        private int countMatching(Board board, Move move, int dRow, int dCol, Symbol symbol) {
            int count = 0;
            int r = move.row + dRow, c = move.col + dCol;
            while (symbol.equals(board.get(r, c))) {
                count++;
                r += dRow;
                c += dCol;
            }
            return count;
        }
    }

    // ---------- MoveStrategy (interface, Strategy) ----------
    interface MoveStrategy {
        Move decideMove(Board board, Symbol symbol);
    }

    /** Picks the first available empty cell -- trivially valid, deliberately simple default AI. */
    static final class FirstAvailableMoveStrategy implements MoveStrategy {
        @Override
        public Move decideMove(Board board, Symbol symbol) {
            for (int r = 0; r < board.size; r++) {
                for (int c = 0; c < board.size; c++) {
                    if (board.isValidMove(r, c)) return new Move(r, c, symbol);
                }
            }
            throw new IllegalStateException("No available moves");
        }
    }

    // ---------- Player (abstract) ----------
    /** Common identity for anything that produces a move. How the move is decided is delegated. */
    abstract static class Player {
        final String id;
        final Symbol symbol;
        Player(String id, Symbol symbol) { this.id = id; this.symbol = symbol; }
        abstract Move getMove(Board board);
    }

    /** Returns externally-supplied input as the move. */
    static final class HumanPlayer extends Player {
        private final Deque<int[]> pendingInputs = new ArrayDeque<>();

        HumanPlayer(String id, Symbol symbol) { super(id, symbol); }

        /** Feed the next external move (e.g. from UI/CLI input) before calling getMove(). */
        void supplyMove(int row, int col) { pendingInputs.addLast(new int[]{row, col}); }

        @Override
        Move getMove(Board board) {
            if (pendingInputs.isEmpty()) throw new IllegalStateException("No input supplied for human player " + id);
            int[] rc = pendingInputs.pollFirst();
            return new Move(rc[0], rc[1], symbol);
        }
    }

    /** Delegates move selection to a MoveStrategy -- the algorithm itself is not hardcoded here. */
    static final class AIPlayer extends Player {
        private final MoveStrategy moveStrategy;
        AIPlayer(String id, Symbol symbol, MoveStrategy moveStrategy) {
            super(id, symbol);
            this.moveStrategy = moveStrategy;
        }
        @Override
        Move getMove(Board board) { return moveStrategy.decideMove(board, symbol); }
    }

    // ---------- TurnBasedGame (abstract, Template Method) ----------
    abstract static class TurnBasedGame {
        Board board;
        final List<Player> players;
        final WinningStrategy winningStrategy;
        private int turnIndex = 0;
        private boolean finished = false;

        TurnBasedGame(List<Player> players, WinningStrategy winningStrategy) {
            this.players = players;
            this.winningStrategy = winningStrategy;
        }

        /** Hook: board dimensions/shape -- subclasses plug in their own structural piece. */
        protected abstract void setupBoard();

        protected abstract void declareResult(MoveResultType type, Player player);

        private Player nextPlayer() {
            Player p = players.get(turnIndex % players.size());
            turnIndex++;
            return p;
        }

        /** Template method: the fixed skeleton shared by any turn-based grid game. */
        MoveResult play() {
            setupBoard();
            while (!finished) {
                Player player = players.get(turnIndex % players.size());
                Move move = player.getMove(board);
                if (!board.isValidMove(move.row, move.col)) continue; // human retries; AI never produces one
                board.placeMark(move.row, move.col, player.symbol);
                nextPlayer();
                if (winningStrategy.checkWinner(board, move)) {
                    finished = true;
                    declareResult(MoveResultType.WIN, player);
                    return new MoveResult(MoveResultType.WIN, player.id + " wins");
                }
                if (board.isFull()) {
                    finished = true;
                    declareResult(MoveResultType.DRAW, null);
                    return new MoveResult(MoveResultType.DRAW, "draw");
                }
            }
            return new MoveResult(MoveResultType.OK, "game already finished");
        }

        boolean isFinished() { return finished; }
    }

    /** Concrete N x N, K-in-a-row game (default Tic-Tac-Toe: 3x3, 3-in-a-row). */
    static final class TicTacToeGame extends TurnBasedGame {
        private final int size;

        TicTacToeGame(int size, List<Player> players, WinningStrategy winningStrategy) {
            super(players, winningStrategy);
            this.size = size;
        }

        @Override
        protected void setupBoard() { this.board = new Board(size); }

        @Override
        protected void declareResult(MoveResultType type, Player player) {
            if (type == MoveResultType.WIN) System.out.println("Result: " + player.id + " (" + player.symbol + ") wins!");
            else System.out.println("Result: draw");
            board.print();
        }
    }

    // ---------- GameController (facade) ----------
    static final class GameController {
        private final TurnBasedGame game;
        GameController(TurnBasedGame game) { this.game = game; }

        MoveResult startGame() { return game.play(); }

        MoveResult makeMove(String playerId, int row, int col) {
            // For human players, external input is supplied before play()/loop consumes it.
            for (Player p : game.players) {
                if (p.id.equals(playerId) && p instanceof HumanPlayer) {
                    ((HumanPlayer) p).supplyMove(row, col);
                    return new MoveResult(MoveResultType.OK, "queued");
                }
            }
            return new MoveResult(MoveResultType.INVALID, "no such human player: " + playerId);
        }
    }

    // ---------- Demo ----------
    public static void main(String[] args) {
        Symbol X = new Symbol('X');
        Symbol O = new Symbol('O');

        HumanPlayer human = new HumanPlayer("P1", X);
        AIPlayer ai = new AIPlayer("P2", O, new FirstAvailableMoveStrategy());

        // Pre-supply a scripted sequence of human moves for this non-interactive demo.
        // Column 0 is targeted (rather than row 0) so it never collides with the AI's
        // deterministic "first empty cell" picks, which fill row 0 left-to-right first.
        human.supplyMove(0, 0);
        human.supplyMove(1, 0);
        human.supplyMove(2, 0); // completes left column -> human should win

        TicTacToeGame game = new TicTacToeGame(3, List.of(human, ai), new LineScanWinningStrategy(3));
        GameController controller = new GameController(game);

        MoveResult result = controller.startGame();
        System.out.println("Final: " + result.type + " -- " + result.message);
    }
}

