#include <iostream>
#include <vector>
#include <string>
#include <memory>
#include <deque>
#include <stdexcept>

// ---------- Symbol (value) ----------
struct Symbol {
    char value;
    bool operator==(const Symbol& other) const { return value == other.value; }
};

// ---------- Move (value) ----------
struct Move {
    int row, col;
    Symbol symbol;
};

enum class MoveResultType { OK, INVALID, WIN, DRAW };
struct MoveResult { MoveResultType type; std::string message; };

// ---------- Board ----------
// Owns the grid and cell occupancy. Does NOT decide whether a placement wins.
class Board {
public:
    int size;
    explicit Board(int size_) : size(size_), grid_(size_, std::vector<bool>(size_, false)),
                                  symbols_(size_, std::vector<char>(size_, '\0')) {}

    bool isValidMove(int row, int col) const {
        return row >= 0 && row < size && col >= 0 && col < size && !grid_[row][col];
    }

    void placeMark(int row, int col, Symbol symbol) {
        if (!isValidMove(row, col)) throw std::invalid_argument("Illegal move");
        grid_[row][col] = true;
        symbols_[row][col] = symbol.value;
    }

    // Returns '\0' via hasSymbol=false when the cell is out of bounds or empty.
    bool get(int row, int col, Symbol& out) const {
        if (row < 0 || row >= size || col < 0 || col >= size || !grid_[row][col]) return false;
        out.value = symbols_[row][col];
        return true;
    }

    bool isFull() const {
        for (auto& r : grid_) for (bool occupied : r) if (!occupied) return false;
        return true;
    }

    void print() const {
        for (int r = 0; r < size; r++) {
            std::string line;
            for (int c = 0; c < size; c++) {
                line += grid_[r][c] ? symbols_[r][c] : '.';
                line += ' ';
            }
            std::cout << line << "\n";
        }
    }

private:
    std::vector<std::vector<bool>> grid_;
    std::vector<std::vector<char>> symbols_;
};

// ---------- WinningStrategy (interface, Strategy) ----------
struct WinningStrategy {
    virtual ~WinningStrategy() = default;
    virtual bool checkWinner(const Board& board, const Move& lastMove) = 0;
};

// Generic K-in-a-row check: scans every row/col/diagonal direction through the last move.
class LineScanWinningStrategy : public WinningStrategy {
public:
    explicit LineScanWinningStrategy(int k) : k_(k) {}

    bool checkWinner(const Board& board, const Move& lastMove) override {
        Symbol symbol;
        if (!board.get(lastMove.row, lastMove.col, symbol)) return false;
        static const int dirs[4][2] = { {0, 1}, {1, 0}, {1, 1}, {1, -1} };
        for (auto& d : dirs) {
            int count = 1;
            count += countMatching(board, lastMove, d[0], d[1], symbol);
            count += countMatching(board, lastMove, -d[0], -d[1], symbol);
            if (count >= k_) return true;
        }
        return false;
    }

private:
    int k_;

    int countMatching(const Board& board, const Move& move, int dRow, int dCol, const Symbol& symbol) const {
        int count = 0;
        int r = move.row + dRow, c = move.col + dCol;
        Symbol cell;
        while (board.get(r, c, cell) && cell == symbol) {
            count++;
            r += dRow;
            c += dCol;
        }
        return count;
    }
};

// ---------- MoveStrategy (interface, Strategy) ----------
struct MoveStrategy {
    virtual ~MoveStrategy() = default;
    virtual Move decideMove(const Board& board, Symbol symbol) = 0;
};

// Picks the first available empty cell -- trivially valid, deliberately simple default AI.
struct FirstAvailableMoveStrategy : MoveStrategy {
    Move decideMove(const Board& board, Symbol symbol) override {
        for (int r = 0; r < board.size; r++)
            for (int c = 0; c < board.size; c++)
                if (board.isValidMove(r, c)) return Move{r, c, symbol};
        throw std::runtime_error("No available moves");
    }
};

// ---------- Player (abstract) ----------
// Common identity for anything that produces a move. How the move is decided is delegated.
class Player {
public:
    std::string id;
    Symbol symbol;
    Player(std::string id_, Symbol symbol_) : id(std::move(id_)), symbol(symbol_) {}
    virtual ~Player() = default;
    virtual Move getMove(const Board& board) = 0;
};

// Returns externally-supplied input as the move.
class HumanPlayer : public Player {
public:
    HumanPlayer(std::string id_, Symbol symbol_) : Player(std::move(id_), symbol_) {}

    void supplyMove(int row, int col) { pendingInputs_.push_back({row, col}); }

    Move getMove(const Board&) override {
        if (pendingInputs_.empty()) throw std::runtime_error("No input supplied for human player " + id);
        auto rc = pendingInputs_.front();
        pendingInputs_.pop_front();
        return Move{rc.first, rc.second, symbol};
    }

private:
    std::deque<std::pair<int, int>> pendingInputs_;
};

// Delegates move selection to a MoveStrategy -- the algorithm itself is not hardcoded here.
class AIPlayer : public Player {
public:
    AIPlayer(std::string id_, Symbol symbol_, std::shared_ptr<MoveStrategy> strategy)
        : Player(std::move(id_), symbol_), moveStrategy_(std::move(strategy)) {}

    Move getMove(const Board& board) override { return moveStrategy_->decideMove(board, symbol); }

private:
    std::shared_ptr<MoveStrategy> moveStrategy_;
};

// ---------- TurnBasedGame (abstract, Template Method) ----------
class TurnBasedGame {
public:
    std::unique_ptr<Board> board;
    std::vector<std::shared_ptr<Player>> players;

    TurnBasedGame(std::vector<std::shared_ptr<Player>> players_, std::shared_ptr<WinningStrategy> winningStrategy)
        : players(std::move(players_)), winningStrategy_(std::move(winningStrategy)) {}
    virtual ~TurnBasedGame() = default;

    // Template method: the fixed skeleton shared by any turn-based grid game.
    MoveResult play() {
        setupBoard();
        while (!finished_) {
            auto player = players[turnIndex_ % players.size()];
            Move move = player->getMove(*board);
            if (!board->isValidMove(move.row, move.col)) continue; // human retries; AI never produces one
            board->placeMark(move.row, move.col, player->symbol);
            turnIndex_++;
            if (winningStrategy_->checkWinner(*board, move)) {
                finished_ = true;
                declareResult(MoveResultType::WIN, player);
                return MoveResult{MoveResultType::WIN, player->id + " wins"};
            }
            if (board->isFull()) {
                finished_ = true;
                declareResult(MoveResultType::DRAW, nullptr);
                return MoveResult{MoveResultType::DRAW, "draw"};
            }
        }
        return MoveResult{MoveResultType::OK, "game already finished"};
    }

protected:
    // Hook: board dimensions/shape -- subclasses plug in their own structural piece.
    virtual void setupBoard() = 0;
    virtual void declareResult(MoveResultType type, std::shared_ptr<Player> player) = 0;

private:
    std::shared_ptr<WinningStrategy> winningStrategy_;
    size_t turnIndex_ = 0;
    bool finished_ = false;
};

// Concrete N x N, K-in-a-row game (default Tic-Tac-Toe: 3x3, 3-in-a-row).
class TicTacToeGame : public TurnBasedGame {
public:
    TicTacToeGame(int size, std::vector<std::shared_ptr<Player>> players, std::shared_ptr<WinningStrategy> strategy)
        : TurnBasedGame(std::move(players), std::move(strategy)), size_(size) {}

protected:
    void setupBoard() override { board = std::make_unique<Board>(size_); }

    void declareResult(MoveResultType type, std::shared_ptr<Player> player) override {
        if (type == MoveResultType::WIN) std::cout << "Result: " << player->id << " (" << player->symbol.value << ") wins!\n";
        else std::cout << "Result: draw\n";
        board->print();
    }

private:
    int size_;
};

// ---------- GameController (facade) ----------
class GameController {
public:
    explicit GameController(std::shared_ptr<TurnBasedGame> game) : game_(std::move(game)) {}

    MoveResult startGame() { return game_->play(); }

    MoveResult makeMove(const std::string& playerId, int row, int col) {
        for (auto& p : game_->players) {
            if (p->id == playerId) {
                auto human = std::dynamic_pointer_cast<HumanPlayer>(p);
                if (human) {
                    human->supplyMove(row, col);
                    return MoveResult{MoveResultType::OK, "queued"};
                }
            }
        }
        return MoveResult{MoveResultType::INVALID, "no such human player: " + playerId};
    }

private:
    std::shared_ptr<TurnBasedGame> game_;
};

int main() {
    Symbol X{'X'};
    Symbol O{'O'};

    auto human = std::make_shared<HumanPlayer>("P1", X);
    auto ai = std::make_shared<AIPlayer>("P2", O, std::make_shared<FirstAvailableMoveStrategy>());

    // Pre-supply a scripted sequence of human moves for this non-interactive demo.
    // Column 0 is targeted (rather than row 0) so it never collides with the AI's
    // deterministic "first empty cell" picks, which fill row 0 left-to-right first.
    human->supplyMove(0, 0);
    human->supplyMove(1, 0);
    human->supplyMove(2, 0); // completes left column -> human should win

    auto game = std::make_shared<TicTacToeGame>(3, std::vector<std::shared_ptr<Player>>{human, ai},
                                                 std::make_shared<LineScanWinningStrategy>(3));
    GameController controller(game);

    MoveResult result = controller.startGame();
    std::cout << "Final: " << (result.type == MoveResultType::WIN ? "WIN" : "DRAW") << " -- " << result.message << "\n";

    return 0;
}

