  constructor(k) { super(); this.k = k; }

  checkWinner(board, lastMove) {
    const symbol = board.get(lastMove.row, lastMove.col);
    if (symbol === null) return false;
    const directions = [[0, 1], [1, 0], [1, 1], [1, -1]]; // horizontal, vertical, diag, anti-diag
    for (const [dRow, dCol] of directions) {
      let count = 1;
      count += this._countMatching(board, lastMove, dRow, dCol, symbol);
      count += this._countMatching(board, lastMove, -dRow, -dCol, symbol);
      if (count >= this.k) return true;
    }
    return false;
  }

  _countMatching(board, move, dRow, dCol, symbol) {
    let count = 0;
    let r = move.row + dRow;
    let c = move.col + dCol;
    while (board.get(r, c) === symbol) {
      count++;
      r += dRow;
      c += dCol;
    }
    return count;
  }
}

// ---------- MoveStrategy (interface, Strategy) ----------
class MoveStrategy {
  decideMove(_board, _symbol) { throw new Error('not implemented'); }
}

// Picks the first available empty cell -- trivially valid, deliberately simple default AI.
class FirstAvailableMoveStrategy extends MoveStrategy {
  decideMove(board, symbol) {
    for (let r = 0; r < board.size; r++) {
      for (let c = 0; c < board.size; c++) {
        if (board.isValidMove(r, c)) return { row: r, col: c, symbol };
      }
    }
    throw new Error('No available moves');
  }
}

// ---------- Player (abstract) ----------
// Common identity for anything that produces a move. How the move is decided is delegated.
class Player {
  constructor(id, symbol) {
    if (new.target === Player) throw new Error('Player is abstract');
    this.id = id;
    this.symbol = symbol;
  }
  getMove(_board) { throw new Error('not implemented'); }
}

// Returns externally-supplied input as the move.
class HumanPlayer extends Player {
  constructor(id, symbol) {
    super(id, symbol);
    this._pendingInputs = [];
  }

  supplyMove(row, col) { this._pendingInputs.push([row, col]); }

  getMove(_board) {
    if (this._pendingInputs.length === 0) throw new Error(`No input supplied for human player ${this.id}`);
    const [row, col] = this._pendingInputs.shift();
    return { row, col, symbol: this.symbol };
  }
}

// Delegates move selection to a MoveStrategy -- the algorithm itself is not hardcoded here.
class AIPlayer extends Player {
  constructor(id, symbol, moveStrategy) {
    super(id, symbol);
    this.moveStrategy = moveStrategy;
  }
  getMove(board) { return this.moveStrategy.decideMove(board, this.symbol); }
}

// ---------- TurnBasedGame (abstract, Template Method) ----------
class TurnBasedGame {
  constructor(players, winningStrategy) {
    if (new.target === TurnBasedGame) throw new Error('TurnBasedGame is abstract');
    this.board = null;
    this.players = players;
    this.winningStrategy = winningStrategy;
    this._turnIndex = 0;
    this._finished = false;
  }

  // Hook: board dimensions/shape -- subclasses plug in their own structural piece.
  setupBoard() { throw new Error('not implemented'); }
  declareResult(_type, _player) { throw new Error('not implemented'); }

  // Template method: the fixed skeleton shared by any turn-based grid game.
  play() {
    this.setupBoard();
    while (!this._finished) {
      const player = this.players[this._turnIndex % this.players.length];
      const move = player.getMove(this.board);
      if (!this.board.isValidMove(move.row, move.col)) continue; // human retries; AI never produces one
      this.board.placeMark(move.row, move.col, player.symbol);
      this._turnIndex++;
      if (this.winningStrategy.checkWinner(this.board, move)) {
        this._finished = true;
        this.declareResult('WIN', player);
        return { type: 'WIN', message: `${player.id} wins` };
      }
      if (this.board.isFull()) {
        this._finished = true;
        this.declareResult('DRAW', null);
        return { type: 'DRAW', message: 'draw' };
      }
    }
    return { type: 'OK', message: 'game already finished' };
  }
}

// Concrete N x N, K-in-a-row game (default Tic-Tac-Toe: 3x3, 3-in-a-row).
class TicTacToeGame extends TurnBasedGame {
  constructor(size, players, winningStrategy) {
    super(players, winningStrategy);
    this.size = size;
  }

  setupBoard() { this.board = new Board(this.size); }

  declareResult(type, player) {
    if (type === 'WIN') console.log(`Result: ${player.id} (${player.symbol}) wins!`);
    else console.log('Result: draw');
    this.board.print();
  }
}

// ---------- GameController (facade) ----------
class GameController {
  constructor(game) { this.game = game; }

  startGame() { return this.game.play(); }

  makeMove(playerId, row, col) {
    for (const p of this.game.players) {
      if (p.id === playerId && p instanceof HumanPlayer) {
        p.supplyMove(row, col);
        return { type: 'OK', message: 'queued' };
      }
    }
    return { type: 'INVALID', message: `no such human player: ${playerId}` };
  }
}

// ---------- Demo ----------
function main() {
  const X = 'X';
  const O = 'O';

  const human = new HumanPlayer('P1', X);
  const ai = new AIPlayer('P2', O, new FirstAvailableMoveStrategy());

  // Pre-supply a scripted sequence of human moves for this non-interactive demo.
  // Column 0 is targeted (rather than row 0) so it never collides with the AI's
  // deterministic "first empty cell" picks, which fill row 0 left-to-right first.
  human.supplyMove(0, 0);
  human.supplyMove(1, 0);
  human.supplyMove(2, 0); // completes left column -> human should win

  const game = new TicTacToeGame(3, [human, ai], new LineScanWinningStrategy(3));
  const controller = new GameController(game);

  const result = controller.startGame();
  console.log(`Final: ${result.type} -- ${result.message}`);
}

if (require.main === module) {
  main();
}

module.exports = {
  Board, WinningStrategy, LineScanWinningStrategy, MoveStrategy, FirstAvailableMoveStrategy,
  Player, HumanPlayer, AIPlayer, TurnBasedGame, TicTacToeGame, GameController,
};

