/**
 * Tic-Tac-Toe / Board Game Engine -- full class-diagram implementation.
 *
 * TurnBasedGame is a Template Method: play() defines the fixed skeleton (setup -> loop
 * of get move / validate / place / check win-or-draw / switch turn) while setupBoard()
 * and the WinningStrategy are the pluggable hooks. WinningStrategy generically scans
 * K-in-a-row through the last move in every direction, so board size/win-length are
 * just parameters, never hardcoded coordinate lists.
 */

type Symbol = string;

interface Move {
  row: number;
  col: number;
  symbol: Symbol;
}

type MoveResultType = 'OK' | 'INVALID' | 'WIN' | 'DRAW';
interface MoveResult {
  type: MoveResultType;
  message: string;
}

// ---------- Board ----------
// Owns the grid and cell occupancy. Does NOT decide whether a placement wins.
class Board {
  private grid: (Symbol | null)[][];

  constructor(readonly size: number) {
    this.grid = Array.from({ length: size }, () => Array<Symbol | null>(size).fill(null));
  }

  isValidMove(row: number, col: number): boolean {
    return row >= 0 && row < this.size && col >= 0 && col < this.size && this.grid[row][col] === null;
  }

  placeMark(row: number, col: number, symbol: Symbol): void {
    if (!this.isValidMove(row, col)) throw new Error(`Illegal move at ${row},${col}`);
    this.grid[row][col] = symbol;
  }

  get(row: number, col: number): Symbol | null {
    if (row < 0 || row >= this.size || col < 0 || col >= this.size) return null;
    return this.grid[row][col];
  }

  isFull(): boolean {
    return this.grid.every((r) => r.every((cell) => cell !== null));
  }

  print(): void {
    for (const row of this.grid) {
      console.log(row.map((c) => (c === null ? '.' : c)).join(' '));
    }
  }
}

// ---------- WinningStrategy (interface, Strategy) ----------
interface WinningStrategy {
  checkWinner(board: Board, lastMove: Move): boolean;
}

// Generic K-in-a-row check: scans every row/col/diagonal direction through the last move.
class LineScanWinningStrategy implements WinningStrategy {
  constructor(private readonly k: number) {}

  checkWinner(board: Board, lastMove: Move): boolean {
    const symbol = board.get(lastMove.row, lastMove.col);
    if (symbol === null) return false;
    const directions: [number, number][] = [[0, 1], [1, 0], [1, 1], [1, -1]]; // horizontal, vertical, diag, anti-diag
    for (const [dRow, dCol] of directions) {
      let count = 1;
      count += this.countMatching(board, lastMove, dRow, dCol, symbol);
      count += this.countMatching(board, lastMove, -dRow, -dCol, symbol);
      if (count >= this.k) return true;
    }
    return false;
  }

  private countMatching(board: Board, move: Move, dRow: number, dCol: number, symbol: Symbol): number {
    let count = 0;
    let r = move.row + dRow;
    let c = move.col + dCol;
    while (board.get(r, c) === symbol) {
      count++;
      r += dRow;
      c += dCol;
    }
    return count;
  }
}

// ---------- MoveStrategy (interface, Strategy) ----------
interface MoveStrategy {
  decideMove(board: Board, symbol: Symbol): Move;
}

// Picks the first available empty cell -- trivially valid, deliberately simple default AI.
class FirstAvailableMoveStrategy implements MoveStrategy {
  decideMove(board: Board, symbol: Symbol): Move {
    for (let r = 0; r < board.size; r++) {
      for (let c = 0; c < board.size; c++) {
        if (board.isValidMove(r, c)) return { row: r, col: c, symbol };
      }
    }
    throw new Error('No available moves');
  }
}

// ---------- Player (abstract) ----------
// Common identity for anything that produces a move. How the move is decided is delegated.
abstract class Player {
  constructor(readonly id: string, readonly symbol: Symbol) {}
  abstract getMove(board: Board): Move;
}

// Returns externally-supplied input as the move.
class HumanPlayer extends Player {
  private pendingInputs: [number, number][] = [];

  supplyMove(row: number, col: number): void {
    this.pendingInputs.push([row, col]);
  }

  getMove(_board: Board): Move {
    const next = this.pendingInputs.shift();
    if (!next) throw new Error(`No input supplied for human player ${this.id}`);
    const [row, col] = next;
    return { row, col, symbol: this.symbol };
  }
}

// Delegates move selection to a MoveStrategy -- the algorithm itself is not hardcoded here.
class AIPlayer extends Player {
  constructor(id: string, symbol: Symbol, private readonly moveStrategy: MoveStrategy) {
    super(id, symbol);
  }
  getMove(board: Board): Move { return this.moveStrategy.decideMove(board, this.symbol); }
}

// ---------- TurnBasedGame (abstract, Template Method) ----------
abstract class TurnBasedGame {
  board!: Board;
  private turnIndex = 0;
  private finished = false;

  constructor(readonly players: Player[], private readonly winningStrategy: WinningStrategy) {}

  /** Hook: board dimensions/shape -- subclasses plug in their own structural piece. */
  protected abstract setupBoard(): void;
  protected abstract declareResult(type: 'WIN' | 'DRAW', player: Player | null): void;

  /** Template method: the fixed skeleton shared by any turn-based grid game. */
  play(): MoveResult {
    this.setupBoard();
    while (!this.finished) {
      const player = this.players[this.turnIndex % this.players.length];
      const move = player.getMove(this.board);
      if (!this.board.isValidMove(move.row, move.col)) continue; // human retries; AI never produces one
      this.board.placeMark(move.row, move.col, player.symbol);
      this.turnIndex++;
      if (this.winningStrategy.checkWinner(this.board, move)) {
        this.finished = true;
        this.declareResult('WIN', player);
        return { type: 'WIN', message: `${player.id} wins` };
      }
      if (this.board.isFull()) {
        this.finished = true;
        this.declareResult('DRAW', null);
        return { type: 'DRAW', message: 'draw' };
      }
    }
    return { type: 'OK', message: 'game already finished' };
  }
}

// Concrete N x N, K-in-a-row game (default Tic-Tac-Toe: 3x3, 3-in-a-row).
class TicTacToeGame extends TurnBasedGame {
  constructor(private readonly size: number, players: Player[], winningStrategy: WinningStrategy) {
    super(players, winningStrategy);
  }

  protected setupBoard(): void { this.board = new Board(this.size); }

  protected declareResult(type: 'WIN' | 'DRAW', player: Player | null): void {
    if (type === 'WIN' && player) console.log(`Result: ${player.id} (${player.symbol}) wins!`);
    else console.log('Result: draw');
    this.board.print();
  }
}

// ---------- GameController (facade) ----------
class GameController {
  constructor(private readonly game: TurnBasedGame) {}

  startGame(): MoveResult { return this.game.play(); }

  makeMove(playerId: string, row: number, col: number): MoveResult {
    for (const p of this.game.players) {
      if (p.id === playerId && p instanceof HumanPlayer) {
        p.supplyMove(row, col);
        return { type: 'OK', message: 'queued' };
      }
    }
    return { type: 'INVALID', message: `no such human player: ${playerId}` };
  }
}

// ---------- Demo ----------
function main(): void {
  const X: Symbol = 'X';
  const O: Symbol = 'O';

  const human = new HumanPlayer('P1', X);
  const ai = new AIPlayer('P2', O, new FirstAvailableMoveStrategy());

  // Pre-supply a scripted sequence of human moves for this non-interactive demo.
  // Column 0 is targeted (rather than row 0) so it never collides with the AI's
  // deterministic "first empty cell" picks, which fill row 0 left-to-right first.
  human.supplyMove(0, 0);
  human.supplyMove(1, 0);
  human.supplyMove(2, 0); // completes left column -> human should win

  const game = new TicTacToeGame(3, [human, ai], new LineScanWinningStrategy(3));
  const controller = new GameController(game);

  const result = controller.startGame();
  console.log(`Final: ${result.type} -- ${result.message}`);
}

if (require.main === module) {
  main();
}

export {
  Board, WinningStrategy, LineScanWinningStrategy, MoveStrategy, FirstAvailableMoveStrategy,
  Player, HumanPlayer, AIPlayer, TurnBasedGame, TicTacToeGame, GameController,
};

