// ATM Machine - full LLD implementation (single-file demo).
// No "Concurrency" badge -> single-threaded; the "must be atomic" requirement is
// modeled as BankServer.debit() being a single check-and-deduct call, not via locks.
//
// Design notes:
// - State pattern for the session: withdrawing from IdleState/CardInsertedState is
//   structurally unavailable (default no-op / rejection), not a scattered runtime if.
// - Chain of Responsibility for CashDispenser: each DenominationHandler only knows its
//   own denomination and passes a remainder to the next link - a new bill is a new
//   link, not a change to a central dispensing algorithm.
// - Strategy for Transaction: withdrawal/deposit/balance/transfer are mutually
//   exclusive alternatives selected once per session.
// - BankServer is the system of record for balance; ATM only tracks its own physical
//   cash tray - this is why WithdrawTransaction debits first, then dispenses, with a
//   compensating credit() if dispensing fails.
import java.util.*;

public class p14 {

    // ---------- Supporting domain types ----------
    static class Card {
        final String cardNumber;
        Card(String cardNumber) { this.cardNumber = cardNumber; }
    }

    static class Account {
        final String accountId;
        double balance;
        Account(String accountId, double balance) { this.accountId = accountId; this.balance = balance; }
    }

    enum AuthResult { SUCCESS, INVALID_PIN }
    enum DebitStatus { SUCCESS, INSUFFICIENT_FUNDS }
    static class DebitResult {
        final DebitStatus status;
        DebitResult(DebitStatus status) { this.status = status; }
    }

    enum TransactionResult { SUCCESS, INSUFFICIENT_FUNDS, DISPENSE_FAILED, BAD_AMOUNT }

    // ---------- BankServer (interface, external authority) ----------
    interface BankServer {
        AuthResult authenticate(Card card, String pin);
        Account accountFor(Card card);
        DebitResult debit(Account account, int amount);  // atomic check-and-deduct at the bank
        void credit(Account account, int amount);
    }

    // In-memory stand-in for "the bank" - the actual system of record for balance.
    static class SimpleBankServer implements BankServer {
        private final Map<String, String> pins = new HashMap<>();
        private final Map<String, Account> accountsByCard = new HashMap<>();

        void enroll(Card card, String pin, Account account) {
            pins.put(card.cardNumber, pin);
            accountsByCard.put(card.cardNumber, account);
        }

        public AuthResult authenticate(Card card, String pin) {
            return pin.equals(pins.get(card.cardNumber)) ? AuthResult.SUCCESS : AuthResult.INVALID_PIN;
        }

        public Account accountFor(Card card) { return accountsByCard.get(card.cardNumber); }

        // Atomic check-and-deduct: never leaves the account debited below zero.
        public synchronized DebitResult debit(Account account, int amount) {
            if (account.balance < amount) return new DebitResult(DebitStatus.INSUFFICIENT_FUNDS);
            account.balance -= amount;
            return new DebitResult(DebitStatus.SUCCESS);
        }

        public synchronized void credit(Account account, int amount) { account.balance += amount; }
    }

    // ---------- CashDispenser / DenominationHandler (Chain of Responsibility) ----------
    static class InsufficientCashException extends RuntimeException {
        InsufficientCashException(String msg) { super(msg); }
    }

    static abstract class DenominationHandler {
        final int value;
        int count;
        DenominationHandler next;
        DenominationHandler(int value, int count) { this.value = value; this.count = count; }

        void setNext(DenominationHandler next) { this.next = next; }

        // Greedily contributes as many of its own bills as it can, then passes the
        // remainder down the chain. Only knows its own denomination.
        void handle(int amount) {
            int used = Math.min(amount / value, count);
            if (used > 0) {
                count -= used;
                System.out.println("  dispensing " + used + " x $" + value);
            }
            int remainder = amount - used * value;
            if (remainder > 0 && next != null) next.handle(remainder);
            else if (remainder > 0) throw new InsufficientCashException("Cannot make change for remainder $" + remainder);
        }
    }

    static class TwentyHandler extends DenominationHandler { TwentyHandler(int count) { super(20, count); } }
    static class FiftyHandler extends DenominationHandler { FiftyHandler(int count) { super(50, count); } }
    static class HundredHandler extends DenominationHandler { HundredHandler(int count) { super(100, count); } }

    static class CashDispenser {
        private final DenominationHandler chainHead;
        CashDispenser(DenominationHandler chainHead) { this.chainHead = chainHead; }
        void dispense(int amount) { chainHead.handle(amount); }
    }

    // ---------- Transaction (interface, Strategy) ----------
    interface Transaction {
        TransactionResult execute(Account account, BankServer bank, ATM atm);
    }

    static class WithdrawTransaction implements Transaction {
        final int amount;
        WithdrawTransaction(int amount) { this.amount = amount; }
        public TransactionResult execute(Account account, BankServer bank, ATM atm) {
            if (amount <= 0) return TransactionResult.BAD_AMOUNT;
            DebitResult result = bank.debit(account, amount); // atomic at the bank
            if (result.status != DebitStatus.SUCCESS) return TransactionResult.INSUFFICIENT_FUNDS;
            try {
                atm.dispense(amount);
            } catch (InsufficientCashException e) {
                bank.credit(account, amount); // compensating action - never leave a debit stranded
                return TransactionResult.DISPENSE_FAILED;
            }
            return TransactionResult.SUCCESS;
        }
    }

    static class DepositTransaction implements Transaction {
        final int amount;
        DepositTransaction(int amount) { this.amount = amount; }
        public TransactionResult execute(Account account, BankServer bank, ATM atm) {
            if (amount <= 0) return TransactionResult.BAD_AMOUNT;
            bank.credit(account, amount);
            return TransactionResult.SUCCESS;
        }
    }

    static class BalanceInquiryTransaction implements Transaction {
        public TransactionResult execute(Account account, BankServer bank, ATM atm) {
            System.out.println("  Balance for " + account.accountId + ": $" + account.balance);
            return TransactionResult.SUCCESS;
        }
    }

    static class TransferTransaction implements Transaction {
        final Account destination;
        final int amount;
        TransferTransaction(Account destination, int amount) { this.destination = destination; this.amount = amount; }
        public TransactionResult execute(Account account, BankServer bank, ATM atm) {
            DebitResult result = bank.debit(account, amount);
            if (result.status != DebitStatus.SUCCESS) return TransactionResult.INSUFFICIENT_FUNDS;
            bank.credit(destination, amount);
            return TransactionResult.SUCCESS;
        }
    }

    // ---------- ATMState (interface, State) ----------
    interface ATMState {
        void insertCard(Card card);
        void enterPin(String pin);
        void selectTransaction(Transaction t);
        void ejectCard();
        String name();
    }

    static class IdleState implements ATMState {
        final ATM atm;
        IdleState(ATM atm) { this.atm = atm; }
        public void insertCard(Card card) {
            atm.currentCard = card;
            atm.setState(atm.cardInsertedState);
        }
        public void enterPin(String pin) { System.out.println("Reject: insert a card first"); }
        public void selectTransaction(Transaction t) { System.out.println("Reject: insert a card first"); }
        public void ejectCard() { System.out.println("Reject: no card to eject"); }
        public String name() { return "Idle"; }
    }

    static class CardInsertedState implements ATMState {
        final ATM atm;
        CardInsertedState(ATM atm) { this.atm = atm; }
        public void insertCard(Card card) { System.out.println("Reject: a card is already inserted"); }
        public void enterPin(String pin) {
            AuthResult result = atm.bank.authenticate(atm.currentCard, pin);
            if (result == AuthResult.SUCCESS) {
                atm.currentAccount = atm.bank.accountFor(atm.currentCard);
                atm.setState(atm.authenticatedState);
            } else {
                System.out.println("Reject: invalid PIN");
                atm.setState(atm.idleState);
                atm.currentCard = null;
            }
        }
        public void selectTransaction(Transaction t) { System.out.println("Reject: PIN not verified yet"); }
        public void ejectCard() { atm.currentCard = null; atm.setState(atm.idleState); }
        public String name() { return "CardInserted"; }
    }

    static class AuthenticatedState implements ATMState {
        final ATM atm;
        AuthenticatedState(ATM atm) { this.atm = atm; }
        public void insertCard(Card card) { System.out.println("Reject: session already active"); }
        public void enterPin(String pin) { System.out.println("Reject: already authenticated"); }
        public void selectTransaction(Transaction t) {
            atm.setState(atm.dispensingState);
            TransactionResult result = t.execute(atm.currentAccount, atm.bank, atm);
            System.out.println("  Transaction result: " + result);
            atm.setState(atm.authenticatedState); // back to menu for another transaction, or eject
        }
        public void ejectCard() { atm.currentCard = null; atm.currentAccount = null; atm.setState(atm.idleState); }
        public String name() { return "Authenticated"; }
    }

    // Transient state while a withdrawal's cash is physically moving; kept as its own
    // state so an in-progress dispense is a distinct, non-reentrant phase.
    static class DispensingState implements ATMState {
        final ATM atm;
        DispensingState(ATM atm) { this.atm = atm; }
        public void insertCard(Card card) { System.out.println("Reject: dispensing in progress"); }
        public void enterPin(String pin) { System.out.println("Reject: dispensing in progress"); }
        public void selectTransaction(Transaction t) { System.out.println("Reject: dispensing in progress"); }
        public void ejectCard() { System.out.println("Reject: dispensing in progress"); }
        public String name() { return "Dispensing"; }
    }

    static class OutOfServiceState implements ATMState {
        public void insertCard(Card card) { System.out.println("ATM out of service"); }
        public void enterPin(String pin) { System.out.println("ATM out of service"); }
        public void selectTransaction(Transaction t) { System.out.println("ATM out of service"); }
        public void ejectCard() { System.out.println("ATM out of service"); }
        public String name() { return "OutOfService"; }
    }

    // ---------- ATM (context) ----------
    static class ATM {
        ATMState currentState;
        final IdleState idleState = new IdleState(this);
        final CardInsertedState cardInsertedState = new CardInsertedState(this);
        final AuthenticatedState authenticatedState = new AuthenticatedState(this);
        final DispensingState dispensingState = new DispensingState(this);
        final OutOfServiceState outOfServiceState = new OutOfServiceState();

        final BankServer bank;
        final CashDispenser cashDispenser;
        Card currentCard;
        Account currentAccount;

        ATM(BankServer bank, CashDispenser cashDispenser) {
            this.bank = bank;
            this.cashDispenser = cashDispenser;
            this.currentState = idleState;
        }

        void setState(ATMState state) { this.currentState = state; }
        void dispense(int amount) { cashDispenser.dispense(amount); } // delegates to the chain

        void insertCard(Card card) { currentState.insertCard(card); }
        void enterPin(String pin) { currentState.enterPin(pin); }
        void selectTransaction(Transaction t) { currentState.selectTransaction(t); }
