// ATM Machine - full LLD implementation (single-file demo).
// No "Concurrency" badge -> single-threaded; the "must be atomic" requirement is
// modeled as BankServer::debit() being a single check-and-deduct call, not via mutexes.
//
// Design notes:
// - State pattern for the session: withdrawing from IdleState/CardInsertedState is
//   structurally unavailable (default rejection), not a scattered runtime if.
// - Chain of Responsibility for CashDispenser: each DenominationHandler only knows its
//   own denomination and passes a remainder to the next link.
// - Strategy for Transaction: withdrawal/deposit/balance/transfer are mutually
//   exclusive alternatives selected once per session.
// - BankServer is the system of record for balance; ATM only tracks its physical cash
//   tray - hence WithdrawTransaction debits first, then dispenses, with a compensating
//   credit() if dispensing fails.
#include <iostream>
#include <string>
#include <unordered_map>
#include <memory>
#include <stdexcept>

using namespace std;

// ---------- Supporting domain types ----------
struct Card { string cardNumber; };

struct Account {
    string accountId;
    double balance;
};

enum class AuthResult { SUCCESS, INVALID_PIN };
enum class DebitStatus { SUCCESS, INSUFFICIENT_FUNDS };
struct DebitResult { DebitStatus status; };

enum class TransactionResult { SUCCESS, INSUFFICIENT_FUNDS, DISPENSE_FAILED, BAD_AMOUNT };

static string toString(TransactionResult r) {
    switch (r) {
        case TransactionResult::SUCCESS: return "SUCCESS";
        case TransactionResult::INSUFFICIENT_FUNDS: return "INSUFFICIENT_FUNDS";
        case TransactionResult::DISPENSE_FAILED: return "DISPENSE_FAILED";
        case TransactionResult::BAD_AMOUNT: return "BAD_AMOUNT";
    }
    return "?";
}

class ATM; // fwd decl

// ---------- BankServer (interface, external authority) ----------
class BankServer {
public:
    virtual ~BankServer() = default;
    virtual AuthResult authenticate(const Card& card, const string& pin) = 0;
    virtual Account* accountFor(const Card& card) = 0;
    virtual DebitResult debit(Account& account, int amount) = 0; // atomic at the bank
    virtual void credit(Account& account, int amount) = 0;
};

class SimpleBankServer : public BankServer {
    unordered_map<string, string> pins;
    unordered_map<string, Account*> accountsByCard;
public:
    void enroll(const Card& card, const string& pin, Account* account) {
        pins[card.cardNumber] = pin;
        accountsByCard[card.cardNumber] = account;
    }
    AuthResult authenticate(const Card& card, const string& pin) override {
        auto it = pins.find(card.cardNumber);
        return (it != pins.end() && it->second == pin) ? AuthResult::SUCCESS : AuthResult::INVALID_PIN;
    }
    Account* accountFor(const Card& card) override { return accountsByCard.at(card.cardNumber); }
    // Atomic check-and-deduct: never leaves the account debited below zero.
    DebitResult debit(Account& account, int amount) override {
        if (account.balance < amount) return { DebitStatus::INSUFFICIENT_FUNDS };
        account.balance -= amount;
        return { DebitStatus::SUCCESS };
    }
    void credit(Account& account, int amount) override { account.balance += amount; }
};

// ---------- CashDispenser / DenominationHandler (Chain of Responsibility) ----------
struct InsufficientCashException : public runtime_error {
    InsufficientCashException(const string& msg) : runtime_error(msg) {}
};

class DenominationHandler {
public:
    int value;
    int count;
    DenominationHandler* next = nullptr;
    DenominationHandler(int value, int count) : value(value), count(count) {}
    virtual ~DenominationHandler() = default;
    void setNext(DenominationHandler* n) { next = n; }

    // Greedily contributes as many of its own bills as possible, passes the remainder on.
    void handle(int amount) {
        int used = min(amount / value, count);
        if (used > 0) {
            count -= used;
            cout << "  dispensing " << used << " x $" << value << "\n";
        }
        int remainder = amount - used * value;
        if (remainder > 0 && next != nullptr) next->handle(remainder);
        else if (remainder > 0) throw InsufficientCashException("Cannot make change for remainder $" + to_string(remainder));
    }
};

class TwentyHandler : public DenominationHandler { public: TwentyHandler(int c) : DenominationHandler(20, c) {} };
class FiftyHandler : public DenominationHandler { public: FiftyHandler(int c) : DenominationHandler(50, c) {} };
class HundredHandler : public DenominationHandler { public: HundredHandler(int c) : DenominationHandler(100, c) {} };

class CashDispenser {
    DenominationHandler* chainHead;
public:
    explicit CashDispenser(DenominationHandler* chainHead) : chainHead(chainHead) {}
    void dispense(int amount) { chainHead->handle(amount); }
};

// ---------- Transaction (interface, Strategy) ----------
class Transaction {
public:
    virtual ~Transaction() = default;
    virtual TransactionResult execute(Account& account, BankServer& bank, ATM& atm) = 0;
};

class WithdrawTransaction : public Transaction {
    int amount;
public:
    explicit WithdrawTransaction(int amount) : amount(amount) {}
    TransactionResult execute(Account& account, BankServer& bank, ATM& atm) override;
};

class DepositTransaction : public Transaction {
    int amount;
public:
    explicit DepositTransaction(int amount) : amount(amount) {}
    TransactionResult execute(Account& account, BankServer& bank, ATM&) override {
        if (amount <= 0) return TransactionResult::BAD_AMOUNT;
        bank.credit(account, amount);
        return TransactionResult::SUCCESS;
    }
};

class BalanceInquiryTransaction : public Transaction {
public:
    TransactionResult execute(Account& account, BankServer&, ATM&) override {
        cout << "  Balance for " << account.accountId << ": $" << account.balance << "\n";
        return TransactionResult::SUCCESS;
    }
};

class TransferTransaction : public Transaction {
    Account* destination;
    int amount;
public:
    TransferTransaction(Account* destination, int amount) : destination(destination), amount(amount) {}
    TransactionResult execute(Account& account, BankServer& bank, ATM&) override {
        DebitResult result = bank.debit(account, amount);
        if (result.status != DebitStatus::SUCCESS) return TransactionResult::INSUFFICIENT_FUNDS;
        bank.credit(*destination, amount);
        return TransactionResult::SUCCESS;
    }
};

// ---------- ATMState (interface, State) ----------
class ATMState {
public:
    virtual ~ATMState() = default;
    virtual void insertCard(const Card& card) = 0;
    virtual void enterPin(const string& pin) = 0;
    virtual void selectTransaction(Transaction& t) = 0;
    virtual void ejectCard() = 0;
    virtual string name() = 0;
};

// ---------- ATM (context) ----------
class ATM {
public:
    ATMState* currentState;
    unique_ptr<ATMState> idleState, cardInsertedState, authenticatedState, dispensingState, outOfServiceState;

    BankServer& bank;
    CashDispenser& cashDispenser;
    Card currentCard;
    bool hasCard = false;
    Account* currentAccount = nullptr;

    ATM(BankServer& bank, CashDispenser& dispenser);

    void setState(ATMState* state) { currentState = state; }
    void dispense(int amount) { cashDispenser.dispense(amount); } // delegates to the chain

    void insertCard(const Card& card) { currentState->insertCard(card); }
    void enterPin(const string& pin) { currentState->enterPin(pin); }
    void selectTransaction(Transaction& t) { currentState->selectTransaction(t); }
    void ejectCard() { currentState->ejectCard(); }
};

TransactionResult WithdrawTransaction::execute(Account& account, BankServer& bank, ATM& atm) {
    if (amount <= 0) return TransactionResult::BAD_AMOUNT;
    DebitResult result = bank.debit(account, amount); // atomic at the bank
    if (result.status != DebitStatus::SUCCESS) return TransactionResult::INSUFFICIENT_FUNDS;
    try {
        atm.dispense(amount);
    } catch (const InsufficientCashException&) {
        bank.credit(account, amount); // compensating action - never leave a debit stranded
        return TransactionResult::DISPENSE_FAILED;
    }
    return TransactionResult::SUCCESS;
}

class IdleStateImpl : public ATMState {
    ATM& atm;
public:
    explicit IdleStateImpl(ATM& atm) : atm(atm) {}
    void insertCard(const Card& card) override;
    void enterPin(const string&) override { cout << "Reject: insert a card first\n"; }
    void selectTransaction(Transaction&) override { cout << "Reject: insert a card first\n"; }
    void ejectCard() override { cout << "Reject: no card to eject\n"; }
    string name() override { return "Idle"; }
};

class CardInsertedStateImpl : public ATMState {
    ATM& atm;
public:
    explicit CardInsertedStateImpl(ATM& atm) : atm(atm) {}
    void insertCard(const Card&) override { cout << "Reject: a card is already inserted\n"; }
    void enterPin(const string& pin) override;
    void selectTransaction(Transaction&) override { cout << "Reject: PIN not verified yet\n"; }
    void ejectCard() override { atm.hasCard = false; atm.setState(atm.idleState.get()); }
    string name() override { return "CardInserted"; }
};

class AuthenticatedStateImpl : public ATMState {
    ATM& atm;
public:
    explicit AuthenticatedStateImpl(ATM& atm) : atm(atm) {}
    void insertCard(const Card&) override { cout << "Reject: session already active\n"; }
    void enterPin(const string&) override { cout << "Reject: already authenticated\n"; }
    void selectTransaction(Transaction& t) override {
        atm.setState(atm.dispensingState.get());
        TransactionResult result = t.execute(*atm.currentAccount, atm.bank, atm);
        cout << "  Transaction result: " << toString(result) << "\n";
        atm.setState(atm.authenticatedState.get()); // back to menu, or eject
    }
    void ejectCard() override { atm.hasCard = false; atm.currentAccount = nullptr; atm.setState(atm.idleState.get()); }
    string name() override { return "Authenticated"; }
};

// Transient state while cash is physically moving - a distinct, non-reentrant phase.
class DispensingStateImpl : public ATMState {
public:
    void insertCard(const Card&) override { cout << "Reject: dispensing in progress\n"; }
    void enterPin(const string&) override { cout << "Reject: dispensing in progress\n"; }
    void selectTransaction(Transaction&) override { cout << "Reject: dispensing in progress\n"; }
    void ejectCard() override { cout << "Reject: dispensing in progress\n"; }
    string name() override { return "Dispensing"; }
};

class OutOfServiceStateImpl : public ATMState {
public:
    void insertCard(const Card&) override { cout << "ATM out of service\n"; }
    void enterPin(const string&) override { cout << "ATM out of service\n"; }
    void selectTransaction(Transaction&) override { cout << "ATM out of service\n"; }
    void ejectCard() override { cout << "ATM out of service\n"; }
    string name() override { return "OutOfService"; }
};

void IdleStateImpl::insertCard(const Card& card) {
    atm.currentCard = card;
    atm.hasCard = true;
    atm.setState(atm.cardInsertedState.get());
}

void CardInsertedStateImpl::enterPin(const string& pin) {
    AuthResult result = atm.bank.authenticate(atm.currentCard, pin);
    if (result == AuthResult::SUCCESS) {
        atm.currentAccount = atm.bank.accountFor(atm.currentCard);
        atm.setState(atm.authenticatedState.get());
    } else {
        cout << "Reject: invalid PIN\n";
        atm.setState(atm.idleState.get());
        atm.hasCard = false;
    }
}

ATM::ATM(BankServer& bank, CashDispenser& dispenser) : bank(bank), cashDispenser(dispenser) {
    idleState = make_unique<IdleStateImpl>(*this);
    cardInsertedState = make_unique<CardInsertedStateImpl>(*this);
    authenticatedState = make_unique<AuthenticatedStateImpl>(*this);
    dispensingState = make_unique<DispensingStateImpl>();
    outOfServiceState = make_unique<OutOfServiceStateImpl>();
    currentState = idleState.get();
}

// ---------- Demo ----------
int main() {
    SimpleBankServer bank;
    Card card{"4111-CARD"};
    Account account{"ACC-1", 500};
    Account friendAccount{"ACC-2", 0};
    bank.enroll(card, "1234", &account);

    HundredHandler hundreds(3);
    FiftyHandler fifties(2);
    TwentyHandler twenties(5);
    hundreds.setNext(&fifties);
    fifties.setNext(&twenties);
    CashDispenser dispenser(&hundreds);

    ATM atm(bank, dispenser);

    atm.insertCard(card);
    cout << "State: " << atm.currentState->name() << "\n";
    atm.enterPin("0000"); // wrong PIN -> ejects back to idle
    cout << "State after bad PIN: " << atm.currentState->name() << "\n";

    atm.insertCard(card);
    atm.enterPin("1234"); // correct PIN
    cout << "State: " << atm.currentState->name() << "\n";

    BalanceInquiryTransaction balanceTxn;
    atm.selectTransaction(balanceTxn);
    WithdrawTransaction withdraw170(170); // 1x100 + 1x50 + 1x20
    atm.selectTransaction(withdraw170);
    atm.selectTransaction(balanceTxn);
    TransferTransaction transfer(&friendAccount, 100);
    atm.selectTransaction(transfer);
    cout << "  Friend balance: $" << friendAccount.balance << "\n";

    DepositTransaction deposit500(500);
    atm.selectTransaction(deposit500);
    WithdrawTransaction withdraw300(300); // exceeds remaining cash on hand -> compensating credit
    atm.selectTransaction(withdraw300);
    atm.selectTransaction(balanceTxn);

    atm.ejectCard();
    cout << "State: " << atm.currentState->name() << "\n";
    return 0;
}

