// No "Concurrency" badge -> single-threaded; the "must be atomic" requirement is
// modeled as BankServer.debit() being a single check-and-deduct call, not via locks.
//
// Design notes:
// - State pattern for the session: withdrawing from IdleState/CardInsertedState is
//   structurally unavailable (default rejection), not a scattered runtime if.
// - Chain of Responsibility for CashDispenser: each DenominationHandler only knows its
//   own denomination and passes a remainder to the next link.
// - Strategy for Transaction: withdrawal/deposit/balance/transfer are mutually
//   exclusive alternatives selected once per session.
// - BankServer is the system of record for balance; ATM only tracks its physical cash
//   tray - hence WithdrawTransaction debits first, then dispenses, with a compensating
//   credit() if dispensing fails.

class Card {
  constructor(cardNumber) { this.cardNumber = cardNumber; }
}

class Account {
  constructor(accountId, balance) { this.accountId = accountId; this.balance = balance; }
}

const AuthResult = Object.freeze({ SUCCESS: 'SUCCESS', INVALID_PIN: 'INVALID_PIN' });
const DebitStatus = Object.freeze({ SUCCESS: 'SUCCESS', INSUFFICIENT_FUNDS: 'INSUFFICIENT_FUNDS' });
const TransactionResult = Object.freeze({
  SUCCESS: 'SUCCESS', INSUFFICIENT_FUNDS: 'INSUFFICIENT_FUNDS',
  DISPENSE_FAILED: 'DISPENSE_FAILED', BAD_AMOUNT: 'BAD_AMOUNT',
});

class InsufficientCashException extends Error {}

// ---------- BankServer (interface, external authority) ----------
class BankServer {
  authenticate(_card, _pin) { throw new Error('not implemented'); }
  accountFor(_card) { throw new Error('not implemented'); }
  debit(_account, _amount) { throw new Error('not implemented'); }
  credit(_account, _amount) { throw new Error('not implemented'); }
}

class SimpleBankServer extends BankServer {
  constructor() {
    super();
    this.pins = new Map();
    this.accountsByCard = new Map();
  }
  enroll(card, pin, account) {
    this.pins.set(card.cardNumber, pin);
    this.accountsByCard.set(card.cardNumber, account);
  }
  authenticate(card, pin) {
    return this.pins.get(card.cardNumber) === pin ? AuthResult.SUCCESS : AuthResult.INVALID_PIN;
  }
  accountFor(card) { return this.accountsByCard.get(card.cardNumber); }
  // Atomic check-and-deduct: never leaves the account debited below zero.
  debit(account, amount) {
    if (account.balance < amount) return { status: DebitStatus.INSUFFICIENT_FUNDS };
    account.balance -= amount;
    return { status: DebitStatus.SUCCESS };
  }
  credit(account, amount) { account.balance += amount; }
}

// ---------- CashDispenser / DenominationHandler (Chain of Responsibility) ----------
class DenominationHandler {
  constructor(value, count) {
    this.value = value;
    this.count = count;
    this.next = null;
  }
  setNext(next) { this.next = next; }

  // Greedily contributes as many of its own bills as possible, passes the remainder on.
  handle(amount) {
    const used = Math.min(Math.floor(amount / this.value), this.count);
    if (used > 0) {
      this.count -= used;
      console.log(`  dispensing ${used} x $${this.value}`);
    }
    const remainder = amount - used * this.value;
    if (remainder > 0 && this.next != null) this.next.handle(remainder);
    else if (remainder > 0) throw new InsufficientCashException(`Cannot make change for remainder $${remainder}`);
  }
}

class TwentyHandler extends DenominationHandler { constructor(count) { super(20, count); } }
class FiftyHandler extends DenominationHandler { constructor(count) { super(50, count); } }
class HundredHandler extends DenominationHandler { constructor(count) { super(100, count); } }

class CashDispenser {
  constructor(chainHead) { this.chainHead = chainHead; }
  dispense(amount) { this.chainHead.handle(amount); }
}

// ---------- Transaction (interface, Strategy) ----------
class Transaction {
  execute(_account, _bank, _atm) { throw new Error('not implemented'); }
}

class WithdrawTransaction extends Transaction {
  constructor(amount) { super(); this.amount = amount; }
  execute(account, bank, atm) {
    if (this.amount <= 0) return TransactionResult.BAD_AMOUNT;
    const result = bank.debit(account, this.amount); // atomic at the bank
    if (result.status !== DebitStatus.SUCCESS) return TransactionResult.INSUFFICIENT_FUNDS;
    try {
      atm.dispense(this.amount);
    } catch (e) {
      if (!(e instanceof InsufficientCashException)) throw e;
      bank.credit(account, this.amount); // compensating action - never leave a debit stranded
      return TransactionResult.DISPENSE_FAILED;
    }
    return TransactionResult.SUCCESS;
  }
}

class DepositTransaction extends Transaction {
  constructor(amount) { super(); this.amount = amount; }
  execute(account, bank, _atm) {
    if (this.amount <= 0) return TransactionResult.BAD_AMOUNT;
    bank.credit(account, this.amount);
    return TransactionResult.SUCCESS;
  }
}

class BalanceInquiryTransaction extends Transaction {
  execute(account, _bank, _atm) {
    console.log(`  Balance for ${account.accountId}: $${account.balance}`);
    return TransactionResult.SUCCESS;
  }
}

class TransferTransaction extends Transaction {
  constructor(destination, amount) { super(); this.destination = destination; this.amount = amount; }
  execute(account, bank, _atm) {
    const result = bank.debit(account, this.amount);
    if (result.status !== DebitStatus.SUCCESS) return TransactionResult.INSUFFICIENT_FUNDS;
    bank.credit(this.destination, this.amount);
    return TransactionResult.SUCCESS;
  }
}

// ---------- ATMState (interface, State) ----------
