  atm.selectTransaction(new TransferTransaction(friendAccount, 100));
  console.log(`  Friend balance: $${friendAccount.balance}`);

  atm.selectTransaction(new DepositTransaction(500));
  atm.selectTransaction(new WithdrawTransaction(300)); // exceeds remaining cash -> compensating credit
  atm.selectTransaction(new BalanceInquiryTransaction());

  atm.ejectCard();
  console.log('State:', atm.currentState.name());
}

if (require.main === module) main();

module.exports = {
