// ATM Machine - full LLD implementation (single-file demo).
// No "Concurrency" badge -> single-threaded; the "must be atomic" requirement is
// modeled as BankServer.debit() being a single check-and-deduct call, not via locks.
//
// Design notes:
// - State pattern for the session: withdrawing from IdleState/CardInsertedState is
//   structurally unavailable (default rejection), not a scattered runtime if.
// - Chain of Responsibility for CashDispenser: each DenominationHandler only knows its
//   own denomination and passes a remainder to the next link.
// - Strategy for Transaction: withdrawal/deposit/balance/transfer are mutually
//   exclusive alternatives selected once per session.
// - BankServer is the system of record for balance; ATM only tracks its physical cash
//   tray - hence WithdrawTransaction debits first, then dispenses, with a compensating
//   credit() if dispensing fails.

class Card {
  constructor(public cardNumber: string) {}
}

class Account {
  constructor(public accountId: string, public balance: number) {}
}

enum AuthResult { SUCCESS = 'SUCCESS', INVALID_PIN = 'INVALID_PIN' }
enum DebitStatus { SUCCESS = 'SUCCESS', INSUFFICIENT_FUNDS = 'INSUFFICIENT_FUNDS' }
interface DebitResult { status: DebitStatus; }

enum TransactionResult {
  SUCCESS = 'SUCCESS', INSUFFICIENT_FUNDS = 'INSUFFICIENT_FUNDS',
  DISPENSE_FAILED = 'DISPENSE_FAILED', BAD_AMOUNT = 'BAD_AMOUNT',
}

class InsufficientCashException extends Error {}

// ---------- BankServer (interface, external authority) ----------
interface BankServer {
  authenticate(card: Card, pin: string): AuthResult;
  accountFor(card: Card): Account;
  debit(account: Account, amount: number): DebitResult; // atomic at the bank
  credit(account: Account, amount: number): void;
}

class SimpleBankServer implements BankServer {
  private pins = new Map<string, string>();
  private accountsByCard = new Map<string, Account>();

  enroll(card: Card, pin: string, account: Account): void {
    this.pins.set(card.cardNumber, pin);
    this.accountsByCard.set(card.cardNumber, account);
  }

  authenticate(card: Card, pin: string): AuthResult {
    return this.pins.get(card.cardNumber) === pin ? AuthResult.SUCCESS : AuthResult.INVALID_PIN;
  }

  accountFor(card: Card): Account {
    const account = this.accountsByCard.get(card.cardNumber);
    if (!account) throw new Error('Unknown card');
    return account;
  }

  // Atomic check-and-deduct: never leaves the account debited below zero.
  debit(account: Account, amount: number): DebitResult {
    if (account.balance < amount) return { status: DebitStatus.INSUFFICIENT_FUNDS };
    account.balance -= amount;
    return { status: DebitStatus.SUCCESS };
  }

  credit(account: Account, amount: number): void { account.balance += amount; }
}

// ---------- CashDispenser / DenominationHandler (Chain of Responsibility) ----------
abstract class DenominationHandler {
  next: DenominationHandler | null = null;
  constructor(public value: number, public count: number) {}
  setNext(next: DenominationHandler): void { this.next = next; }

  // Greedily contributes as many of its own bills as possible, passes the remainder on.
  handle(amount: number): void {
    const used = Math.min(Math.floor(amount / this.value), this.count);
    if (used > 0) {
      this.count -= used;
      console.log(`  dispensing ${used} x $${this.value}`);
    }
    const remainder = amount - used * this.value;
    if (remainder > 0 && this.next != null) this.next.handle(remainder);
    else if (remainder > 0) throw new InsufficientCashException(`Cannot make change for remainder $${remainder}`);
  }
}

class TwentyHandler extends DenominationHandler { constructor(count: number) { super(20, count); } }
class FiftyHandler extends DenominationHandler { constructor(count: number) { super(50, count); } }
class HundredHandler extends DenominationHandler { constructor(count: number) { super(100, count); } }

class CashDispenser {
  constructor(private chainHead: DenominationHandler) {}
  dispense(amount: number): void { this.chainHead.handle(amount); }
}

// ---------- Transaction (interface, Strategy) ----------
interface Transaction {
  execute(account: Account, bank: BankServer, atm: ATM): TransactionResult;
}

class WithdrawTransaction implements Transaction {
  constructor(private amount: number) {}
  execute(account: Account, bank: BankServer, atm: ATM): TransactionResult {
    if (this.amount <= 0) return TransactionResult.BAD_AMOUNT;
    const result = bank.debit(account, this.amount); // atomic at the bank
    if (result.status !== DebitStatus.SUCCESS) return TransactionResult.INSUFFICIENT_FUNDS;
    try {
      atm.dispense(this.amount);
    } catch (e) {
      if (!(e instanceof InsufficientCashException)) throw e;
      bank.credit(account, this.amount); // compensating action - never leave a debit stranded
      return TransactionResult.DISPENSE_FAILED;
    }
    return TransactionResult.SUCCESS;
  }
}

class DepositTransaction implements Transaction {
  constructor(private amount: number) {}
  execute(account: Account, bank: BankServer, _atm: ATM): TransactionResult {
    if (this.amount <= 0) return TransactionResult.BAD_AMOUNT;
    bank.credit(account, this.amount);
    return TransactionResult.SUCCESS;
  }
}

class BalanceInquiryTransaction implements Transaction {
  execute(account: Account, _bank: BankServer, _atm: ATM): TransactionResult {
    console.log(`  Balance for ${account.accountId}: $${account.balance}`);
    return TransactionResult.SUCCESS;
  }
}

class TransferTransaction implements Transaction {
  constructor(private destination: Account, private amount: number) {}
  execute(account: Account, bank: BankServer, _atm: ATM): TransactionResult {
    const result = bank.debit(account, this.amount);
    if (result.status !== DebitStatus.SUCCESS) return TransactionResult.INSUFFICIENT_FUNDS;
    bank.credit(this.destination, this.amount);
    return TransactionResult.SUCCESS;
  }
}

// ---------- ATMState (interface, State) ----------
interface ATMState {
  insertCard(card: Card): void;
  enterPin(pin: string): void;
  selectTransaction(t: Transaction): void;
  ejectCard(): void;
  name(): string;
}

class IdleState implements ATMState {
  constructor(private atm: ATM) {}
  insertCard(card: Card): void {
    this.atm.currentCard = card;
    this.atm.setState(this.atm.cardInsertedState);
  }
  enterPin(_pin: string): void { console.log('Reject: insert a card first'); }
  selectTransaction(_t: Transaction): void { console.log('Reject: insert a card first'); }
  ejectCard(): void { console.log('Reject: no card to eject'); }
  name(): string { return 'Idle'; }
}

class CardInsertedState implements ATMState {
  constructor(private atm: ATM) {}
  insertCard(_card: Card): void { console.log('Reject: a card is already inserted'); }
  enterPin(pin: string): void {
    const result = this.atm.bank.authenticate(this.atm.currentCard as Card, pin);
    if (result === AuthResult.SUCCESS) {
      this.atm.currentAccount = this.atm.bank.accountFor(this.atm.currentCard as Card);
      this.atm.setState(this.atm.authenticatedState);
    } else {
      console.log('Reject: invalid PIN');
      this.atm.setState(this.atm.idleState);
      this.atm.currentCard = null;
    }
  }
  selectTransaction(_t: Transaction): void { console.log('Reject: PIN not verified yet'); }
  ejectCard(): void { this.atm.currentCard = null; this.atm.setState(this.atm.idleState); }
  name(): string { return 'CardInserted'; }
}

class AuthenticatedState implements ATMState {
  constructor(private atm: ATM) {}
  insertCard(_card: Card): void { console.log('Reject: session already active'); }
  enterPin(_pin: string): void { console.log('Reject: already authenticated'); }
  selectTransaction(t: Transaction): void {
    this.atm.setState(this.atm.dispensingState);
    const result = t.execute(this.atm.currentAccount as Account, this.atm.bank, this.atm);
    console.log(`  Transaction result: ${result}`);
    this.atm.setState(this.atm.authenticatedState); // back to menu, or eject
  }
  ejectCard(): void {
    this.atm.currentCard = null;
    this.atm.currentAccount = null;
    this.atm.setState(this.atm.idleState);
  }
  name(): string { return 'Authenticated'; }
}

// Transient state while cash is physically moving - a distinct, non-reentrant phase.
class DispensingState implements ATMState {
  insertCard(_card: Card): void { console.log('Reject: dispensing in progress'); }
  enterPin(_pin: string): void { console.log('Reject: dispensing in progress'); }
  selectTransaction(_t: Transaction): void { console.log('Reject: dispensing in progress'); }
  ejectCard(): void { console.log('Reject: dispensing in progress'); }
  name(): string { return 'Dispensing'; }
}

class OutOfServiceState implements ATMState {
  insertCard(_card: Card): void { console.log('ATM out of service'); }
  enterPin(_pin: string): void { console.log('ATM out of service'); }
  selectTransaction(_t: Transaction): void { console.log('ATM out of service'); }
  ejectCard(): void { console.log('ATM out of service'); }
  name(): string { return 'OutOfService'; }
}

// ---------- ATM (context) ----------
class ATM {
  currentState: ATMState;
  idleState: ATMState;
  cardInsertedState: ATMState;
  authenticatedState: ATMState;
  dispensingState: ATMState;
  outOfServiceState: ATMState;
  currentCard: Card | null = null;
  currentAccount: Account | null = null;

  constructor(public bank: BankServer, private cashDispenser: CashDispenser) {
    this.idleState = new IdleState(this);
    this.cardInsertedState = new CardInsertedState(this);
    this.authenticatedState = new AuthenticatedState(this);
    this.dispensingState = new DispensingState();
    this.outOfServiceState = new OutOfServiceState();
    this.currentState = this.idleState;
  }

  setState(state: ATMState): void { this.currentState = state; }
  dispense(amount: number): void { this.cashDispenser.dispense(amount); } // delegates to the chain

  insertCard(card: Card): void { this.currentState.insertCard(card); }
  enterPin(pin: string): void { this.currentState.enterPin(pin); }
  selectTransaction(t: Transaction): void { this.currentState.selectTransaction(t); }
  ejectCard(): void { this.currentState.ejectCard(); }
}

// ---------- Demo ----------
function main(): void {
  const bank = new SimpleBankServer();
  const card = new Card('4111-CARD');
  const account = new Account('ACC-1', 500);
  const friendAccount = new Account('ACC-2', 0);
  bank.enroll(card, '1234', account);

  const hundreds = new HundredHandler(3);
  const fifties = new FiftyHandler(2);
  const twenties = new TwentyHandler(5);
  hundreds.setNext(fifties);
  fifties.setNext(twenties);
  const dispenser = new CashDispenser(hundreds);

  const atm = new ATM(bank, dispenser);

  atm.insertCard(card);
  console.log('State:', atm.currentState.name());
  atm.enterPin('0000'); // wrong PIN -> ejects back to idle
  console.log('State after bad PIN:', atm.currentState.name());

  atm.insertCard(card);
  atm.enterPin('1234'); // correct PIN
  console.log('State:', atm.currentState.name());

  atm.selectTransaction(new BalanceInquiryTransaction());
  atm.selectTransaction(new WithdrawTransaction(170)); // 1x100 + 1x50 + 1x20
  atm.selectTransaction(new BalanceInquiryTransaction());
  atm.selectTransaction(new TransferTransaction(friendAccount, 100));
  console.log(`  Friend balance: $${friendAccount.balance}`);

  atm.selectTransaction(new DepositTransaction(500));
  atm.selectTransaction(new WithdrawTransaction(300)); // exceeds remaining cash -> compensating credit
  atm.selectTransaction(new BalanceInquiryTransaction());

  atm.ejectCard();
  console.log('State:', atm.currentState.name());
}

main();

export {
  Card, Account, AuthResult, DebitStatus, TransactionResult, BankServer, SimpleBankServer,
  DenominationHandler, TwentyHandler, FiftyHandler, HundredHandler, CashDispenser,
  Transaction, WithdrawTransaction, DepositTransaction, BalanceInquiryTransaction, TransferTransaction,
  ATMState, IdleState, CardInsertedState, AuthenticatedState, DispensingState, OutOfServiceState, ATM,
};

p15-ag.java:
// Library Management System - full LLD implementation (single-file demo).
// No "Concurrency" badge -> single-threaded; the "two members racing the last copy"
// requirement is satisfied by checkout() being one atomic status-check-and-flip step
// against a single BookItem, not by explicit locking primitives.
//
// Design notes:
// - Book (title metadata) vs. BookItem (physical copy) is the central modeling
//   decision: metadata is shared/immutable across copies, status is per-copy and
//   constantly changing.
// - Observer for holds: BookItem.returnItem() notifies the title's HoldQueue, which
//   pops the next Hold in FIFO order and hands the copy to that member - decoupling
//   "a copy became available" from "who reacts to that".
// - Strategy for fines: FineStrategy.calculateFine(loan) isolates rate changes from
//   Loan/Library's record-keeping code.
import java.util.*;

public class p15 {

    enum ItemStatus { AVAILABLE, CHECKED_OUT, ON_HOLD, LOST }
    enum Category { FICTION, NON_FICTION, REFERENCE }
    enum MembershipType { REGULAR, PREMIUM }

    // ---------- Book (title-level metadata) ----------
    static class Book {
        final String isbn, title, author;
        final Category category;
        Book(String isbn, String title, String author, Category category) {
            this.isbn = isbn; this.title = title; this.author = author; this.category = category;
        }
    }

    // ---------- BookItem (one physical, lendable copy) ----------
    static class BookItem {
        final String barcode;
        final Book book;
        ItemStatus status = ItemStatus.AVAILABLE;
        Date dueDate;
        final Library library; // back-reference used to reach the right HoldQueue on return

        BookItem(String barcode, Book book, Library library) {
            this.barcode = barcode; this.book = book; this.library = library;
        }

        // Marks the copy checked out; Library owns creating/recording the Loan itself.
        void checkout(Date dueDate) {
            this.status = ItemStatus.CHECKED_OUT;
            this.dueDate = dueDate;
        }

        // Flips back to available, then defers to the title's HoldQueue (Observer) to
        // decide whether this copy should instead go straight to the next waiting member.
        void returnItem() {
            this.status = ItemStatus.AVAILABLE;
            this.dueDate = null;
            HoldQueue queue = library.holdQueueFor(book);
            if (queue != null && queue.hasWaiting()) {
                Hold nextHold = queue.popNext();
                this.status = ItemStatus.ON_HOLD; // reserved, not generally available
                queue.notifyNext(this, nextHold);
            }
        }
    }

    // ---------- Member ----------
    static class Member {
        final String id;
        final MembershipType membershipType;
        final List<Loan> activeLoans = new ArrayList<>();
        final List<Hold> activeHolds = new ArrayList<>();
        Member(String id, MembershipType membershipType) { this.id = id; this.membershipType = membershipType; }
    }

    // ---------- Loan (one active checkout record) ----------
    static class Loan {
        final Member member;
        final BookItem bookItem;
        final Date checkoutDate;
        final Date dueDate;
        boolean returned = false;

        Loan(Member member, BookItem bookItem, Date checkoutDate, Date dueDate) {
            this.member = member; this.bookItem = bookItem; this.checkoutDate = checkoutDate; this.dueDate = dueDate;
        }

        boolean isOverdue(Date asOf) { return !returned && asOf.after(dueDate); }
    }

    // ---------- Hold (one member's place in a title's wait queue) ----------
    static class Hold {
        final Member member;
        final Book book;
        final long timestamp;
        Hold(Member member, Book book, long timestamp) { this.member = member; this.book = book; this.timestamp = timestamp; }
    }

    // ---------- HoldQueue (FIFO wait list + Observer subject for availability) ----------
    static class HoldQueue {
        private final Deque<Hold> queue = new ArrayDeque<>();

        void addHold(Hold hold) { queue.addLast(hold); }
        boolean hasWaiting() { return !queue.isEmpty(); }
        Hold popNext() { return queue.pollFirst(); }
        int waitingCount() { return queue.size(); }

        // The "reaction" side of the Observer relationship: BookItem triggers this,
        // HoldQueue decides who gets notified. A real system would email/page the
        // member here; we just print, and record it as satisfied.
        void notifyNext(BookItem item, Hold hold) {
            hold.member.activeHolds.remove(hold);
            System.out.println("  Notifying " + hold.member.id + ": your hold on \"" + item.book.title + "\" is ready (barcode " + item.barcode + ")");
        }
    }

    // ---------- FineStrategy (interface, Strategy) ----------
    interface FineStrategy {
        double calculateFine(Loan loan, Date asOf);
    }

    // Rate depends on both member type and item category - isolated here so a rate
    // change never touches Loan or Library.
    static class StandardFineStrategy implements FineStrategy {
        public double calculateFine(Loan loan, Date asOf) {
            if (!loan.isOverdue(asOf)) return 0.0;
            long overdueDays = (asOf.getTime() - loan.dueDate.getTime()) / (1000L * 60 * 60 * 24) + 1;
            double perDay = loan.bookItem.book.category == Category.REFERENCE ? 1.0 : 0.25;
            if (loan.member.membershipType == MembershipType.PREMIUM) perDay *= 0.5; // premium discount
            return overdueDays * perDay;
        }
    }

    // ---------- Catalog (search index over Book entries) ----------
    static class Catalog {
        private final List<Book> books = new ArrayList<>();
        void addBook(Book book) { books.add(book); }

        List<Book> search(String query) {
            String q = query.toLowerCase();
            List<Book> results = new ArrayList<>();
            for (Book b : books) {
                if (b.title.toLowerCase().contains(q) || b.author.toLowerCase().contains(q)
                        || b.category.name().toLowerCase().contains(q)) {
                    results.add(b);
                }
            }
            return results;
        }
    }

    // ---------- Library (facade) ----------
    static class Library {
        final Catalog catalog = new Catalog();
        final Map<String, BookItem> itemsByBarcode = new HashMap<>();
        final Map<String, Loan> activeLoanByBarcode = new HashMap<>();
        final Map<String, HoldQueue> holdQueuesByIsbn = new HashMap<>();
        final FineStrategy fineStrategy;
        private static final long LOAN_PERIOD_MILLIS = 14L * 24 * 60 * 60 * 1000; // 14 days, flat for demo

        Library(FineStrategy fineStrategy) { this.fineStrategy = fineStrategy; }

        void addBookItem(BookItem item) { itemsByBarcode.put(item.barcode, item); }

        HoldQueue holdQueueFor(Book book) { return holdQueuesByIsbn.get(book.isbn); }

        List<Book> search(String query) { return catalog.search(query); }

        // Single atomic status-check-and-flip against one BookItem - this is exactly
        // what stops two members both succeeding against what they each believe is
        // "the last copy".
        Loan checkout(Member member, String barcode) {
            BookItem item = itemsByBarcode.get(barcode);
            if (item == null) throw new IllegalArgumentException("No such item: " + barcode);
            if (item.status != ItemStatus.AVAILABLE) return null; // reject: not free to check out

            Date due = new Date(System.currentTimeMillis() + LOAN_PERIOD_MILLIS);
            item.checkout(due);
            Loan loan = new Loan(member, item, new Date(), due);
            member.activeLoans.add(loan);
            activeLoanByBarcode.put(barcode, loan);
            return loan;
        }

        void returnItem(String barcode) {
            BookItem item = itemsByBarcode.get(barcode);
            if (item == null) throw new IllegalArgumentException("No such item: " + barcode);
            Loan loan = activeLoanByBarcode.remove(barcode);
            if (loan != null) {
                loan.returned = true;
                loan.member.activeLoans.remove(loan);
            }
            item.returnItem(); // triggers the HoldQueue Observer hook internally
        }

        double calculateFine(Loan loan) { return fineStrategy.calculateFine(loan, new Date()); }

        // Places a hold only when no copy is free; otherwise the member should just checkout.
        void placeHold(Member member, Book book) {
            HoldQueue queue = holdQueuesByIsbn.computeIfAbsent(book.isbn, k -> new HoldQueue());
            Hold hold = new Hold(member, book, System.currentTimeMillis());
            queue.addHold(hold);
            member.activeHolds.add(hold);
        }
    }

    // ---------- Demo ----------
    public static void main(String[] args) throws InterruptedException {
        Library library = new Library(new StandardFineStrategy());

        Book book = new Book("978-1", "The Pragmatic Programmer", "Hunt & Thomas", Category.NON_FICTION);
        library.catalog.addBook(book);
        BookItem copy1 = new BookItem("BC-1", book, library);
        BookItem copy2 = new BookItem("BC-2", book, library);
        library.addBookItem(copy1);
        library.addBookItem(copy2);

        System.out.println("Search 'pragmatic': " + library.search("pragmatic").size() + " result(s)");

        Member alice = new Member("alice", MembershipType.REGULAR);
        Member bob = new Member("bob", MembershipType.PREMIUM);
        Member carol = new Member("carol", MembershipType.REGULAR);

        Loan loan1 = library.checkout(alice, "BC-1");
        Loan loan2 = library.checkout(bob, "BC-2");
        System.out.println("Alice checked out BC-1: " + (loan1 != null));
        System.out.println("Bob checked out BC-2: " + (loan2 != null));

        // Both copies are gone now - Carol must queue for a hold instead of a 3rd checkout.
        Loan failedLoan = library.checkout(carol, "BC-1");
        System.out.println("Carol tries BC-1 while checked out: " + (failedLoan == null ? "rejected as expected" : "unexpectedly succeeded"));
        library.placeHold(carol, book);
        System.out.println("Carol placed a hold; queue size: " + library.holdQueueFor(book).waitingCount());

        // Alice returns her copy -> Observer hook should notify Carol and reserve BC-1 for her.
        library.returnItem("BC-1");
        System.out.println("BC-1 status after return: " + copy1.status);

        // Simulate an overdue fine: backdate the due date on Bob's loan and price it.
        loan2.dueDate.setTime(System.currentTimeMillis() - (3L * 24 * 60 * 60 * 1000));
        double fine = library.calculateFine(loan2);
        System.out.println("Bob's fine for 3 overdue days (premium discount applied): $" + fine);
    }
}

