import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.*;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

/**
 * Problem 16: Hotel Reservation System
 *
 * Key design decisions faithfully reproduced from the class diagram:
 *  - Room (static attrs) vs RoomInventory (per-room booked-interval calendar) split.
 *  - ReservationRequestBuilder assembles an in-progress booking intent step by step.
 *  - PricingStrategy is injected (Strategy) so pricing rules can change independently.
 *  - BookingNotifier is a thin Observer subject for booking lifecycle events.
 *  - Hotel is the facade orchestrating search/book/cancel.
 */
public class p16 {

    // ---------- Shared value types ----------

    enum RoomType { SINGLE, DOUBLE, SUITE, DELUXE }

    enum AddOn { BREAKFAST, LATE_CHECKOUT, AIRPORT_PICKUP, EXTRA_BED }

    enum ReservationStatus { CONFIRMED, CANCELLED }

    /** Half-open [checkIn, checkOut) interval. Overlap math lives here, not on Room. */
    static final class DateRange {
        final LocalDate checkIn;
        final LocalDate checkOut;

        DateRange(LocalDate checkIn, LocalDate checkOut) {
            if (!checkIn.isBefore(checkOut)) throw new IllegalArgumentException("checkIn must be before checkOut");
            this.checkIn = checkIn;
            this.checkOut = checkOut;
        }

        boolean overlaps(DateRange other) {
            return this.checkIn.isBefore(other.checkOut) && other.checkIn.isBefore(this.checkOut);
        }

        long nights() {
            return checkOut.toEpochDay() - checkIn.toEpochDay();
        }

        @Override public String toString() { return checkIn + " -> " + checkOut; }
    }

    static final class Guest {
        final String id, name, email;
        Guest(String id, String name, String email) { this.id = id; this.name = name; this.email = email; }
    }

    // ---------- Room / RoomInventory ----------

    /** Per-room calendar of booked intervals; the sole overlap-checking authority. */
    static final class RoomInventory {
        private final List<DateRange> bookedIntervals = new ArrayList<>();
        private final Lock lock = new ReentrantLock();

        boolean isAvailable(DateRange range) {
            lock.lock();
            try {
                return isAvailableInternal(range);
            } finally {
                lock.unlock();
            }
        }

        private boolean isAvailableInternal(DateRange range) {
            for (DateRange existing : bookedIntervals) {
                if (existing.overlaps(range)) return false;
            }
            return true;
        }

        /** Atomic check-then-book under the same lock, preventing double booking. */
        boolean book(DateRange range) {
            lock.lock();
            try {
                if (!isAvailableInternal(range)) return false;
                bookedIntervals.add(range);
                return true;
            } finally {
                lock.unlock();
            }
        }

        void release(DateRange range) {
            lock.lock();
            try {
                bookedIntervals.removeIf(r -> r.checkIn.equals(range.checkIn) && r.checkOut.equals(range.checkOut));
            } finally {
                lock.unlock();
            }
        }
    }

    static final class Room {
        final String roomNumber;
        final RoomType roomType;
        final int floor;
        private final RoomInventory inventory = new RoomInventory(); // composition: Room owns its inventory 1:1

        Room(String roomNumber, RoomType roomType, int floor) {
            this.roomNumber = roomNumber;
            this.roomType = roomType;
            this.floor = floor;
        }

        RoomInventory getInventory() { return inventory; }
    }

    // ---------- Reservation request + builder ----------

    static final class ReservationRequest {
        final DateRange range;
        final RoomType roomType;
        final int guestCount;
        final Set<AddOn> addOns;
        final String specialRequests;

        ReservationRequest(DateRange range, RoomType roomType, int guestCount, Set<AddOn> addOns, String specialRequests) {
            this.range = range;
            this.roomType = roomType;
            this.guestCount = guestCount;
            this.addOns = addOns;
            this.specialRequests = specialRequests;
        }
    }

    /** Fluent, step-by-step construction; validates once at build() instead of at every setter. */
    static final class ReservationRequestBuilder {
        private DateRange range;
        private RoomType roomType;
        private int guestCount = 1;
        private final Set<AddOn> addOns = new LinkedHashSet<>();
        private String specialRequests = "";

        ReservationRequestBuilder withDates(LocalDate checkIn, LocalDate checkOut) {
            this.range = new DateRange(checkIn, checkOut);
            return this;
        }

        ReservationRequestBuilder withRoomType(RoomType type) {
            this.roomType = type;
            return this;
        }

        ReservationRequestBuilder withGuestCount(int count) {
            this.guestCount = count;
            return this;
        }

        ReservationRequestBuilder withAddOn(AddOn addOn) {
            this.addOns.add(addOn);
            return this;
        }

        ReservationRequestBuilder withSpecialRequests(String text) {
            this.specialRequests = text;
            return this;
        }

        ReservationRequest build() {
            if (range == null) throw new IllegalStateException("dates are required");
            if (roomType == null) throw new IllegalStateException("roomType is required");
            return new ReservationRequest(range, roomType, guestCount, addOns, specialRequests);
        }
    }

    // ---------- Pricing strategy ----------

    interface PricingStrategy {
        double calculatePrice(Room room, DateRange range);
    }

    /** Flat per-night rate by room type. */
    static final class StandardPricingStrategy implements PricingStrategy {
        private final Map<RoomType, Double> baseRates = Map.of(
                RoomType.SINGLE, 80.0, RoomType.DOUBLE, 120.0, RoomType.SUITE, 220.0, RoomType.DELUXE, 350.0);

        @Override
        public double calculatePrice(Room room, DateRange range) {
            return baseRates.get(room.roomType) * range.nights();
        }
    }

    /** Adds a weekend surcharge on top of the base rate -- a *new* rule, no change to Reservation/Hotel. */
    static final class WeekendSurchargePricingStrategy implements PricingStrategy {
        private final PricingStrategy delegate;
        private final double weekendMultiplier;

        WeekendSurchargePricingStrategy(PricingStrategy delegate, double weekendMultiplier) {
            this.delegate = delegate;
            this.weekendMultiplier = weekendMultiplier;
        }

        @Override
        public double calculatePrice(Room room, DateRange range) {
            double perNightBase = delegate.calculatePrice(room, new DateRange(range.checkIn, range.checkIn.plusDays(1)));
            double total = 0;
            LocalDate day = range.checkIn;
            while (day.isBefore(range.checkOut)) {
                boolean isWeekend = day.getDayOfWeek() == DayOfWeek.SATURDAY || day.getDayOfWeek() == DayOfWeek.SUNDAY;
                total += isWeekend ? perNightBase * weekendMultiplier : perNightBase;
                day = day.plusDays(1);
            }
            return total;
        }
    }

    // ---------- Reservation ----------

    static final class Reservation {
        final String id;
        final Guest guest;
        final Room room;
        final DateRange range;
        ReservationStatus status;
        final double totalPrice;
        private final BookingNotifier notifier;

        Reservation(String id, Guest guest, Room room, DateRange range, double totalPrice, BookingNotifier notifier) {
            this.id = id;
            this.guest = guest;
            this.room = room;
            this.range = range;
            this.totalPrice = totalPrice;
            this.notifier = notifier;
            this.status = ReservationStatus.CONFIRMED;
        }

        void cancel() {
            if (status == ReservationStatus.CANCELLED) return;
            status = ReservationStatus.CANCELLED;
            room.getInventory().release(range);
            notifier.notifyCancelled(this);
        }
    }

    // ---------- Booking notifier (Observer) ----------

    interface BookingObserver {
        void onConfirmed(Reservation reservation);
        void onCancelled(Reservation reservation);
    }

    static final class BookingNotifier {
        private final List<BookingObserver> observers = new ArrayList<>();

        void subscribe(BookingObserver observer) { observers.add(observer); }

        void notifyConfirmed(Reservation reservation) {
            for (BookingObserver o : observers) o.onConfirmed(reservation);
        }

        void notifyCancelled(Reservation reservation) {
            for (BookingObserver o : observers) o.onCancelled(reservation);
        }
    }

    static final class ConsoleGuestNotifier implements BookingObserver {
        @Override
        public void onConfirmed(Reservation r) {
            System.out.printf("[notify] Reservation %s CONFIRMED for %s, room %s, %.2f total%n",
                    r.id, r.guest.name, r.room.roomNumber, r.totalPrice);
        }

        @Override
        public void onCancelled(Reservation r) {
            System.out.printf("[notify] Reservation %s CANCELLED for %s%n", r.id, r.guest.name);
        }
    }

    // ---------- Hotel (facade) ----------

    static final class Hotel {
        private final List<Room> rooms;
        private final PricingStrategy pricingStrategy;
        private final BookingNotifier notifier;
        private final Map<String, Reservation> reservations = new HashMap<>();
        private int reservationSeq = 0;

        Hotel(List<Room> rooms, PricingStrategy pricingStrategy, BookingNotifier notifier) {
            this.rooms = rooms;
            this.pricingStrategy = pricingStrategy;
            this.notifier = notifier;
        }

        List<Room> searchAvailability(LocalDate checkIn, LocalDate checkOut, RoomType type) {
            DateRange range = new DateRange(checkIn, checkOut);
            List<Room> result = new ArrayList<>();
            for (Room room : rooms) {
                if (type != null && room.roomType != type) continue;
                if (room.getInventory().isAvailable(range)) result.add(room);
            }
            return result;
        }

        Reservation bookRoom(Guest guest, ReservationRequest request) {
            for (Room candidate : rooms) {
                if (candidate.roomType != request.roomType) continue;
                // Atomic check-then-book lives inside RoomInventory.book(); try the next
                // candidate room of the same type if this one lost the race or was already booked.
                if (candidate.getInventory().book(request.range)) {
                    double price = pricingStrategy.calculatePrice(candidate, request.range);
                    String id = "RES-" + (++reservationSeq);
                    Reservation reservation = new Reservation(id, guest, candidate, request.range, price, notifier);
                    reservations.put(id, reservation);
                    notifier.notifyConfirmed(reservation);
                    return reservation;
                }
            }
            throw new IllegalStateException("No available room of type " + request.roomType + " for " + request.range);
        }

        void cancelReservation(String reservationId) {
            Reservation reservation = reservations.get(reservationId);
            if (reservation == null) throw new NoSuchElementException("Unknown reservation " + reservationId);
            reservation.cancel();
        }
    }

    // ---------- Demo ----------

    public static void main(String[] args) throws InterruptedException {
        List<Room> rooms = new ArrayList<>();
        rooms.add(new Room("101", RoomType.DOUBLE, 1));
        rooms.add(new Room("102", RoomType.DOUBLE, 1));
        rooms.add(new Room("201", RoomType.SUITE, 2));

        PricingStrategy pricing = new WeekendSurchargePricingStrategy(new StandardPricingStrategy(), 1.25);
        BookingNotifier notifier = new BookingNotifier();
        notifier.subscribe(new ConsoleGuestNotifier());

        Hotel hotel = new Hotel(rooms, pricing, notifier);

        LocalDate in = LocalDate.of(2026, 10, 2);
        LocalDate out = LocalDate.of(2026, 10, 5);

        System.out.println("Available DOUBLE rooms: " + hotel.searchAvailability(in, out, RoomType.DOUBLE).size());

        ReservationRequest request = new ReservationRequestBuilder()
                .withDates(in, out)
                .withRoomType(RoomType.DOUBLE)
                .withGuestCount(2)
                .withAddOn(AddOn.BREAKFAST)
                .build();

        Guest alice = new Guest("g1", "Alice", "alice@example.com");
        Reservation resA = hotel.bookRoom(alice, request);
        System.out.println("Booked room: " + resA.room.roomNumber + " price=" + resA.totalPrice);

        // Concurrency demo: two guests race for the SAME remaining double room + dates.
        Guest bob = new Guest("g2", "Bob", "bob@example.com");
        ReservationRequest sameRequest = new ReservationRequestBuilder().withDates(in, out).withRoomType(RoomType.DOUBLE).build();
        final Reservation[] results = new Reservation[2];
        Runnable attempt = () -> {
            try {
                results[0] = hotel.bookRoom(bob, sameRequest);
            } catch (Exception ignored) { }
        };
        Thread t1 = new Thread(attempt);
        Thread t2 = new Thread(attempt);
        t1.start(); t2.start();
        t1.join(); t2.join();
        System.out.println("Second concurrent booking landed on room: " + (results[0] != null ? results[0].room.roomNumber : "none"));

        System.out.println("Available DOUBLE rooms after bookings: " + hotel.searchAvailability(in, out, RoomType.DOUBLE).size());

        hotel.cancelReservation(resA.id);
        System.out.println("Available DOUBLE rooms after cancel: " + hotel.searchAvailability(in, out, RoomType.DOUBLE).size());
    }
}

