// Problem 16: Hotel Reservation System
//
// Room (static attrs) vs RoomInventory (per-room booked-interval calendar) split.
// ReservationRequestBuilder assembles a booking intent step by step.
// PricingStrategy is injected (Strategy) so pricing rules change independently.
// BookingNotifier is a thin Observer subject for booking lifecycle events.
// Hotel is the facade orchestrating search/book/cancel.
#include <iostream>
#include <vector>
#include <memory>
#include <string>
#include <map>
#include <set>
#include <mutex>
#include <thread>
#include <stdexcept>
#include <sstream>

// ---------- Simple date type (days since epoch-ish counter is enough for this demo) ----------
struct SimpleDate {
    int y, m, d;
    long toOrdinal() const { return y * 372L + m * 31L + d; } // stable-enough ordering for a demo
    int dayOfWeekMod7() const { return static_cast<int>(toOrdinal() % 7); } // pretend weekend detector
    bool isBefore(const SimpleDate& o) const { return toOrdinal() < o.toOrdinal(); }
    SimpleDate plusDays(int n) const {
        // Minimal, non-calendar-accurate increment sufficient for the pricing loop below.
        SimpleDate copy = *this;
        for (int i = 0; i < n; ++i) {
            copy.d++;
            if (copy.d > 28) { copy.d = 1; copy.m++; if (copy.m > 12) { copy.m = 1; copy.y++; } }
        }
        return copy;
    }
    std::string toString() const {
        std::ostringstream os; os << y << "-" << m << "-" << d; return os.str();
    }
};

enum class RoomType { SINGLE, DOUBLE, SUITE, DELUXE };
enum class AddOn { BREAKFAST, LATE_CHECKOUT, AIRPORT_PICKUP, EXTRA_BED };
enum class ReservationStatus { CONFIRMED, CANCELLED };

// Half-open [checkIn, checkOut) interval; overlap math lives here, not on Room.
struct DateRange {
    SimpleDate checkIn, checkOut;
    DateRange(SimpleDate in, SimpleDate out) : checkIn(in), checkOut(out) {
        if (!in.isBefore(out)) throw std::invalid_argument("checkIn must be before checkOut");
    }
    bool overlaps(const DateRange& other) const {
        return checkIn.isBefore(other.checkOut) && other.checkIn.isBefore(checkOut);
    }
    long nights() const { return checkOut.toOrdinal() - checkIn.toOrdinal(); }
};

struct Guest {
    std::string id, name, email;
};

// Per-room calendar of booked intervals; the sole overlap-checking authority.
class RoomInventory {
public:
    bool isAvailable(const DateRange& range) {
        std::lock_guard<std::mutex> lock(mutex_);
        return isAvailableInternal(range);
    }

    // Atomic check-then-book under the same lock, preventing double booking.
    bool book(const DateRange& range) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (!isAvailableInternal(range)) return false;
        bookedIntervals_.push_back(range);
        return true;
    }

    void release(const DateRange& range) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto it = bookedIntervals_.begin(); it != bookedIntervals_.end(); ++it) {
            if (it->checkIn.toOrdinal() == range.checkIn.toOrdinal() &&
                it->checkOut.toOrdinal() == range.checkOut.toOrdinal()) {
                bookedIntervals_.erase(it);
                return;
            }
        }
    }

private:
    bool isAvailableInternal(const DateRange& range) const {
        for (const auto& existing : bookedIntervals_) if (existing.overlaps(range)) return false;
        return true;
    }
    std::vector<DateRange> bookedIntervals_;
    std::mutex mutex_;
};

class Room {
public:
    std::string roomNumber;
    RoomType roomType;
    int floor;
    Room(std::string number, RoomType type, int fl) : roomNumber(std::move(number)), roomType(type), floor(fl) {}
    RoomInventory& getInventory() { return inventory_; } // composition: Room owns its inventory 1:1
private:
    RoomInventory inventory_;
};

struct ReservationRequest {
    DateRange range;
    RoomType roomType;
    int guestCount;
    std::set<AddOn> addOns;
    std::string specialRequests;
};

// Fluent, step-by-step construction; validates once at build() instead of at every setter.
class ReservationRequestBuilder {
public:
    ReservationRequestBuilder& withDates(SimpleDate in, SimpleDate out) {
        range_ = std::make_unique<DateRange>(in, out);
        return *this;
    }
    ReservationRequestBuilder& withRoomType(RoomType type) { roomType_ = type; hasType_ = true; return *this; }
    ReservationRequestBuilder& withGuestCount(int count) { guestCount_ = count; return *this; }
    ReservationRequestBuilder& withAddOn(AddOn addOn) { addOns_.insert(addOn); return *this; }
    ReservationRequestBuilder& withSpecialRequests(std::string text) { specialRequests_ = std::move(text); return *this; }

    ReservationRequest build() {
        if (!range_) throw std::logic_error("dates are required");
        if (!hasType_) throw std::logic_error("roomType is required");
        return ReservationRequest{*range_, roomType_, guestCount_, addOns_, specialRequests_};
    }

private:
    std::unique_ptr<DateRange> range_;
    RoomType roomType_ = RoomType::SINGLE;
    bool hasType_ = false;
    int guestCount_ = 1;
    std::set<AddOn> addOns_;
    std::string specialRequests_;
};

class PricingStrategy {
public:
    virtual ~PricingStrategy() = default;
    virtual double calculatePrice(const Room& room, const DateRange& range) = 0;
};

// Flat per-night rate by room type.
class StandardPricingStrategy : public PricingStrategy {
public:
    double calculatePrice(const Room& room, const DateRange& range) override {
        return baseRate(room.roomType) * static_cast<double>(range.nights());
    }
    static double baseRate(RoomType type) {
        switch (type) {
            case RoomType::SINGLE: return 80.0;
            case RoomType::DOUBLE: return 120.0;
            case RoomType::SUITE: return 220.0;
            case RoomType::DELUXE: return 350.0;
        }
        return 0.0;
    }
};

// Adds a weekend surcharge on top of a delegate rate -- a *new* rule, no change to Reservation/Hotel.
class WeekendSurchargePricingStrategy : public PricingStrategy {
public:
    WeekendSurchargePricingStrategy(std::shared_ptr<PricingStrategy> delegate, double multiplier)
        : delegate_(std::move(delegate)), multiplier_(multiplier) {}

    double calculatePrice(const Room& room, const DateRange& range) override {
        DateRange oneNight(range.checkIn, range.checkIn.plusDays(1));
        double perNight = delegate_->calculatePrice(room, oneNight);
        double total = 0;
        SimpleDate day = range.checkIn;
        while (day.isBefore(range.checkOut)) {
            bool isWeekend = day.dayOfWeekMod7() == 5 || day.dayOfWeekMod7() == 6;
            total += isWeekend ? perNight * multiplier_ : perNight;
            day = day.plusDays(1);
        }
        return total;
    }

private:
    std::shared_ptr<PricingStrategy> delegate_;
    double multiplier_;
};

class Reservation;

class BookingObserver {
public:
    virtual ~BookingObserver() = default;
    virtual void onConfirmed(const Reservation& reservation) = 0;
    virtual void onCancelled(const Reservation& reservation) = 0;
};

class BookingNotifier {
public:
    void subscribe(std::shared_ptr<BookingObserver> observer) { observers_.push_back(std::move(observer)); }
    void notifyConfirmed(const Reservation& reservation) { for (auto& o : observers_) o->onConfirmed(reservation); }
    void notifyCancelled(const Reservation& reservation) { for (auto& o : observers_) o->onCancelled(reservation); }
private:
    std::vector<std::shared_ptr<BookingObserver>> observers_;
};

class Reservation {
public:
    std::string id;
    Guest guest;
    Room* room;
    DateRange range;
    ReservationStatus status;
    double totalPrice;

    Reservation(std::string id_, Guest guest_, Room* room_, DateRange range_, double price, BookingNotifier* notifier)
        : id(std::move(id_)), guest(std::move(guest_)), room(room_), range(range_),
          status(ReservationStatus::CONFIRMED), totalPrice(price), notifier_(notifier) {}

    void cancel() {
        if (status == ReservationStatus::CANCELLED) return;
        status = ReservationStatus::CANCELLED;
        room->getInventory().release(range);
        notifier_->notifyCancelled(*this);
    }

private:
    BookingNotifier* notifier_;
};

class ConsoleGuestNotifier : public BookingObserver {
public:
    void onConfirmed(const Reservation& r) override {
        std::cout << "[notify] Reservation " << r.id << " CONFIRMED for " << r.guest.name
                   << ", room " << r.room->roomNumber << ", " << r.totalPrice << " total\n";
    }
    void onCancelled(const Reservation& r) override {
        std::cout << "[notify] Reservation " << r.id << " CANCELLED for " << r.guest.name << "\n";
    }
};

// Facade: top-level orchestration.
class Hotel {
public:
    Hotel(std::vector<std::unique_ptr<Room>> rooms, std::shared_ptr<PricingStrategy> pricing, std::shared_ptr<BookingNotifier> notifier)
        : rooms_(std::move(rooms)), pricingStrategy_(std::move(pricing)), notifier_(std::move(notifier)) {}

    std::vector<Room*> searchAvailability(SimpleDate in, SimpleDate out, RoomType type) {
        DateRange range(in, out);
        std::vector<Room*> result;
        for (auto& room : rooms_) {
            if (room->roomType != type) continue;
            if (room->getInventory().isAvailable(range)) result.push_back(room.get());
        }
        return result;
    }

    std::shared_ptr<Reservation> bookRoom(const Guest& guest, const ReservationRequest& request) {
        for (auto& candidate : rooms_) {
            if (candidate->roomType != request.roomType) continue;
            // Atomic check-then-book lives inside RoomInventory::book(); try the next
            // candidate room of the same type if this one lost the race or was already booked.
            if (candidate->getInventory().book(request.range)) {
                double price = pricingStrategy_->calculatePrice(*candidate, request.range);
                std::string id = "RES-" + std::to_string(++reservationSeq_);
                auto reservation = std::make_shared<Reservation>(id, guest, candidate.get(), request.range, price, notifier_.get());
                std::lock_guard<std::mutex> lock(reservationsMutex_);
                reservations_[id] = reservation;
                notifier_->notifyConfirmed(*reservation);
                return reservation;
            }
        }
        throw std::runtime_error("No available room of requested type for given dates");
    }

    void cancelReservation(const std::string& reservationId) {
        std::lock_guard<std::mutex> lock(reservationsMutex_);
        auto it = reservations_.find(reservationId);
        if (it == reservations_.end()) throw std::runtime_error("Unknown reservation " + reservationId);
        it->second->cancel();
    }

private:
    std::vector<std::unique_ptr<Room>> rooms_;
    std::shared_ptr<PricingStrategy> pricingStrategy_;
    std::shared_ptr<BookingNotifier> notifier_;
    std::map<std::string, std::shared_ptr<Reservation>> reservations_;
    std::mutex reservationsMutex_;
    int reservationSeq_ = 0;
};

int main() {
    std::vector<std::unique_ptr<Room>> rooms;
    rooms.push_back(std::make_unique<Room>("101", RoomType::DOUBLE, 1));
    rooms.push_back(std::make_unique<Room>("102", RoomType::DOUBLE, 1));
    rooms.push_back(std::make_unique<Room>("201", RoomType::SUITE, 2));

    auto standard = std::make_shared<StandardPricingStrategy>();
    auto pricing = std::make_shared<WeekendSurchargePricingStrategy>(standard, 1.25);
    auto notifier = std::make_shared<BookingNotifier>();
    notifier->subscribe(std::make_shared<ConsoleGuestNotifier>());

    Hotel hotel(std::move(rooms), pricing, notifier);

    SimpleDate in{2026, 10, 2};
    SimpleDate out{2026, 10, 5};

    std::cout << "Available DOUBLE rooms: " << hotel.searchAvailability(in, out, RoomType::DOUBLE).size() << "\n";

    ReservationRequest request = ReservationRequestBuilder()
        .withDates(in, out)
        .withRoomType(RoomType::DOUBLE)
        .withGuestCount(2)
        .withAddOn(AddOn::BREAKFAST)
        .build();

    Guest alice{"g1", "Alice", "alice@example.com"};
    auto resA = hotel.bookRoom(alice, request);
    std::cout << "Booked room: " << resA->room->roomNumber << " price=" << resA->totalPrice << "\n";

    // Concurrency demo: two guests race for the SAME remaining double room + dates.
    Guest bob{"g2", "Bob", "bob@example.com"};
    ReservationRequest sameRequest = ReservationRequestBuilder().withDates(in, out).withRoomType(RoomType::DOUBLE).build();
    std::shared_ptr<Reservation> winner;
    std::mutex winnerMutex;
    auto attempt = [&]() {
        try {
            auto r = hotel.bookRoom(bob, sameRequest);
            std::lock_guard<std::mutex> lock(winnerMutex);
            winner = r;
        } catch (...) { }
    };
    std::thread t1(attempt), t2(attempt);
    t1.join(); t2.join();
    std::cout << "Second concurrent booking landed on room: " << (winner ? winner->room->roomNumber : "none") << "\n";

    std::cout << "Available DOUBLE rooms after bookings: " << hotel.searchAvailability(in, out, RoomType::DOUBLE).size() << "\n";

    hotel.cancelReservation(resA->id);
    std::cout << "Available DOUBLE rooms after cancel: " << hotel.searchAvailability(in, out, RoomType::DOUBLE).size() << "\n";

    return 0;
}

