// BookingNotifier is a thin Observer subject for booking lifecycle events.
// Hotel is the facade orchestrating search/book/cancel.
//
// Node's event loop is single-threaded, so true data races are impossible here;
// the AsyncMutex below still models the same "lock the inventory during the
// check-then-book" shape as the Java/C++ versions for structural fidelity, and
// matters for real correctness once any I/O (e.g. a DB call) is added inside it.

const RoomType = Object.freeze({ SINGLE: 'SINGLE', DOUBLE: 'DOUBLE', SUITE: 'SUITE', DELUXE: 'DELUXE' });
const AddOn = Object.freeze({ BREAKFAST: 'BREAKFAST', LATE_CHECKOUT: 'LATE_CHECKOUT', AIRPORT_PICKUP: 'AIRPORT_PICKUP', EXTRA_BED: 'EXTRA_BED' });
const ReservationStatus = Object.freeze({ CONFIRMED: 'CONFIRMED', CANCELLED: 'CANCELLED' });

/** A minimal FIFO mutual-exclusion primitive: a queue of waiters, one holder at a time. */
class AsyncMutex {
  constructor() { this._locked = false; this._waiters = []; }
  _acquire() {
    return new Promise((resolve) => {
      if (!this._locked) { this._locked = true; resolve(); }
      else this._waiters.push(resolve);
    });
  }
  _release() {
    if (this._waiters.length > 0) this._waiters.shift()();
    else this._locked = false;
  }
  async runExclusive(fn) {
    await this._acquire();
    try {
      return await fn();
    } finally {
      this._release();
    }
  }
}

/** Half-open [checkIn, checkOut) interval; overlap math lives here, not on Room. */
class DateRange {
  constructor(checkIn, checkOut) {
    if (!(checkIn < checkOut)) throw new Error('checkIn must be before checkOut');
    this.checkIn = checkIn;
    this.checkOut = checkOut;
  }
  overlaps(other) { return this.checkIn < other.checkOut && other.checkIn < this.checkOut; }
  nights() { return Math.round((this.checkOut - this.checkIn) / 86400000); }
}

class Guest {
  constructor(id, name, email) { this.id = id; this.name = name; this.email = email; }
}

/** Per-room calendar of booked intervals; the sole overlap-checking authority. */
class RoomInventory {
  constructor() {
    this._bookedIntervals = [];
    this._mutex = new AsyncMutex();
  }
  _isAvailableInternal(range) {
    return this._bookedIntervals.every((existing) => !existing.overlaps(range));
  }
  async isAvailable(range) {
    return this._mutex.runExclusive(() => this._isAvailableInternal(range));
  }
  // Atomic check-then-book under the same lock, preventing double booking.
  async book(range) {
    return this._mutex.runExclusive(() => {
      if (!this._isAvailableInternal(range)) return false;
      this._bookedIntervals.push(range);
      return true;
    });
  }
  async release(range) {
    return this._mutex.runExclusive(() => {
      this._bookedIntervals = this._bookedIntervals.filter(
        (r) => !(r.checkIn.getTime() === range.checkIn.getTime() && r.checkOut.getTime() === range.checkOut.getTime())
      );
    });
  }
}

class Room {
  constructor(roomNumber, roomType, floor) {
    this.roomNumber = roomNumber;
    this.roomType = roomType;
    this.floor = floor;
    this.inventory = new RoomInventory(); // composition: Room owns its inventory 1:1
