}

class ReservationRequest {
  constructor(range, roomType, guestCount, addOns, specialRequests) {
    this.range = range;
    this.roomType = roomType;
    this.guestCount = guestCount;
    this.addOns = addOns;
    this.specialRequests = specialRequests;
  }
}

/** Fluent, step-by-step construction; validates once at build() instead of at every setter. */
class ReservationRequestBuilder {
  constructor() {
    this._range = null;
    this._roomType = null;
    this._guestCount = 1;
    this._addOns = new Set();
    this._specialRequests = '';
  }
  withDates(checkIn, checkOut) { this._range = new DateRange(checkIn, checkOut); return this; }
  withRoomType(type) { this._roomType = type; return this; }
  withGuestCount(count) { this._guestCount = count; return this; }
  withAddOn(addOn) { this._addOns.add(addOn); return this; }
  withSpecialRequests(text) { this._specialRequests = text; return this; }
  build() {
    if (!this._range) throw new Error('dates are required');
    if (!this._roomType) throw new Error('roomType is required');
    return new ReservationRequest(this._range, this._roomType, this._guestCount, this._addOns, this._specialRequests);
  }
}

/** @interface PricingStrategy: calculatePrice(room, range) -> number */

/** Flat per-night rate by room type. */
class StandardPricingStrategy {
  constructor() {
    this._baseRates = { [RoomType.SINGLE]: 80, [RoomType.DOUBLE]: 120, [RoomType.SUITE]: 220, [RoomType.DELUXE]: 350 };
  }
  calculatePrice(room, range) { return this._baseRates[room.roomType] * range.nights(); }
}

/** Adds a weekend surcharge on top of a delegate rate -- a *new* rule, no change to Reservation/Hotel. */
class WeekendSurchargePricingStrategy {
  constructor(delegate, weekendMultiplier) { this._delegate = delegate; this._weekendMultiplier = weekendMultiplier; }
  calculatePrice(room, range) {
    const oneNight = new DateRange(range.checkIn, new Date(range.checkIn.getTime() + 86400000));
    const perNight = this._delegate.calculatePrice(room, oneNight);
    let total = 0;
    for (let d = new Date(range.checkIn); d < range.checkOut; d = new Date(d.getTime() + 86400000)) {
      const isWeekend = d.getDay() === 0 || d.getDay() === 6;
      total += isWeekend ? perNight * this._weekendMultiplier : perNight;
    }
    return total;
  }
}

/** @interface BookingObserver: onConfirmed(reservation), onCancelled(reservation) */

class BookingNotifier {
  constructor() { this._observers = []; }
  subscribe(observer) { this._observers.push(observer); }
  notifyConfirmed(reservation) { this._observers.forEach((o) => o.onConfirmed(reservation)); }
  notifyCancelled(reservation) { this._observers.forEach((o) => o.onCancelled(reservation)); }
}

class Reservation {
  constructor(id, guest, room, range, totalPrice, notifier) {
    this.id = id;
    this.guest = guest;
    this.room = room;
    this.range = range;
    this.totalPrice = totalPrice;
    this.status = ReservationStatus.CONFIRMED;
    this._notifier = notifier;
  }
  async cancel() {
    if (this.status === ReservationStatus.CANCELLED) return;
    this.status = ReservationStatus.CANCELLED;
    await this.room.inventory.release(this.range);
    this._notifier.notifyCancelled(this);
  }
}

class ConsoleGuestNotifier {
  onConfirmed(r) {
    console.log(`[notify] Reservation ${r.id} CONFIRMED for ${r.guest.name}, room ${r.room.roomNumber}, ${r.totalPrice.toFixed(2)} total`);
  }
  onCancelled(r) {
    console.log(`[notify] Reservation ${r.id} CANCELLED for ${r.guest.name}`);
  }
}

/** Facade: top-level orchestration. */
class Hotel {
  constructor(rooms, pricingStrategy, notifier) {
    this._rooms = rooms;
    this._pricingStrategy = pricingStrategy;
    this._notifier = notifier;
    this._reservations = new Map();
    this._reservationSeq = 0;
  }

  async searchAvailability(checkIn, checkOut, roomType) {
    const range = new DateRange(checkIn, checkOut);
    const result = [];
    for (const room of this._rooms) {
      if (roomType && room.roomType !== roomType) continue;
      if (await room.inventory.isAvailable(range)) result.push(room);
    }
    return result;
  }

  async bookRoom(guest, request) {
    for (const candidate of this._rooms) {
      if (candidate.roomType !== request.roomType) continue;
      // Atomic check-then-book lives inside RoomInventory.book(); try the next
      // candidate room of the same type if this one lost the race or was already booked.
      if (await candidate.inventory.book(request.range)) {
        const price = this._pricingStrategy.calculatePrice(candidate, request.range);
        const id = `RES-${++this._reservationSeq}`;
        const reservation = new Reservation(id, guest, candidate, request.range, price, this._notifier);
        this._reservations.set(id, reservation);
        this._notifier.notifyConfirmed(reservation);
        return reservation;
      }
    }
    throw new Error(`No available room of type ${request.roomType} for given dates`);
  }

  async cancelReservation(reservationId) {
    const reservation = this._reservations.get(reservationId);
    if (!reservation) throw new Error(`Unknown reservation ${reservationId}`);
    await reservation.cancel();
  }
}

async function main() {
  const rooms = [
    new Room('101', RoomType.DOUBLE, 1),
    new Room('102', RoomType.DOUBLE, 1),
    new Room('201', RoomType.SUITE, 2),
  ];

  const pricing = new WeekendSurchargePricingStrategy(new StandardPricingStrategy(), 1.25);
  const notifier = new BookingNotifier();
  notifier.subscribe(new ConsoleGuestNotifier());

  const hotel = new Hotel(rooms, pricing, notifier);

  const checkIn = new Date(2026, 9, 2);
  const checkOut = new Date(2026, 9, 5);

  console.log('Available DOUBLE rooms:', (await hotel.searchAvailability(checkIn, checkOut, RoomType.DOUBLE)).length);

  const request = new ReservationRequestBuilder()
    .withDates(checkIn, checkOut)
    .withRoomType(RoomType.DOUBLE)
    .withGuestCount(2)
    .withAddOn(AddOn.BREAKFAST)
    .build();

  const alice = new Guest('g1', 'Alice', 'alice@example.com');
  const resA = await hotel.bookRoom(alice, request);
  console.log(`Booked room: ${resA.room.roomNumber} price=${resA.totalPrice}`);

  // "Concurrency" demo: two overlapping async attempts racing on the last DOUBLE room.
  const bob = new Guest('g2', 'Bob', 'bob@example.com');
  const sameRequest = new ReservationRequestBuilder().withDates(checkIn, checkOut).withRoomType(RoomType.DOUBLE).build();
  const [r1, r2] = await Promise.allSettled([hotel.bookRoom(bob, sameRequest), hotel.bookRoom(bob, sameRequest)]);
  const winner = r1.status === 'fulfilled' ? r1.value : (r2.status === 'fulfilled' ? r2.value : null);
  console.log('Second concurrent booking landed on room:', winner ? winner.room.roomNumber : 'none');

  console.log('Available DOUBLE rooms after bookings:', (await hotel.searchAvailability(checkIn, checkOut, RoomType.DOUBLE)).length);

  await hotel.cancelReservation(resA.id);
  console.log('Available DOUBLE rooms after cancel:', (await hotel.searchAvailability(checkIn, checkOut, RoomType.DOUBLE)).length);
}

if (require.main === module) {
  main().catch((e) => { console.error(e); process.exit(1); });
}

module.exports = {
  RoomType, AddOn, ReservationStatus, DateRange, Guest, RoomInventory, Room,
  ReservationRequest, ReservationRequestBuilder, StandardPricingStrategy,
  WeekendSurchargePricingStrategy, BookingNotifier, Reservation, ConsoleGuestNotifier, Hotel,
};

