/** A minimal FIFO mutual-exclusion primitive: a queue of waiters, one holder at a time. */
class AsyncMutex {
  private locked = false;
  private waiters: Array<() => void> = [];

  private acquire(): Promise<void> {
    return new Promise<void>((resolve) => {
      if (!this.locked) { this.locked = true; resolve(); }
      else this.waiters.push(resolve);
    });
  }

  private release(): void {
    const next = this.waiters.shift();
    if (next) next();
    else this.locked = false;
  }

  async runExclusive<T>(fn: () => T | Promise<T>): Promise<T> {
    await this.acquire();
    try {
      return await fn();
    } finally {
      this.release();
    }
  }
}

/** Half-open [checkIn, checkOut) interval; overlap math lives here, not on Room. */
class DateRange {
  constructor(public readonly checkIn: Date, public readonly checkOut: Date) {
