// Problem 17: Movie Ticket Booking System (Concurrency Showcase)
//
// Seat (static attrs) vs ShowSeat (per-show status) split.
// ShowSeatState hierarchy encodes AVAILABLE -> LOCKED -> BOOKED legality, and LOCKED/BOOKED -> AVAILABLE on expire/release.
// SeatLock is a TTL-bound soft hold; only a successful payment converts it into a Booking confirmation.
// PricingStrategy is injected (Strategy); WaitlistNotifier is an Observer subject.
// BookingService is the facade; holdSeats() locks seats in canonical (sorted) order to avoid deadlock
// against another user holding an overlapping seat set.
#include <iostream>
#include <vector>
#include <memory>
#include <string>
#include <map>
#include <mutex>
#include <thread>
#include <chrono>
#include <stdexcept>
#include <algorithm>

enum class SeatCategory { SILVER, GOLD, PREMIUM };
enum class ShowSeatStatus { AVAILABLE, LOCKED, BOOKED };
enum class BookingStatus { HOLD, CONFIRMED, CANCELLED };

struct User { std::string id, name; };
struct PaymentResult { bool success; };

struct Seat {
    std::string seatNumber;
    SeatCategory category;
};

struct Movie { std::string id, title; int durationMinutes; };

struct Screen {
    std::string id, name;
    std::vector<Seat> seats;
};

class ShowSeat;

class Show {
public:
    std::string id;
    Movie movie;
    Screen screen;
    int startHour; // simplified: just the hour-of-day, enough to decide "peak"

    Show(std::string id_, Movie movie_, Screen screen_, int startHour_)
        : id(std::move(id_)), movie(std::move(movie_)), screen(std::move(screen_)), startHour(startHour_) {
        buildShowSeats();
    }

    ShowSeat& getShowSeat(const std::string& seatNumber);

private:
    void buildShowSeats();
    std::map<std::string, std::unique_ptr<ShowSeat>> showSeats_;
};

// ---------- ShowSeatState (State pattern) ----------
class ShowSeat;

class ShowSeatState {
public:
    virtual ~ShowSeatState() = default;
    virtual void onLock(ShowSeat& seat) = 0;
    virtual void onConfirm(ShowSeat& seat) = 0;
    virtual void onExpire(ShowSeat& seat) = 0;
};

class AvailableState : public ShowSeatState {
public:
    static ShowSeatState& instance();
    void onLock(ShowSeat& seat) override;
    void onConfirm(ShowSeat&) override { throw std::logic_error("Cannot confirm a seat that was never locked"); }
    void onExpire(ShowSeat&) override { /* already available; no-op */ }
};

class LockedState : public ShowSeatState {
public:
    static ShowSeatState& instance();
    void onLock(ShowSeat&) override { throw std::logic_error("Seat already locked"); }
    void onConfirm(ShowSeat& seat) override;
    void onExpire(ShowSeat& seat) override;
};

class BookedState : public ShowSeatState {
public:
    static ShowSeatState& instance();
    void onLock(ShowSeat&) override { throw std::logic_error("Seat already booked"); }
    void onConfirm(ShowSeat&) override { throw std::logic_error("Seat already booked"); }
    void onExpire(ShowSeat& seat) override; // booking cancellation frees the seat
};

class ShowSeat {
public:
    Seat seat;
    Show* show;

    ShowSeat(Seat seat_, Show* show_) : seat(std::move(seat_)), show(show_), status_(ShowSeatStatus::AVAILABLE), state_(&AvailableState::instance()) {}

    void setState(ShowSeatStatus status, ShowSeatState& state) { status_ = status; state_ = &state; }
    ShowSeatStatus getStatus() const { return status_; }

    void lock() { std::lock_guard<std::mutex> g(mutex_); state_->onLock(*this); }
    void confirm() { std::lock_guard<std::mutex> g(mutex_); state_->onConfirm(*this); }
    void release() { std::lock_guard<std::mutex> g(mutex_); state_->onExpire(*this); }

private:
    ShowSeatStatus status_;
    ShowSeatState* state_;
    std::mutex mutex_;
};

ShowSeatState& AvailableState::instance() { static AvailableState s; return s; }
ShowSeatState& LockedState::instance() { static LockedState s; return s; }
ShowSeatState& BookedState::instance() { static BookedState s; return s; }
void AvailableState::onLock(ShowSeat& seat) { seat.setState(ShowSeatStatus::LOCKED, LockedState::instance()); }
void LockedState::onConfirm(ShowSeat& seat) { seat.setState(ShowSeatStatus::BOOKED, BookedState::instance()); }
void LockedState::onExpire(ShowSeat& seat) { seat.setState(ShowSeatStatus::AVAILABLE, AvailableState::instance()); }
void BookedState::onExpire(ShowSeat& seat) { seat.setState(ShowSeatStatus::AVAILABLE, AvailableState::instance()); }

void Show::buildShowSeats() {
    for (auto& s : screen.seats) showSeats_[s.seatNumber] = std::make_unique<ShowSeat>(s, this);
}

ShowSeat& Show::getShowSeat(const std::string& seatNumber) {
    auto it = showSeats_.find(seatNumber);
    if (it == showSeats_.end()) throw std::out_of_range("No such seat: " + seatNumber);
    return *it->second;
}

// ---------- SeatLock ----------
struct SeatLock {
    std::string id;
    User user;
    std::vector<ShowSeat*> seats;
    std::chrono::steady_clock::time_point expiresAt;

    bool isExpired() const { return std::chrono::steady_clock::now() > expiresAt; }
};

// ---------- PricingStrategy ----------
class PricingStrategy {
public:
    virtual ~PricingStrategy() = default;
    virtual double calculatePrice(const Seat& seat, const Show& show) = 0;
};

class CategoryTimeBasedPricingStrategy : public PricingStrategy {
public:
    double calculatePrice(const Seat& seat, const Show& show) override {
        double base = baseRate(seat.category);
        bool peak = show.startHour >= 18 && show.startHour < 22;
        return peak ? base * 1.3 : base;
    }
private:
    static double baseRate(SeatCategory c) {
        switch (c) {
            case SeatCategory::SILVER: return 100.0;
            case SeatCategory::GOLD: return 180.0;
            case SeatCategory::PREMIUM: return 280.0;
        }
        return 0.0;
    }
};

// ---------- Booking ----------
class Booking {
public:
    std::string id;
    User user;
    Show* show;
    std::vector<ShowSeat*> seats;
    BookingStatus status;
    double totalPrice;

    Booking(std::string id_, User user_, Show* show_, std::vector<ShowSeat*> seats_, PricingStrategy& pricingStrategy)
        : id(std::move(id_)), user(std::move(user_)), show(show_), seats(std::move(seats_)), status(BookingStatus::HOLD) {
        totalPrice = 0;
        for (auto* s : seats) totalPrice += pricingStrategy.calculatePrice(s->seat, *show);
    }

    void confirm() {
        for (auto* s : seats) s->confirm();
        status = BookingStatus::CONFIRMED;
    }

    void cancel() {
        for (auto* s : seats) s->release();
        status = BookingStatus::CANCELLED;
    }
};

// ---------- WaitlistNotifier (Observer) ----------
class WaitlistObserver {
public:
    virtual ~WaitlistObserver() = default;
    virtual void onSeatAvailable(ShowSeat& seat) = 0;
};

class WaitlistNotifier {
public:
    void subscribe(std::shared_ptr<WaitlistObserver> observer) { observers_.push_back(std::move(observer)); }
    void notifyWaiting(const std::vector<ShowSeat*>& freedSeats) {
        for (auto* seat : freedSeats) for (auto& o : observers_) o->onSeatAvailable(*seat);
    }
private:
    std::vector<std::shared_ptr<WaitlistObserver>> observers_;
};

class ConsoleWaitlistNotifier : public WaitlistObserver {
public:
    void onSeatAvailable(ShowSeat& seat) override {
        std::cout << "[waitlist] Seat " << seat.seat.seatNumber << " on show " << seat.show->id << " is available again\n";
    }
};

// ---------- BookingService (facade) ----------
class BookingService {
public:
    BookingService(std::shared_ptr<PricingStrategy> pricingStrategy, std::shared_ptr<WaitlistNotifier> waitlistNotifier)
        : pricingStrategy_(std::move(pricingStrategy)), waitlistNotifier_(std::move(waitlistNotifier)) {}

    // Locks seats in canonical (sorted) order so two overlapping multi-seat holds never deadlock.
    std::shared_ptr<SeatLock> holdSeats(const User& user, Show& show, std::vector<std::string> seatNumbers) {
        std::lock_guard<std::mutex> g(serviceMutex_); // coarse-grained: whole hold operation is atomic
        std::sort(seatNumbers.begin(), seatNumbers.end());
        std::vector<ShowSeat*> locked;
        try {
            for (auto& id : seatNumbers) {
                ShowSeat& seat = show.getShowSeat(id);
                seat.lock(); // throws if not AVAILABLE
                locked.push_back(&seat);
            }
        } catch (const std::exception& rejected) {
            for (auto* seat : locked) seat->release(); // rollback partial holds
            throw std::runtime_error(std::string("Could not hold all requested seats: ") + rejected.what());
        }
        auto lock = std::make_shared<SeatLock>();
        lock->id = "LOCK-" + std::to_string(++lockSeq_);
        lock->user = user;
        lock->seats = locked;
        lock->expiresAt = std::chrono::steady_clock::now() + std::chrono::milliseconds(2000);
        activeLocks_[lock->id] = lock;
        return lock;
    }

    std::shared_ptr<Booking> confirmBooking(const std::string& lockId, PaymentResult paymentResult, const std::string& idempotencyKey) {
        std::lock_guard<std::mutex> g(serviceMutex_);
        auto idemIt = idempotencyRecords_.find(idempotencyKey);
        if (idemIt != idempotencyRecords_.end()) return idemIt->second; // idempotent retry

        auto lockIt = activeLocks_.find(lockId);
        if (lockIt == activeLocks_.end()) throw std::runtime_error("Unknown or already-consumed lock " + lockId);
        auto seatLock = lockIt->second;
        if (seatLock->isExpired()) {
            activeLocks_.erase(lockId);
            for (auto* seat : seatLock->seats) seat->release();
            throw std::runtime_error("Seat hold expired for lock " + lockId);
        }

        auto booking = std::make_shared<Booking>("BKG-" + std::to_string(++bookingSeq_), seatLock->user,
                                                   seatLock->seats[0]->show, seatLock->seats, *pricingStrategy_);
        if (paymentResult.success) {
            booking->confirm();
        } else {
            booking->cancel();
            waitlistNotifier_->notifyWaiting(seatLock->seats);
        }
        activeLocks_.erase(lockId);
        bookings_[booking->id] = booking;
        idempotencyRecords_[idempotencyKey] = booking;
        return booking;
    }

    void cancelBooking(const std::string& bookingId) {
        std::lock_guard<std::mutex> g(serviceMutex_);
        auto it = bookings_.find(bookingId);
        if (it == bookings_.end()) throw std::runtime_error("Unknown booking " + bookingId);
        it->second->cancel();
        waitlistNotifier_->notifyWaiting(it->second->seats);
    }

private:
    std::shared_ptr<PricingStrategy> pricingStrategy_;
    std::shared_ptr<WaitlistNotifier> waitlistNotifier_;
    std::map<std::string, std::shared_ptr<SeatLock>> activeLocks_;
    std::map<std::string, std::shared_ptr<Booking>> bookings_;
    std::map<std::string, std::shared_ptr<Booking>> idempotencyRecords_;
    std::mutex serviceMutex_;
    int lockSeq_ = 0, bookingSeq_ = 0;
};

static const char* statusName(ShowSeatStatus s) {
    switch (s) {
        case ShowSeatStatus::AVAILABLE: return "AVAILABLE";
        case ShowSeatStatus::LOCKED: return "LOCKED";
        case ShowSeatStatus::BOOKED: return "BOOKED";
    }
    return "?";
}
static const char* statusName(BookingStatus s) {
    switch (s) {
        case BookingStatus::HOLD: return "HOLD";
        case BookingStatus::CONFIRMED: return "CONFIRMED";
        case BookingStatus::CANCELLED: return "CANCELLED";
    }
    return "?";
}

int main() {
    std::vector<Seat> seats = {
        {"A1", SeatCategory::PREMIUM}, {"A2", SeatCategory::PREMIUM},
        {"B1", SeatCategory::GOLD}, {"B2", SeatCategory::GOLD},
        {"C1", SeatCategory::SILVER}, {"C2", SeatCategory::SILVER},
    };
    Screen screen{"SCR-1", "Screen 1", seats};
    Movie movie{"MOV-1", "Interstellar", 169};
    Show show("SHOW-1", movie, screen, 19); // peak hour

    auto waitlistNotifier = std::make_shared<WaitlistNotifier>();
    waitlistNotifier->subscribe(std::make_shared<ConsoleWaitlistNotifier>());
    auto pricing = std::make_shared<CategoryTimeBasedPricingStrategy>();
    BookingService bookingService(pricing, waitlistNotifier);

    User alice{"u1", "Alice"};
    User bob{"u2", "Bob"};

    // Concurrency demo: Alice holds {A1,A2}, Bob holds {A2,B1} -- overlapping sets, sorted-order locking prevents deadlock.
    std::shared_ptr<SeatLock> aliceLock, bobLockAttempt;
    std::thread t1([&]() {
        try { aliceLock = bookingService.holdSeats(alice, show, {"A1", "A2"}); } catch (...) { }
    });
    std::thread t2([&]() {
        try { bobLockAttempt = bookingService.holdSeats(bob, show, {"A2", "B1"}); }
        catch (const std::exception& e) { std::cout << "Bob's hold rejected (expected, contends on A2): " << e.what() << "\n"; }
    });
    t1.join(); t2.join();

    std::cout << "Alice locked seats: " << aliceLock->seats.size() << "\n";

    auto booking = bookingService.confirmBooking(aliceLock->id, {true}, "idem-key-1");
    std::cout << "Booking " << booking->id << " CONFIRMED, total=" << booking->totalPrice << "\n";

    auto retry = bookingService.confirmBooking(aliceLock->id, {true}, "idem-key-1");
    std::cout << "Idempotent retry returns same booking: " << (retry == booking ? "true" : "false") << "\n";

    auto bobLock = bookingService.holdSeats(bob, show, {"B1", "B2"});
    auto failedPayment = bookingService.confirmBooking(bobLock->id, {false}, "idem-key-2");
    std::cout << "Bob's failed-payment booking status: " << statusName(failedPayment->status) << " (seats released, waitlist notified)\n";

    bookingService.cancelBooking(booking->id);
    std::cout << "A1 status after cancellation: " << statusName(show.getShowSeat("A1").getStatus()) << "\n";
