'use strict';
// Problem 17: Movie Ticket Booking System (Concurrency Showcase)
//
// Seat (static attrs) vs ShowSeat (per-show status) split.
// ShowSeatState hierarchy encodes AVAILABLE -> LOCKED -> BOOKED legality, and LOCKED/BOOKED -> AVAILABLE on expire/release.
// SeatLock is a TTL-bound soft hold; only a successful payment converts it into a Booking confirmation.
// PricingStrategy is injected (Strategy); WaitlistNotifier is an Observer subject.
// BookingService is the facade; holdSeats() locks seats in canonical (sorted) order so two overlapping
// multi-seat holds never deadlock -- modeled here with an AsyncMutex since Node has no real threads.

const SeatCategory = Object.freeze({ SILVER: 'SILVER', GOLD: 'GOLD', PREMIUM: 'PREMIUM' });
const ShowSeatStatus = Object.freeze({ AVAILABLE: 'AVAILABLE', LOCKED: 'LOCKED', BOOKED: 'BOOKED' });
const BookingStatus = Object.freeze({ HOLD: 'HOLD', CONFIRMED: 'CONFIRMED', CANCELLED: 'CANCELLED' });

/** A minimal FIFO mutual-exclusion primitive: a queue of waiters, one holder at a time. */
class AsyncMutex {
  constructor() { this._locked = false; this._waiters = []; }
  _acquire() {
    return new Promise((resolve) => {
      if (!this._locked) { this._locked = true; resolve(); }
      else this._waiters.push(resolve);
    });
  }
  _release() {
    if (this._waiters.length > 0) this._waiters.shift()();
    else this._locked = false;
  }
  async runExclusive(fn) {
    await this._acquire();
    try { return await fn(); } finally { this._release(); }
  }
}

class User {
  constructor(id, name) { this.id = id; this.name = name; }
}

class Seat {
  constructor(seatNumber, category) { this.seatNumber = seatNumber; this.category = category; }
}

class Movie {
  constructor(id, title, durationMinutes) { this.id = id; this.title = title; this.durationMinutes = durationMinutes; }
}

class Screen {
  constructor(id, name, seats) { this.id = id; this.name = name; this.seats = seats; }
}

// ---------- ShowSeatState (State pattern) ----------

class AvailableState {
  onLock(seat) { seat._setState(ShowSeatStatus.LOCKED, LOCKED_STATE); }
  onConfirm() { throw new Error('Cannot confirm a seat that was never locked'); }
  onExpire() { /* already available; no-op */ }
}
class LockedState {
  onLock() { throw new Error('Seat already locked'); }
  onConfirm(seat) { seat._setState(ShowSeatStatus.BOOKED, BOOKED_STATE); }
  onExpire(seat) { seat._setState(ShowSeatStatus.AVAILABLE, AVAILABLE_STATE); }
}
class BookedState {
  onLock() { throw new Error('Seat already booked'); }
  onConfirm() { throw new Error('Seat already booked'); }
  onExpire(seat) { seat._setState(ShowSeatStatus.AVAILABLE, AVAILABLE_STATE); } // booking cancellation frees the seat
}
const AVAILABLE_STATE = new AvailableState();
const LOCKED_STATE = new LockedState();
const BOOKED_STATE = new BookedState();

class ShowSeat {
  constructor(seat, show) {
    this.seat = seat;
    this.show = show;
    this.status = ShowSeatStatus.AVAILABLE;
    this._state = AVAILABLE_STATE;
    this._mutex = new AsyncMutex();
  }
  _setState(status, state) { this.status = status; this._state = state; }
  async lock() { return this._mutex.runExclusive(() => this._state.onLock(this)); }
  async confirm() { return this._mutex.runExclusive(() => this._state.onConfirm(this)); }
  async release() { return this._mutex.runExclusive(() => this._state.onExpire(this)); }
}

class Show {
  constructor(id, movie, screen, startHour) {
    this.id = id;
    this.movie = movie;
    this.screen = screen;
    this.startHour = startHour; // simplified: just the hour-of-day, enough to decide "peak"
    this._showSeats = new Map();
    for (const seat of screen.seats) this._showSeats.set(seat.seatNumber, new ShowSeat(seat, this));
  }
  getShowSeat(seatNumber) {
    const seat = this._showSeats.get(seatNumber);
    if (!seat) throw new Error(`No such seat: ${seatNumber}`);
    return seat;
  }
}

/** @interface PricingStrategy: calculatePrice(seat, show) -> number */
class CategoryTimeBasedPricingStrategy {
  calculatePrice(seat, show) {
    const baseRates = { [SeatCategory.SILVER]: 100, [SeatCategory.GOLD]: 180, [SeatCategory.PREMIUM]: 280 };
    const peak = show.startHour >= 18 && show.startHour < 22;
    return peak ? baseRates[seat.category] * 1.3 : baseRates[seat.category];
  }
}

class SeatLock {
  constructor(id, user, seats, ttlMillis) {
    this.id = id;
    this.user = user;
    this.seats = seats;
    this.expiresAt = Date.now() + ttlMillis;
  }
  isExpired() { return Date.now() > this.expiresAt; }
}

class Booking {
  constructor(id, user, show, seats, pricingStrategy) {
    this.id = id;
    this.user = user;
    this.show = show;
    this.seats = seats;
    this.status = BookingStatus.HOLD;
    this.totalPrice = seats.reduce((sum, s) => sum + pricingStrategy.calculatePrice(s.seat, show), 0);
  }
  async confirm() {
    for (const s of this.seats) await s.confirm();
    this.status = BookingStatus.CONFIRMED;
  }
  async cancel() {
    for (const s of this.seats) await s.release();
    this.status = BookingStatus.CANCELLED;
  }
}

/** @interface WaitlistObserver: onSeatAvailable(showSeat) */
class WaitlistNotifier {
  constructor() { this._observers = []; }
  subscribe(observer) { this._observers.push(observer); }
  notifyWaiting(freedSeats) {
    for (const seat of freedSeats) for (const o of this._observers) o.onSeatAvailable(seat);
  }
}
class ConsoleWaitlistNotifier {
  onSeatAvailable(seat) {
    console.log(`[waitlist] Seat ${seat.seat.seatNumber} on show ${seat.show.id} is available again`);
  }
}

/** Facade: top-level orchestration. holdSeats() locks in canonical (sorted) order. */
class BookingService {
  static HOLD_TTL_MILLIS = 2000;

  constructor(pricingStrategy, waitlistNotifier) {
    this._pricingStrategy = pricingStrategy;
    this._waitlistNotifier = waitlistNotifier;
    this._activeLocks = new Map();
    this._bookings = new Map();
    this._idempotencyRecords = new Map();
    this._serviceMutex = new AsyncMutex(); // coarse-grained: whole hold/confirm operation is atomic
    this._lockSeq = 0;
    this._bookingSeq = 0;
  }

  async holdSeats(user, show, seatNumbers) {
    return this._serviceMutex.runExclusive(async () => {
      const ordered = [...seatNumbers].sort();
      const locked = [];
      try {
        for (const id of ordered) {
          const seat = show.getShowSeat(id);
          await seat.lock(); // throws if not AVAILABLE
          locked.push(seat);
        }
      } catch (rejected) {
        for (const seat of locked) await seat.release(); // rollback partial holds
        throw new Error(`Could not hold all requested seats: ${rejected.message}`);
      }
      const lockId = `LOCK-${++this._lockSeq}`;
      const seatLock = new SeatLock(lockId, user, locked, BookingService.HOLD_TTL_MILLIS);
      this._activeLocks.set(lockId, seatLock);
      return seatLock;
    });
  }

  async confirmBooking(lockId, paymentResult, idempotencyKey) {
    return this._serviceMutex.runExclusive(async () => {
      if (this._idempotencyRecords.has(idempotencyKey)) return this._idempotencyRecords.get(idempotencyKey);

      const seatLock = this._activeLocks.get(lockId);
      if (!seatLock) throw new Error(`Unknown or already-consumed lock ${lockId}`);
      if (seatLock.isExpired()) {
        this._activeLocks.delete(lockId);
        for (const seat of seatLock.seats) await seat.release();
        throw new Error(`Seat hold expired for lock ${lockId}`);
      }

      const booking = new Booking(`BKG-${++this._bookingSeq}`, seatLock.user, seatLock.seats[0].show, seatLock.seats, this._pricingStrategy);
      if (paymentResult.success) {
        await booking.confirm();
      } else {
        await booking.cancel();
        this._waitlistNotifier.notifyWaiting(seatLock.seats);
      }
      this._activeLocks.delete(lockId);
      this._bookings.set(booking.id, booking);
      this._idempotencyRecords.set(idempotencyKey, booking);
      return booking;
    });
  }

  async cancelBooking(bookingId) {
    return this._serviceMutex.runExclusive(async () => {
      const booking = this._bookings.get(bookingId);
      if (!booking) throw new Error(`Unknown booking ${bookingId}`);
      await booking.cancel();
      this._waitlistNotifier.notifyWaiting(booking.seats);
    });
  }
}

async function main() {
  const seats = [
    new Seat('A1', SeatCategory.PREMIUM), new Seat('A2', SeatCategory.PREMIUM),
    new Seat('B1', SeatCategory.GOLD), new Seat('B2', SeatCategory.GOLD),
    new Seat('C1', SeatCategory.SILVER), new Seat('C2', SeatCategory.SILVER),
  ];
