 *
 * Key design decisions faithfully reproduced from the class diagram:
 *  - MenuItem (live, editable catalog) vs OrderLineItem (frozen price/name snapshot at checkout).
 *  - OrderState hierarchy: PLACED -> CONFIRMED -> PREPARING -> OUT_FOR_DELIVERY -> DELIVERED, each
 *    state only accepting its own legal next event; illegal/duplicated events are rejected by the state.
 *  - DeliveryAssignmentStrategy is injected (Strategy); DeliveryDispatcher does the atomic select-then-claim.
 *  - OrderStatusNotifier is a thin Observer subject fanning out every legal transition.
 *  - OrderService is the facade: placeOrder() / updateStatus().
 */
public class p18 {

    enum OrderStatus { PLACED, CONFIRMED, PREPARING, OUT_FOR_DELIVERY, DELIVERED, CANCELLED }
    enum StatusEvent { CONFIRM, PREPARE, PICKUP, DELIVER, CANCEL }
    enum PartnerStatus { AVAILABLE, BUSY }

    static final class Customer {
        final String id, name, address;
        Customer(String id, String name, String address) { this.id = id; this.name = name; this.address = address; }
    }

    static final class Restaurant {
        final String id, name, location;
        final List<MenuItem> menu = new ArrayList<>();
        Restaurant(String id, String name, String location) { this.id = id; this.name = name; this.location = location; }
        void addMenuItem(MenuItem item) { menu.add(item); }
    }

    // ---------- MenuItem (live catalog) vs OrderLineItem (frozen snapshot) ----------

    static final class MenuItem {
        final String id;
        String name;
        double price;
        boolean available;
        MenuItem(String id, String name, double price) { this.id = id; this.name = name; this.price = price; this.available = true; }
    }

    static final class OrderLineItem {
        final String nameAtOrderTime;
        final double priceAtOrderTime;
        final int quantity;
        OrderLineItem(MenuItem item, int quantity) {
            // Freeze name/price at checkout -- a later price change must never rewrite a past receipt.
            this.nameAtOrderTime = item.name;
            this.priceAtOrderTime = item.price;
            this.quantity = quantity;
        }
        double subtotal() { return priceAtOrderTime * quantity; }
    }

    static final class CartItem {
        final MenuItem menuItem;
        final int quantity;
        CartItem(MenuItem menuItem, int quantity) { this.menuItem = menuItem; this.quantity = quantity; }
    }

    static final class Cart {
        final List<CartItem> items = new ArrayList<>();
        void addItem(MenuItem item, int quantity) { items.add(new CartItem(item, quantity)); }
    }

    // ---------- OrderState (State pattern) ----------

    interface OrderState {
        OrderState onConfirm();
        OrderState onPrepared();
        OrderState onPickedUp();
        OrderState onDelivered();
        OrderStatus status();
    }

    static final class PlacedState implements OrderState {
        static final PlacedState INSTANCE = new PlacedState();
        public OrderState onConfirm() { return ConfirmedState.INSTANCE; }
        public OrderState onPrepared() { throw new IllegalStateException("Cannot prepare before confirmation"); }
        public OrderState onPickedUp() { throw new IllegalStateException("Cannot pick up before confirmation"); }
        public OrderState onDelivered() { throw new IllegalStateException("Cannot deliver before confirmation"); }
        public OrderStatus status() { return OrderStatus.PLACED; }
    }

    static final class ConfirmedState implements OrderState {
        static final ConfirmedState INSTANCE = new ConfirmedState();
        public OrderState onConfirm() { throw new IllegalStateException("Already confirmed"); }
        public OrderState onPrepared() { return PreparingState.INSTANCE; }
        public OrderState onPickedUp() { throw new IllegalStateException("Cannot pick up before preparation"); }
        public OrderState onDelivered() { throw new IllegalStateException("Cannot deliver before preparation"); }
        public OrderStatus status() { return OrderStatus.CONFIRMED; }
    }

    static final class PreparingState implements OrderState {
        static final PreparingState INSTANCE = new PreparingState();
        public OrderState onConfirm() { throw new IllegalStateException("Already confirmed"); }
        public OrderState onPrepared() { throw new IllegalStateException("Already preparing"); }
        public OrderState onPickedUp() { return OutForDeliveryState.INSTANCE; }
        public OrderState onDelivered() { throw new IllegalStateException("Cannot deliver before pickup"); }
        public OrderStatus status() { return OrderStatus.PREPARING; }
    }

    static final class OutForDeliveryState implements OrderState {
        static final OutForDeliveryState INSTANCE = new OutForDeliveryState();
        public OrderState onConfirm() { throw new IllegalStateException("Already confirmed"); }
        public OrderState onPrepared() { throw new IllegalStateException("Already prepared"); }
        public OrderState onPickedUp() { throw new IllegalStateException("Already picked up"); }
        public OrderState onDelivered() { return DeliveredState.INSTANCE; }
        public OrderStatus status() { return OrderStatus.OUT_FOR_DELIVERY; }
    }

    static final class DeliveredState implements OrderState {
        static final DeliveredState INSTANCE = new DeliveredState();
        public OrderState onConfirm() { throw new IllegalStateException("Order already delivered -- terminal state"); }
        public OrderState onPrepared() { throw new IllegalStateException("Order already delivered -- terminal state"); }
        public OrderState onPickedUp() { throw new IllegalStateException("Order already delivered -- terminal state"); }
        public OrderState onDelivered() { throw new IllegalStateException("Order already delivered -- terminal state"); }
        public OrderStatus status() { return OrderStatus.DELIVERED; }
    }

    // ---------- Order ----------

    static final class Order {
        final String id;
        final Customer customer;
        final Restaurant restaurant;
        final List<OrderLineItem> lineItems;
        private OrderState state = PlacedState.INSTANCE;
        private final OrderStatusNotifier notifier;
        DeliveryPartner assignedPartner;

        Order(String id, Customer customer, Restaurant restaurant, List<OrderLineItem> lineItems, OrderStatusNotifier notifier) {
            this.id = id; this.customer = customer; this.restaurant = restaurant; this.lineItems = lineItems; this.notifier = notifier;
        }

        OrderStatus getStatus() { return state.status(); }

        double totalPrice() {
            double total = 0;
            for (OrderLineItem li : lineItems) total += li.subtotal();
            return total;
        }

        /** Delegates transition legality to the current state; illegal events are rejected by the state itself. */
        void transitionTo(StatusEvent event) {
            OrderState next;
            switch (event) {
                case CONFIRM: next = state.onConfirm(); break;
                case PREPARE: next = state.onPrepared(); break;
                case PICKUP: next = state.onPickedUp(); break;
                case DELIVER: next = state.onDelivered(); break;
                default: throw new IllegalArgumentException("Unsupported event via transitionTo: " + event);
            }
            state = next;
            notifier.notifyStatusChanged(this);
        }

        void cancel() {
            if (state == DeliveredState.INSTANCE) throw new IllegalStateException("Cannot cancel a delivered order");
            state = new OrderState() {
                public OrderState onConfirm() { throw new IllegalStateException("Order is cancelled"); }
                public OrderState onPrepared() { throw new IllegalStateException("Order is cancelled"); }
                public OrderState onPickedUp() { throw new IllegalStateException("Order is cancelled"); }
                public OrderState onDelivered() { throw new IllegalStateException("Order is cancelled"); }
                public OrderStatus status() { return OrderStatus.CANCELLED; }
            };
            notifier.notifyStatusChanged(this);
        }
    }

    // ---------- Delivery assignment ----------

    static final class DeliveryPartner {
        final String id, name;
        PartnerStatus status = PartnerStatus.AVAILABLE;
        String location;
        DeliveryPartner(String id, String name, String location) { this.id = id; this.name = name; this.location = location; }

        /** Claims this partner for a delivery. Caller (DeliveryDispatcher) must already hold the pool lock. */
        void claim() {
            if (status != PartnerStatus.AVAILABLE) throw new IllegalStateException("Partner " + id + " is not available");
            status = PartnerStatus.BUSY;
        }

        void release() { status = PartnerStatus.AVAILABLE; }
    }

    interface DeliveryAssignmentStrategy {
        DeliveryPartner selectPartner(Order order, List<DeliveryPartner> candidates);
    }

    /** Picks the first available partner whose recorded location matches the restaurant's -- a simple "nearest" proxy. */
    static final class NearestAvailablePartnerStrategy implements DeliveryAssignmentStrategy {
        public DeliveryPartner selectPartner(Order order, List<DeliveryPartner> candidates) {
            for (DeliveryPartner p : candidates) {
                if (p.location.equals(order.restaurant.location)) return p;
            }
            if (candidates.isEmpty()) throw new NoSuchElementException("No available delivery partners");
            return candidates.get(0); // fall back to any available partner
        }
    }

    /** Atomically selects and claims a partner -- selection and claim happen under the same lock. */
    static final class DeliveryDispatcher {
        private final List<DeliveryPartner> partnerPool;
        private final DeliveryAssignmentStrategy strategy;

        DeliveryDispatcher(List<DeliveryPartner> partnerPool, DeliveryAssignmentStrategy strategy) {
            this.partnerPool = partnerPool;
            this.strategy = strategy;
        }

        synchronized DeliveryPartner assign(Order order) {
            List<DeliveryPartner> candidates = new ArrayList<>();
            for (DeliveryPartner p : partnerPool) if (p.status == PartnerStatus.AVAILABLE) candidates.add(p);
            DeliveryPartner chosen = strategy.selectPartner(order, candidates);
            chosen.claim(); // claim happens inside the same lock as selection -- no double-assignment race
            order.assignedPartner = chosen;
            return chosen;
        }
    }

    // ---------- OrderStatusNotifier (Observer) ----------

    interface OrderStatusObserver {
        void onStatusChanged(Order order);
    }

    static final class OrderStatusNotifier {
        private final List<OrderStatusObserver> observers = new ArrayList<>();
        void subscribe(OrderStatusObserver observer) { observers.add(observer); }
        void notifyStatusChanged(Order order) { for (OrderStatusObserver o : observers) o.onStatusChanged(order); }
    }

    static final class ConsoleStatusObserver implements OrderStatusObserver {
        public void onStatusChanged(Order order) {
            System.out.printf("[push] Order %s status -> %s%n", order.id, order.getStatus());
        }
    }

    // ---------- OrderService (facade) ----------

    static final class OrderService {
        private final DeliveryDispatcher dispatcher;
        private final OrderStatusNotifier notifier;
        private final Map<String, Order> orders = new HashMap<>();
        private int orderSeq = 0;

        OrderService(DeliveryDispatcher dispatcher, OrderStatusNotifier notifier) {
            this.dispatcher = dispatcher;
            this.notifier = notifier;
        }

        Order placeOrder(Customer customer, Restaurant restaurant, Cart cart) {
            List<OrderLineItem> lineItems = new ArrayList<>();
            for (CartItem ci : cart.items) lineItems.add(new OrderLineItem(ci.menuItem, ci.quantity)); // freeze price/name now
            String id = "ORD-" + (++orderSeq);
            Order order = new Order(id, customer, restaurant, lineItems, notifier);
            orders.put(id, order);
            notifier.notifyStatusChanged(order); // announce the initial PLACED state too
            return order;
        }

        void updateStatus(String orderId, StatusEvent event) {
            Order order = orders.get(orderId);
            if (order == null) throw new NoSuchElementException("Unknown order " + orderId);
            if (event == StatusEvent.CANCEL) { order.cancel(); return; }
            if (event == StatusEvent.PICKUP) dispatcher.assign(order); // assign a courier right before pickup
            order.transitionTo(event);
        }
    }

    // ---------- Demo ----------

    public static void main(String[] args) {
        Restaurant restaurant = new Restaurant("R1", "Curry House", "Downtown");
        MenuItem biryani = new MenuItem("M1", "Chicken Biryani", 12.50);
        MenuItem naan = new MenuItem("M2", "Garlic Naan", 3.00);
        restaurant.addMenuItem(biryani);
        restaurant.addMenuItem(naan);

        OrderStatusNotifier notifier = new OrderStatusNotifier();
        notifier.subscribe(new ConsoleStatusObserver());

        List<DeliveryPartner> partners = List.of(
                new DeliveryPartner("P1", "Sam", "Downtown"),
                new DeliveryPartner("P2", "Robin", "Uptown"));
        DeliveryDispatcher dispatcher = new DeliveryDispatcher(partners, new NearestAvailablePartnerStrategy());

        OrderService orderService = new OrderService(dispatcher, notifier);

        Customer customer = new Customer("C1", "Alice", "12 Elm St");
        Cart cart = new Cart();
        cart.addItem(biryani, 2);
        cart.addItem(naan, 1);

        Order order = orderService.placeOrder(customer, restaurant, cart);
        System.out.printf("Order placed: %s, total=%.2f%n", order.id, order.totalPrice());

        // Live menu price changes after checkout must NOT affect this already-placed order's receipt.
        biryani.price = 15.00;
        System.out.printf("Menu price changed to %.2f, but order total is still %.2f%n", biryani.price, order.totalPrice());

        orderService.updateStatus(order.id, StatusEvent.CONFIRM);
        orderService.updateStatus(order.id, StatusEvent.PREPARE);
        orderService.updateStatus(order.id, StatusEvent.PICKUP); // triggers atomic partner assignment
        System.out.println("Assigned partner: " + order.assignedPartner.name);
        orderService.updateStatus(order.id, StatusEvent.DELIVER);

        // Illegal transition: a duplicated/out-of-order DELIVER event on an already-delivered order must be rejected.
        try {
            orderService.updateStatus(order.id, StatusEvent.DELIVER);
        } catch (IllegalStateException e) {
            System.out.println("Rejected duplicate DELIVER event: " + e.getMessage());
        }

        // A second order competing for the same restaurant-local partner must not double-assign that partner.
        Order order2 = orderService.placeOrder(customer, restaurant, cart);
        orderService.updateStatus(order2.id, StatusEvent.CONFIRM);
        orderService.updateStatus(order2.id, StatusEvent.PREPARE);
        // P1 was claimed (BUSY) for order1 and is never auto-released on delivery in this simplified model,
        // so the dispatcher correctly falls back to the only remaining available partner, P2.
        orderService.updateStatus(order2.id, StatusEvent.PICKUP);
        System.out.println("Order2 assigned partner: " + order2.assignedPartner.name);

        // Direct PLACED -> DELIVERED must never be allowed.
        Order order3 = orderService.placeOrder(customer, restaurant, cart);
        try {
            orderService.updateStatus(order3.id, StatusEvent.DELIVER);
        } catch (IllegalStateException e) {
            System.out.println("Rejected out-of-order DELIVER on a freshly placed order: " + e.getMessage());
        }
    }
}

p18-ag.cpp:
// Problem 18: Restaurant / Food Delivery System (single-threaded -- no concurrency badge)
//
// MenuItem (live, editable catalog) vs OrderLineItem (frozen price/name snapshot at checkout).
// OrderState hierarchy: PLACED -> CONFIRMED -> PREPARING -> OUT_FOR_DELIVERY -> DELIVERED, each
// state only accepting its own legal next event; illegal/duplicated events are rejected by the state.
// DeliveryAssignmentStrategy is injected (Strategy); DeliveryDispatcher does the atomic select-then-claim.
// OrderStatusNotifier is a thin Observer subject fanning out every legal transition.
// OrderService is the facade: placeOrder() / updateStatus().
#include <iostream>
#include <vector>
#include <memory>
#include <string>
#include <map>
#include <stdexcept>

enum class OrderStatus { PLACED, CONFIRMED, PREPARING, OUT_FOR_DELIVERY, DELIVERED, CANCELLED };
enum class StatusEvent { CONFIRM, PREPARE, PICKUP, DELIVER, CANCEL };
enum class PartnerStatus { AVAILABLE, BUSY };

static const char* statusName(OrderStatus s) {
    switch (s) {
        case OrderStatus::PLACED: return "PLACED";
        case OrderStatus::CONFIRMED: return "CONFIRMED";
        case OrderStatus::PREPARING: return "PREPARING";
        case OrderStatus::OUT_FOR_DELIVERY: return "OUT_FOR_DELIVERY";
        case OrderStatus::DELIVERED: return "DELIVERED";
        case OrderStatus::CANCELLED: return "CANCELLED";
    }
    return "?";
}

struct Customer { std::string id, name, address; };

struct MenuItem {
    std::string id, name;
    double price;
    bool available;
    MenuItem(std::string id_, std::string name_, double price_) : id(std::move(id_)), name(std::move(name_)), price(price_), available(true) {}
};

struct Restaurant {
    std::string id, name, location;
    std::vector<std::shared_ptr<MenuItem>> menu;
    void addMenuItem(std::shared_ptr<MenuItem> item) { menu.push_back(std::move(item)); }
};

// Freezes name/price at checkout -- a later price change must never rewrite a past receipt.
struct OrderLineItem {
    std::string nameAtOrderTime;
    double priceAtOrderTime;
    int quantity;
    OrderLineItem(const MenuItem& item, int qty) : nameAtOrderTime(item.name), priceAtOrderTime(item.price), quantity(qty) {}
    double subtotal() const { return priceAtOrderTime * quantity; }
};

struct CartItem { std::shared_ptr<MenuItem> menuItem; int quantity; };

struct Cart {
    std::vector<CartItem> items;
    void addItem(std::shared_ptr<MenuItem> item, int quantity) { items.push_back({std::move(item), quantity}); }
};

// ---------- OrderState (State pattern) ----------
class Order;

class OrderState {
public:
    virtual ~OrderState() = default;
    virtual std::shared_ptr<OrderState> onConfirm() = 0;
    virtual std::shared_ptr<OrderState> onPrepared() = 0;
    virtual std::shared_ptr<OrderState> onPickedUp() = 0;
    virtual std::shared_ptr<OrderState> onDelivered() = 0;
    virtual OrderStatus status() const = 0;
};

class ConfirmedState;
class PreparingState;
class OutForDeliveryState;
class DeliveredState;

class PlacedState : public OrderState {
public:
    std::shared_ptr<OrderState> onConfirm() override;
    std::shared_ptr<OrderState> onPrepared() override { throw std::logic_error("Cannot prepare before confirmation"); }
    std::shared_ptr<OrderState> onPickedUp() override { throw std::logic_error("Cannot pick up before confirmation"); }
    std::shared_ptr<OrderState> onDelivered() override { throw std::logic_error("Cannot deliver before confirmation"); }
    OrderStatus status() const override { return OrderStatus::PLACED; }
};

class ConfirmedState : public OrderState {
public:
    std::shared_ptr<OrderState> onConfirm() override { throw std::logic_error("Already confirmed"); }
    std::shared_ptr<OrderState> onPrepared() override;
    std::shared_ptr<OrderState> onPickedUp() override { throw std::logic_error("Cannot pick up before preparation"); }
    std::shared_ptr<OrderState> onDelivered() override { throw std::logic_error("Cannot deliver before preparation"); }
    OrderStatus status() const override { return OrderStatus::CONFIRMED; }
};

class PreparingState : public OrderState {
public:
    std::shared_ptr<OrderState> onConfirm() override { throw std::logic_error("Already confirmed"); }
    std::shared_ptr<OrderState> onPrepared() override { throw std::logic_error("Already preparing"); }
    std::shared_ptr<OrderState> onPickedUp() override;
    std::shared_ptr<OrderState> onDelivered() override { throw std::logic_error("Cannot deliver before pickup"); }
    OrderStatus status() const override { return OrderStatus::PREPARING; }
};

class OutForDeliveryState : public OrderState {
public:
    std::shared_ptr<OrderState> onConfirm() override { throw std::logic_error("Already confirmed"); }
    std::shared_ptr<OrderState> onPrepared() override { throw std::logic_error("Already prepared"); }
    std::shared_ptr<OrderState> onPickedUp() override { throw std::logic_error("Already picked up"); }
    std::shared_ptr<OrderState> onDelivered() override;
    OrderStatus status() const override { return OrderStatus::OUT_FOR_DELIVERY; }
};

class DeliveredState : public OrderState {
public:
    std::shared_ptr<OrderState> onConfirm() override { throw std::logic_error("Order already delivered -- terminal state"); }
    std::shared_ptr<OrderState> onPrepared() override { throw std::logic_error("Order already delivered -- terminal state"); }
    std::shared_ptr<OrderState> onPickedUp() override { throw std::logic_error("Order already delivered -- terminal state"); }
    std::shared_ptr<OrderState> onDelivered() override { throw std::logic_error("Order already delivered -- terminal state"); }
    OrderStatus status() const override { return OrderStatus::DELIVERED; }
};

class CancelledState : public OrderState {
public:
    std::shared_ptr<OrderState> onConfirm() override { throw std::logic_error("Order is cancelled"); }
    std::shared_ptr<OrderState> onPrepared() override { throw std::logic_error("Order is cancelled"); }
    std::shared_ptr<OrderState> onPickedUp() override { throw std::logic_error("Order is cancelled"); }
    std::shared_ptr<OrderState> onDelivered() override { throw std::logic_error("Order is cancelled"); }
    OrderStatus status() const override { return OrderStatus::CANCELLED; }
};

std::shared_ptr<OrderState> PlacedState::onConfirm() { return std::make_shared<ConfirmedState>(); }
std::shared_ptr<OrderState> ConfirmedState::onPrepared() { return std::make_shared<PreparingState>(); }
std::shared_ptr<OrderState> PreparingState::onPickedUp() { return std::make_shared<OutForDeliveryState>(); }
std::shared_ptr<OrderState> OutForDeliveryState::onDelivered() { return std::make_shared<DeliveredState>(); }

// ---------- Delivery assignment ----------
struct DeliveryPartner {
    std::string id, name, location;
    PartnerStatus status = PartnerStatus::AVAILABLE;

    // Claims this partner for a delivery. Caller (DeliveryDispatcher) is the sole atomic gate.
    void claim() {
        if (status != PartnerStatus::AVAILABLE) throw std::runtime_error("Partner " + id + " is not available");
        status = PartnerStatus::BUSY;
    }
    void release() { status = PartnerStatus::AVAILABLE; }
};

class OrderStatusNotifier;

class Order {
public:
    std::string id;
    Customer customer;
    Restaurant restaurant;
    std::vector<OrderLineItem> lineItems;
    DeliveryPartner* assignedPartner = nullptr;

    Order(std::string id_, Customer customer_, Restaurant restaurant_, std::vector<OrderLineItem> lineItems_, OrderStatusNotifier& notifier_)
        : id(std::move(id_)), customer(std::move(customer_)), restaurant(std::move(restaurant_)),
          lineItems(std::move(lineItems_)), state_(std::make_shared<PlacedState>()), notifier_(notifier_) {}

    OrderStatus getStatus() const { return state_->status(); }

    double totalPrice() const {
        double total = 0;
        for (auto& li : lineItems) total += li.subtotal();
        return total;
    }

    void transitionTo(StatusEvent event); // defined after OrderStatusNotifier below
    void cancel();

private:
    std::shared_ptr<OrderState> state_;
    OrderStatusNotifier& notifier_;
};

class OrderStatusObserver {
public:
    virtual ~OrderStatusObserver() = default;
    virtual void onStatusChanged(Order& order) = 0;
};

class OrderStatusNotifier {
public:
    void subscribe(std::shared_ptr<OrderStatusObserver> observer) { observers_.push_back(std::move(observer)); }
    void notifyStatusChanged(Order& order) { for (auto& o : observers_) o->onStatusChanged(order); }
private:
    std::vector<std::shared_ptr<OrderStatusObserver>> observers_;
};

void Order::transitionTo(StatusEvent event) {
    std::shared_ptr<OrderState> next;
    switch (event) {
        case StatusEvent::CONFIRM: next = state_->onConfirm(); break;
        case StatusEvent::PREPARE: next = state_->onPrepared(); break;
        case StatusEvent::PICKUP: next = state_->onPickedUp(); break;
        case StatusEvent::DELIVER: next = state_->onDelivered(); break;
        default: throw std::invalid_argument("Unsupported event via transitionTo");
    }
    state_ = next;
    notifier_.notifyStatusChanged(*this);
}

void Order::cancel() {
    if (state_->status() == OrderStatus::DELIVERED) throw std::logic_error("Cannot cancel a delivered order");
    state_ = std::make_shared<CancelledState>();
    notifier_.notifyStatusChanged(*this);
}

class ConsoleStatusObserver : public OrderStatusObserver {
public:
    void onStatusChanged(Order& order) override {
        std::cout << "[push] Order " << order.id << " status -> " << statusName(order.getStatus()) << "\n";
    }
};

class DeliveryAssignmentStrategy {
public:
    virtual ~DeliveryAssignmentStrategy() = default;
    virtual DeliveryPartner* selectPartner(Order& order, std::vector<DeliveryPartner*>& candidates) = 0;
};

// Picks the first available partner whose recorded location matches the restaurant's -- a simple "nearest" proxy.
class NearestAvailablePartnerStrategy : public DeliveryAssignmentStrategy {
public:
    DeliveryPartner* selectPartner(Order& order, std::vector<DeliveryPartner*>& candidates) override {
        for (auto* p : candidates) if (p->location == order.restaurant.location) return p;
        if (candidates.empty()) throw std::runtime_error("No available delivery partners");
        return candidates.front(); // fall back to any available partner
    }
};

// Atomically selects and claims a partner -- selection and claim happen in the same call, no separate lock needed
// in this single-threaded model, but the shape mirrors the locked select-then-claim used in Problems 11/17.
class DeliveryDispatcher {
public:
    DeliveryDispatcher(std::vector<std::shared_ptr<DeliveryPartner>> pool, std::shared_ptr<DeliveryAssignmentStrategy> strategy)
        : partnerPool_(std::move(pool)), strategy_(std::move(strategy)) {}

    DeliveryPartner* assign(Order& order) {
        std::vector<DeliveryPartner*> candidates;
        for (auto& p : partnerPool_) if (p->status == PartnerStatus::AVAILABLE) candidates.push_back(p.get());
        DeliveryPartner* chosen = strategy_->selectPartner(order, candidates);
        chosen->claim();
        order.assignedPartner = chosen;
        return chosen;
    }

private:
    std::vector<std::shared_ptr<DeliveryPartner>> partnerPool_;
    std::shared_ptr<DeliveryAssignmentStrategy> strategy_;
};

// ---------- OrderService (facade) ----------
class OrderService {
public:
    OrderService(std::shared_ptr<DeliveryDispatcher> dispatcher, std::shared_ptr<OrderStatusNotifier> notifier)
        : dispatcher_(std::move(dispatcher)), notifier_(std::move(notifier)) {}

    std::shared_ptr<Order> placeOrder(Customer customer, Restaurant restaurant, const Cart& cart) {
        std::vector<OrderLineItem> lineItems;
        for (auto& ci : cart.items) lineItems.emplace_back(*ci.menuItem, ci.quantity); // freeze price/name now
        std::string id = "ORD-" + std::to_string(++orderSeq_);
        auto order = std::make_shared<Order>(id, std::move(customer), std::move(restaurant), std::move(lineItems), *notifier_);
        orders_[id] = order;
        notifier_->notifyStatusChanged(*order); // announce the initial PLACED state too
        return order;
    }

    void updateStatus(const std::string& orderId, StatusEvent event) {
        auto it = orders_.find(orderId);
        if (it == orders_.end()) throw std::runtime_error("Unknown order " + orderId);
        auto& order = *it->second;
        if (event == StatusEvent::CANCEL) { order.cancel(); return; }
        if (event == StatusEvent::PICKUP) dispatcher_->assign(order); // assign a courier right before pickup
        order.transitionTo(event);
    }

private:
    std::shared_ptr<DeliveryDispatcher> dispatcher_;
    std::shared_ptr<OrderStatusNotifier> notifier_;
    std::map<std::string, std::shared_ptr<Order>> orders_;
    int orderSeq_ = 0;
};

int main() {
    Restaurant restaurant;
    restaurant.id = "R1"; restaurant.name = "Curry House"; restaurant.location = "Downtown";
    auto biryani = std::make_shared<MenuItem>("M1", "Chicken Biryani", 12.50);
    auto naan = std::make_shared<MenuItem>("M2", "Garlic Naan", 3.00);
    restaurant.addMenuItem(biryani);
    restaurant.addMenuItem(naan);

    auto notifier = std::make_shared<OrderStatusNotifier>();
