// state only accepting its own legal next event; illegal/duplicated events are rejected by the state.
// DeliveryAssignmentStrategy is injected (Strategy); DeliveryDispatcher does the atomic select-then-claim.
// OrderStatusNotifier is a thin Observer subject fanning out every legal transition.
// OrderService is the facade: placeOrder() / updateStatus().

const OrderStatus = Object.freeze({
  PLACED: 'PLACED', CONFIRMED: 'CONFIRMED', PREPARING: 'PREPARING',
  OUT_FOR_DELIVERY: 'OUT_FOR_DELIVERY', DELIVERED: 'DELIVERED', CANCELLED: 'CANCELLED',
});
const StatusEvent = Object.freeze({ CONFIRM: 'CONFIRM', PREPARE: 'PREPARE', PICKUP: 'PICKUP', DELIVER: 'DELIVER', CANCEL: 'CANCEL' });
const PartnerStatus = Object.freeze({ AVAILABLE: 'AVAILABLE', BUSY: 'BUSY' });

class Customer {
  constructor(id, name, address) { this.id = id; this.name = name; this.address = address; }
}

class MenuItem {
  constructor(id, name, price) { this.id = id; this.name = name; this.price = price; this.available = true; }
}

class Restaurant {
  constructor(id, name, location) { this.id = id; this.name = name; this.location = location; this.menu = []; }
  addMenuItem(item) { this.menu.push(item); }
}

/** Freezes name/price at checkout -- a later price change must never rewrite a past receipt. */
class OrderLineItem {
  constructor(menuItem, quantity) {
    this.nameAtOrderTime = menuItem.name;
    this.priceAtOrderTime = menuItem.price;
    this.quantity = quantity;
  }
  subtotal() { return this.priceAtOrderTime * this.quantity; }
}

class Cart {
  constructor() { this.items = []; }
  addItem(menuItem, quantity) { this.items.push({ menuItem, quantity }); }
}

// ---------- OrderState (State pattern) ----------

class PlacedState {
  onConfirm() { return CONFIRMED_STATE; }
  onPrepared() { throw new Error('Cannot prepare before confirmation'); }
  onPickedUp() { throw new Error('Cannot pick up before confirmation'); }
  onDelivered() { throw new Error('Cannot deliver before confirmation'); }
  status() { return OrderStatus.PLACED; }
}
class ConfirmedState {
  onConfirm() { throw new Error('Already confirmed'); }
  onPrepared() { return PREPARING_STATE; }
  onPickedUp() { throw new Error('Cannot pick up before preparation'); }
  onDelivered() { throw new Error('Cannot deliver before preparation'); }
  status() { return OrderStatus.CONFIRMED; }
}
class PreparingState {
  onConfirm() { throw new Error('Already confirmed'); }
  onPrepared() { throw new Error('Already preparing'); }
  onPickedUp() { return OUT_FOR_DELIVERY_STATE; }
  onDelivered() { throw new Error('Cannot deliver before pickup'); }
  status() { return OrderStatus.PREPARING; }
}
class OutForDeliveryState {
  onConfirm() { throw new Error('Already confirmed'); }
  onPrepared() { throw new Error('Already prepared'); }
  onPickedUp() { throw new Error('Already picked up'); }
  onDelivered() { return DELIVERED_STATE; }
  status() { return OrderStatus.OUT_FOR_DELIVERY; }
}
class DeliveredState {
  onConfirm() { throw new Error('Order already delivered -- terminal state'); }
  onPrepared() { throw new Error('Order already delivered -- terminal state'); }
  onPickedUp() { throw new Error('Order already delivered -- terminal state'); }
  onDelivered() { throw new Error('Order already delivered -- terminal state'); }
  status() { return OrderStatus.DELIVERED; }
}
class CancelledState {
  onConfirm() { throw new Error('Order is cancelled'); }
  onPrepared() { throw new Error('Order is cancelled'); }
  onPickedUp() { throw new Error('Order is cancelled'); }
  onDelivered() { throw new Error('Order is cancelled'); }
  status() { return OrderStatus.CANCELLED; }
}
const PLACED_STATE = new PlacedState();
const CONFIRMED_STATE = new ConfirmedState();
const PREPARING_STATE = new PreparingState();
const OUT_FOR_DELIVERY_STATE = new OutForDeliveryState();
const DELIVERED_STATE = new DeliveredState();

class Order {
  constructor(id, customer, restaurant, lineItems, notifier) {
    this.id = id;
    this.customer = customer;
    this.restaurant = restaurant;
    this.lineItems = lineItems;
    this._state = PLACED_STATE;
    this._notifier = notifier;
    this.assignedPartner = null;
  }

  getStatus() { return this._state.status(); }
  totalPrice() { return this.lineItems.reduce((sum, li) => sum + li.subtotal(), 0); }

  /** Delegates transition legality to the current state; illegal events are rejected by the state itself. */
  transitionTo(event) {
    let next;
    switch (event) {
      case StatusEvent.CONFIRM: next = this._state.onConfirm(); break;
      case StatusEvent.PREPARE: next = this._state.onPrepared(); break;
      case StatusEvent.PICKUP: next = this._state.onPickedUp(); break;
      case StatusEvent.DELIVER: next = this._state.onDelivered(); break;
      default: throw new Error(`Unsupported event via transitionTo: ${event}`);
    }
    this._state = next;
    this._notifier.notifyStatusChanged(this);
  }

  cancel() {
    if (this._state === DELIVERED_STATE) throw new Error('Cannot cancel a delivered order');
    this._state = new CancelledState();
    this._notifier.notifyStatusChanged(this);
  }
}

// ---------- Delivery assignment ----------

class DeliveryPartner {
  constructor(id, name, location) { this.id = id; this.name = name; this.location = location; this.status = PartnerStatus.AVAILABLE; }
  claim() {
    if (this.status !== PartnerStatus.AVAILABLE) throw new Error(`Partner ${this.id} is not available`);
    this.status = PartnerStatus.BUSY;
  }
  release() { this.status = PartnerStatus.AVAILABLE; }
}

/** @interface DeliveryAssignmentStrategy: selectPartner(order, candidates) -> DeliveryPartner */
class NearestAvailablePartnerStrategy {
  selectPartner(order, candidates) {
    const match = candidates.find((p) => p.location === order.restaurant.location);
    if (match) return match;
    if (candidates.length === 0) throw new Error('No available delivery partners');
    return candidates[0]; // fall back to any available partner
  }
}

/** Atomically selects and claims a partner -- selection and claim happen in the same call. */
class DeliveryDispatcher {
  constructor(partnerPool, strategy) { this._partnerPool = partnerPool; this._strategy = strategy; }
  assign(order) {
    const candidates = this._partnerPool.filter((p) => p.status === PartnerStatus.AVAILABLE);
    const chosen = this._strategy.selectPartner(order, candidates);
    chosen.claim(); // claim happens as part of the same selection step -- no double-assignment race
    order.assignedPartner = chosen;
    return chosen;
  }
}

// ---------- OrderStatusNotifier (Observer) ----------

class OrderStatusNotifier {
  constructor() { this._observers = []; }
  subscribe(observer) { this._observers.push(observer); }
  notifyStatusChanged(order) { this._observers.forEach((o) => o.onStatusChanged(order)); }
}
class ConsoleStatusObserver {
  onStatusChanged(order) { console.log(`[push] Order ${order.id} status -> ${order.getStatus()}`); }
}

// ---------- OrderService (facade) ----------

class OrderService {
  constructor(dispatcher, notifier) {
    this._dispatcher = dispatcher;
    this._notifier = notifier;
    this._orders = new Map();
    this._orderSeq = 0;
  }

  placeOrder(customer, restaurant, cart) {
    const lineItems = cart.items.map((ci) => new OrderLineItem(ci.menuItem, ci.quantity)); // freeze price/name now
    const id = `ORD-${++this._orderSeq}`;
    const order = new Order(id, customer, restaurant, lineItems, this._notifier);
    this._orders.set(id, order);
    this._notifier.notifyStatusChanged(order); // announce the initial PLACED state too
    return order;
  }

  updateStatus(orderId, event) {
    const order = this._orders.get(orderId);
    if (!order) throw new Error(`Unknown order ${orderId}`);
    if (event === StatusEvent.CANCEL) { order.cancel(); return; }
    if (event === StatusEvent.PICKUP) this._dispatcher.assign(order); // assign a courier right before pickup
    order.transitionTo(event);
  }
}

function main() {
  const restaurant = new Restaurant('R1', 'Curry House', 'Downtown');
  const biryani = new MenuItem('M1', 'Chicken Biryani', 12.50);
  const naan = new MenuItem('M2', 'Garlic Naan', 3.00);
  restaurant.addMenuItem(biryani);
  restaurant.addMenuItem(naan);

  const notifier = new OrderStatusNotifier();
  notifier.subscribe(new ConsoleStatusObserver());

  const partners = [new DeliveryPartner('P1', 'Sam', 'Downtown'), new DeliveryPartner('P2', 'Robin', 'Uptown')];
  const dispatcher = new DeliveryDispatcher(partners, new NearestAvailablePartnerStrategy());

  const orderService = new OrderService(dispatcher, notifier);

