  biryani.price = 15.00;
  console.log(`Menu price changed to ${biryani.price.toFixed(2)}, but order total is still ${order.totalPrice().toFixed(2)}`);

  orderService.updateStatus(order.id, StatusEvent.CONFIRM);
  orderService.updateStatus(order.id, StatusEvent.PREPARE);
