// Problem 19: E-commerce Shopping Cart & Checkout
// Patterns: Decorator (add-ons on CartItem), Strategy (pricing pipeline), State (Order lifecycle), Facade (CheckoutService)
#include <iostream>
#include <vector>
#include <map>
#include <memory>
#include <string>
#include <algorithm>
#include <stdexcept>

using namespace std;

// ---------- Exceptions ----------
struct OutOfStockException : runtime_error { OutOfStockException(const string& m) : runtime_error(m) {} };
struct OrderNotFoundException : runtime_error { OrderNotFoundException(const string& m) : runtime_error(m) {} };

// ---------- Catalog ----------
struct Product {
    string id, name;
    double price;
    int stock;
    Product(string id_, string name_, double price_, int stock_)
        : id(move(id_)), name(move(name_)), price(price_), stock(stock_) {}

    void decrementStock(int qty) {
        if (stock < qty) throw OutOfStockException("Insufficient stock for " + id);
        stock -= qty;
    }
    void restoreStock(int qty) { stock += qty; }
};

// ---------- CartItem (component) + Decorator ----------
class CartItem {
public:
    Product* product;
    int quantity;
    CartItem(Product* product_, int quantity_) : product(product_), quantity(quantity_) {}
    virtual ~CartItem() = default;
    virtual double getPrice() const { return product->price * quantity; }
    Product* getProduct() const { return product; }
    int getQuantity() const { return quantity; }
};

// Abstract decorator: subclasses CartItem so it's substitutable everywhere a CartItem is
// expected, but wraps another CartItem to layer one stackable add-on charge on top.
class CartItemDecorator : public CartItem {
protected:
    shared_ptr<CartItem> wrapped;
public:
    CartItemDecorator(shared_ptr<CartItem> wrapped_)
        : CartItem(wrapped_->getProduct(), wrapped_->getQuantity()), wrapped(wrapped_) {}
};

class GiftWrapDecorator : public CartItemDecorator {
    static constexpr double FEE = 2.99;
public:
    GiftWrapDecorator(shared_ptr<CartItem> wrapped_) : CartItemDecorator(wrapped_) {}
    double getPrice() const override { return wrapped->getPrice() + FEE; }
};

class EngravingDecorator : public CartItemDecorator {
    static constexpr double FEE = 5.00;
public:
    EngravingDecorator(shared_ptr<CartItem> wrapped_) : CartItemDecorator(wrapped_) {}
    double getPrice() const override { return wrapped->getPrice() + FEE; }
};

// ---------- Cart ----------
class Cart {
    vector<shared_ptr<CartItem>> items;
public:
    void addItem(shared_ptr<CartItem> item) { items.push_back(item); }

    void removeItem(const string& productId) {
        items.erase(remove_if(items.begin(), items.end(),
            [&](const shared_ptr<CartItem>& i) { return i->getProduct()->id == productId; }), items.end());
    }

    double subtotal() const {
        double total = 0;
        for (auto& i : items) total += i->getPrice();
        return total;
    }

    int quantityFor(const string& productId) const {
        int qty = 0;
        for (auto& i : items) if (i->getProduct()->id == productId) qty += i->getQuantity();
        return qty;
    }

    const vector<shared_ptr<CartItem>>& getItems() const { return items; }
};

// ---------- Pricing pipeline (Strategy) ----------
class PricingStep {
public:
    virtual ~PricingStep() = default;
    virtual double apply(double runningTotal, const Cart& cart) = 0;
};

class TaxPricingStep : public PricingStep {
    double rate;
public:
    TaxPricingStep(double rate_) : rate(rate_) {}
    double apply(double runningTotal, const Cart& cart) override { return runningTotal + runningTotal * rate; }
};

class CouponDiscountPricingStep : public PricingStep {
    string couponCode;
    map<string, double> validCoupons;
public:
    CouponDiscountPricingStep(string couponCode_, map<string, double> validCoupons_)
        : couponCode(move(couponCode_)), validCoupons(move(validCoupons_)) {}
    double apply(double runningTotal, const Cart& cart) override {
        auto it = validCoupons.find(couponCode);
        if (it == validCoupons.end()) return runningTotal;
        return runningTotal * (1 - it->second);
    }
};

// ---------- Order lifecycle (State) ----------
enum class OrderStatus { PENDING_PAYMENT, PAID, SHIPPED, DELIVERED, CANCELLED };

class Order; // fwd decl

class OrderState {
public:
    virtual ~OrderState() = default;
    virtual unique_ptr<OrderState> onPaid(Order& order) = 0;
    virtual unique_ptr<OrderState> onShipped(Order& order) = 0;
    virtual unique_ptr<OrderState> onDelivered(Order& order) = 0;
    virtual unique_ptr<OrderState> onCancelled(Order& order) = 0;
};

class Order {
public:
    string id;
    vector<shared_ptr<CartItem>> lineItems; // frozen at checkout time
    double totalPrice;
    OrderStatus status;
    unique_ptr<OrderState> state;

    Order(string id_, vector<shared_ptr<CartItem>> lineItems_, double totalPrice_);
    Order* transitionTo(OrderStatus target);
};

class PendingPaymentState : public OrderState {
public:
    unique_ptr<OrderState> onPaid(Order& order) override;
    unique_ptr<OrderState> onShipped(Order& order) override { throw runtime_error("Cannot ship before payment"); }
    unique_ptr<OrderState> onDelivered(Order& order) override { throw runtime_error("Cannot deliver before payment"); }
    unique_ptr<OrderState> onCancelled(Order& order) override;
};
class PaidState : public OrderState {
public:
    unique_ptr<OrderState> onPaid(Order& order) override;
    unique_ptr<OrderState> onShipped(Order& order) override;
    unique_ptr<OrderState> onDelivered(Order& order) override { throw runtime_error("Cannot deliver before shipping"); }
    unique_ptr<OrderState> onCancelled(Order& order) override; // refund path
};
class ShippedState : public OrderState {
public:
    unique_ptr<OrderState> onPaid(Order& order) override;
    unique_ptr<OrderState> onShipped(Order& order) override;
    unique_ptr<OrderState> onDelivered(Order& order) override;
    unique_ptr<OrderState> onCancelled(Order& order) override { throw runtime_error("Cannot cancel a shipped order"); }
};
class DeliveredState : public OrderState {
public:
    unique_ptr<OrderState> onPaid(Order& order) override;
    unique_ptr<OrderState> onShipped(Order& order) override;
    unique_ptr<OrderState> onDelivered(Order& order) override;
    unique_ptr<OrderState> onCancelled(Order& order) override { throw runtime_error("Cannot cancel a delivered order"); }
};
class CancelledState : public OrderState {
public:
    unique_ptr<OrderState> onPaid(Order& order) override { throw runtime_error("Order is cancelled"); }
    unique_ptr<OrderState> onShipped(Order& order) override { throw runtime_error("Order is cancelled"); }
    unique_ptr<OrderState> onDelivered(Order& order) override { throw runtime_error("Order is cancelled"); }
    unique_ptr<OrderState> onCancelled(Order& order) override;
};

unique_ptr<OrderState> PendingPaymentState::onPaid(Order& order) { order.status = OrderStatus::PAID; return make_unique<PaidState>(); }
unique_ptr<OrderState> PendingPaymentState::onCancelled(Order& order) { order.status = OrderStatus::CANCELLED; return make_unique<CancelledState>(); }
unique_ptr<OrderState> PaidState::onPaid(Order& order) { return make_unique<PaidState>(); }
unique_ptr<OrderState> PaidState::onShipped(Order& order) { order.status = OrderStatus::SHIPPED; return make_unique<ShippedState>(); }
unique_ptr<OrderState> PaidState::onCancelled(Order& order) { order.status = OrderStatus::CANCELLED; return make_unique<CancelledState>(); }
unique_ptr<OrderState> ShippedState::onPaid(Order& order) { return make_unique<ShippedState>(); }
unique_ptr<OrderState> ShippedState::onShipped(Order& order) { return make_unique<ShippedState>(); }
unique_ptr<OrderState> ShippedState::onDelivered(Order& order) { order.status = OrderStatus::DELIVERED; return make_unique<DeliveredState>(); }
unique_ptr<OrderState> DeliveredState::onPaid(Order& order) { return make_unique<DeliveredState>(); }
unique_ptr<OrderState> DeliveredState::onShipped(Order& order) { return make_unique<DeliveredState>(); }
unique_ptr<OrderState> DeliveredState::onDelivered(Order& order) { return make_unique<DeliveredState>(); }
unique_ptr<OrderState> CancelledState::onCancelled(Order& order) { return make_unique<CancelledState>(); }

Order::Order(string id_, vector<shared_ptr<CartItem>> lineItems_, double totalPrice_)
    : id(move(id_)), lineItems(move(lineItems_)), totalPrice(totalPrice_),
      status(OrderStatus::PENDING_PAYMENT), state(make_unique<PendingPaymentState>()) {}

Order* Order::transitionTo(OrderStatus target) {
    switch (target) {
        case OrderStatus::PAID: state = state->onPaid(*this); break;
        case OrderStatus::SHIPPED: state = state->onShipped(*this); break;
        case OrderStatus::DELIVERED: state = state->onDelivered(*this); break;
        case OrderStatus::CANCELLED: state = state->onCancelled(*this); break;
    }
    return this;
}

struct PaymentResult { bool success; };

string statusToString(OrderStatus s) {
    switch (s) {
        case OrderStatus::PENDING_PAYMENT: return "PENDING_PAYMENT";
        case OrderStatus::PAID: return "PAID";
        case OrderStatus::SHIPPED: return "SHIPPED";
        case OrderStatus::DELIVERED: return "DELIVERED";
        case OrderStatus::CANCELLED: return "CANCELLED";
    }
    return "?";
}

// ---------- CheckoutService (Facade) ----------
class CheckoutService {
    vector<shared_ptr<PricingStep>> pricingPipeline;
    map<string, shared_ptr<Order>> ordersById;
    map<string, shared_ptr<Order>> processedIdempotencyKeys;
    int nextOrderId = 1;
public:
    CheckoutService(vector<shared_ptr<PricingStep>> pipeline) : pricingPipeline(move(pipeline)) {}

    shared_ptr<Order> checkout(Cart& cart, const string& couponCode) {
        vector<string> orderedProductIds;
        for (auto& item : cart.getItems()) {
            if (find(orderedProductIds.begin(), orderedProductIds.end(), item->getProduct()->id) == orderedProductIds.end())
                orderedProductIds.push_back(item->getProduct()->id);
        }
        sort(orderedProductIds.begin(), orderedProductIds.end()); // canonical order avoids cross-cart deadlock

        vector<Product*> reserved;
        vector<int> reservedQty;
        try {
            for (auto& productId : orderedProductIds) {
                Product* product = productFor(cart, productId);
                int qty = cart.quantityFor(productId);
                product->decrementStock(qty); // throws OutOfStockException on failure
                reserved.push_back(product);
                reservedQty.push_back(qty);
            }
        } catch (OutOfStockException&) {
            for (size_t i = 0; i < reserved.size(); i++) reserved[i]->restoreStock(reservedQty[i]);
            throw;
        }

        double total = cart.subtotal(); // includes decorator-priced add-ons
        for (auto& step : pricingPipeline) total = step->apply(total, cart);

        auto order = make_shared<Order>("ORD-" + to_string(nextOrderId++), cart.getItems(), total);
        ordersById[order->id] = order;
        return order;
    }

    shared_ptr<Order> confirmPayment(const string& orderId, PaymentResult result, const string& idempotencyKey) {
        auto found = processedIdempotencyKeys.find(idempotencyKey);
        if (found != processedIdempotencyKeys.end()) return found->second;

        auto it = ordersById.find(orderId);
        if (it == ordersById.end()) throw OrderNotFoundException("No such order: " + orderId);
        auto order = it->second;

        if (result.success) {
            order->transitionTo(OrderStatus::PAID);
        } else {
            order->transitionTo(OrderStatus::CANCELLED);
            restoreInventory(*order);
        }
        processedIdempotencyKeys[idempotencyKey] = order;
        return order;
    }

private:
    void restoreInventory(Order& order) {
        for (auto& item : order.lineItems) item->getProduct()->restoreStock(item->getQuantity());
    }

    Product* productFor(Cart& cart, const string& productId) {
        for (auto& item : cart.getItems()) if (item->getProduct()->id == productId) return item->getProduct();
        throw runtime_error("Product not in cart: " + productId);
    }
};

// ---------- Demo ----------
int main() {
    Product laptop("P1", "Laptop", 1000.0, 5);
    Product mug("P2", "Mug", 15.0, 10);

    Cart cart;
    cart.addItem(make_shared<GiftWrapDecorator>(make_shared<CartItem>(&laptop, 1)));
    cart.addItem(make_shared<EngravingDecorator>(make_shared<CartItem>(&mug, 2)));

    cout << "Subtotal (with add-ons): " << cart.subtotal() << endl;

    map<string, double> coupons = {{"SAVE10", 0.10}};
    vector<shared_ptr<PricingStep>> pipeline;
    pipeline.push_back(make_shared<CouponDiscountPricingStep>("SAVE10", coupons));
    pipeline.push_back(make_shared<TaxPricingStep>(0.08));

    CheckoutService checkoutService(pipeline);
    auto order = checkoutService.checkout(cart, "SAVE10");
    cout << "Order created: " << order->id << " total=" << order->totalPrice << " status=" << statusToString(order->status) << endl;
    cout << "Laptop stock after checkout: " << laptop.stock << endl;

    auto confirmed = checkoutService.confirmPayment(order->id, PaymentResult{true}, "idem-key-1");
    cout << "After payment: " << statusToString(confirmed->status) << endl;

    auto retried = checkoutService.confirmPayment(order->id, PaymentResult{true}, "idem-key-1");
    cout << "Retry same order id? " << (retried == confirmed) << endl;

    confirmed->transitionTo(OrderStatus::SHIPPED);
    confirmed->transitionTo(OrderStatus::DELIVERED);
    cout << "Final status: " << statusToString(confirmed->status) << endl;

    return 0;
}

