// Problem 19: E-commerce Shopping Cart & Checkout
// Patterns: Decorator (add-ons on CartItem), Strategy (pricing pipeline), State (Order lifecycle), Facade (CheckoutService)

class OutOfStockException extends Error {}
class OrderNotFoundException extends Error {}

// ---------- Catalog ----------
class Product {
  constructor(public id: string, public name: string, public price: number, public stock: number) {}

  decrementStock(qty: number): void {
    if (this.stock < qty) throw new OutOfStockException(`Insufficient stock for ${this.id}`);
    this.stock -= qty;
  }
  restoreStock(qty: number): void { this.stock += qty; }
}

// ---------- CartItem (component) + Decorator ----------
class CartItem {
  constructor(protected product: Product, protected quantity: number) {}

  getPrice(): number { return this.product.price * this.quantity; }
  getProduct(): Product { return this.product; }
  getQuantity(): number { return this.quantity; }
}

// Abstract decorator: subclasses CartItem so it's substitutable everywhere a CartItem is
// expected, but wraps another CartItem to layer one stackable add-on charge on top.
abstract class CartItemDecorator extends CartItem {
  constructor(protected wrapped: CartItem) {
    super(wrapped.getProduct(), wrapped.getQuantity());
  }
  abstract getPrice(): number;
}

class GiftWrapDecorator extends CartItemDecorator {
  private static readonly FEE = 2.99;
  getPrice(): number { return this.wrapped.getPrice() + GiftWrapDecorator.FEE; }
}

class EngravingDecorator extends CartItemDecorator {
  private static readonly FEE = 5.00;
  getPrice(): number { return this.wrapped.getPrice() + EngravingDecorator.FEE; }
}

// ---------- Cart ----------
class Cart {
  private items: CartItem[] = [];

  addItem(item: CartItem): void { this.items.push(item); }
  removeItem(productId: string): void { this.items = this.items.filter(i => i.getProduct().id !== productId); }
  subtotal(): number { return this.items.reduce((sum, i) => sum + i.getPrice(), 0); }
  quantityFor(productId: string): number {
    return this.items.filter(i => i.getProduct().id === productId).reduce((sum, i) => sum + i.getQuantity(), 0);
  }
  getItems(): CartItem[] { return this.items; }
}

// ---------- Pricing pipeline (Strategy) ----------
interface PricingStep {
  apply(runningTotal: number, cart: Cart): number;
}

class TaxPricingStep implements PricingStep {
  constructor(private rate: number) {}
  apply(runningTotal: number, _cart: Cart): number { return runningTotal + runningTotal * this.rate; }
}

class CouponDiscountPricingStep implements PricingStep {
  constructor(private couponCode: string, private validCoupons: Map<string, number>) {}
  apply(runningTotal: number, _cart: Cart): number {
    if (!this.validCoupons.has(this.couponCode)) return runningTotal;
    return runningTotal * (1 - this.validCoupons.get(this.couponCode)!);
  }
}

// ---------- Order lifecycle (State) ----------
enum OrderStatus { PENDING_PAYMENT = 'PENDING_PAYMENT', PAID = 'PAID', SHIPPED = 'SHIPPED', DELIVERED = 'DELIVERED', CANCELLED = 'CANCELLED' }

interface OrderState {
  onPaid(order: Order): OrderState;
  onShipped(order: Order): OrderState;
  onDelivered(order: Order): OrderState;
  onCancelled(order: Order): OrderState;
}

class PendingPaymentState implements OrderState {
  onPaid(order: Order): OrderState { order.status = OrderStatus.PAID; return new PaidState(); }
  onShipped(): OrderState { throw new Error('Cannot ship before payment'); }
  onDelivered(): OrderState { throw new Error('Cannot deliver before payment'); }
  onCancelled(order: Order): OrderState { order.status = OrderStatus.CANCELLED; return new CancelledState(); }
}
class PaidState implements OrderState {
  onPaid(): OrderState { return this; }
  onShipped(order: Order): OrderState { order.status = OrderStatus.SHIPPED; return new ShippedState(); }
  onDelivered(): OrderState { throw new Error('Cannot deliver before shipping'); }
  onCancelled(order: Order): OrderState { order.status = OrderStatus.CANCELLED; return new CancelledState(); } // refund path
}
class ShippedState implements OrderState {
  onPaid(): OrderState { return this; }
  onShipped(): OrderState { return this; }
  onDelivered(order: Order): OrderState { order.status = OrderStatus.DELIVERED; return new DeliveredState(); }
  onCancelled(): OrderState { throw new Error('Cannot cancel a shipped order'); }
}
class DeliveredState implements OrderState {
  onPaid(): OrderState { return this; }
  onShipped(): OrderState { return this; }
  onDelivered(): OrderState { return this; }
  onCancelled(): OrderState { throw new Error('Cannot cancel a delivered order'); }
}
class CancelledState implements OrderState {
  onPaid(): OrderState { throw new Error('Order is cancelled'); }
  onShipped(): OrderState { throw new Error('Order is cancelled'); }
  onDelivered(): OrderState { throw new Error('Order is cancelled'); }
  onCancelled(): OrderState { return this; }
}

// ---------- Order (immutable snapshot + lifecycle) ----------
class Order {
  readonly id: string;
  readonly lineItems: ReadonlyArray<CartItem>;
  readonly totalPrice: number;
  status: OrderStatus;
  private state: OrderState;

  constructor(id: string, lineItems: CartItem[], totalPrice: number) {
    this.id = id;
    this.lineItems = Object.freeze([...lineItems]);
    this.totalPrice = totalPrice;
    this.status = OrderStatus.PENDING_PAYMENT;
    this.state = new PendingPaymentState();
  }

  transitionTo(target: OrderStatus): Order {
    switch (target) {
      case OrderStatus.PAID: this.state = this.state.onPaid(this); break;
      case OrderStatus.SHIPPED: this.state = this.state.onShipped(this); break;
      case OrderStatus.DELIVERED: this.state = this.state.onDelivered(this); break;
      case OrderStatus.CANCELLED: this.state = this.state.onCancelled(this); break;
      default: throw new Error(`Unsupported transition: ${target}`);
    }
    return this;
  }
}

interface PaymentResult { success: boolean; }

// ---------- CheckoutService (Facade) ----------
class CheckoutService {
  private ordersById = new Map<string, Order>();
  private processedIdempotencyKeys = new Map<string, Order>();
  private nextOrderId = 1;

  constructor(private pricingPipeline: PricingStep[]) {}

  checkout(cart: Cart, _couponCode: string | null): Order {
    const orderedProductIds = [...new Set(cart.getItems().map(i => i.getProduct().id))].sort(); // canonical order

    const reserved: { product: Product; qty: number }[] = [];
    try {
      for (const productId of orderedProductIds) {
        const product = this.productFor(cart, productId);
        const qty = cart.quantityFor(productId);
        product.decrementStock(qty); // throws OutOfStockException on failure
        reserved.push({ product, qty });
      }
    } catch (e) {
      for (const r of reserved) r.product.restoreStock(r.qty);
      throw e;
    }

    let total = cart.subtotal(); // includes decorator-priced add-ons
    for (const step of this.pricingPipeline) total = step.apply(total, cart);

    const order = new Order(`ORD-${this.nextOrderId++}`, cart.getItems(), total);
    this.ordersById.set(order.id, order);
    return order;
  }

  confirmPayment(orderId: string, result: PaymentResult, idempotencyKey: string): Order {
    if (this.processedIdempotencyKeys.has(idempotencyKey)) {
      return this.processedIdempotencyKeys.get(idempotencyKey)!; // already processed: no double effect
    }
    const order = this.ordersById.get(orderId);
    if (!order) throw new OrderNotFoundException(`No such order: ${orderId}`);

    if (result.success) {
      order.transitionTo(OrderStatus.PAID);
    } else {
      order.transitionTo(OrderStatus.CANCELLED);
      this.restoreInventory(order);
    }
    this.processedIdempotencyKeys.set(idempotencyKey, order);
    return order;
  }

  private restoreInventory(order: Order): void {
    for (const item of order.lineItems) item.getProduct().restoreStock(item.getQuantity());
  }

  private productFor(cart: Cart, productId: string): Product {
    const item = cart.getItems().find(i => i.getProduct().id === productId);
    if (!item) throw new Error(`Product not in cart: ${productId}`);
    return item.getProduct();
  }
}

// ---------- Demo ----------
function main(): void {
  const laptop = new Product('P1', 'Laptop', 1000.0, 5);
  const mug = new Product('P2', 'Mug', 15.0, 10);

  const cart = new Cart();
  cart.addItem(new GiftWrapDecorator(new CartItem(laptop, 1)));
  cart.addItem(new EngravingDecorator(new CartItem(mug, 2)));

  console.log('Subtotal (with add-ons):', cart.subtotal());

  const coupons = new Map<string, number>([['SAVE10', 0.10]]);
  const pipeline: PricingStep[] = [new CouponDiscountPricingStep('SAVE10', coupons), new TaxPricingStep(0.08)];

  const checkoutService = new CheckoutService(pipeline);
  const order = checkoutService.checkout(cart, 'SAVE10');
  console.log(`Order created: ${order.id} total=${order.totalPrice} status=${order.status}`);
  console.log('Laptop stock after checkout:', laptop.stock);

  const confirmed = checkoutService.confirmPayment(order.id, { success: true }, 'idem-key-1');
  console.log('After payment:', confirmed.status);

  const retried = checkoutService.confirmPayment(order.id, { success: true }, 'idem-key-1');
  console.log('Retry same order id?', retried === confirmed);

  confirmed.transitionTo(OrderStatus.SHIPPED);
  confirmed.transitionTo(OrderStatus.DELIVERED);
  console.log('Final status:', confirmed.status);
}

