// Problem 20: Chat Application (WhatsApp-style)
// Patterns: Mediator + Observer (Conversation), State (MessageStatus per recipient), Facade (ChatService)
import java.util.*;

public class p20 {

    // ---------- User ----------
    static class User {
        final String id;
        final Set<String> connectedDevices = new HashSet<>();
        User(String id) { this.id = id; }
    }

    // ---------- MessageStatus (per-recipient state machine) ----------
    interface MessageStatus {
        MessageStatus onDelivered();
        MessageStatus onRead();
        String name();
    }

    static class SentStatus implements MessageStatus {
        @Override public MessageStatus onDelivered() { return new DeliveredStatus(); }
        @Override public MessageStatus onRead() { throw new IllegalStateException("Must be delivered before read"); }
        @Override public String name() { return "SENT"; }
    }
    static class DeliveredStatus implements MessageStatus {
        @Override public MessageStatus onDelivered() { return this; }
        @Override public MessageStatus onRead() { return new ReadStatus(); }
        @Override public String name() { return "DELIVERED"; }
    }
    static class ReadStatus implements MessageStatus {
        @Override public MessageStatus onDelivered() { return this; }
        @Override public MessageStatus onRead() { return this; }
        @Override public String name() { return "READ"; }
    }

    // ---------- Message ----------
    static class Message {
        final User sender;
        final String content;
        final long sequenceNo;
        final Map<String, MessageStatus> receipts = new HashMap<>(); // recipientId -> status

        Message(User sender, String content, long sequenceNo, List<User> recipients) {
            this.sender = sender; this.content = content; this.sequenceNo = sequenceNo;
            for (User r : recipients) receipts.put(r.id, new SentStatus());
        }

        void markDelivered(String userId) { receipts.computeIfPresent(userId, (k, s) -> s.onDelivered()); }
        void markRead(String userId) { receipts.computeIfPresent(userId, (k, s) -> s.onRead()); }
    }

    // ---------- PresenceTracker ----------
    static class PresenceTracker {
        private final Map<String, Set<String>> connectedDeviceIds = new HashMap<>();

        void deviceConnected(String userId, String deviceId) {
            connectedDeviceIds.computeIfAbsent(userId, k -> new HashSet<>()).add(deviceId);
        }
        void deviceDisconnected(String userId, String deviceId) {
            Set<String> devices = connectedDeviceIds.get(userId);
            if (devices != null) devices.remove(deviceId);
        }
        boolean isOnline(String userId) {
            Set<String> devices = connectedDeviceIds.get(userId);
            return devices != null && !devices.isEmpty();
        }
    }

    // Simple per-user append-only log of messages missed while offline.
    // NOTE (interview-scale simplification): the cursor passed to reconnect() is treated as an
    // index into this per-user queue (not the message's own per-conversation sequenceNo), since
    // a user's offline queue spans multiple conversations whose sequence numbers aren't
    // comparable to each other. Same cursor -> same slice, so replay is idempotent.
    static class OfflineQueue {
        private final List<Message> messages = new ArrayList<>();
        void enqueue(Message m) { messages.add(m); }
        List<Message> allAfter(long cursor) {
            int from = Math.min((int) cursor, messages.size());
            return new ArrayList<>(messages.subList(from, messages.size()));
        }
        void clearUpTo(long cursor) {
            int upTo = Math.min((int) cursor, messages.size());
            messages.subList(0, upTo).clear();
        }
    }

    // ---------- Conversation (Mediator + Observer subject) ----------
    static abstract class Conversation {
        final String id;
        final List<User> participants = new ArrayList<>();
        final List<Message> messages = new ArrayList<>();
        long nextSequence = 0;
        private final PresenceTracker presenceTracker;
        private final Map<String, OfflineQueue> offlineQueues; // shared reference, owned by ChatService

        Conversation(String id, PresenceTracker presenceTracker, Map<String, OfflineQueue> offlineQueues) {
            this.id = id; this.presenceTracker = presenceTracker; this.offlineQueues = offlineQueues;
        }

        void addParticipant(User user) {
            if (!participants.contains(user)) participants.add(user);
        }

        Message send(User sender, String content) {
            long seq = ++nextSequence; // server-assigned, monotonic per conversation
            List<User> recipients = new ArrayList<>();
            for (User p : participants) if (!p.id.equals(sender.id)) recipients.add(p);
            Message message = new Message(sender, content, seq, recipients);
            messages.add(message);

            for (User participant : recipients) { // Observer fan-out
                if (presenceTracker.isOnline(participant.id)) {
                    message.markDelivered(participant.id);
                } else {
                    offlineQueues.computeIfAbsent(participant.id, k -> new OfflineQueue()).enqueue(message);
                }
            }
            return message;
        }
    }

    static class DirectConversation extends Conversation {
        DirectConversation(String id, User a, User b, PresenceTracker tracker, Map<String, OfflineQueue> offlineQueues) {
            super(id, tracker, offlineQueues);
            participants.add(a); participants.add(b);
        }
        @Override void addParticipant(User user) {
            throw new UnsupportedOperationException("DirectConversation is fixed at 2 participants");
        }
    }

    static class GroupConversation extends Conversation {
        GroupConversation(String id, List<User> initialParticipants, PresenceTracker tracker, Map<String, OfflineQueue> offlineQueues) {
            super(id, tracker, offlineQueues);
            participants.addAll(initialParticipants);
        }
        void removeParticipant(User user) { participants.remove(user); }
    }

    // ---------- ChatService (Facade) ----------
    static class ChatService {
        private final PresenceTracker presenceTracker = new PresenceTracker();
        private final Map<String, OfflineQueue> offlineQueues = new HashMap<>();
        private int nextConversationId = 1;

        PresenceTracker getPresenceTracker() { return presenceTracker; }

        DirectConversation createDirectConversation(User a, User b) {
            return new DirectConversation("C" + (nextConversationId++), a, b, presenceTracker, offlineQueues);
        }

        GroupConversation createGroupConversation(List<User> participants) {
            return new GroupConversation("C" + (nextConversationId++), participants, presenceTracker, offlineQueues);
        }

        Message sendMessage(User sender, Conversation conversation, String content) {
            return conversation.send(sender, content);
        }

        // Exactly-once replay: client passes back the cursor from its last successful reconnect.
        List<Message> reconnect(User user, long lastSeenSequence) {
            OfflineQueue queue = offlineQueues.computeIfAbsent(user.id, k -> new OfflineQueue());
            List<Message> missed = queue.allAfter(lastSeenSequence);
            queue.clearUpTo(lastSeenSequence + missed.size());
            for (Message m : missed) m.markDelivered(user.id);
            return missed;
        }
    }

    // ---------- Demo ----------
    public static void main(String[] args) {
        ChatService chatService = new ChatService();
        User alice = new User("alice");
        User bob = new User("bob");
        User carol = new User("carol");

        chatService.getPresenceTracker().deviceConnected("alice", "alice-phone");
        chatService.getPresenceTracker().deviceConnected("bob", "bob-laptop");
        // carol is offline (no connected device)

        GroupConversation group = chatService.createGroupConversation(Arrays.asList(alice, bob, carol));

        Message m1 = chatService.sendMessage(alice, group, "Hello everyone!");
        System.out.println("Sent seq=" + m1.sequenceNo + " bob receipt=" + m1.receipts.get("bob").name()
                + " carol receipt=" + m1.receipts.get("carol").name());

        Message m2 = chatService.sendMessage(bob, group, "Hi Alice!");
        System.out.println("Sent seq=" + m2.sequenceNo);

        // Carol reconnects and should receive both missed messages, exactly once, in order.
        List<Message> missed = chatService.reconnect(carol, 0);
        System.out.println("Carol missed " + missed.size() + " messages, first content='" + missed.get(0).content + "'");

        // Idempotent retry with an already-advanced cursor should now return nothing new.
        List<Message> replay = chatService.reconnect(carol, missed.size());
        System.out.println("Carol replay after ack: " + replay.size() + " messages (expect 0)");

        m1.markRead("bob");
        System.out.println("Bob's receipt for m1 after reading: " + m1.receipts.get("bob").name());
    }
}

