#include <algorithm>
#include <stdexcept>

using namespace std;

// ---------- User ----------
struct User {
    string id;
    set<string> connectedDevices;
    User(string id_) : id(move(id_)) {}
};

// ---------- MessageStatus (per-recipient state machine) ----------
class MessageStatus {
public:
    virtual ~MessageStatus() = default;
    virtual shared_ptr<MessageStatus> onDelivered() = 0;
    virtual shared_ptr<MessageStatus> onRead() = 0;
    virtual string name() const = 0;
};

class SentStatus : public MessageStatus {
public:
    shared_ptr<MessageStatus> onDelivered() override;
    shared_ptr<MessageStatus> onRead() override { throw runtime_error("Must be delivered before read"); }
    string name() const override { return "SENT"; }
};
class DeliveredStatus : public MessageStatus {
public:
    shared_ptr<MessageStatus> onDelivered() override { return make_shared<DeliveredStatus>(); }
    shared_ptr<MessageStatus> onRead() override;
    string name() const override { return "DELIVERED"; }
};
class ReadStatus : public MessageStatus {
public:
    shared_ptr<MessageStatus> onDelivered() override { return make_shared<ReadStatus>(); }
    shared_ptr<MessageStatus> onRead() override { return make_shared<ReadStatus>(); }
    string name() const override { return "READ"; }
};
shared_ptr<MessageStatus> SentStatus::onDelivered() { return make_shared<DeliveredStatus>(); }
shared_ptr<MessageStatus> DeliveredStatus::onRead() { return make_shared<ReadStatus>(); }

// ---------- Message ----------
class Message {
public:
    shared_ptr<User> sender;
    string content;
    long long sequenceNo;
    map<string, shared_ptr<MessageStatus>> receipts; // recipientId -> status

    Message(shared_ptr<User> sender_, string content_, long long seq, const vector<shared_ptr<User>>& recipients)
        : sender(sender_), content(move(content_)), sequenceNo(seq) {
        for (auto& r : recipients) receipts[r->id] = make_shared<SentStatus>();
    }

    void markDelivered(const string& userId) {
        auto it = receipts.find(userId);
        if (it != receipts.end()) it->second = it->second->onDelivered();
    }
    void markRead(const string& userId) {
        auto it = receipts.find(userId);
        if (it != receipts.end()) it->second = it->second->onRead();
    }
};

// ---------- PresenceTracker ----------
class PresenceTracker {
    map<string, set<string>> connectedDeviceIds;
public:
    void deviceConnected(const string& userId, const string& deviceId) { connectedDeviceIds[userId].insert(deviceId); }
    void deviceDisconnected(const string& userId, const string& deviceId) {
        auto it = connectedDeviceIds.find(userId);
        if (it != connectedDeviceIds.end()) it->second.erase(deviceId);
    }
    bool isOnline(const string& userId) {
        auto it = connectedDeviceIds.find(userId);
        return it != connectedDeviceIds.end() && !it->second.empty();
    }
};

// Simple per-user append-only log of messages missed while offline.
// NOTE (interview-scale simplification): the cursor passed to reconnect() is treated as an
// index into this per-user queue (not the message's own per-conversation sequenceNo), since
// a user's offline queue spans multiple conversations whose sequence numbers aren't
// comparable to each other. Same cursor -> same slice, so replay is idempotent.
class OfflineQueue {
    vector<shared_ptr<Message>> messages;
public:
    void enqueue(shared_ptr<Message> m) { messages.push_back(m); }
    vector<shared_ptr<Message>> allAfter(long long cursor) {
        size_t from = min((size_t) max<long long>(cursor, 0), messages.size());
        return vector<shared_ptr<Message>>(messages.begin() + from, messages.end());
    }
    void clearUpTo(long long cursor) {
        size_t upTo = min((size_t) max<long long>(cursor, 0), messages.size());
        messages.erase(messages.begin(), messages.begin() + upTo);
    }
};

// ---------- Conversation (Mediator + Observer subject) ----------
class Conversation {
protected:
    PresenceTracker* presenceTracker;
    map<string, shared_ptr<OfflineQueue>>* offlineQueues; // shared reference, owned by ChatService
public:
    string id;
    vector<shared_ptr<User>> participants;
    vector<shared_ptr<Message>> messages;
    long long nextSequence = 0;

    Conversation(string id_, PresenceTracker* tracker, map<string, shared_ptr<OfflineQueue>>* queues)
        : presenceTracker(tracker), offlineQueues(queues), id(move(id_)) {}
    virtual ~Conversation() = default;

    virtual void addParticipant(shared_ptr<User> user) {
        if (find(participants.begin(), participants.end(), user) == participants.end()) participants.push_back(user);
    }

    shared_ptr<Message> send(shared_ptr<User> sender, const string& content) {
        long long seq = ++nextSequence; // server-assigned, monotonic per conversation
        vector<shared_ptr<User>> recipients;
        for (auto& p : participants) if (p->id != sender->id) recipients.push_back(p);
        auto message = make_shared<Message>(sender, content, seq, recipients);
        messages.push_back(message);

        for (auto& participant : recipients) { // Observer fan-out
            if (presenceTracker->isOnline(participant->id)) {
                message->markDelivered(participant->id);
            } else {
                auto& q = (*offlineQueues)[participant->id];
                if (!q) q = make_shared<OfflineQueue>();
                q->enqueue(message);
            }
        }
        return message;
    }
};

class DirectConversation : public Conversation {
public:
    DirectConversation(string id_, shared_ptr<User> a, shared_ptr<User> b, PresenceTracker* tracker,
                        map<string, shared_ptr<OfflineQueue>>* queues)
        : Conversation(move(id_), tracker, queues) {
        participants.push_back(a); participants.push_back(b);
    }
    void addParticipant(shared_ptr<User> user) override {
        throw runtime_error("DirectConversation is fixed at 2 participants");
    }
};

class GroupConversation : public Conversation {
public:
    GroupConversation(string id_, vector<shared_ptr<User>> initial, PresenceTracker* tracker,
                       map<string, shared_ptr<OfflineQueue>>* queues)
        : Conversation(move(id_), tracker, queues) {
        participants = move(initial);
    }
    void removeParticipant(shared_ptr<User> user) {
        participants.erase(remove(participants.begin(), participants.end(), user), participants.end());
    }
};

// ---------- ChatService (Facade) ----------
class ChatService {
    PresenceTracker presenceTracker;
    map<string, shared_ptr<OfflineQueue>> offlineQueues;
    int nextConversationId = 1;
public:
    PresenceTracker& getPresenceTracker() { return presenceTracker; }

    shared_ptr<DirectConversation> createDirectConversation(shared_ptr<User> a, shared_ptr<User> b) {
        return make_shared<DirectConversation>("C" + to_string(nextConversationId++), a, b, &presenceTracker, &offlineQueues);
    }

    shared_ptr<GroupConversation> createGroupConversation(vector<shared_ptr<User>> participants) {
        return make_shared<GroupConversation>("C" + to_string(nextConversationId++), move(participants), &presenceTracker, &offlineQueues);
    }

    shared_ptr<Message> sendMessage(shared_ptr<User> sender, shared_ptr<Conversation> conversation, const string& content) {
        return conversation->send(sender, content);
    }

    // Exactly-once replay: client passes back the cursor from its last successful reconnect.
    vector<shared_ptr<Message>> reconnect(shared_ptr<User> user, long long lastSeenSequence) {
        auto& q = offlineQueues[user->id];
        if (!q) q = make_shared<OfflineQueue>();
        auto missed = q->allAfter(lastSeenSequence);
        q->clearUpTo(lastSeenSequence + (long long) missed.size());
        for (auto& m : missed) m->markDelivered(user->id);
        return missed;
    }
};

// ---------- Demo ----------
int main() {
    ChatService chatService;
    auto alice = make_shared<User>("alice");
    auto bob = make_shared<User>("bob");
    auto carol = make_shared<User>("carol");

    chatService.getPresenceTracker().deviceConnected("alice", "alice-phone");
    chatService.getPresenceTracker().deviceConnected("bob", "bob-laptop");
    // carol is offline (no connected device)

    auto group = chatService.createGroupConversation({alice, bob, carol});

    auto m1 = chatService.sendMessage(alice, group, "Hello everyone!");
    cout << "Sent seq=" << m1->sequenceNo << " bob receipt=" << m1->receipts["bob"]->name()
         << " carol receipt=" << m1->receipts["carol"]->name() << endl;

    auto m2 = chatService.sendMessage(bob, group, "Hi Alice!");
    cout << "Sent seq=" << m2->sequenceNo << endl;

    auto missed = chatService.reconnect(carol, 0);
    cout << "Carol missed " << missed.size() << " messages, first content='" << missed[0]->content << "'" << endl;

    auto replay = chatService.reconnect(carol, (long long) missed.size());
    cout << "Carol replay after ack: " << replay.size() << " messages (expect 0)" << endl;

    m1->markRead("bob");
    cout << "Bob's receipt for m1 after reading: " << m1->receipts["bob"]->name() << endl;

    return 0;
}

