// Problem 20: Chat Application (WhatsApp-style)
// Patterns: Mediator + Observer (Conversation), State (MessageStatus per recipient), Facade (ChatService)

// ---------- User ----------
class User {
  constructor(id) { this.id = id; this.connectedDevices = new Set(); }
}

// ---------- MessageStatus (per-recipient state machine) ----------
class SentStatus {
  onDelivered() { return new DeliveredStatus(); }
  onRead() { throw new Error('Must be delivered before read'); }
  name() { return 'SENT'; }
}
class DeliveredStatus {
  onDelivered() { return this; }
  onRead() { return new ReadStatus(); }
  name() { return 'DELIVERED'; }
}
class ReadStatus {
  onDelivered() { return this; }
  onRead() { return this; }
  name() { return 'READ'; }
}

// ---------- Message ----------
class Message {
  constructor(sender, content, sequenceNo, recipients) {
    this.sender = sender; this.content = content; this.sequenceNo = sequenceNo;
    this.receipts = new Map(); // recipientId -> status
    for (const r of recipients) this.receipts.set(r.id, new SentStatus());
  }
  markDelivered(userId) {
    if (this.receipts.has(userId)) this.receipts.set(userId, this.receipts.get(userId).onDelivered());
  }
  markRead(userId) {
    if (this.receipts.has(userId)) this.receipts.set(userId, this.receipts.get(userId).onRead());
  }
}

// ---------- PresenceTracker ----------
class PresenceTracker {
  constructor() { this.connectedDeviceIds = new Map(); }
  deviceConnected(userId, deviceId) {
    if (!this.connectedDeviceIds.has(userId)) this.connectedDeviceIds.set(userId, new Set());
    this.connectedDeviceIds.get(userId).add(deviceId);
  }
  deviceDisconnected(userId, deviceId) {
    const devices = this.connectedDeviceIds.get(userId);
    if (devices) devices.delete(deviceId);
  }
  isOnline(userId) {
    const devices = this.connectedDeviceIds.get(userId);
    return !!devices && devices.size > 0;
  }
}

// Simple per-user append-only log of messages missed while offline.
// NOTE (interview-scale simplification): the cursor passed to reconnect() is treated as an
// index into this per-user queue (not the message's own per-conversation sequenceNo), since
// a user's offline queue spans multiple conversations whose sequence numbers aren't
// comparable to each other. Same cursor -> same slice, so replay is idempotent.
class OfflineQueue {
  constructor() { this.messages = []; }
  enqueue(m) { this.messages.push(m); }
  allAfter(cursor) {
    const from = Math.min(cursor, this.messages.length);
    return this.messages.slice(from);
  }
  clearUpTo(cursor) {
    const upTo = Math.min(cursor, this.messages.length);
    this.messages.splice(0, upTo);
  }
}

// ---------- Conversation (Mediator + Observer subject) ----------
class Conversation {
  constructor(id, presenceTracker, offlineQueues) {
    this.id = id;
    this.participants = [];
    this.messages = [];
    this.nextSequence = 0;
    this.presenceTracker = presenceTracker;
    this.offlineQueues = offlineQueues; // shared Map reference, owned by ChatService
  }

  addParticipant(user) {
    if (!this.participants.includes(user)) this.participants.push(user);
  }

  send(sender, content) {
    const seq = ++this.nextSequence; // server-assigned, monotonic per conversation
    const recipients = this.participants.filter(p => p.id !== sender.id);
    const message = new Message(sender, content, seq, recipients);
    this.messages.push(message);

    for (const participant of recipients) { // Observer fan-out
      if (this.presenceTracker.isOnline(participant.id)) {
        message.markDelivered(participant.id);
      } else {
        if (!this.offlineQueues.has(participant.id)) this.offlineQueues.set(participant.id, new OfflineQueue());
        this.offlineQueues.get(participant.id).enqueue(message);
      }
    }
    return message;
  }
}

class DirectConversation extends Conversation {
  constructor(id, a, b, presenceTracker, offlineQueues) {
    super(id, presenceTracker, offlineQueues);
    this.participants.push(a, b);
  }
  addParticipant() { throw new Error('DirectConversation is fixed at 2 participants'); }
}

class GroupConversation extends Conversation {
  constructor(id, initialParticipants, presenceTracker, offlineQueues) {
    super(id, presenceTracker, offlineQueues);
    this.participants.push(...initialParticipants);
  }
  removeParticipant(user) { this.participants = this.participants.filter(p => p !== user); }
}

// ---------- ChatService (Facade) ----------
class ChatService {
  constructor() {
    this.presenceTracker = new PresenceTracker();
    this.offlineQueues = new Map();
    this.nextConversationId = 1;
  }

  createDirectConversation(a, b) {
    return new DirectConversation(`C${this.nextConversationId++}`, a, b, this.presenceTracker, this.offlineQueues);
  }

  createGroupConversation(participants) {
    return new GroupConversation(`C${this.nextConversationId++}`, participants, this.presenceTracker, this.offlineQueues);
  }

  sendMessage(sender, conversation, content) {
    return conversation.send(sender, content);
  }

  // Exactly-once replay: client passes back the cursor from its last successful reconnect.
  reconnect(user, lastSeenSequence) {
    if (!this.offlineQueues.has(user.id)) this.offlineQueues.set(user.id, new OfflineQueue());
    const queue = this.offlineQueues.get(user.id);
    const missed = queue.allAfter(lastSeenSequence);
    queue.clearUpTo(lastSeenSequence + missed.length);
    for (const m of missed) m.markDelivered(user.id);
    return missed;
  }
}

// ---------- Demo ----------
function main() {
  const chatService = new ChatService();
  const alice = new User('alice');
  const bob = new User('bob');
  const carol = new User('carol');

  chatService.presenceTracker.deviceConnected('alice', 'alice-phone');
  chatService.presenceTracker.deviceConnected('bob', 'bob-laptop');
  // carol is offline (no connected device)

  const group = chatService.createGroupConversation([alice, bob, carol]);

  const m1 = chatService.sendMessage(alice, group, 'Hello everyone!');
  console.log(`Sent seq=${m1.sequenceNo} bob receipt=${m1.receipts.get('bob').name()} carol receipt=${m1.receipts.get('carol').name()}`);

  const m2 = chatService.sendMessage(bob, group, 'Hi Alice!');
  console.log(`Sent seq=${m2.sequenceNo}`);

  const missed = chatService.reconnect(carol, 0);
  console.log(`Carol missed ${missed.length} messages, first content='${missed[0].content}'`);

  const replay = chatService.reconnect(carol, missed.length);
  console.log(`Carol replay after ack: ${replay.length} messages (expect 0)`);

  m1.markRead('bob');
  console.log(`Bob's receipt for m1 after reading: ${m1.receipts.get('bob').name()}`);
}

if (require.main === module) main();

module.exports = {
  User, SentStatus, DeliveredStatus, ReadStatus, Message, PresenceTracker,
  OfflineQueue, Conversation, DirectConversation, GroupConversation, ChatService,
};

