// Problem 21: Stock Brokerage System
// Patterns: Strategy (ExecutionStrategy), Observer (MarketDataFeed -> Broker), Facade (Broker)
// Concurrency: per-account lock guards reserve+execute+settle so cash/holdings never corrupt
// under concurrent orders (badge: Advanced, Concurrency & Consistency).
import java.util.*;
import java.util.concurrent.locks.ReentrantLock;

public class p21 {

    // ---------- Exceptions ----------
    static class InsufficientFundsException extends RuntimeException { InsufficientFundsException(String m) { super(m); } }
    static class InsufficientHoldingsException extends RuntimeException { InsufficientHoldingsException(String m) { super(m); } }
    static class InvalidOrderStateException extends RuntimeException { InvalidOrderStateException(String m) { super(m); } }
    static class OrderNotFoundException extends RuntimeException { OrderNotFoundException(String m) { super(m); } }

    enum Side { BUY, SELL }
    enum OrderType { MARKET, LIMIT }
    enum OrderStatus { PENDING, EXECUTED, CANCELLED }

    // ---------- Stock ----------
    static class Stock {
        final String symbol;
        volatile double currentPrice;
        Stock(String symbol, double currentPrice) { this.symbol = symbol; this.currentPrice = currentPrice; }
        void updatePrice(double newPrice) { this.currentPrice = newPrice; }
    }

    // ---------- Portfolio (owned by Account) ----------
    static class Portfolio {
        private final Map<String, Integer> holdings = new HashMap<>();
        private final Map<String, Integer> reserved = new HashMap<>();

        void reserveShares(Stock stock, int qty) {
            int owned = holdings.getOrDefault(stock.symbol, 0);
            int alreadyReserved = reserved.getOrDefault(stock.symbol, 0);
            if (owned - alreadyReserved < qty) throw new InsufficientHoldingsException("Not enough shares of " + stock.symbol);
            reserved.merge(stock.symbol, qty, Integer::sum);
        }

        void releaseShares(Stock stock, int qty) {
            reserved.merge(stock.symbol, -qty, Integer::sum);
        }

        void addHolding(Stock stock, int qty) {
            holdings.merge(stock.symbol, qty, Integer::sum);
        }

        // Removes settled (sold) shares from both holdings and their reservation.
        void settle(Stock stock, int qty, Side side) {
            if (side == Side.SELL) {
                holdings.merge(stock.symbol, -qty, Integer::sum);
                reserved.merge(stock.symbol, -qty, Integer::sum);
            }
        }

        int holdingOf(String symbol) { return holdings.getOrDefault(symbol, 0); }
    }

    // ---------- Account (owns Portfolio) ----------
    static class Account {
        final String id;
        double cashBalance;
        double reservedCash;
        final Portfolio portfolio = new Portfolio();
        final ReentrantLock lock = new ReentrantLock(); // guards reserve/execute/settle atomicity

        Account(String id, double initialCash) { this.id = id; this.cashBalance = initialCash; }

        void reserve(double amount) {
            if (cashBalance - reservedCash < amount) throw new InsufficientFundsException("Insufficient funds in " + id);
            reservedCash += amount;
        }
        void release(double amount) { reservedCash = Math.max(0, reservedCash - amount); }
        void deposit(double amount) { cashBalance += amount; }
        void withdraw(double amount) {
            if (cashBalance < amount) throw new InsufficientFundsException("Insufficient funds in " + id);
            cashBalance -= amount;
        }
    }

    // ---------- Order (abstract) ----------
    static abstract class Order {
        final String id;
        final Account account;
        final Stock stock;
        final int quantity;
        final OrderType type;
        final double limitPrice; // unused for MARKET
        double reservedEstimate;
        OrderStatus status = OrderStatus.PENDING;
        final long createdAt = System.nanoTime();

        Order(String id, Account account, Stock stock, int quantity, OrderType type, double limitPrice) {
            this.id = id; this.account = account; this.stock = stock;
            this.quantity = quantity; this.type = type; this.limitPrice = limitPrice;
        }

        abstract Side getSide();

        void cancel() {
            if (status != OrderStatus.PENDING) throw new InvalidOrderStateException("Order not cancellable: " + status);
            status = OrderStatus.CANCELLED;
        }
    }

    static class BuyOrder extends Order {
        BuyOrder(String id, Account account, Stock stock, int quantity, OrderType type, double limitPrice) {
            super(id, account, stock, quantity, type, limitPrice);
        }
        @Override Side getSide() { return Side.BUY; }
    }

    static class SellOrder extends Order {
        SellOrder(String id, Account account, Stock stock, int quantity, OrderType type, double limitPrice) {
            super(id, account, stock, quantity, type, limitPrice);
        }
        @Override Side getSide() { return Side.SELL; }
    }

    // ---------- ExecutionStrategy ----------
    interface ExecutionStrategy {
        OptionalDouble tryExecute(Order order, double currentPrice);
    }

    static class MarketExecutionStrategy implements ExecutionStrategy {
        @Override public OptionalDouble tryExecute(Order order, double currentPrice) {
            return OptionalDouble.of(currentPrice); // market orders always execute immediately
        }
    }

    static class LimitExecutionStrategy implements ExecutionStrategy {
        @Override public OptionalDouble tryExecute(Order order, double currentPrice) {
            boolean conditionMet = order.getSide() == Side.BUY
                    ? currentPrice <= order.limitPrice
                    : currentPrice >= order.limitPrice;
            return conditionMet ? OptionalDouble.of(currentPrice) : OptionalDouble.empty();
        }
    }

    // ---------- MarketDataFeed ----------
    interface PriceListener {
        void onPriceUpdate(String symbol, double newPrice);
    }

    interface MarketDataFeed {
        double getPrice(String symbol);
        void subscribe(String symbol, PriceListener listener);
    }

    static class SimpleMarketDataFeed implements MarketDataFeed {
        private final Map<String, Stock> stocks;
        private final Map<String, List<PriceListener>> listeners = new HashMap<>();

        SimpleMarketDataFeed(Map<String, Stock> stocks) { this.stocks = stocks; }

        @Override public double getPrice(String symbol) { return stocks.get(symbol).currentPrice; }

        @Override public void subscribe(String symbol, PriceListener listener) {
            List<PriceListener> ls = listeners.computeIfAbsent(symbol, k -> new ArrayList<>());
            if (!ls.contains(listener)) ls.add(listener);
        }

        void updatePrice(String symbol, double newPrice) {
            stocks.get(symbol).updatePrice(newPrice);
            for (PriceListener l : listeners.getOrDefault(symbol, Collections.emptyList())) {
                l.onPriceUpdate(symbol, newPrice); // push, don't poll
            }
        }
    }

    // ---------- Broker (Facade) ----------
    static class Broker implements PriceListener {
        private final Map<String, Account> accounts = new HashMap<>();
        private final Map<String, Order> ordersById = new HashMap<>();
        private final Map<String, List<Order>> pendingOrdersBySymbol = new HashMap<>();
        private final MarketDataFeed feed;
        private final ExecutionStrategy marketStrategy = new MarketExecutionStrategy();
        private final ExecutionStrategy limitStrategy = new LimitExecutionStrategy();
        private int nextOrderId = 1;

        Broker(MarketDataFeed feed) { this.feed = feed; }

        void addAccount(Account account) { accounts.put(account.id, account); }

        void deposit(Account account, double amount) { account.deposit(amount); }

        void withdraw(Account account, double amount) { account.withdraw(amount); }

        Order placeOrder(Account account, Stock stock, Side side, int quantity, OrderType type, double limitPrice) {
            account.lock.lock(); // guard reserve + execution-attempt + settle atomically
            try {
                ExecutionStrategy strategy = (type == OrderType.MARKET) ? marketStrategy : limitStrategy;
                double currentPrice = feed.getPrice(stock.symbol);
                String id = "ORD-" + (nextOrderId++);
                Order order;

                if (side == Side.BUY) {
                    double estimatedCost = quantity * (type == OrderType.MARKET ? currentPrice : limitPrice);
                    account.reserve(estimatedCost); // throws InsufficientFundsException
                    order = new BuyOrder(id, account, stock, quantity, type, limitPrice);
                    order.reservedEstimate = estimatedCost;
                } else {
                    account.portfolio.reserveShares(stock, quantity); // throws InsufficientHoldingsException
                    order = new SellOrder(id, account, stock, quantity, type, limitPrice);
                }
                ordersById.put(order.id, order);

                OptionalDouble result = strategy.tryExecute(order, currentPrice);
                if (result.isPresent()) {
                    settle(order, result.getAsDouble());
                } else {
                    order.status = OrderStatus.PENDING;
                    pendingOrdersBySymbol.computeIfAbsent(stock.symbol, k -> new ArrayList<>()).add(order);
                    feed.subscribe(stock.symbol, this); // re-checked on future price ticks
                }
                return order;
            } finally {
                account.lock.unlock();
            }
        }

        @Override public void onPriceUpdate(String symbol, double newPrice) {
            List<Order> pending = pendingOrdersBySymbol.get(symbol);
            if (pending == null) return;
            List<Order> stillPending = new ArrayList<>();
            for (Order order : new ArrayList<>(pending)) {
                if (order.status != OrderStatus.PENDING) continue; // already cancelled/executed
                order.account.lock.lock();
                try {
                    ExecutionStrategy strategy = (order.type == OrderType.MARKET) ? marketStrategy : limitStrategy;
                    OptionalDouble result = strategy.tryExecute(order, newPrice);
                    if (result.isPresent()) {
                        settle(order, result.getAsDouble());
                    } else {
                        stillPending.add(order);
                    }
                } finally {
                    order.account.lock.unlock();
                }
            }
            pendingOrdersBySymbol.put(symbol, stillPending);
        }

        // Must be called while holding order.account.lock.
        private void settle(Order order, double executionPrice) {
            Account account = order.account;
            if (order.getSide() == Side.BUY) {
                account.release(order.reservedEstimate);
                account.withdraw(executionPrice * order.quantity);
                account.portfolio.addHolding(order.stock, order.quantity);
            } else {
                account.portfolio.settle(order.stock, order.quantity, Side.SELL); // removes reserved shares
                account.deposit(executionPrice * order.quantity);
            }
            order.status = OrderStatus.EXECUTED;
        }

        void cancelOrder(String orderId) {
            Order order = ordersById.get(orderId);
            if (order == null) throw new OrderNotFoundException("No such order: " + orderId);
            order.account.lock.lock();
            try {
                if (order.status != OrderStatus.PENDING) throw new InvalidOrderStateException("Order not cancellable: " + order.status);
                if (order.getSide() == Side.BUY) order.account.release(order.reservedEstimate);
                else order.account.portfolio.releaseShares(order.stock, order.quantity);
                order.status = OrderStatus.CANCELLED;
            } finally {
                order.account.lock.unlock();
            }
        }
    }

    // ---------- Demo ----------
    public static void main(String[] args) throws InterruptedException {
        Stock appl = new Stock("AAPL", 150.0);
        Map<String, Stock> stocks = new HashMap<>();
        stocks.put("AAPL", appl);
        SimpleMarketDataFeed feed = new SimpleMarketDataFeed(stocks);

        Broker broker = new Broker(feed);
        Account account = new Account("A1", 10000.0);
        broker.addAccount(account);

        // Market buy: executes immediately.
        Order buy = broker.placeOrder(account, appl, Side.BUY, 10, OrderType.MARKET, 0);
        System.out.println("Market buy status=" + buy.status + " cash=" + account.cashBalance + " holdings=" + account.portfolio.holdingOf("AAPL"));

        // Limit sell above current price: stays pending until price rises.
        Order limitSell = broker.placeOrder(account, appl, Side.SELL, 5, OrderType.LIMIT, 160.0);
        System.out.println("Limit sell status=" + limitSell.status);

        feed.updatePrice("AAPL", 161.0); // Observer push triggers re-check
        System.out.println("After price tick, limit sell status=" + limitSell.status + " cash=" + account.cashBalance);

        // Place another limit sell, then cancel it before it executes.
        Order toCancel = broker.placeOrder(account, appl, Side.SELL, 2, OrderType.LIMIT, 500.0);
        broker.cancelOrder(toCancel.id);
        System.out.println("Cancelled order status=" + toCancel.status + " holdings=" + account.portfolio.holdingOf("AAPL"));

        // Concurrency demo: two threads race to sell the last 3 shares concurrently.
        Account raceAccount = new Account("A2", 5000.0);
        broker.addAccount(raceAccount);
        broker.placeOrder(raceAccount, appl, Side.BUY, 3, OrderType.MARKET, 0); // gives raceAccount exactly 3 shares

        Runnable trySell = () -> {
            try {
                broker.placeOrder(raceAccount, appl, Side.SELL, 3, OrderType.MARKET, 0);
            } catch (InsufficientHoldingsException e) {
                System.out.println("Thread correctly rejected: " + e.getMessage());
            }
        };
        Thread t1 = new Thread(trySell);
        Thread t2 = new Thread(trySell);
        t1.start(); t2.start();
        t1.join(); t2.join();
        System.out.println("Race account final holdings=" + raceAccount.portfolio.holdingOf("AAPL") + " (never negative)");
    }
}

