// Problem 21: Stock Brokerage System
// Patterns: Strategy (ExecutionStrategy), Observer (MarketDataFeed -> Broker), Facade (Broker)
// Concurrency: per-account mutex guards reserve+execute+settle so cash/holdings never corrupt
// under concurrent orders (badge: Advanced, Concurrency & Consistency).
#include <iostream>
#include <vector>
#include <map>
#include <memory>
#include <string>
#include <optional>
#include <mutex>
#include <thread>
#include <stdexcept>
#include <algorithm>

using namespace std;

// ---------- Exceptions ----------
struct InsufficientFundsException : runtime_error { InsufficientFundsException(const string& m) : runtime_error(m) {} };
struct InsufficientHoldingsException : runtime_error { InsufficientHoldingsException(const string& m) : runtime_error(m) {} };
struct InvalidOrderStateException : runtime_error { InvalidOrderStateException(const string& m) : runtime_error(m) {} };
struct OrderNotFoundException : runtime_error { OrderNotFoundException(const string& m) : runtime_error(m) {} };

enum class Side { BUY, SELL };
enum class OrderType { MARKET, LIMIT };
enum class OrderStatus { PENDING, EXECUTED, CANCELLED };

// ---------- Stock ----------
struct Stock {
    string symbol;
    double currentPrice;
    Stock(string symbol_, double price) : symbol(move(symbol_)), currentPrice(price) {}
    void updatePrice(double newPrice) { currentPrice = newPrice; }
};

// ---------- Portfolio (owned by Account) ----------
class Portfolio {
    map<string, int> holdings;
    map<string, int> reserved;
public:
    void reserveShares(const Stock& stock, int qty) {
        int owned = holdings.count(stock.symbol) ? holdings[stock.symbol] : 0;
        int alreadyReserved = reserved.count(stock.symbol) ? reserved[stock.symbol] : 0;
        if (owned - alreadyReserved < qty) throw InsufficientHoldingsException("Not enough shares of " + stock.symbol);
        reserved[stock.symbol] += qty;
    }
    void releaseShares(const Stock& stock, int qty) { reserved[stock.symbol] -= qty; }
    void addHolding(const Stock& stock, int qty) { holdings[stock.symbol] += qty; }

    // Removes settled (sold) shares from both holdings and their reservation.
    void settle(const Stock& stock, int qty, Side side) {
        if (side == Side::SELL) {
            holdings[stock.symbol] -= qty;
            reserved[stock.symbol] -= qty;
        }
    }
    int holdingOf(const string& symbol) { return holdings.count(symbol) ? holdings[symbol] : 0; }
};

// ---------- Account (owns Portfolio) ----------
class Account {
public:
    string id;
    double cashBalance;
    double reservedCash = 0;
    Portfolio portfolio;
    mutex lockMutex; // guards reserve/execute/settle atomicity

    Account(string id_, double initialCash) : id(move(id_)), cashBalance(initialCash) {}

    void reserve(double amount) {
        if (cashBalance - reservedCash < amount) throw InsufficientFundsException("Insufficient funds in " + id);
        reservedCash += amount;
    }
    void release(double amount) { reservedCash = max(0.0, reservedCash - amount); }
    void deposit(double amount) { cashBalance += amount; }
    void withdraw(double amount) {
        if (cashBalance < amount) throw InsufficientFundsException("Insufficient funds in " + id);
        cashBalance -= amount;
    }
};

// ---------- Order (abstract) ----------
class Order {
public:
    string id;
    shared_ptr<Account> account;
    shared_ptr<Stock> stock;
    int quantity;
    OrderType type;
    double limitPrice; // unused for MARKET
    double reservedEstimate = 0;
    OrderStatus status = OrderStatus::PENDING;

    Order(string id_, shared_ptr<Account> account_, shared_ptr<Stock> stock_, int quantity_, OrderType type_, double limitPrice_)
        : id(move(id_)), account(account_), stock(stock_), quantity(quantity_), type(type_), limitPrice(limitPrice_) {}
    virtual ~Order() = default;

    virtual Side getSide() const = 0;

    void cancel() {
        if (status != OrderStatus::PENDING) throw InvalidOrderStateException("Order not cancellable");
        status = OrderStatus::CANCELLED;
    }
};

class BuyOrder : public Order {
public:
    using Order::Order;
    Side getSide() const override { return Side::BUY; }
};
class SellOrder : public Order {
public:
    using Order::Order;
    Side getSide() const override { return Side::SELL; }
};

// ---------- ExecutionStrategy ----------
class ExecutionStrategy {
public:
    virtual ~ExecutionStrategy() = default;
    virtual optional<double> tryExecute(Order& order, double currentPrice) = 0;
};

class MarketExecutionStrategy : public ExecutionStrategy {
public:
    optional<double> tryExecute(Order&, double currentPrice) override { return currentPrice; } // always executes
};

class LimitExecutionStrategy : public ExecutionStrategy {
public:
    optional<double> tryExecute(Order& order, double currentPrice) override {
        bool conditionMet = order.getSide() == Side::BUY
            ? currentPrice <= order.limitPrice
            : currentPrice >= order.limitPrice;
        return conditionMet ? optional<double>(currentPrice) : nullopt;
    }
};

// ---------- MarketDataFeed ----------
class PriceListener {
public:
    virtual ~PriceListener() = default;
    virtual void onPriceUpdate(const string& symbol, double newPrice) = 0;
};

class MarketDataFeed {
public:
    virtual ~MarketDataFeed() = default;
    virtual double getPrice(const string& symbol) = 0;
    virtual void subscribe(const string& symbol, PriceListener* listener) = 0;
};

class SimpleMarketDataFeed : public MarketDataFeed {
    map<string, shared_ptr<Stock>> stocks;
    map<string, vector<PriceListener*>> listeners;
public:
    SimpleMarketDataFeed(map<string, shared_ptr<Stock>> stocks_) : stocks(move(stocks_)) {}

    double getPrice(const string& symbol) override { return stocks[symbol]->currentPrice; }

    void subscribe(const string& symbol, PriceListener* listener) override {
        auto& ls = listeners[symbol];
        if (find(ls.begin(), ls.end(), listener) == ls.end()) ls.push_back(listener);
    }

    void updatePrice(const string& symbol, double newPrice) {
        stocks[symbol]->updatePrice(newPrice);
        for (auto* l : listeners[symbol]) l->onPriceUpdate(symbol, newPrice); // push, don't poll
    }
};

// ---------- Broker (Facade) ----------
class Broker : public PriceListener {
    map<string, shared_ptr<Account>> accounts;
    map<string, shared_ptr<Order>> ordersById;
    map<string, vector<shared_ptr<Order>>> pendingOrdersBySymbol;
    MarketDataFeed* feed;
    MarketExecutionStrategy marketStrategy;
    LimitExecutionStrategy limitStrategy;
    int nextOrderId = 1;

public:
    Broker(MarketDataFeed* feed_) : feed(feed_) {}

    void addAccount(shared_ptr<Account> account) { accounts[account->id] = account; }
    void deposit(shared_ptr<Account> account, double amount) { account->deposit(amount); }
    void withdraw(shared_ptr<Account> account, double amount) { account->withdraw(amount); }

    shared_ptr<Order> placeOrder(shared_ptr<Account> account, shared_ptr<Stock> stock, Side side,
                                  int quantity, OrderType type, double limitPrice) {
        lock_guard<mutex> guard(account->lockMutex); // guard reserve + execution-attempt + settle atomically
        ExecutionStrategy* strategy = (type == OrderType::MARKET) ? (ExecutionStrategy*)&marketStrategy : (ExecutionStrategy*)&limitStrategy;
        double currentPrice = feed->getPrice(stock->symbol);
        string id = "ORD-" + to_string(nextOrderId++);
        shared_ptr<Order> order;

        if (side == Side::BUY) {
            double estimatedCost = quantity * (type == OrderType::MARKET ? currentPrice : limitPrice);
            account->reserve(estimatedCost); // throws InsufficientFundsException
            order = make_shared<BuyOrder>(id, account, stock, quantity, type, limitPrice);
            order->reservedEstimate = estimatedCost;
        } else {
            account->portfolio.reserveShares(*stock, quantity); // throws InsufficientHoldingsException
            order = make_shared<SellOrder>(id, account, stock, quantity, type, limitPrice);
        }
        ordersById[order->id] = order;

        auto result = strategy->tryExecute(*order, currentPrice);
        if (result.has_value()) {
            settle(*order, *result);
        } else {
            order->status = OrderStatus::PENDING;
            pendingOrdersBySymbol[stock->symbol].push_back(order);
            feed->subscribe(stock->symbol, this); // re-checked on future price ticks
        }
        return order;
    }

    void onPriceUpdate(const string& symbol, double newPrice) override {
        auto it = pendingOrdersBySymbol.find(symbol);
        if (it == pendingOrdersBySymbol.end()) return;
        vector<shared_ptr<Order>> stillPending;
        for (auto& order : it->second) {
            if (order->status != OrderStatus::PENDING) continue;
            lock_guard<mutex> guard(order->account->lockMutex);
            ExecutionStrategy* strategy = (order->type == OrderType::MARKET) ? (ExecutionStrategy*)&marketStrategy : (ExecutionStrategy*)&limitStrategy;
            auto result = strategy->tryExecute(*order, newPrice);
            if (result.has_value()) settle(*order, *result);
            else stillPending.push_back(order);
        }
        it->second = stillPending;
    }

    void cancelOrder(const string& orderId) {
        auto it = ordersById.find(orderId);
        if (it == ordersById.end()) throw OrderNotFoundException("No such order: " + orderId);
        auto order = it->second;
        lock_guard<mutex> guard(order->account->lockMutex);
        if (order->status != OrderStatus::PENDING) throw InvalidOrderStateException("Order not cancellable");
        if (order->getSide() == Side::BUY) order->account->release(order->reservedEstimate);
        else order->account->portfolio.releaseShares(*order->stock, order->quantity);
        order->status = OrderStatus::CANCELLED;
    }

private:
    // Must be called while holding order.account->lockMutex.
    void settle(Order& order, double executionPrice) {
        auto account = order.account;
        if (order.getSide() == Side::BUY) {
            account->release(order.reservedEstimate);
            account->withdraw(executionPrice * order.quantity);
            account->portfolio.addHolding(*order.stock, order.quantity);
        } else {
            account->portfolio.settle(*order.stock, order.quantity, Side::SELL); // removes reserved shares
            account->deposit(executionPrice * order.quantity);
        }
        order.status = OrderStatus::EXECUTED;
    }
};

string statusName(OrderStatus s) {
    switch (s) {
        case OrderStatus::PENDING: return "PENDING";
        case OrderStatus::EXECUTED: return "EXECUTED";
        case OrderStatus::CANCELLED: return "CANCELLED";
    }
    return "?";
}

// ---------- Demo ----------
int main() {
    auto appl = make_shared<Stock>("AAPL", 150.0);
    map<string, shared_ptr<Stock>> stocks = {{"AAPL", appl}};
    SimpleMarketDataFeed feed(stocks);

    Broker broker(&feed);
    auto account = make_shared<Account>("A1", 10000.0);
    broker.addAccount(account);

    auto buy = broker.placeOrder(account, appl, Side::BUY, 10, OrderType::MARKET, 0);
    cout << "Market buy status=" << statusName(buy->status) << " cash=" << account->cashBalance
         << " holdings=" << account->portfolio.holdingOf("AAPL") << endl;

    auto limitSell = broker.placeOrder(account, appl, Side::SELL, 5, OrderType::LIMIT, 160.0);
    cout << "Limit sell status=" << statusName(limitSell->status) << endl;

    feed.updatePrice("AAPL", 161.0); // Observer push triggers re-check
    cout << "After price tick, limit sell status=" << statusName(limitSell->status) << " cash=" << account->cashBalance << endl;

    auto toCancel = broker.placeOrder(account, appl, Side::SELL, 2, OrderType::LIMIT, 500.0);
    broker.cancelOrder(toCancel->id);
    cout << "Cancelled order status=" << statusName(toCancel->status) << " holdings=" << account->portfolio.holdingOf("AAPL") << endl;

    // Concurrency demo: two threads race to sell the last 3 shares concurrently.
    auto raceAccount = make_shared<Account>("A2", 5000.0);
    broker.addAccount(raceAccount);
    broker.placeOrder(raceAccount, appl, Side::BUY, 3, OrderType::MARKET, 0);

    auto trySell = [&]() {
        try {
            broker.placeOrder(raceAccount, appl, Side::SELL, 3, OrderType::MARKET, 0);
        } catch (InsufficientHoldingsException& e) {
            cout << "Thread correctly rejected: " << e.what() << endl;
        }
    };
    thread t1(trySell), t2(trySell);
    t1.join(); t2.join();
    cout << "Race account final holdings=" << raceAccount->portfolio.holdingOf("AAPL") << " (never negative)" << endl;

    return 0;
}

