// Problem 21: Stock Brokerage System
// Patterns: Strategy (ExecutionStrategy), Observer (MarketDataFeed -> Broker), Facade (Broker)
// Concurrency note: Node.js runs this synchronous demo on a single thread, so there is no
// real data race to guard against here -- but we still model a per-account Lock explicitly
// (mirroring the Java/C++ versions' mutex) so that the *shape* of the critical section
// (reserve -> tryExecute -> settle, all atomic w.r.t. one account) is structurally faithful
// and would compose correctly if ported to a worker/thread-based environment.

class InsufficientFundsException extends Error {}
class InsufficientHoldingsException extends Error {}
class InvalidOrderStateException extends Error {}
class OrderNotFoundException extends Error {}

const Side = Object.freeze({ BUY: 'BUY', SELL: 'SELL' });
const OrderType = Object.freeze({ MARKET: 'MARKET', LIMIT: 'LIMIT' });
const OrderStatus = Object.freeze({ PENDING: 'PENDING', EXECUTED: 'EXECUTED', CANCELLED: 'CANCELLED' });

// Trivial synchronous lock: acquire/release bracket the critical section explicitly,
// keeping the code shape identical to the Java/C++ mutex-guarded versions.
class Lock {
  acquire() { /* no-op: single-threaded event loop, but marks the critical section */ }
  release() { /* no-op */ }
}

// ---------- Stock ----------
class Stock {
  constructor(symbol, currentPrice) { this.symbol = symbol; this.currentPrice = currentPrice; }
  updatePrice(newPrice) { this.currentPrice = newPrice; }
}

// ---------- Portfolio (owned by Account) ----------
class Portfolio {
  constructor() { this.holdings = new Map(); this.reserved = new Map(); }

  reserveShares(stock, qty) {
    const owned = this.holdings.get(stock.symbol) || 0;
    const alreadyReserved = this.reserved.get(stock.symbol) || 0;
    if (owned - alreadyReserved < qty) throw new InsufficientHoldingsException(`Not enough shares of ${stock.symbol}`);
    this.reserved.set(stock.symbol, alreadyReserved + qty);
  }
  releaseShares(stock, qty) {
    this.reserved.set(stock.symbol, (this.reserved.get(stock.symbol) || 0) - qty);
  }
  addHolding(stock, qty) {
    this.holdings.set(stock.symbol, (this.holdings.get(stock.symbol) || 0) + qty);
  }
  // Removes settled (sold) shares from both holdings and their reservation.
  settle(stock, qty, side) {
    if (side === Side.SELL) {
      this.holdings.set(stock.symbol, (this.holdings.get(stock.symbol) || 0) - qty);
      this.reserved.set(stock.symbol, (this.reserved.get(stock.symbol) || 0) - qty);
    }
  }
  holdingOf(symbol) { return this.holdings.get(symbol) || 0; }
}

// ---------- Account (owns Portfolio) ----------
class Account {
  constructor(id, initialCash) {
    this.id = id; this.cashBalance = initialCash; this.reservedCash = 0;
    this.portfolio = new Portfolio();
    this.lock = new Lock(); // guards reserve/execute/settle atomicity
  }
  reserve(amount) {
    if (this.cashBalance - this.reservedCash < amount) throw new InsufficientFundsException(`Insufficient funds in ${this.id}`);
    this.reservedCash += amount;
  }
  release(amount) { this.reservedCash = Math.max(0, this.reservedCash - amount); }
  deposit(amount) { this.cashBalance += amount; }
  withdraw(amount) {
    if (this.cashBalance < amount) throw new InsufficientFundsException(`Insufficient funds in ${this.id}`);
    this.cashBalance -= amount;
  }
}

// ---------- Order (abstract) ----------
class Order {
  constructor(id, account, stock, quantity, type, limitPrice) {
    if (new.target === Order) throw new Error('Order is abstract');
    this.id = id; this.account = account; this.stock = stock;
    this.quantity = quantity; this.type = type; this.limitPrice = limitPrice;
    this.reservedEstimate = 0;
    this.status = OrderStatus.PENDING;
  }
  getSide() { throw new Error('abstract method'); }
  cancel() {
    if (this.status !== OrderStatus.PENDING) throw new InvalidOrderStateException('Order not cancellable');
    this.status = OrderStatus.CANCELLED;
  }
}

class BuyOrder extends Order { getSide() { return Side.BUY; } }
class SellOrder extends Order { getSide() { return Side.SELL; } }

// ---------- ExecutionStrategy ----------
class MarketExecutionStrategy {
  tryExecute(order, currentPrice) { return currentPrice; } // always executes, market orders take the going price
}
class LimitExecutionStrategy {
  tryExecute(order, currentPrice) {
    const conditionMet = order.getSide() === Side.BUY ? currentPrice <= order.limitPrice : currentPrice >= order.limitPrice;
    return conditionMet ? currentPrice : null;
  }
}

// ---------- MarketDataFeed ----------
class SimpleMarketDataFeed {
  constructor(stocks) { this.stocks = stocks; this.listeners = new Map(); } // symbol -> Stock, symbol -> listeners[]

  getPrice(symbol) { return this.stocks.get(symbol).currentPrice; }

  subscribe(symbol, listener) {
    if (!this.listeners.has(symbol)) this.listeners.set(symbol, []);
    const ls = this.listeners.get(symbol);
    if (!ls.includes(listener)) ls.push(listener);
  }

  updatePrice(symbol, newPrice) {
    this.stocks.get(symbol).updatePrice(newPrice);
    for (const l of this.listeners.get(symbol) || []) l.onPriceUpdate(symbol, newPrice); // push, don't poll
  }
}

// ---------- Broker (Facade) ----------
class Broker {
  constructor(feed) {
    this.feed = feed;
    this.accounts = new Map();
    this.ordersById = new Map();
    this.pendingOrdersBySymbol = new Map();
    this.marketStrategy = new MarketExecutionStrategy();
    this.limitStrategy = new LimitExecutionStrategy();
    this.nextOrderId = 1;
  }

  addAccount(account) { this.accounts.set(account.id, account); }
  deposit(account, amount) { account.deposit(amount); }
  withdraw(account, amount) { account.withdraw(amount); }

  placeOrder(account, stock, side, quantity, type, limitPrice) {
    account.lock.acquire(); // guard reserve + execution-attempt + settle atomically
    try {
      const strategy = type === OrderType.MARKET ? this.marketStrategy : this.limitStrategy;
      const currentPrice = this.feed.getPrice(stock.symbol);
      const id = `ORD-${this.nextOrderId++}`;
      let order;

      if (side === Side.BUY) {
        const estimatedCost = quantity * (type === OrderType.MARKET ? currentPrice : limitPrice);
        account.reserve(estimatedCost); // throws InsufficientFundsException
        order = new BuyOrder(id, account, stock, quantity, type, limitPrice);
        order.reservedEstimate = estimatedCost;
      } else {
        account.portfolio.reserveShares(stock, quantity); // throws InsufficientHoldingsException
        order = new SellOrder(id, account, stock, quantity, type, limitPrice);
      }
      this.ordersById.set(order.id, order);

      const result = strategy.tryExecute(order, currentPrice);
      if (result !== null) {
        this._settle(order, result);
      } else {
        order.status = OrderStatus.PENDING;
        if (!this.pendingOrdersBySymbol.has(stock.symbol)) this.pendingOrdersBySymbol.set(stock.symbol, []);
        this.pendingOrdersBySymbol.get(stock.symbol).push(order);
        this.feed.subscribe(stock.symbol, this); // re-checked on future price ticks
      }
      return order;
    } finally {
      account.lock.release();
    }
  }

  onPriceUpdate(symbol, newPrice) {
    const pending = this.pendingOrdersBySymbol.get(symbol);
    if (!pending) return;
    const stillPending = [];
    for (const order of pending) {
      if (order.status !== OrderStatus.PENDING) continue;
      order.account.lock.acquire();
      try {
        const strategy = order.type === OrderType.MARKET ? this.marketStrategy : this.limitStrategy;
        const result = strategy.tryExecute(order, newPrice);
        if (result !== null) this._settle(order, result);
        else stillPending.push(order);
      } finally {
        order.account.lock.release();
      }
    }
    this.pendingOrdersBySymbol.set(symbol, stillPending);
  }

  cancelOrder(orderId) {
    const order = this.ordersById.get(orderId);
    if (!order) throw new OrderNotFoundException(`No such order: ${orderId}`);
    order.account.lock.acquire();
    try {
      if (order.status !== OrderStatus.PENDING) throw new InvalidOrderStateException('Order not cancellable');
      if (order.getSide() === Side.BUY) order.account.release(order.reservedEstimate);
      else order.account.portfolio.releaseShares(order.stock, order.quantity);
      order.status = OrderStatus.CANCELLED;
    } finally {
      order.account.lock.release();
    }
  }

  // Must be called while holding order.account.lock.
  _settle(order, executionPrice) {
    const account = order.account;
    if (order.getSide() === Side.BUY) {
      account.release(order.reservedEstimate);
      account.withdraw(executionPrice * order.quantity);
      account.portfolio.addHolding(order.stock, order.quantity);
    } else {
      account.portfolio.settle(order.stock, order.quantity, Side.SELL); // removes reserved shares
      account.deposit(executionPrice * order.quantity);
    }
    order.status = OrderStatus.EXECUTED;
  }
}

// ---------- Demo ----------
function main() {
  const appl = new Stock('AAPL', 150.0);
  const stocks = new Map([['AAPL', appl]]);
  const feed = new SimpleMarketDataFeed(stocks);

  const broker = new Broker(feed);
  const account = new Account('A1', 10000.0);
  broker.addAccount(account);

  const buy = broker.placeOrder(account, appl, Side.BUY, 10, OrderType.MARKET, 0);
  console.log(`Market buy status=${buy.status} cash=${account.cashBalance} holdings=${account.portfolio.holdingOf('AAPL')}`);

  const limitSell = broker.placeOrder(account, appl, Side.SELL, 5, OrderType.LIMIT, 160.0);
  console.log(`Limit sell status=${limitSell.status}`);

  feed.updatePrice('AAPL', 161.0); // Observer push triggers re-check
  console.log(`After price tick, limit sell status=${limitSell.status} cash=${account.cashBalance}`);

  const toCancel = broker.placeOrder(account, appl, Side.SELL, 2, OrderType.LIMIT, 500.0);
  broker.cancelOrder(toCancel.id);
  console.log(`Cancelled order status=${toCancel.status} holdings=${account.portfolio.holdingOf('AAPL')}`);

  // Sequential "race": both attempts guarded by the same lock discipline as Java/C++;
  // the second is correctly rejected because the first already consumed all shares.
  const raceAccount = new Account('A2', 5000.0);
  broker.addAccount(raceAccount);
  broker.placeOrder(raceAccount, appl, Side.BUY, 3, OrderType.MARKET, 0);

  const trySell = () => {
    try {
      broker.placeOrder(raceAccount, appl, Side.SELL, 3, OrderType.MARKET, 0);
    } catch (e) {
      console.log('Rejected as expected:', e.message);
    }
  };
  trySell();
  trySell();
  console.log(`Race account final holdings=${raceAccount.portfolio.holdingOf('AAPL')} (never negative)`);
}

if (require.main === module) main();

module.exports = {
  Account, Portfolio, Stock, Order, BuyOrder, SellOrder,
  MarketExecutionStrategy, LimitExecutionStrategy, SimpleMarketDataFeed, Broker,
  Side, OrderType, OrderStatus,
};

